INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ポリエステルは、石油を原料として化学的に合成される繊維で、シワになりにくく、乾きやすい性質を持ちます。衣料品や様々な工業製品に広く用いられています。", "primary_collocate": null, "pronunciation": "ぽりえすてる", "ipa": "poɾieseɯteɾɯ", "syllable_count": 6, "sentences": [{"text": "ポリエステルは石油を原料にして化学的に作られる繊維だ。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは石油[せきゆ]を原料[げんりょう]にして化学的[かがくてき]に作[つく]られる繊維[せんい]だ。", "sentence_source": "generated"}, {"text": "ポリエステルは丈夫で、洗ったあとの縮みが少ない。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは丈夫[じょうぶ]で、洗[あら]ったあとの縮[ちぢ]みが少[すく]ない。", "sentence_source": "generated"}, {"text": "ペットボトルを再利用して、ポリエステルの糸を作る会社がある。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ペットボトルを再利用[さいりよう]して、ポリエステルの糸[いと]を作[つく]る会社[かいしゃ]がある。", "sentence_source": "generated"}, {"text": "ポリエステルは衣料品だけでなく、ロープやシートにも用いられる。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは衣料品[いりょうひん]だけでなく、ロープやシートにも用[もち]いられる。", "sentence_source": "generated"}, {"text": "ポリエステルは乾きやすい性質があるので、スポーツウェアに向いている。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルは乾[かわ]きやすい性質[せいしつ]があるので、スポーツウェアに向[む]いている。", "sentence_source": "generated"}, {"text": "綿は自然の繊維だが、ポリエステルは人が合成した繊維だ。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "綿[めん]は自然[しぜん]の繊維[せんい]だが、ポリエステルは人[ひと]が合成[ごうせい]した繊維[せんい]だ。", "sentence_source": "generated"}, {"text": "工場では、溶かしたポリエステルを細く伸ばして糸にする。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、溶[と]かしたポリエステルを細[ほそ]く伸[の]ばして糸[いと]にする。", "sentence_source": "generated"}, {"text": "ポリエステルはしわになりにくいため、制服の材料として人気がある。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "ポリエステルはしわになりにくいため、制服[せいふく]の材料[ざいりょう]として人気[にんき]がある。", "sentence_source": "generated"}, {"text": "石油の値段が上がると、ポリエステルの価格も高くなりやすい。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "石油[せきゆ]の値段[ねだん]が上[あ]がると、ポリエステルの価格[かかく]も高[たか]くなりやすい。", "sentence_source": "generated"}, {"text": "古いポリエステルの服を細かくして、新しい繊維に作り直す研究が進んでいる。", "target_word": "ポリエステル", "complexity_tier": "T3", "furigana": "古[ふる]いポリエステルの服[ふく]を細[こま]かくして、新[あたら]しい繊維[せんい]に作[つく]り直[なお]す研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポリエステル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "石油を原料に合成する、しわになりにくく乾きやすい繊維。衣料や工業製品に使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポリエステル", "is_correct": true, "explanation": "石油を原料に化学的に作る繊維という説明に合う。"}, {"text": "大根", "is_correct": false, "explanation": "野菜で、石油を原料にして作る繊維ではないので、文が成り立たない。"}, {"text": "豆腐", "is_correct": false, "explanation": "大豆の食品で、化学的に作る繊維ではないので合わない。"}, {"text": "氷", "is_correct": false, "explanation": "水が固まったもので、石油を原料とする繊維ではないので合わない。"}], "explanations": {"ポリエステル": "石油を原料に化学的に作る繊維という説明に合う。", "大根": "野菜で、石油を原料にして作る繊維ではないので、文が成り立たない。", "豆腐": "大豆の食品で、化学的に作る繊維ではないので合わない。", "氷": "水が固まったもので、石油を原料とする繊維ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ポリエステル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポリエステルは木材のパルプから作られ、とろりとした光沢がある。", "explanation": "ここは〈レーヨン〉の意味。木材パルプから作る繊維の説明で、石油から作るポリエステルには合わない。"}, {"text": "ポリエステルは錆びにくく、鍋やフライパンに使われる。", "explanation": "ここは〈ステンレス〉の意味。錆びにくい金属の鍋の話で、繊維のポリエステルを鍋に使うとは言わない。"}, {"text": "ポリエステルは水と混ぜて固め、道路や橋に使われる。", "explanation": "ここは〈セメント〉の意味。水と混ぜて固める建材を指し、繊維のポリエステルには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポリエステル", "is_correct": true, "explanation": "溶かして細く伸ばし、糸にできる合成繊維の材料として文に合う。"}, {"text": "パン", "is_correct": false, "explanation": "食品で、溶かして細く伸ばし糸にする材料ではないので合わない。"}, {"text": "畳", "is_correct": false, "explanation": "床に敷く素材で、溶かして糸にするものではないので文が成り立たない。"}, {"text": "味噌", "is_correct": false, "explanation": "発酵食品で、糸にする材料にはならないので文に合わない。"}], "explanations": {"ポリエステル": "溶かして細く伸ばし、糸にできる合成繊維の材料として文に合う。", "パン": "食品で、溶かして細く伸ばし糸にする材料ではないので合わない。", "畳": "床に敷く素材で、溶かして糸にするものではないので文が成り立たない。", "味噌": "発酵食品で、糸にする材料にはならないので文に合わない。"}, "sentence_index": 6, "correct_answer": "ポリエステル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポリエステルは弾力があり、タイヤや輪ゴムに使われる。", "explanation": "ここは〈ゴム〉の意味。弾力のある素材で、タイヤや輪ゴムに使われるものを指す。繊維のポリエステルには当てはまらない。"}, {"text": "ポリエステルは焼いた土で作られ、食器に使われる。", "explanation": "ここは〈陶器〉の意味。焼いた土で作る食器の話で、繊維のポリエステルには合わない。"}, {"text": "ポリエステルは石油から作られ、ろうそくの材料になる。", "explanation": "ここは〈パラフィン〉の意味。石油から作るろうそくの材料を指し、ポリエステルは繊維なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このシャツは、ポリエステルを作られている。", "corrected_sentence": "このシャツは、ポリエステルで作られている。", "error_description": "「作られる」で材料を示すときは「で」を使う。「ポリエステルを作られている」は助詞「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39119, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ポリエステルを使いた服は、しわになりにくい。", "corrected_sentence": "ポリエステルを使った服は、しわになりにくい。", "error_description": "動詞「使う」の過去形は「使った」。「使いた」は活用の誤りで、正しい形は「使った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39120, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「行う」の主体（機械）を示す助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「機械を行う」は対象にならず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「機械へ行う」は方向の意味になり不自然です。"}, {"text": "に", "is_correct": false, "explanation": "「機械に行う」は意味が通りません。"}], "correct_answer": "が", "explanations": {"が": "「行う」の主体（機械）を示す助詞です。", "を": "「機械を行う」は対象にならず不自然です。", "へ": "「機械へ行う」は方向の意味になり不自然です。", "に": "「機械に行う」は意味が通りません。"}, "error_tags": {"を": "object", "へ": "direction", "に": "target_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "作る製造に対し、壊す破壊が対の関係です。"}, {"text": "製作", "is_correct": false, "explanation": "製造に近い意味の類義語です。"}, {"text": "生産", "is_correct": false, "explanation": "製造と近い意味の類義語です。"}, {"text": "販売", "is_correct": false, "explanation": "製造した物を売ることで、対義語ではありません。"}], "correct_answer": "破壊", "explanations": {"破壊": "作る製造に対し、壊す破壊が対の関係です。", "製作": "製造に近い意味の類義語です。", "生産": "製造と近い意味の類義語です。", "販売": "製造した物を売ることで、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39120, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "製造する場所を示す助詞です。"}, {"text": "を", "is_correct": false, "explanation": "「国内を製造する」は場所の意味にならず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「国内へ製造する」は方向の意味になり成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「国内と製造する」は意味が通りません。"}], "correct_answer": "で", "explanations": {"で": "製造する場所を示す助詞です。", "を": "「国内を製造する」は場所の意味にならず不自然です。", "へ": "「国内へ製造する」は方向の意味になり成り立ちません。", "と": "「国内と製造する」は意味が通りません。"}, "error_tags": {"を": "object", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消費", "is_correct": true, "explanation": "作る製造に対し、使って減らす消費が対の関係です。"}, {"text": "製作", "is_correct": false, "explanation": "製造に近い意味の類義語です。"}, {"text": "作成", "is_correct": false, "explanation": "作ることを表す類義語です。"}, {"text": "加工", "is_correct": false, "explanation": "ものを作る過程の一つで、対義語ではありません。"}], "correct_answer": "消費", "explanations": {"消費": "作る製造に対し、使って減らす消費が対の関係です。", "製作": "製造に近い意味の類義語です。", "作成": "作ることを表す類義語です。", "加工": "ものを作る過程の一つで、対義語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39120, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを作ること。", "primary_collocate": null, "pronunciation": "せいぞう", "ipa": "seːzoː", "syllable_count": 4, "sentences": [{"text": "パンを製造する工場を見学した。", "target_word": "製造", "complexity_tier": "T3", "furigana": "パンを製造[せいぞう]する工場[こうじょう]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "製造は機械が行う。", "target_word": "製造", "complexity_tier": "T1", "furigana": "製造[せいぞう]は機械[きかい]が行[おこな]う。", "sentence_source": "generated"}, {"text": "おもちゃの製造が始まりました。", "target_word": "製造", "complexity_tier": "T2", "furigana": "おもちゃの製造[せいぞう]が始[はじ]まりました。", "sentence_source": "generated"}, {"text": "この店は菓子の製造をやめた。", "target_word": "製造", "complexity_tier": "T3", "furigana": "この店[みせ]は菓子[かし]の製造[せいぞう]をやめた。", "sentence_source": "generated"}, {"text": "製造の仕事は楽ではない。", "target_word": "製造", "complexity_tier": "T3", "furigana": "製造[せいぞう]の仕事[しごと]は楽[らく]ではない。", "sentence_source": "generated"}, {"text": "ここで製造された靴は丈夫だ。", "target_word": "製造", "complexity_tier": "T4", "furigana": "ここで製造[せいぞう]された靴[くつ]は丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "製造を担当する人が説明した。", "target_word": "製造", "complexity_tier": "T3", "furigana": "製造[せいぞう]を担当[たんとう]する人[ひと]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "国内で製造するほうが安心だ。", "target_word": "製造", "complexity_tier": "T3", "furigana": "国内[こくない]で製造[せいぞう]するほうが安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "製造する量を減らします。", "target_word": "製造", "complexity_tier": "T2", "furigana": "製造[せいぞう]する量[りょう]を減[へ]らします。", "sentence_source": "generated"}, {"text": "夏は飲み物の製造が忙しい。", "target_word": "製造", "complexity_tier": "T3", "furigana": "夏[なつ]は飲[の]み物[もの]の製造[せいぞう]が忙[いそが]しい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製造する", "label": "活用"}, {"form": "製造された", "label": "活用"}, {"form": "製造業", "label": "派生"}, {"form": "製造元", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ものを作ること、作る仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
