INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "製造する対象（部品）を示す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「部品に製造する」は対象を表せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「部品へ製造する」は方向の意味になり成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「部品が製造する」は主体と対象が合わず不自然です。"}], "correct_answer": "を", "explanations": {"を": "製造する対象（部品）を示す助詞です。", "に": "「部品に製造する」は対象を表せず不自然です。", "へ": "「部品へ製造する」は方向の意味になり成り立ちません。", "が": "「部品が製造する」は主体と対象が合わず不自然です。"}, "error_tags": {"に": "target_marker", "へ": "direction", "が": "subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消費", "is_correct": true, "explanation": "作り出す製造に対し、使って減らす消費が対の関係です。"}, {"text": "生産", "is_correct": false, "explanation": "製造とほぼ同じ意味の類義語です。"}, {"text": "加工", "is_correct": false, "explanation": "製造の過程の一部で、対義語ではありません。"}, {"text": "設計", "is_correct": false, "explanation": "製造の前段階の作業で、対義語ではありません。"}], "correct_answer": "消費", "explanations": {"消費": "作り出す製造に対し、使って減らす消費が対の関係です。", "生産": "製造とほぼ同じ意味の類義語です。", "加工": "製造の過程の一部で、対義語ではありません。", "設計": "製造の前段階の作業で、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
