INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "原料や材料を加工して、製品を作り出すこと。", "primary_collocate": null, "pronunciation": "せいぞう", "ipa": "seːzoː", "syllable_count": 4, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "製造", "complexity_tier": "T6", "furigana": "再生可能[さいせいかのう]エネルギーの導入[どうにゅう]加速[かそく]にもかかわらず、製造[せいぞう]プロセスの性質上[せいしつじょう]、炭素[たんそ]発生[はっせい]をゼロ化[か]し得[え]ない領域[りょういき]において、CCUSは極[きわ]めて重要[じゅうよう]な役割[やくわり]を担[にな]う。", "sentence_source": "mined"}, {"text": "この工場では自動車の部品を製造しています。", "target_word": "製造", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では自動車[じどうしゃ]の部品[ぶひん]を製造[せいぞう]しています。", "sentence_source": "generated"}, {"text": "製造の現場で働いています。", "target_word": "製造", "complexity_tier": "T3", "furigana": "製造[せいぞう]の現場[げんば]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "製造された薬は検査に回されます。", "target_word": "製造", "complexity_tier": "T4", "furigana": "製造[せいぞう]された薬[くすり]は検査[けんさ]に回[まわ]されます。", "sentence_source": "generated"}, {"text": "この製品は日本で製造された。", "target_word": "製造", "complexity_tier": "T4", "furigana": "この製品[せいひん]は日本[にほん]で製造[せいぞう]された。", "sentence_source": "generated"}, {"text": "製造コストが上がってしまった。", "target_word": "製造", "complexity_tier": "T3", "furigana": "製造[せいぞう]コストが上[あ]がってしまった。", "sentence_source": "generated"}, {"text": "新しい製造ラインが完成した。", "target_word": "製造", "complexity_tier": "T3", "furigana": "新[あたら]しい製造[せいぞう]ラインが完成[かんせい]した。", "sentence_source": "generated"}, {"text": "製造を止めると、納期に遅れる。", "target_word": "製造", "complexity_tier": "T4", "furigana": "製造[せいぞう]を止[と]めると、納期[のうき]に遅[おく]れる。", "sentence_source": "generated"}, {"text": "この会社は食品の製造を行っています。", "target_word": "製造", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は食品[しょくひん]の製造[せいぞう]を行[おこな]っています。", "sentence_source": "generated"}, {"text": "製造の方法を工場で学んだ。", "target_word": "製造", "complexity_tier": "T3", "furigana": "製造[せいぞう]の方法[ほうほう]を工場[こうじょう]で学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製造する", "label": "活用"}, {"form": "製造された", "label": "活用"}, {"form": "製造業", "label": "派生"}, {"form": "製造元", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 原料を加工して製品を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "製造", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "清掃", "is_correct": false, "explanation": "せいそう。「ぞ」が「そ」に変わる別の語です。"}, {"text": "青銅", "is_correct": false, "explanation": "せいどう。「ぞ」が「ど」に変わる別の語です。"}, {"text": "成功", "is_correct": false, "explanation": "せいこう。「ぞ」が「こ」に変わる別の語です。"}, {"text": "生存", "is_correct": false, "explanation": "せいぞん。最後の「う」が「ん」に変わる別の語です。"}], "explanations": {"製造": "見出し語そのものです。", "清掃": "せいそう。「ぞ」が「そ」に変わる別の語です。", "青銅": "せいどう。「ぞ」が「ど」に変わる別の語です。", "成功": "せいこう。「ぞ」が「こ」に変わる別の語です。", "生存": "せいぞん。最後の「う」が「ん」に変わる別の語です。"}, "sentence_index": null, "correct_answer": "製造"}, "level_3": {"options": [{"text": "製造", "is_correct": true, "explanation": "「製造プロセス」は原料を加工して製品を作る過程で、炭素発生の文脈に合います。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが、翻訳の過程は炭素発生の話に意味が合わない。"}, {"text": "採点", "is_correct": false, "explanation": "形は合うが、採点の過程は炭素発生の話に意味が合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "形は合うが、睡眠のプロセスは産業の領域の話に意味が合わない。"}], "explanations": {"製造": "「製造プロセス」は原料を加工して製品を作る過程で、炭素発生の文脈に合います。", "翻訳": "形は合うが、翻訳の過程は炭素発生の話に意味が合わない。", "採点": "形は合うが、採点の過程は炭素発生の話に意味が合わない。", "睡眠": "形は合うが、睡眠のプロセスは産業の領域の話に意味が合わない。"}, "sentence_index": 0, "correct_answer": "製造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は家族のために夕食を製造した。", "explanation": "製造は工場などで製品を作ることで、家庭で料理を作る意味には使わない。"}, {"text": "昨日は大きな地震が製造して、棚が倒れた。", "explanation": "製造は「起こる」という意味では使えず、自然現象の発生には合わない。"}, {"text": "彼は風邪の製造で会社を休んだ。", "explanation": "製造は「原因」の意味ではなく、病気の理由を表すのに誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "製造", "is_correct": true, "explanation": "見出し語そのものです。"}, {"text": "政党", "is_correct": false, "explanation": "せいとう。「ぞ」が「と」に変わる別の語です。"}, {"text": "西洋", "is_correct": false, "explanation": "せいよう。「ぞ」が「よ」に変わる別の語です。"}, {"text": "製法", "is_correct": false, "explanation": "せいほう。「ぞ」が「ほ」に変わる別の語です。"}], "explanations": {"製造": "見出し語そのものです。", "政党": "せいとう。「ぞ」が「と」に変わる別の語です。", "西洋": "せいよう。「ぞ」が「よ」に変わる別の語です。", "製法": "せいほう。「ぞ」が「ほ」に変わる別の語です。"}, "sentence_index": null, "correct_answer": "製造"}, "level_3": {"options": [{"text": "製造", "is_correct": true, "explanation": "製品を作る「製造ライン」は完成するものとして自然です。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが、翻訳のラインというものは意味が合わない。"}, {"text": "採点", "is_correct": false, "explanation": "形は合うが、採点のラインは完成するものとして意味が合わない。"}, {"text": "読書", "is_correct": false, "explanation": "形は合うが、読書のラインは意味が合わない。"}], "explanations": {"製造": "製品を作る「製造ライン」は完成するものとして自然です。", "翻訳": "形は合うが、翻訳のラインというものは意味が合わない。", "採点": "形は合うが、採点のラインは完成するものとして意味が合わない。", "読書": "形は合うが、読書のラインは意味が合わない。"}, "sentence_index": 6, "correct_answer": "製造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎朝、庭で花を製造して楽しんでいる。", "explanation": "製造は工業的に物を作ることで、植物を育てる意味には使わない。"}, {"text": "彼女は悲しい気持ちを製造して泣き出した。", "explanation": "製造は感情には使えず、気持ちが生まれる意味では誤用です。"}, {"text": "電車の製造に乗って学校へ行った。", "explanation": "製造は乗り物に乗る行為を指さず、「乗る」と結びつかない誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は食品に製造を行っています。", "corrected_sentence": "この会社は食品の製造を行っています。", "error_description": "名詞「製造」を修飾するには「に」ではなく「の」を使います。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39121, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は海外に製造された。", "corrected_sentence": "この薬は海外で製造された。", "error_description": "製造される場所を示す助詞は「に」ではなく「で」です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
