INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39123, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "数量が非常に大きいさま。莫大。", "primary_collocate": null, "pronunciation": "ぼうだい", "ipa": "boːdai", "syllable_count": 4, "sentences": [{"text": "研究には、膨大な費用がかかります。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "研究[けんきゅう]には、膨大[ぼうだい]な費用[ひよう]がかかります。", "sentence_source": "generated"}, {"text": "調査のデータが膨大で、整理するのに数週間かかりました。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "調査[ちょうさ]のデータが膨大[ぼうだい]で、整理[せいり]するのに数週間[すうしゅうかん]かかりました。", "sentence_source": "generated"}, {"text": "その会社は膨大な利益を上げました。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は膨大[ぼうだい]な利益[りえき]を上[あ]げました。", "sentence_source": "generated"}, {"text": "膨大な数の人が、駅前に集まりました。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "膨大[ぼうだい]な数[かず]の人[ひと]が、駅前[えきまえ]に集[あつ]まりました。", "sentence_source": "generated"}, {"text": "膨大な量の写真をスマホに保存しています。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "膨大[ぼうだい]な量[りょう]の写真[しゃしん]をスマホに保存[ほぞん]しています。", "sentence_source": "generated"}, {"text": "彼は膨大な遺産を相続しました。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "彼[かれ]は膨大[ぼうだい]な遺産[いさん]を相続[そうぞく]しました。", "sentence_source": "generated"}, {"text": "台風のあと、膨大な被害が出ました。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、膨大[ぼうだい]な被害[ひがい]が出[で]ました。", "sentence_source": "generated"}, {"text": "膨大なアクセスのため、サイトがつながりません。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "膨大[ぼうだい]なアクセスのため、サイトがつながりません。", "sentence_source": "generated"}, {"text": "地震の復旧には、膨大な予算が必要です。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "地震[じしん]の復旧[ふっきゅう]には、膨大[ぼうだい]な予算[よさん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "計算する数字が膨大なので、コンピューターを使います。", "target_word": "膨大", "complexity_tier": "T3", "furigana": "計算[けいさん]する数字[すうじ]が膨大[ぼうだい]なので、コンピューターを使[つか]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "膨大な", "label": "連体形"}, {"form": "膨大で", "label": "連用形"}, {"form": "膨大に", "label": "連用形"}], "register": "やや硬い", "sense_fingerprint": "数量が非常に大きいさま、莫大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eedbe05-f7a1-46a5-8c64-cbc0a50099f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39123, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "膨大な", "is_correct": true, "explanation": "「膨大」は数量が非常に大きい様子。研究費用の多さを述べる文に合う。"}, {"text": "器用な", "is_correct": false, "explanation": "手先の巧みさを表す。費用の多さには使えない。"}, {"text": "清らかな", "is_correct": false, "explanation": "清潔で澄んだ様子を表す。費用の文には合わない。"}, {"text": "朗らかな", "is_correct": false, "explanation": "明るい性格を表す。費用の量を述べる文には使えない。"}], "explanations": {"膨大な": "「膨大」は数量が非常に大きい様子。研究費用の多さを述べる文に合う。", "器用な": "手先の巧みさを表す。費用の多さには使えない。", "清らかな": "清潔で澄んだ様子を表す。費用の文には合わない。", "朗らかな": "明るい性格を表す。費用の量を述べる文には使えない。"}, "sentence_index": 0, "correct_answer": "膨大な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その海は膨大で、夕日がきれいです。", "explanation": "ここは〈美しい〉の意味。「膨大」は数量の多さを表し、景色の美しさは言えない。"}, {"text": "この箱は膨大で、片手で持てます。", "explanation": "ここは〈軽い〉の意味。「膨大」は量の多さで、重さの軽さは表せない。"}, {"text": "その部屋は膨大で、とても静かです。", "explanation": "ここは〈静か〉の意味。「膨大」は量を表すので、場所の静かさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39123, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "膨大な", "is_correct": true, "explanation": "「膨大」は数量が非常に大きい様子。被害の規模の大きさを述べる文に合う。"}, {"text": "鮮やかな", "is_correct": false, "explanation": "色や印象のはっきりした様子を表す。被害の規模は言えない。"}, {"text": "素朴な", "is_correct": false, "explanation": "飾り気のない様子を表す。被害の文には合わない。"}, {"text": "賢明な", "is_correct": false, "explanation": "判断の確かさを表す。被害の規模を述べる文には使えない。"}], "explanations": {"膨大な": "「膨大」は数量が非常に大きい様子。被害の規模の大きさを述べる文に合う。", "鮮やかな": "色や印象のはっきりした様子を表す。被害の規模は言えない。", "素朴な": "飾り気のない様子を表す。被害の文には合わない。", "賢明な": "判断の確かさを表す。被害の規模を述べる文には使えない。"}, "sentence_index": 6, "correct_answer": "膨大な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は膨大で、ベッドを置く場所がありません。", "explanation": "ここは〈狭い〉の意味。「膨大」は数量の多さを表し、空間の狭さには使わない。"}, {"text": "このナイフは膨大で、よく切れます。", "explanation": "ここは〈鋭い〉の意味。「膨大」は量の多さを表し、切れ味は言えない。"}, {"text": "彼女は膨大な性格で、みんなを笑わせます。", "explanation": "ここは〈陽気〉の意味。「膨大」は数や量に使うので、性格の明るさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39123, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店は膨大に量の商品を仕入れました。", "corrected_sentence": "その店は膨大な量の商品を仕入れました。", "error_description": "形の誤り。「膨大」は名詞を直接修飾するとき連体形「膨大な」にする。「膨大に」は連用形で、「量」を直接修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "膨大", "is_correct": true, "explanation": "「で」の前に置く語幹。「調査のデータが膨大で」と述語として続け、データの多さを表す。"}, {"text": "膨大な", "is_correct": false, "explanation": "名詞の前に置く連体形。「で」の前には入らず「膨大なで」となり不自然。"}, {"text": "膨大に", "is_correct": false, "explanation": "「なる」「する」などに続く連用形。「膨大にで」とは続かない。"}, {"text": "膨大だ", "is_correct": false, "explanation": "断定の形。「膨大だで」となり、「で」に続けられない。"}], "correct_form": "膨大", "base_form": "膨大", "form_label": "語幹", "sentence_index": 1, "explanations": {"膨大": "「で」の前に置く語幹。「調査のデータが膨大で」と述語として続け、データの多さを表す。", "膨大な": "名詞の前に置く連体形。「で」の前には入らず「膨大なで」となり不自然。", "膨大に": "「なる」「する」などに続く連用形。「膨大にで」とは続かない。", "膨大だ": "断定の形。「膨大だで」となり、「で」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39123, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店には、膨大の数の客が来ます。", "corrected_sentence": "この店には、膨大な数の客が来ます。", "error_description": "形の誤り。「膨大」は形状詞で、名詞の前では「膨大な」の形にする。「膨大の」は助詞「の」を続けた誤りで、「数」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "膨大", "is_correct": true, "explanation": "「な」の前に置く語幹。「膨大なアクセス」と名詞を修飾し、アクセスの多さを表す。"}, {"text": "膨大で", "is_correct": false, "explanation": "述語や連用の形。「膨大でなアクセス」とは名詞に続かず不自然。"}, {"text": "膨大さ", "is_correct": false, "explanation": "名詞化した形。「膨大さなアクセス」とは続かず、「の」などを挟む必要があるため不自然。"}, {"text": "膨大化", "is_correct": false, "explanation": "「化」を付けた名詞。「膨大化なアクセス」とは名詞修飾の形にならず、この文脈では使えない。"}], "correct_form": "膨大", "base_form": "膨大", "form_label": "語幹", "sentence_index": 7, "explanations": {"膨大": "「な」の前に置く語幹。「膨大なアクセス」と名詞を修飾し、アクセスの多さを表す。", "膨大で": "述語や連用の形。「膨大でなアクセス」とは名詞に続かず不自然。", "膨大さ": "名詞化した形。「膨大さなアクセス」とは続かず、「の」などを挟む必要があるため不自然。", "膨大化": "「化」を付けた名詞。「膨大化なアクセス」とは名詞修飾の形にならず、この文脈では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44825a8d-c4d0-466b-8571-68d71a7bdd62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
