INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39124, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "川や湖からとれる、塩けのない水のこと。", "primary_collocate": null, "pronunciation": "たんすい", "ipa": "taɴsɯi", "syllable_count": 4, "sentences": [{"text": "この湖の水は淡水なので、塩の味がしません。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "この湖[みずうみ]の水[みず]は淡水[たんすい]なので、塩[しお]の味[あじ]がしません。", "sentence_source": "generated"}, {"text": "川でとれる魚は、淡水で育ったものが多いです。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "川[かわ]でとれる魚[さかな]は、淡水[たんすい]で育[そだ]ったものが多[おお]いです。", "sentence_source": "generated"}, {"text": "海の水と違って、川の水は淡水です。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "海[うみ]の水[みず]と違[ちが]って、川[かわ]の水[みず]は淡水[たんすい]です。", "sentence_source": "generated"}, {"text": "淡水の湖には、コイやフナがすんでいます。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "淡水[たんすい]の湖[みずうみ]には、コイやフナがすんでいます。", "sentence_source": "generated"}, {"text": "海に流れこむ前の川の水は、淡水です。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "海[うみ]に流[なが]れこむ前[まえ]の川[かわ]の水[みず]は、淡水[たんすい]です。", "sentence_source": "generated"}, {"text": "湖で泳いだあと、淡水だったので目がしみませんでした。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "湖[みずうみ]で泳[およ]いだあと、淡水[たんすい]だったので目[め]がしみませんでした。", "sentence_source": "generated"}, {"text": "この池は淡水だから、海の魚は生きられません。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "この池[いけ]は淡水[たんすい]だから、海[うみ]の魚[さかな]は生[い]きられません。", "sentence_source": "generated"}, {"text": "淡水と海水がまざる川口には、めずらしい生き物がいます。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "淡水[たんすい]と海水[かいすい]がまざる川口[かわぐち]には、めずらしい生[い]き物[もの]がいます。", "sentence_source": "generated"}, {"text": "先生は「この水は淡水ですか、海水ですか」と聞きました。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "先生[せんせい]は「この水[みず]は淡水[たんすい]ですか、海水[かいすい]ですか」と聞[き]きました。", "sentence_source": "generated"}, {"text": "淡水にすむカメを、学校の池で見つけました。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "淡水[たんすい]にすむカメを、学校[がっこう]の池[いけ]で見[み]つけました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡水", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "塩分のない川や湖の水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T4: contains vocabulary far above tier T4: まざる (Zipf 1.26)']::text[], 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39124, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "塩分のない川や湖の水を指し、「塩の味がしません」と合う。"}, {"text": "海水", "is_correct": false, "explanation": "海の水は塩分が多いので、「塩の味がしません」と矛盾する。"}, {"text": "塩水", "is_correct": false, "explanation": "塩を含む水なので、塩の味がしないという文脈に合わない。"}, {"text": "食塩水", "is_correct": false, "explanation": "食塩を溶かした水で、塩の味がするという文脈と矛盾する。"}], "explanations": {"淡水": "塩分のない川や湖の水を指し、「塩の味がしません」と合う。", "海水": "海の水は塩分が多いので、「塩の味がしません」と矛盾する。", "塩水": "塩を含む水なので、塩の味がしないという文脈に合わない。", "食塩水": "食塩を溶かした水で、塩の味がするという文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは淡水のように薄味で、塩気が足りない。", "explanation": "ここは〈淡白な味〉の意味。淡水は水の種類を指す語で、料理の味の評価には使わない。"}, {"text": "彼は淡水のような人で、人間関係にこだわらない。", "explanation": "ここは〈さっぱりした人柄〉の意味。淡水は水の種類を指す語で、人の性格には使わない。"}, {"text": "この果物は淡水のように甘くて、子どもに人気だ。", "explanation": "ここは〈糖度が高い〉の意味。淡水は水の種類を指す語で、味の甘さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39124, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "塩分のない水なので、海の魚が生きられないという理由と合う。"}, {"text": "排水", "is_correct": false, "explanation": "排水は使い終わった水を流すことで、池の水の種類を表さず文に合わない。"}, {"text": "温水", "is_correct": false, "explanation": "温かい水のことで、塩分の違いを述べる文脈とは関係なく、海の魚が生きられない理由にならない。"}, {"text": "冷水", "is_correct": false, "explanation": "冷たい水のことで、水の温度を表すだけなので、海の魚が生きられない理由として合わない。"}], "explanations": {"淡水": "塩分のない水なので、海の魚が生きられないという理由と合う。", "排水": "排水は使い終わった水を流すことで、池の水の種類を表さず文に合わない。", "温水": "温かい水のことで、塩分の違いを述べる文脈とは関係なく、海の魚が生きられない理由にならない。", "冷水": "冷たい水のことで、水の温度を表すだけなので、海の魚が生きられない理由として合わない。"}, "sentence_index": 6, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は淡水の塩を使い、味がきりっと締まる。", "explanation": "ここは〈食塩〉の意味。淡水は水のことで、食塩そのものを指す語ではない。"}, {"text": "淡水は塩分が多いので、スープの味付けに向いている。", "explanation": "ここは〈海水〉の意味。淡水は塩分を含まない水で、海水のように塩分が多いものとは違う。"}, {"text": "海の波が岸に打ち寄せ、淡水のしぶきが砂浜を濡らす。", "explanation": "ここは〈海水〉の意味。淡水は海の水には使わず、海のしぶきを言うときは別の語になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39124, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "淡水を育つ魚は、海にもすんでいます。", "corrected_sentence": "淡水で育つ魚は、海にもすんでいます。", "error_description": "助詞の誤り。「育つ」は場所を表す「で」が必要で、「を」は目的語をとる他動詞に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39124, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "淡水を海水が混じると、塩分が増えます。", "corrected_sentence": "淡水に海水が混じると、塩分が増えます。", "error_description": "助詞の誤り。「混じる」は目的語をとらない自動詞なので、「を」は使えず「に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「淡水は」と話題を示し、後の「使われます」につながる正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「使われます」の受け身文では、目的語の「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「淡水に」では、使われる対象の関係が不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では、主題を示す文として意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「淡水は」と話題を示し、後の「使われます」につながる正しい助詞。", "を": "「使われます」の受け身文では、目的語の「を」は使えない。", "に": "「淡水に」では、使われる対象の関係が不自然になる。", "で": "手段の「で」では、主題を示す文として意味が通らない。"}, "error_tags": {"を": "目的語の誤り", "に": "対象の関係が不自然", "で": "手段を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「淡水を守る」と目的語を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「淡水が守る」では淡水が守る側になり、意味が逆になる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」では、守る対象が表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では、守る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「淡水を守る」と目的語を示す正しい助詞。", "が": "「淡水が守る」では淡水が守る側になり、意味が逆になる。", "と": "並列や相手を示す「と」では、守る対象が表せない。", "で": "手段の「で」では、守る対象を示せない。"}, "error_tags": {"が": "主語になり意味が逆", "と": "並列や相手を表す", "で": "手段を表す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "塩分を含まない、陸上の河川や湖沼などに存在する水。飲料水や農業・工業用水として利用される。", "primary_collocate": null, "pronunciation": "たんすい", "ipa": "taɴsɯi", "syllable_count": 4, "sentences": [{"text": "地球の水のうち、淡水はほんの少ししかありません。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の水[みず]のうち、淡水[たんすい]はほんの少[すこ]ししかありません。", "sentence_source": "generated"}, {"text": "淡水は、飲み水や畑の水として大切に使われます。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "淡水[たんすい]は、飲[の]み水[みず]や畑[はたけ]の水[みず]として大切[たいせつ]に使[つか]われます。", "sentence_source": "generated"}, {"text": "山にふった雪がとけて、貴重な淡水になります。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "山[やま]にふった雪[ゆき]がとけて、貴重[きちょう]な淡水[たんすい]になります。", "sentence_source": "generated"}, {"text": "工場では、機械を冷やすために大量の淡水を使います。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]を冷[ひ]やすために大量[たいりょう]の淡水[たんすい]を使[つか]います。", "sentence_source": "generated"}, {"text": "この島では淡水が足りないので、海の水から作っています。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "この島[しま]では淡水[たんすい]が足[た]りないので、海[うみ]の水[みず]から作[つく]っています。", "sentence_source": "generated"}, {"text": "川や湖の淡水は、農業にも欠かせません。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "川[かわ]や湖[みずうみ]の淡水[たんすい]は、農業[のうぎょう]にも欠[か]かせません。", "sentence_source": "generated"}, {"text": "雨が少ない年は、使える淡水が減って困ります。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない年[とし]は、使[つか]える淡水[たんすい]が減[へ]って困[こま]ります。", "sentence_source": "generated"}, {"text": "淡水を守るために、川によごれた水を流してはいけません。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "淡水[たんすい]を守[まも]るために、川[かわ]によごれた水[みず]を流[なが]してはいけません。", "sentence_source": "generated"}, {"text": "乾燥した国では、淡水の確保が大きな問題です。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した国[くに]では、淡水[たんすい]の確保[かくほ]が大[おお]きな問題[もんだい]です。", "sentence_source": "generated"}, {"text": "船の中では、積んだ淡水を大切に使います。", "target_word": "淡水", "complexity_tier": "T3", "furigana": "船[ふね]の中[なか]では、積[つ]んだ淡水[たんすい]を大切[たいせつ]に使[つか]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "淡水", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が利用する資源としての塩分のない水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "地球の水のうち陸の淡水は少ないという文脈に合う。"}, {"text": "海水", "is_correct": false, "explanation": "地球の水の大部分は海水なので、「ほんの少し」と矛盾する。"}, {"text": "塩水", "is_correct": false, "explanation": "塩水は量が多く、「ほんの少ししか」の文脈と合わない。"}, {"text": "重油", "is_correct": false, "explanation": "水ではなく油なので、「地球の水のうち」の文脈に合わない。"}], "explanations": {"淡水": "地球の水のうち陸の淡水は少ないという文脈に合う。", "海水": "地球の水の大部分は海水なので、「ほんの少し」と矛盾する。", "塩水": "塩水は量が多く、「ほんの少ししか」の文脈と合わない。", "重油": "水ではなく油なので、「地球の水のうち」の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、機械を冷やすために大量の淡水の油を使います。", "explanation": "ここは〈潤滑剤〉の意味。淡水は水を指す語で、潤滑剤の種類を表す語としては使わない。"}, {"text": "淡水は塩分が多いので、工場の機械を冷やすのに向かない。", "explanation": "ここは〈海水〉の意味。淡水は塩分を含まない水で、海水のように塩分が多いとは言えない。"}, {"text": "夏の夜、淡水のように熱帯夜が続き、眠れない人が増えた。", "explanation": "ここは〈暑い〉の意味。淡水は水の種類を指す語で、気温の高さを表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淡水", "is_correct": true, "explanation": "使える水が減って困るという文脈に合う資源の語。"}, {"text": "燃料", "is_correct": false, "explanation": "雨の少なさと直接関係せず、使える水の減少という文脈に合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合で、使える水が減る話に合わない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は使える水の量とは関係なく、文脈に合わない。"}], "explanations": {"淡水": "使える水が減って困るという文脈に合う資源の語。", "燃料": "雨の少なさと直接関係せず、使える水の減少という文脈に合わない。", "湿度": "空気の湿り具合で、使える水が減る話に合わない。", "気温": "気温は使える水の量とは関係なく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "淡水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船の中では、積んだ淡水の塩を抜くために煮詰めています。", "explanation": "ここは〈海水〉の意味。淡水は塩分を含まない水で、塩を抜く対象の水としては使わない。"}, {"text": "淡水の味が濃いので、船では料理に使えません。", "explanation": "ここは〈塩水〉の意味。淡水は塩分を含まない水で、塩水のように味が濃いとは言えない。"}, {"text": "船の中では、淡水の波を大切に見張っています。", "explanation": "ここは〈海の波〉の意味。淡水は水の種類を指し、波の状態を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "淡水が流れこむと、海水を薄まります。", "corrected_sentence": "淡水が流れこむと、海水が薄まります。", "error_description": "助詞の誤り。「薄まる」は自動詞なので目的語の「を」は使えず、主語の「が」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39125, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海辺の町では、淡水を確保が難しいです。", "corrected_sentence": "海辺の町では、淡水の確保が難しいです。", "error_description": "助詞の誤り。「確保」を修飾するには「の」が必要で、「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "人の手が加わったものという意味で、「天然」の対義語として辞書に並ぶ。"}, {"text": "書籍", "is_correct": false, "explanation": "本の意味で、「天然」の対義語関係にはない。"}, {"text": "都市", "is_correct": false, "explanation": "人が暮らす場所の意味で、自然のままの状態の対義語ではない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品の名前で、「天然」の対義語関係にはない。"}], "correct_answer": "人工", "explanations": {"人工": "人の手が加わったものという意味で、「天然」の対義語として辞書に並ぶ。", "書籍": "本の意味で、「天然」の対義語関係にはない。", "都市": "人が暮らす場所の意味で、自然のままの状態の対義語ではない。", "砂糖": "食品の名前で、「天然」の対義語関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人工", "is_correct": true, "explanation": "人の手が加わったものという意味で、「天然」の対義語として辞書に並ぶ。"}, {"text": "食材", "is_correct": false, "explanation": "料理に使う材料の意味で、「天然」の対義語関係にはない。"}, {"text": "鉱物", "is_correct": false, "explanation": "自然界にできる物質の名で、対義語関係にはない。"}, {"text": "装置", "is_correct": false, "explanation": "機械や仕組みの意味で、「天然」の対義語ではない。"}], "correct_answer": "人工", "explanations": {"人工": "人の手が加わったものという意味で、「天然」の対義語として辞書に並ぶ。", "食材": "料理に使う材料の意味で、「天然」の対義語関係にはない。", "鉱物": "自然界にできる物質の名で、対義語関係にはない。", "装置": "機械や仕組みの意味で、「天然」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "人が手を加えていない、自然のままのようす。", "primary_collocate": null, "pronunciation": "てんねん", "ipa": "teɴneɴ", "syllable_count": 4, "sentences": [{"text": "この真珠は養殖ではなく、天然のものです。", "target_word": "天然", "complexity_tier": "T3", "furigana": "この真珠[しんじゅ]は養殖[ようしょく]ではなく、天然[てんねん]のものです。", "sentence_source": "generated"}, {"text": "天然のままの森が、この山には残っています。", "target_word": "天然", "complexity_tier": "T3", "furigana": "天然[てんねん]のままの森[もり]が、この山[やま]には残[のこ]っています。", "sentence_source": "generated"}, {"text": "天然の温泉に入って、体が温まりました。", "target_word": "天然", "complexity_tier": "T3", "furigana": "天然[てんねん]の温泉[おんせん]に入[はい]って、体[からだ]が温[あたた]まりました。", "sentence_source": "generated"}, {"text": "この色は人工ではなく、天然の色です。", "target_word": "天然", "complexity_tier": "T3", "furigana": "この色[いろ]は人工[じんこう]ではなく、天然[てんねん]の色[いろ]です。", "sentence_source": "generated"}, {"text": "このあたりでは、天然の岩がそのまま橋になっています。", "target_word": "天然", "complexity_tier": "T3", "furigana": "このあたりでは、天然[てんねん]の岩[いわ]がそのまま橋[はし]になっています。", "sentence_source": "generated"}, {"text": "祖母は、天然の素材だけで服を作ります。", "target_word": "天然", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、天然[てんねん]の素材[そざい]だけで服[ふく]を作[つく]ります。", "sentence_source": "generated"}, {"text": "この湖は人が作ったのではなく、天然のものです。", "target_word": "天然", "complexity_tier": "T3", "furigana": "この湖[みずうみ]は人[ひと]が作[つく]ったのではなく、天然[てんねん]のものです。", "sentence_source": "generated"}, {"text": "天然のうなぎは数が少なく、値段が高いです。", "target_word": "天然", "complexity_tier": "T3", "furigana": "天然[てんねん]のうなぎは数[かず]が少[すく]なく、値段[ねだん]が高[たか]いです。", "sentence_source": "generated"}, {"text": "天然のほら穴の中は、ひんやりしていました。", "target_word": "天然", "complexity_tier": "T3", "furigana": "天然[てんねん]のほら穴[あな]の中[なか]は、ひんやりしていました。", "sentence_source": "generated"}, {"text": "養殖の魚より、天然の魚のほうが味が濃いと言われます。", "target_word": "天然", "complexity_tier": "T3", "furigana": "養殖[ようしょく]の魚[さかな]より、天然[てんねん]の魚[さかな]のほうが味[あじ]が濃[こ]いと言[い]われます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人工ではなく自然のままであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: ほら穴 (Zipf 1.98)']::text[], 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天然", "is_correct": true, "explanation": "人が手を加えていない自然のものという意味で、文に合う。"}, {"text": "加工", "is_correct": false, "explanation": "人が手を加えた状態を指すので、「養殖ではなく」の対比に合わない。"}, {"text": "手作り", "is_correct": false, "explanation": "人が手で作ったものを指し、真珠の由来を述べる文脈に合わない。"}, {"text": "機械", "is_correct": false, "explanation": "機械で作られたものという意味で、「のもの」の形と文脈が合わない。"}], "explanations": {"天然": "人が手を加えていない自然のものという意味で、文に合う。", "加工": "人が手を加えた状態を指すので、「養殖ではなく」の対比に合わない。", "手作り": "人が手で作ったものを指し、真珠の由来を述べる文脈に合わない。", "機械": "機械で作られたものという意味で、「のもの」の形と文脈が合わない。"}, "sentence_index": 0, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この色は天然に作られた人工物で、自然とは関係がない。", "explanation": "ここは〈天然素材〉の意味。天然は人が手を加えていない状態を表し、人が作った製品には使わない。"}, {"text": "この魚は天然で、養殖場で一年間育てられた。", "explanation": "ここは〈畜養〉の意味。天然は自然の中で生まれ育ったものを指し、人が育てた魚には使わない。"}, {"text": "この村では天然の機械を使い、今でも古いやり方が続いている。", "explanation": "ここは〈原始的〉の意味。天然は人が手を加えていない状態を表す語で、古い技術を言う語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天然", "is_correct": true, "explanation": "人が作ったのではないという文に対応し、自然のままの意味で合う。"}, {"text": "工業", "is_correct": false, "explanation": "工場で作られる意味で、人が作ったものではないという文と合わない。"}, {"text": "石油", "is_correct": false, "explanation": "地下資源の名前で、湖を修飾する形としてつながらない。"}, {"text": "放射", "is_correct": false, "explanation": "光や熱が広がる意味で、湖の成り立ちを表す語としてずれる。"}], "explanations": {"天然": "人が作ったのではないという文に対応し、自然のままの意味で合う。", "工業": "工場で作られる意味で、人が作ったものではないという文と合わない。", "石油": "地下資源の名前で、湖を修飾する形としてつながらない。", "放射": "光や熱が広がる意味で、湖の成り立ちを表す語としてずれる。"}, "sentence_index": 6, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この切手は天然で、世界に三枚しかない。", "explanation": "ここは〈希少〉の意味。天然は自然のままの状態を表す語で、数が少ないことは表さない。"}, {"text": "この天然の油は、機械を動かすために化学で作られている。", "explanation": "ここは〈合成油〉の意味。天然は自然から得たものを指し、化学で合成した油には使わない。"}, {"text": "この湖は天然だが、人が掘って作ったものだ。", "explanation": "ここは〈人造湖〉の意味。天然は自然にできた湖を指し、人が掘って作った湖には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天然へ温泉に入ると、疲れがとれます。", "corrected_sentence": "天然の温泉に入ると、疲れがとれます。", "error_description": "助詞の誤り。「天然」が「温泉」を修飾するには「の」が必要で、「へ」は方向を表すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39126, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天然へ魚は、養殖より育つ時間が長いです。", "corrected_sentence": "天然の魚は、養殖より育つ時間が長いです。", "error_description": "助詞の誤り。「天然」が「魚」を修飾するには「の」が必要で、「へ」は方向を表すため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39132, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "取り出す対象の「部分」を示す「を」が合います。"}, {"text": "の", "is_correct": false, "explanation": "「必要な部分の抽出している」は文として成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「部分が抽出している」では部分が取り出す側になり、成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「部分と抽出している」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "取り出す対象の「部分」を示す「を」が合います。", "の": "「必要な部分の抽出している」は文として成り立ちません。", "が": "「部分が抽出している」では部分が取り出す側になり、成り立ちません。", "と": "「部分と抽出している」は文として成り立ちません。"}, "error_tags": {"の": "ungrammatical", "が": "object_vs_subject", "と": "ungrammatical"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39132, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「抽出に失敗する」で、失敗する事柄を示す「に」が合います。"}, {"text": "の", "is_correct": false, "explanation": "「抽出の失敗したら」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「抽出と失敗したら」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「抽出へ失敗したら」は文として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "「抽出に失敗する」で、失敗する事柄を示す「に」が合います。", "の": "「抽出の失敗したら」は文として成り立ちません。", "と": "「抽出と失敗したら」は文として成り立ちません。", "へ": "「抽出へ失敗したら」は文として成り立ちません。"}, "error_tags": {"の": "ungrammatical", "と": "ungrammatical", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39132, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "多くのものの中から、条件に合うものや必要なものを選んで取り出すこと（情報・データなど）。", "primary_collocate": null, "pronunciation": "ちゅうしゅつ", "ipa": "tɕɯːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "情報を抽出する。", "target_word": "抽出", "complexity_tier": "T1", "furigana": "情報[じょうほう]を抽出[ちゅうしゅつ]する。", "sentence_source": "generated"}, {"text": "データを抽出します。", "target_word": "抽出", "complexity_tier": "T2", "furigana": "データを抽出[ちゅうしゅつ]します。", "sentence_source": "generated"}, {"text": "抽出はもう終わりました。", "target_word": "抽出", "complexity_tier": "T2", "furigana": "抽出[ちゅうしゅつ]はもう終[お]わりました。", "sentence_source": "generated"}, {"text": "ファイルから必要な部分を抽出している。", "target_word": "抽出", "complexity_tier": "T3", "furigana": "ファイルから必要[ひつよう]な部分[ぶぶん]を抽出[ちゅうしゅつ]している。", "sentence_source": "generated"}, {"text": "顧客リストから東京に住む人だけを抽出できる。", "target_word": "抽出", "complexity_tier": "T3", "furigana": "顧客[こきゃく]リストから東京[とうきょう]に住[す]む人[ひと]だけを抽出[ちゅうしゅつ]できる。", "sentence_source": "generated"}, {"text": "抽出の手順をノートに書いておく。", "target_word": "抽出", "complexity_tier": "T3", "furigana": "抽出[ちゅうしゅつ]の手順[てじゅん]をノートに書[か]いておく。", "sentence_source": "generated"}, {"text": "名簿から条件に合う人が抽出された。", "target_word": "抽出", "complexity_tier": "T4", "furigana": "名簿[めいぼ]から条件[じょうけん]に合[あ]う人[ひと]が抽出[ちゅうしゅつ]された。", "sentence_source": "generated"}, {"text": "もし抽出に失敗したら、もう一度やり直してください。", "target_word": "抽出", "complexity_tier": "T4", "furigana": "もし抽出[ちゅうしゅつ]に失敗[しっぱい]したら、もう一度[いちど]やり直[なお]してください。", "sentence_source": "generated"}, {"text": "アンケートの結果から、回答の傾向を抽出する作業を担当している。", "target_word": "抽出", "complexity_tier": "T5", "furigana": "アンケートの結果[けっか]から、回答[かいとう]の傾向[けいこう]を抽出[ちゅうしゅつ]する作業[さぎょう]を担当[たんとう]している。", "sentence_source": "generated"}, {"text": "大量の文章の中から特定の単語だけを抽出するには、専用のソフトが便利だ。", "target_word": "抽出", "complexity_tier": "T5", "furigana": "大量[たいりょう]の文章[ぶんしょう]の中[なか]から特定[とくてい]の単語[たんご]だけを抽出[ちゅうしゅつ]するには、専用[せんよう]のソフトが便利[べんり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽出する", "label": "活用"}, {"form": "抽出される", "label": "活用"}, {"form": "抽出物", "label": "派生"}, {"form": "抽出液", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | データ・情報・名簿から条件に合うものを選び出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39132, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽出", "is_correct": true, "explanation": "「情報を抽出する」で、必要なものを取り出す意味が合います。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。情報を卒業することはできません。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが意味が合わない。情報を結婚することはできません。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。情報を散歩することはできません。"}], "explanations": {"抽出": "「情報を抽出する」で、必要なものを取り出す意味が合います。", "卒業": "形は合うが意味が合わない。情報を卒業することはできません。", "結婚": "形は合うが意味が合わない。情報を結婚することはできません。", "散歩": "形は合うが意味が合わない。情報を散歩することはできません。"}, "sentence_index": 0, "correct_answer": "抽出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の電気を抽出している。", "explanation": "「抽出」を「消す」の意味で誤用しています。"}, {"text": "先生にファイルを抽出している。", "explanation": "「抽出」を「提出」の意味で誤用しています。"}, {"text": "彼は大学を抽出して、会社に入った。", "explanation": "「抽出」を「卒業」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39132, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽出", "is_correct": true, "explanation": "「名簿から…人が抽出された」で、選んで取り出す意味が合います。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが意味が合わない。名簿から到着されることはありません。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが意味が合わない。名簿から散歩されることはありません。"}, {"text": "乾杯", "is_correct": false, "explanation": "形は合うが意味が合わない。名簿から乾杯されることはありません。"}], "explanations": {"抽出": "「名簿から…人が抽出された」で、選んで取り出す意味が合います。", "到着": "形は合うが意味が合わない。名簿から到着されることはありません。", "散歩": "形は合うが意味が合わない。名簿から散歩されることはありません。", "乾杯": "形は合うが意味が合わない。名簿から乾杯されることはありません。"}, "sentence_index": 6, "correct_answer": "抽出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風が強くて、帽子が頭から抽出した。", "explanation": "「抽出」を「飛んだ」の意味で誤用しています。"}, {"text": "駅で電車が抽出するのを待った。", "explanation": "「抽出」を「出発」の意味で誤用しています。"}, {"text": "友達にお土産を抽出するために、箱を買った。", "explanation": "「抽出」を「渡す」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
