INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注入", "is_correct": true, "explanation": "外に取り出すの反対で、中へ入れるという意味です。"}, {"text": "分離", "is_correct": false, "explanation": "成分を分け離す意味で、反対語ではありません。"}, {"text": "採取", "is_correct": false, "explanation": "必要なものを取る意味で、反対語ではありません。"}, {"text": "精製", "is_correct": false, "explanation": "不純物を除く意味で、反対語ではありません。"}], "correct_answer": "注入", "explanations": {"注入": "外に取り出すの反対で、中へ入れるという意味です。", "分離": "成分を分け離す意味で、反対語ではありません。", "採取": "必要なものを取る意味で、反対語ではありません。", "精製": "不純物を除く意味で、反対語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「抽出」を主語として示す「が」が合います。"}, {"text": "を", "is_correct": false, "explanation": "「抽出をうまくいかない」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「抽出にうまくいかない」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「抽出とうまくいかない」は文として成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「抽出」を主語として示す「が」が合います。", "を": "「抽出をうまくいかない」は文として成り立ちません。", "に": "「抽出にうまくいかない」は文として成り立ちません。", "と": "「抽出とうまくいかない」は文として成り立ちません。"}, "error_tags": {"を": "object_vs_subject", "に": "ungrammatical", "と": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注入", "is_correct": true, "explanation": "取り出すの反対で、中へ入れるという意味です。"}, {"text": "抜粋", "is_correct": false, "explanation": "必要な部分を取り出す意味で、類義語です。"}, {"text": "摘出", "is_correct": false, "explanation": "中から取り出す意味で、類義語です。"}, {"text": "採取", "is_correct": false, "explanation": "必要なものを取る意味で、反対語ではありません。"}], "correct_answer": "注入", "explanations": {"注入": "取り出すの反対で、中へ入れるという意味です。", "抜粋": "必要な部分を取り出す意味で、類義語です。", "摘出": "中から取り出す意味で、類義語です。", "採取": "必要なものを取る意味で、反対語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものの中から、必要な部分だけを取り出すこと。特に、液体や成分を汲み出したり、分離したりすること。", "primary_collocate": null, "pronunciation": "ちゅうしゅつ", "ipa": "tɕɯːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "抽出", "complexity_tier": "T6", "furigana": "しかし、抽出[ちゅうしゅつ]された液[えき]は未[いま]だ不安定[ふあんてい]な色彩[しきさい]に過[す]ぎず、そのままでは時間[じかん]と共[とも]に退色[たいしょく]してしまう。", "sentence_source": "mined"}, {"text": "色を抽出する。", "target_word": "抽出", "complexity_tier": "T1", "furigana": "色[いろ]を抽出[ちゅうしゅつ]する。", "sentence_source": "generated"}, {"text": "植物から色を抽出します。", "target_word": "抽出", "complexity_tier": "T2", "furigana": "植物[しょくぶつ]から色[いろ]を抽出[ちゅうしゅつ]します。", "sentence_source": "generated"}, {"text": "この抽出は時間がかかります。", "target_word": "抽出", "complexity_tier": "T2", "furigana": "この抽出[ちゅうしゅつ]は時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "お湯で茶葉の成分を抽出している。", "target_word": "抽出", "complexity_tier": "T3", "furigana": "お湯[ゆ]で茶葉[ちゃば]の成分[せいぶん]を抽出[ちゅうしゅつ]している。", "sentence_source": "generated"}, {"text": "抽出した液を冷やしてから使います。", "target_word": "抽出", "complexity_tier": "T3", "furigana": "抽出[ちゅうしゅつ]した液[えき]を冷[ひ]やしてから使[つか]います。", "sentence_source": "generated"}, {"text": "この色素は藍の葉から抽出されたものだ。", "target_word": "抽出", "complexity_tier": "T4", "furigana": "この色素[しきそ]は藍[あい]の葉[は]から抽出[ちゅうしゅつ]されたものだ。", "sentence_source": "generated"}, {"text": "温度が高すぎると、抽出がうまくいかない。", "target_word": "抽出", "complexity_tier": "T4", "furigana": "温度[おんど]が高[たか]すぎると、抽出[ちゅうしゅつ]がうまくいかない。", "sentence_source": "generated"}, {"text": "抽出の方法によって、染め上がりの色合いは大きく変わる。", "target_word": "抽出", "complexity_tier": "T4", "furigana": "抽出[ちゅうしゅつ]の方法[ほうほう]によって、染[そ]め上[あ]がりの色合[いろあ]いは大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "染料の抽出を終えたら、液をろ過して不純物を取り除く必要がある。", "target_word": "抽出", "complexity_tier": "T5", "furigana": "染料[せんりょう]の抽出[ちゅうしゅつ]を終[お]えたら、液[えき]をろ過[かこ]して不純物[ふじゅんぶつ]を取[と]り除[のぞ]く必要[ひつよう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽出する", "label": "活用"}, {"form": "抽出される", "label": "活用"}, {"form": "抽出液", "label": "派生"}, {"form": "抽出物", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 全体から成分や部分を取り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽出", "is_correct": true, "explanation": "「抽出された液」で、成分を取り出した液という意味が合います。"}, {"text": "解散", "is_correct": false, "explanation": "形は合うが意味が合わない。液が解散されることはありません。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが意味が合わない。液が卒業されることはありません。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが意味が合わない。液が出発されることはありません。"}], "explanations": {"抽出": "「抽出された液」で、成分を取り出した液という意味が合います。", "解散": "形は合うが意味が合わない。液が解散されることはありません。", "卒業": "形は合うが意味が合わない。液が卒業されることはありません。", "出発": "形は合うが意味が合わない。液が出発されることはありません。"}, "sentence_index": 0, "correct_answer": "抽出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、学校へ抽出している。", "explanation": "「抽出」を「出発」の意味で誤用しており、成分を取り出す意味ではありません。"}, {"text": "友達に手紙を抽出した。", "explanation": "「抽出」を「手紙を出す」の意味で誤用しています。"}, {"text": "風邪をひいたので、会社を抽出した。", "explanation": "「抽出」を「休む」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽出", "is_correct": true, "explanation": "「藍の葉から抽出された」で、成分を取り出した意味が合います。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが意味が合わない。色素が葉から到着することはありません。"}, {"text": "就職", "is_correct": false, "explanation": "形は合うが意味が合わない。色素が就職されることはありません。"}, {"text": "優勝", "is_correct": false, "explanation": "形は合うが意味が合わない。色素が優勝されることはありません。"}], "explanations": {"抽出": "「藍の葉から抽出された」で、成分を取り出した意味が合います。", "到着": "形は合うが意味が合わない。色素が葉から到着することはありません。", "就職": "形は合うが意味が合わない。色素が就職されることはありません。", "優勝": "形は合うが意味が合わない。色素が優勝されることはありません。"}, "sentence_index": 6, "correct_answer": "抽出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵を壁に抽出して飾った。", "explanation": "「抽出」を「掛ける」の意味で誤用しています。"}, {"text": "お客さんを玄関まで抽出した。", "explanation": "「抽出」を「見送る」の意味で誤用しています。"}, {"text": "熱があって授業を抽出した。", "explanation": "「抽出」を「休む」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
