INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ハーブから精油が抽出している。", "corrected_sentence": "ハーブから精油が抽出されている。", "error_description": "精油は取り出される側なので、「抽出している」ではなく受身の「抽出されている」にします。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「常態になって」と変化の結果を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「常態を」では、なる対象を目的語として示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」では、変化の結果が表せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では、「常態」と「なって」をつなげられない。"}], "correct_answer": "に", "explanations": {"に": "「常態になって」と変化の結果を示す正しい助詞。", "を": "「常態を」では、なる対象を目的語として示せず不自然。", "で": "場所や手段の「で」では、変化の結果が表せない。", "の": "連体の「の」では、「常態」と「なって」をつなげられない。"}, "error_tags": {"を": "目的語の誤り", "で": "場所や手段を表す", "の": "連体修飾になる"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "異常", "is_correct": true, "explanation": "通常の状態と外れたという意味で、「常態」の対義語として辞書に並ぶ。"}, {"text": "夕食", "is_correct": false, "explanation": "食事の時間を表す語で、「常態」の対義語関係にはない。"}, {"text": "残業", "is_correct": false, "explanation": "仕事の時間外の作業を表す語で、対義語関係にはない。"}, {"text": "工事", "is_correct": false, "explanation": "建設の作業を表す語で、「常態」の対義語ではない。"}], "correct_answer": "異常", "explanations": {"異常": "通常の状態と外れたという意味で、「常態」の対義語として辞書に並ぶ。", "夕食": "食事の時間を表す語で、「常態」の対義語関係にはない。", "残業": "仕事の時間外の作業を表す語で、対義語関係にはない。", "工事": "建設の作業を表す語で、「常態」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
