INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ずっと変わらないようすになること。", "primary_collocate": null, "pronunciation": "じょうたい", "ipa": "dʑoːtai", "syllable_count": 4, "sentences": [{"text": "残業が常態となり、家族と夕食をとる時間がなくなった。", "target_word": "常態", "complexity_tier": "T3", "furigana": "残業[ざんぎょう]が常態[じょうたい]となり、家族[かぞく]と夕食[ゆうしょく]をとる時間[じかん]がなくなった。", "sentence_source": "generated"}, {"text": "工事の音が常態になって、近所の人も気にしなくなった。", "target_word": "常態", "complexity_tier": "T3", "furigana": "工事[こうじ]の音[おと]が常態[じょうたい]になって、近所[きんじょ]の人[ひと]も気[き]にしなくなった。", "sentence_source": "generated"}, {"text": "人手不足が常態となった店では、休みも取りにくい。", "target_word": "常態", "complexity_tier": "T3", "furigana": "人手不足[ひとでぶそく]が常態[じょうたい]となった店[みせ]では、休[やす]みも取[と]りにくい。", "sentence_source": "generated"}, {"text": "赤字が常態になると、会社は新しい手を打てなくなる。", "target_word": "常態", "complexity_tier": "T3", "furigana": "赤字[あかじ]が常態[じょうたい]になると、会社[かいしゃ]は新[あたら]しい手[て]を打[う]てなくなる。", "sentence_source": "generated"}, {"text": "長い間の混雑が常態となり、駅の周りは落ち着かない。", "target_word": "常態", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]の混雑[こんざつ]が常態[じょうたい]となり、駅[えき]の周[まわ]りは落[お]ち着[つ]かない。", "sentence_source": "generated"}, {"text": "大雨のたびに道が水につかるのが常態になってしまった。", "target_word": "常態", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のたびに道[みち]が水[みず]につかるのが常態[じょうたい]になってしまった。", "sentence_source": "generated"}, {"text": "雨が降らない日が続き、水不足が常態となりました。", "target_word": "常態", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らない日[ひ]が続[つづ]き、水不足[みずぶそく]が常態[じょうたい]となりました。", "sentence_source": "generated"}, {"text": "夜遅くまで起きているのが常態になって、朝起きられない。", "target_word": "常態", "complexity_tier": "T3", "furigana": "夜[よる]遅[おそ]くまで起[お]きているのが常態[じょうたい]になって、朝[あさ]起[お]きられない。", "sentence_source": "generated"}, {"text": "値上げが常態となり、買い物のたびにため息が出る。", "target_word": "常態", "complexity_tier": "T3", "furigana": "値上[ねあ]げが常態[じょうたい]となり、買[か]い物[もの]のたびにため息[いき]が出[で]る。", "sentence_source": "generated"}, {"text": "見張りがいるのが常態となって、町の人はそれに慣れた。", "target_word": "常態", "complexity_tier": "T3", "furigana": "見張[みは]りがいるのが常態[じょうたい]となって、町[まち]の人[ひと]はそれに慣[な]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "常態", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある状態がいつものこととして定着すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常態", "is_correct": true, "explanation": "ずっと続く状態になるという意味で、残業が続く文に合う。"}, {"text": "休暇", "is_correct": false, "explanation": "休みの期間の意味で、残業が「となり」続く文と矛盾する。"}, {"text": "給料", "is_correct": false, "explanation": "賃金の意味で、残業が「となり」状態を表す文に合わない。"}, {"text": "一時", "is_correct": false, "explanation": "少しの間の意味で、「なり、時間がなくなった」の継続の文脈と合わない。"}], "explanations": {"常態": "ずっと続く状態になるという意味で、残業が続く文に合う。", "休暇": "休みの期間の意味で、残業が「となり」続く文と矛盾する。", "給料": "賃金の意味で、残業が「となり」状態を表す文に合わない。", "一時": "少しの間の意味で、「なり、時間がなくなった」の継続の文脈と合わない。"}, "sentence_index": 0, "correct_answer": "常態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤字が常態になったのは一時的で、すぐに黒字に戻った。", "explanation": "ここは〈例外〉の意味。常態はいつもの状態を表すので、たまに起きる例外的な出来事には使わない。"}, {"text": "赤字は常態の習慣なので、会社は慌てず対応できる。", "explanation": "ここは〈慣習〉の意味。常態は状態を表す語で、人の行いとしての慣習とは別の語になる。"}, {"text": "赤字が常態の決算で、会社はすぐに黒字にできた。", "explanation": "ここは〈業績〉の意味。常態は続くいつもの状態を指す語で、一度きりの業績の結果を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常態", "is_correct": true, "explanation": "雨が降らない状態が続いて水不足がいつものことになった、という文に合う。"}, {"text": "報告", "is_correct": false, "explanation": "伝える行為の意味で、水不足が続く状態を表す語にならない。"}, {"text": "計画", "is_correct": false, "explanation": "前もって決めた予定の意味で、状態の変化の文脈と合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "出かける行為の意味で、水不足の文脈と関係がない。"}], "explanations": {"常態": "雨が降らない状態が続いて水不足がいつものことになった、という文に合う。", "報告": "伝える行為の意味で、水不足が続く状態を表す語にならない。", "計画": "前もって決めた予定の意味で、状態の変化の文脈と合わない。", "旅行": "出かける行為の意味で、水不足の文脈と関係がない。"}, "sentence_index": 6, "correct_answer": "常態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一度だけ雨が降ったのが常態となって、町は大騒ぎした。", "explanation": "ここは〈異変〉の意味。常態は続く状態を表すので、一度きりの異常な出来事を指す語ではない。"}, {"text": "新しい規則が常態として、ひと月で廃止された。", "explanation": "ここは〈法令〉の意味。常態は状態を表す語で、制定された決まりそのものを指す語ではない。"}, {"text": "一晩だけの徹夜が常態になって、ふだんは寝ている。", "explanation": "ここは〈臨時〉の意味。常態は続く状態で、たまに起こる臨時の事態を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "残業が常態でなって、夜の家事もできなくなった。", "corrected_sentence": "残業が常態となって、夜の家事もできなくなった。", "error_description": "助詞の誤り。「常態となる」は「と」で結ぶ形で、「で」では「なって」と続かず文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39134, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜ふかしが常態にって、朝起きられない日が続く。", "corrected_sentence": "夜ふかしが常態になって、朝起きられない日が続く。", "error_description": "活用の誤り。「なる」の「な」が抜けている。正しくは「になって」で、「にって」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「常態とする」で、常態を〜と見なすという判断の対象を示す。文の意味に合う"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す「で」。「常態でする」では動詞との関係が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「常態へする」は意味が通らない"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「常態からする」は判断の対象を示せない"}], "correct_answer": "と", "explanations": {"と": "「常態とする」で、常態を〜と見なすという判断の対象を示す。文の意味に合う", "で": "場所・手段を示す「で」。「常態でする」では動詞との関係が成り立たない", "へ": "方向を示す「へ」。「常態へする」は意味が通らない", "から": "起点を示す「から」。「常態からする」は判断の対象を示せない"}, "error_tags": {"と": "判断・見なしの対象", "で": "場所・手段", "へ": "方向", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "異常", "is_correct": true, "explanation": "普通の状態から外れているという意味で、「常態」の対義語として辞書に並ぶ。"}, {"text": "夕食", "is_correct": false, "explanation": "食事の時間を表す語で、「常態」の対義語関係にはない。"}, {"text": "工事", "is_correct": false, "explanation": "建設の作業を表す語で、「常態」の対義語関係にはない。"}, {"text": "残業", "is_correct": false, "explanation": "仕事の時間外の作業を表す語で、「常態」の対義語関係にはない。"}], "correct_answer": "異常", "explanations": {"異常": "普通の状態から外れているという意味で、「常態」の対義語として辞書に並ぶ。", "夕食": "食事の時間を表す語で、「常態」の対義語関係にはない。", "工事": "建設の作業を表す語で、「常態」の対義語関係にはない。", "残業": "仕事の時間外の作業を表す語で、「常態」の対義語関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「常態のこの土地」で、常態を後ろの名詞「土地」に結びつける連体修飾の格助詞。文の意味に合う"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「常態がこの土地で」となり、修飾関係が崩れる"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「常態をこの土地」では名詞同士がつながらない"}, {"text": "に", "is_correct": false, "explanation": "帰着・位置を示す「に」。「常態にこの土地」は名詞を修飾できない"}], "correct_answer": "の", "explanations": {"の": "「常態のこの土地」で、常態を後ろの名詞「土地」に結びつける連体修飾の格助詞。文の意味に合う", "が": "主格の「が」。「常態がこの土地で」となり、修飾関係が崩れる", "を": "目的語の「を」。「常態をこの土地」では名詞同士がつながらない", "に": "帰着・位置を示す「に」。「常態にこの土地」は名詞を修飾できない"}, "error_tags": {"の": "連体修飾", "が": "主語", "を": "目的語", "に": "場所・帰着"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "異常", "is_correct": true, "explanation": "普通の状態から外れているという意味で、「常態」の対義語として辞書に並ぶ。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かすことの意味で、「常態」の対義語関係にはない。"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場の意味で、「常態」の対義語関係にはない。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くことの意味で、「常態」の対義語関係にはない。"}], "correct_answer": "異常", "explanations": {"異常": "普通の状態から外れているという意味で、「常態」の対義語として辞書に並ぶ。", "運動": "体を動かすことの意味で、「常態」の対義語関係にはない。", "会議": "話し合いの場の意味で、「常態」の対義語関係にはない。", "散歩": "気晴らしに歩くことの意味で、「常態」の対義語関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある状態が普通のこととして続くこと。", "primary_collocate": null, "pronunciation": "じょうたい", "ipa": "dʑoːtai", "syllable_count": 4, "sentences": [{"text": "この地域では、停電が常態として続いている。", "target_word": "常態", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、停電[ていでん]が常態[じょうたい]として続[つづ]いている。", "sentence_source": "generated"}, {"text": "長時間労働を常態とする職場は、見直すべきだ。", "target_word": "常態", "complexity_tier": "T3", "furigana": "長時間労働[ちょうじかんろうどう]を常態[じょうたい]とする職場[しょくば]は、見直[みなお]すべきだ。", "sentence_source": "generated"}, {"text": "彼にとって、遅く寝ることは常態だ。", "target_word": "常態", "complexity_tier": "T3", "furigana": "彼[かれ]にとって、遅[おそ]く寝[ね]ることは常態[じょうたい]だ。", "sentence_source": "generated"}, {"text": "渋滞が常態の道路では、時間に余裕を持って出発する。", "target_word": "常態", "complexity_tier": "T3", "furigana": "渋滞[じゅうたい]が常態[じょうたい]の道路[どうろ]では、時間[じかん]に余裕[よゆう]を持[も]って出発[しゅっぱつ]する。", "sentence_source": "generated"}, {"text": "緊張が常態だった日々から、やっと解放された。", "target_word": "常態", "complexity_tier": "T3", "furigana": "緊張[きんちょう]が常態[じょうたい]だった日々[ひび]から、やっと解放[かいほう]された。", "sentence_source": "generated"}, {"text": "赤字を常態とする経営は、長くは続かない。", "target_word": "常態", "complexity_tier": "T3", "furigana": "赤字[あかじ]を常態[じょうたい]とする経営[けいえい]は、長[なが]くは続[つづ]かない。", "sentence_source": "generated"}, {"text": "人が足りない状態を常態とみなしてはいけない。", "target_word": "常態", "complexity_tier": "T3", "furigana": "人[ひと]が足[た]りない状態[じょうたい]を常態[じょうたい]とみなしてはいけない。", "sentence_source": "generated"}, {"text": "小さな地震が常態のこの土地で、人々は落ち着いて暮らしている。", "target_word": "常態", "complexity_tier": "T3", "furigana": "小[ちい]さな地震[じしん]が常態[じょうたい]のこの土地[とち]で、人々[ひとびと]は落[お]ち着[つ]いて暮[く]らしている。", "sentence_source": "generated"}, {"text": "騒音が常態である町では、静かな夜は貴重だ。", "target_word": "常態", "complexity_tier": "T3", "furigana": "騒音[そうおん]が常態[じょうたい]である町[まち]では、静[しず]かな夜[よる]は貴重[きちょう]だ。", "sentence_source": "generated"}, {"text": "物不足を常態として暮らす人々を、支える仕組みが必要だ。", "target_word": "常態", "complexity_tier": "T3", "furigana": "物不足[ものぶそく]を常態[じょうたい]として暮[く]らす人々[ひとびと]を、支[ささ]える仕組[しく]みが必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "常態", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特別ではなく普通のこととして続いている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常態", "is_correct": true, "explanation": "「続いている状態」を表す名詞で、「常態として続いている」の空所に合う"}, {"text": "中断", "is_correct": false, "explanation": "途中で止まることを表す。「中断として続いている」では意味が通らない"}, {"text": "復旧", "is_correct": false, "explanation": "元どおりに戻すことを表す。続いている状態を述べる文脈には合わない"}, {"text": "再開", "is_correct": false, "explanation": "止まっていたものが始まり直すことを表す。「再開として続いている」は成り立たない"}], "explanations": {"常態": "「続いている状態」を表す名詞で、「常態として続いている」の空所に合う", "中断": "途中で止まることを表す。「中断として続いている」では意味が通らない", "復旧": "元どおりに戻すことを表す。続いている状態を述べる文脈には合わない", "再開": "止まっていたものが始まり直すことを表す。「再開として続いている」は成り立たない"}, "sentence_index": 0, "correct_answer": "常態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "常態は、毎朝七時に出社する。", "explanation": "ここは〈通常〉の意味（ふつうは〜する）。常態は状態を表す名詞で、動詞を副詞的に修飾できないので、この文では使えない"}, {"text": "この店の定食は、常態の値段で食べられる。", "explanation": "ここは〈普通〉の意味（ありふれた、ふつうの）。常態は「ふつうの状態が続くこと」で、値段の水準には使わない"}, {"text": "毎朝のストレッチを、常態に取り入れる。", "explanation": "ここは〈日常〉の意味（毎日の暮らしの中）。常態は続いている状態を表すので、習慣を取り入れる対象にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常態", "is_correct": true, "explanation": "続いている状態を表す名詞で、「常態とみなしてはいけない」の空所に合う"}, {"text": "季節", "is_correct": false, "explanation": "一年の区分を表す。「季節とみなす」では、人手不足を状態として扱う意味にならない"}, {"text": "天候", "is_correct": false, "explanation": "空模様や気象を表す。人が足りない状態を天候とみなすのは意味が通らない"}, {"text": "景色", "is_correct": false, "explanation": "目に映る風景を表す。人手不足を景色とみなす文脈には合わない"}], "explanations": {"常態": "続いている状態を表す名詞で、「常態とみなしてはいけない」の空所に合う", "季節": "一年の区分を表す。「季節とみなす」では、人手不足を状態として扱う意味にならない", "天候": "空模様や気象を表す。人が足りない状態を天候とみなすのは意味が通らない", "景色": "目に映る風景を表す。人手不足を景色とみなす文脈には合わない"}, "sentence_index": 6, "correct_answer": "常態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の停電は、一時的な常態だった。", "explanation": "ここは〈偶発〉の意味（たまたま起きたこと）。常態は続いている状態を指すので、一度きりの出来事には使えない"}, {"text": "この店の常態はカレーだ。", "explanation": "ここは〈定番〉の意味（決まって出される品）。常態は状態を表す語で、料理そのものにはならない"}, {"text": "あの店の常態が、また来た。", "explanation": "ここは〈常連〉の意味（いつも来る人）。常態は人を指さないので、来る主体にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域では、断水が常態に続いている。", "corrected_sentence": "この地域では、断水が常態として続いている。", "error_description": "正しくは「常態として続いている」。「として」を「に」にすると、常態を状態の名詞として扱えず、文法的に不自然になる。誤りは常態に付く助詞の部分", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39135, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日が続くことを常態をみなす人が多い。", "corrected_sentence": "雨の日が続くことを常態とみなす人が多い。", "error_description": "正しくは「常態とみなす」。「みなす」は「〜を〜とみなす」の形で、常態に続く助詞は「と」。「を」にすると誤り。誤りは常態に付く助詞", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飲料を買う」で、買う対象を示す目的語の格助詞。文の意味に合う"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「飲料が買って」は飲料が買う主体になり、意味が崩れる"}, {"text": "に", "is_correct": false, "explanation": "相手・帰着の「に」。「飲料に買って」は買う対象を示せない"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「飲料へ買って」は意味が通らない"}], "correct_answer": "を", "explanations": {"を": "「飲料を買う」で、買う対象を示す目的語の格助詞。文の意味に合う", "が": "主格の「が」。「飲料が買って」は飲料が買う主体になり、意味が崩れる", "に": "相手・帰着の「に」。「飲料に買って」は買う対象を示せない", "へ": "方向の「へ」。「飲料へ買って」は意味が通らない"}, "error_tags": {"を": "目的語", "が": "主語", "に": "相手・帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
