INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "のむもの。お茶や水のような、のむためのもの。", "primary_collocate": null, "pronunciation": "いんりょう", "ipa": "iɴɾʲoː", "syllable_count": 4, "sentences": [{"text": "運動のあとは、冷たい飲料がおいしいです。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、冷[つめ]たい飲料[いんりょう]がおいしいです。", "sentence_source": "generated"}, {"text": "店で飲料を買って、公園で飲みました。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "店[みせ]で飲料[いんりょう]を買[か]って、公園[こうえん]で飲[の]みました。", "sentence_source": "generated"}, {"text": "会場には、お茶や水などの飲料が用意されています。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "会場[かいじょう]には、お茶[ちゃ]や水[みず]などの飲料[いんりょう]が用意[ようい]されています。", "sentence_source": "generated"}, {"text": "暑い日は、飲料をたくさん持って出かけます。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、飲料[いんりょう]をたくさん持[も]って出[で]かけます。", "sentence_source": "generated"}, {"text": "コーヒーのようなあたたかい飲料は、寒い朝にぴったりです。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "コーヒーのようなあたたかい飲料[いんりょう]は、寒[さむ]い朝[あさ]にぴったりです。", "sentence_source": "generated"}, {"text": "この自動販売機には、いろいろな飲料があります。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "この自動販売機[じどうはんばいき]には、いろいろな飲料[いんりょう]があります。", "sentence_source": "generated"}, {"text": "冷蔵庫の中の飲料は、自由に飲んでください。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]の飲料[いんりょう]は、自由[じゆう]に飲[の]んでください。", "sentence_source": "generated"}, {"text": "子どもが好きな飲料は、あまいジュースです。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "子[こ]どもが好[す]きな飲料[いんりょう]は、あまいジュースです。", "sentence_source": "generated"}, {"text": "映画館には、飲料を持ちこめません。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "映画館[えいがかん]には、飲料[いんりょう]を持[も]ちこめません。", "sentence_source": "generated"}, {"text": "遠足に、飲料を入れた水筒を持っていきます。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "遠足[えんそく]に、飲料[いんりょう]を入[い]れた水筒[すいとう]を持[も]っていきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲料", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お茶や水など、のむためのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飲料", "is_correct": true, "explanation": "飲むためのもので、「冷たい飲料がおいしい」の空所に合う"}, {"text": "冷房", "is_correct": false, "explanation": "室内の温度を下げる設備。「冷たい冷房がおいしい」は意味が通らない"}, {"text": "照明", "is_correct": false, "explanation": "明かりを与える設備。食べ物や飲み物の味を表す文には合わない"}, {"text": "包装", "is_correct": false, "explanation": "物を包むことを表す。「冷たい包装がおいしい」は成り立たない"}], "explanations": {"飲料": "飲むためのもので、「冷たい飲料がおいしい」の空所に合う", "冷房": "室内の温度を下げる設備。「冷たい冷房がおいしい」は意味が通らない", "照明": "明かりを与える設備。食べ物や飲み物の味を表す文には合わない", "包装": "物を包むことを表す。「冷たい包装がおいしい」は成り立たない"}, "sentence_index": 0, "correct_answer": "飲料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この村は、野菜や魚などの飲料を自給している。", "explanation": "ここは〈食料〉の意味（食べ物全般）。飲料は飲むものだけを指すので、野菜や魚の代わりにはならない"}, {"text": "料理に、塩やしょうゆなどの飲料を加える。", "explanation": "ここは〈調味料〉の意味（味付けの材料）。飲料は飲むためのものなので、料理の味付けには合わない"}, {"text": "ガソリンスタンドで、車に飲料を入れて走らせる。", "explanation": "ここは〈燃料〉の意味（車を動かすもの）。飲料は飲むためのものなので、車に入れる対象にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飲料", "is_correct": true, "explanation": "飲むためのもので、「冷蔵庫の中の飲料は、自由に飲んでください」の空所に合う"}, {"text": "食器", "is_correct": false, "explanation": "食べ物を盛る器。「自由に飲んでください」とは結びつかない"}, {"text": "洗剤", "is_correct": false, "explanation": "汚れを落とす液体。飲んでよいものとして扱う文には合わない"}, {"text": "文房具", "is_correct": false, "explanation": "書くための道具。冷蔵庫の中で飲むものとして扱うのは意味が通らない"}], "explanations": {"飲料": "飲むためのもので、「冷蔵庫の中の飲料は、自由に飲んでください」の空所に合う", "食器": "食べ物を盛る器。「自由に飲んでください」とは結びつかない", "洗剤": "汚れを落とす液体。飲んでよいものとして扱う文には合わない", "文房具": "書くための道具。冷蔵庫の中で飲むものとして扱うのは意味が通らない"}, "sentence_index": 6, "correct_answer": "飲料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい飲料のコートを買った。", "explanation": "ここは〈衣類〉の意味（着るもの）。飲料は飲むためのものなので、コートのように身に着けるものには使えない"}, {"text": "この通りの古い飲料は、来年取り壊される。", "explanation": "ここは〈建物〉の意味（建築物）。飲料は建物ではないので、取り壊しの対象にはならない"}, {"text": "新しい飲料が故障したので、修理に出した。", "explanation": "ここは〈家電〉の意味（電気製品）。飲料は故障して修理に出す機械ではないので、この文では使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の売店で飲料が買って、ベンチで飲んだ。", "corrected_sentence": "駅の売店で飲料を買って、ベンチで飲んだ。", "error_description": "正しくは「飲料を買う」。買う対象を示す目的語の「を」が「が」になっており、誤り。誤りは飲料に付く助詞", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39136, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会場で飲料が配った。", "corrected_sentence": "会場で飲料を配った。", "error_description": "正しくは「飲料を配る」。配る対象を示す目的語の「を」が「が」になっており、誤り。誤りは飲料に付く助詞", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39137, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「飲料がならんでいる」で、並んでいる主体を示す主格の格助詞。文の意味に合う"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「飲料をならんでいる」は並ぶ動作の対象にならない"}, {"text": "に", "is_correct": false, "explanation": "場所・帰着の「に」。ここは並ぶ主体を示す位置で、合わない"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「飲料へならんでいる」は並ぶ主体を表せない"}], "correct_answer": "が", "explanations": {"が": "「飲料がならんでいる」で、並んでいる主体を示す主格の格助詞。文の意味に合う", "を": "目的語の「を」。「飲料をならんでいる」は並ぶ動作の対象にならない", "に": "場所・帰着の「に」。ここは並ぶ主体を示す位置で、合わない", "へ": "方向の「へ」。「飲料へならんでいる」は並ぶ主体を表せない"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所・帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39137, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「飲料を作る」で、作る対象を示す目的語の格助詞。文の意味に合う"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「飲料が作る会社」は飲料が作る主体になり、意味が崩れる"}, {"text": "と", "is_correct": false, "explanation": "共同・相手の「と」。「飲料と作る会社」は意味が通らない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「飲料の作る会社」では作る対象を示せない"}], "correct_answer": "を", "explanations": {"を": "「飲料を作る」で、作る対象を示す目的語の格助詞。文の意味に合う", "が": "主格の「が」。「飲料が作る会社」は飲料が作る主体になり、意味が崩れる", "と": "共同・相手の「と」。「飲料と作る会社」は意味が通らない", "の": "連体修飾の「の」。「飲料の作る会社」では作る対象を示せない"}, "error_tags": {"を": "目的語", "が": "主語", "と": "共同・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39137, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飲むための液体。水やお茶、ジュースなどの総称。", "primary_collocate": null, "pronunciation": "いんりょう", "ipa": "iɴɾʲoː", "syllable_count": 4, "sentences": [{"text": "店では、酒類を含むさまざまな飲料を販売している。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "店[みせ]では、酒類[しゅるい]を含[ふく]むさまざまな飲料[いんりょう]を販売[はんばい]している。", "sentence_source": "generated"}, {"text": "この棚には、水やお茶などの飲料がならんでいる。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "この棚[たな]には、水[みず]やお茶[ちゃ]などの飲料[いんりょう]がならんでいる。", "sentence_source": "generated"}, {"text": "飲料の容器には、ペットボトルや缶などがある。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "飲料[いんりょう]の容器[ようき]には、ペットボトルや缶[かん]などがある。", "sentence_source": "generated"}, {"text": "飲料の売り上げは、夏に大きく伸びる。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "飲料[いんりょう]の売[う]り上[あ]げは、夏[なつ]に大[おお]きく伸[の]びる。", "sentence_source": "generated"}, {"text": "工場では、飲料をびんにつめる作業が行われている。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、飲料[いんりょう]をびんにつめる作業[さぎょう]が行[おこな]われている。", "sentence_source": "generated"}, {"text": "食品や飲料の表示には、決まりがある。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "食品[しょくひん]や飲料[いんりょう]の表示[ひょうじ]には、決[き]まりがある。", "sentence_source": "generated"}, {"text": "運動中は、こまめに飲料を補給するとよい。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "運動[うんどう]中[ちゅう]は、こまめに飲料[いんりょう]を補給[ほきゅう]するとよい。", "sentence_source": "generated"}, {"text": "飲料を作る会社が、新しいお茶を発売した。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "飲料[いんりょう]を作[つく]る会社[かいしゃ]が、新[あたら]しいお茶[ちゃ]を発売[はつばい]した。", "sentence_source": "generated"}, {"text": "冷たい飲料は、飲みすぎるとおなかをこわすことがある。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "冷[つめ]たい飲料[いんりょう]は、飲[の]みすぎるとおなかをこわすことがある。", "sentence_source": "generated"}, {"text": "会議室では、飲料の持ちこみが認められている。", "target_word": "飲料", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]では、飲料[いんりょう]の持[も]ちこみが認[みと]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲料", "label": "基本形"}], "register": "formal", "sense_fingerprint": "水・お茶・ジュースなど飲む液体の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 持ちこみ (Zipf 1.75)']::text[], 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39137, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飲料", "is_correct": true, "explanation": "飲むための液体の総称で、「酒類を含むさまざまな飲料を販売している」の空所に合う"}, {"text": "雷雨", "is_correct": false, "explanation": "激しい雨と雷。販売する対象にはならない"}, {"text": "騒音", "is_correct": false, "explanation": "不快な音。店が販売するものとしては意味が通らない"}, {"text": "天気", "is_correct": false, "explanation": "空の状態。「天気を販売している」は成り立たない"}], "explanations": {"飲料": "飲むための液体の総称で、「酒類を含むさまざまな飲料を販売している」の空所に合う", "雷雨": "激しい雨と雷。販売する対象にはならない", "騒音": "不快な音。店が販売するものとしては意味が通らない", "天気": "空の状態。「天気を販売している」は成り立たない"}, "sentence_index": 0, "correct_answer": "飲料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもが、飲料の教科書を開いて勉強する。", "explanation": "ここは〈教科書〉の意味（学ぶための本）。飲料は飲むためのものなので、教科書の代わりにはならない"}, {"text": "味噌汁に、だしの素などの飲料を足す。", "explanation": "ここは〈調味料〉の意味（味付けに使うもの）。飲料は飲むためのものなので、味付けの素には合わない"}, {"text": "トイレットペーパーなどの飲料を買う。", "explanation": "ここは〈日用品〉の意味（日々使う生活用品）。トイレットペーパーは飲料ではないので、同じ意味では使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39137, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飲料", "is_correct": true, "explanation": "飲むための液体で、「運動中は、こまめに飲料を補給するとよい」の空所に合う"}, {"text": "感情", "is_correct": false, "explanation": "心の動き。体に補給するものとしては意味が通らない"}, {"text": "教訓", "is_correct": false, "explanation": "経験から得る教え。補給する対象にはならない"}, {"text": "理屈", "is_correct": false, "explanation": "筋道の通った考え。補給するという動詞とは結びつかない"}], "explanations": {"飲料": "飲むための液体で、「運動中は、こまめに飲料を補給するとよい」の空所に合う", "感情": "心の動き。体に補給するものとしては意味が通らない", "教訓": "経験から得る教え。補給する対象にはならない", "理屈": "筋道の通った考え。補給するという動詞とは結びつかない"}, "sentence_index": 6, "correct_answer": "飲料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の土に、飲料をまいて花を育てる。", "explanation": "ここは〈肥料〉の意味（植物を育てる材料）。飲料は飲むためのもので、土にまく肥やしにはならない"}, {"text": "けがをした傷口に、飲料を貼った。", "explanation": "ここは〈絆創膏〉の意味（傷に貼る手当て用品）。飲料は貼るものではないので、傷の手当てには使えない"}, {"text": "新しい飲料の机を買った。", "explanation": "ここは〈家具〉の意味（部屋に置く道具）。飲料は飲むためのもので、机の代わりにはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
