INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39138, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "することがむずかしいこと。", "primary_collocate": null, "pronunciation": "こんなん", "ipa": "koɴnaɴ", "syllable_count": 4, "sentences": [{"text": "彼は多くの困難を乗り越えて、夢をかなえた。", "target_word": "困難", "complexity_tier": "T3", "furigana": "かれはおおくのこんなんをのりこえて、ゆめをかなえた。", "sentence_source": "generated"}, {"text": "一人でこの荷物を運ぶのは困難です。", "target_word": "困難", "complexity_tier": "T3", "furigana": "ひとりでこのにもつをはこぶのはこんなんです。", "sentence_source": "generated"}, {"text": "長い旅の途中で、私たちは何度も困難にぶつかった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "ながいたびのとちゅうで、わたしたちはなんどもこんなんにぶつかった。", "sentence_source": "generated"}, {"text": "足をけがして、階段を上がるのが困難になった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "あしをけがして、かいだんをあがるのがこんなんになった。", "sentence_source": "generated"}, {"text": "困難な問題でも、みんなで考えれば答えが見つかる。", "target_word": "困難", "complexity_tier": "T3", "furigana": "こんなんなもんだいでも、みんなでかんがえればこたえがみつかる。", "sentence_source": "generated"}, {"text": "台風で電車が止まり、帰宅が困難になった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "たいふうででんしゃがとまり、きたくがこんなんになった。", "sentence_source": "generated"}, {"text": "友達が困難にあったときは、助けてあげたい。", "target_word": "困難", "complexity_tier": "T3", "furigana": "ともだちがこんなんにあったときは、たすけてあげたい。", "sentence_source": "generated"}, {"text": "目が悪い祖父は、小さい字を読むのが困難だ。", "target_word": "困難", "complexity_tier": "T3", "furigana": "めがわるいそふは、ちいさいじをよむのがこんなんだ。", "sentence_source": "generated"}, {"text": "どんな困難があっても、あきらめないでください。", "target_word": "困難", "complexity_tier": "T3", "furigana": "どんなこんなんがあっても、あきらめないでください。", "sentence_source": "generated"}, {"text": "川の水かさが増えて、向こう岸へ渡ることが困難になった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "かわのみずかさがふえて、むこうぎしへわたることがこんなんになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "困難", "label": "基本形"}, {"form": "困難な", "label": "連体形"}, {"form": "困難だ", "label": "断定形"}, {"form": "困難に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "することがむずかしいこと・行く手の障害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: けがし (Zipf 2.18)','sentence 9 above tier T2: contains vocabulary far above tier T2: 水かさ (Zipf 1.84), 向こう岸 (Zipf 2.28)']::text[], '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39138, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困難", "is_correct": true, "explanation": "「多くの〜を乗り越えて」に入り、乗り越える対象となる難題を表す。"}, {"text": "祝福", "is_correct": false, "explanation": "祝いの言葉や恵みの意味で、乗り越える対象にはならないので合わない。"}, {"text": "余裕", "is_correct": false, "explanation": "ゆとりの意味で、「多くの余裕を乗り越えて」では意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "乗り越える対象にはならず、「多くの散歩を乗り越えて」は文として成り立たない。"}], "explanations": {"困難": "「多くの〜を乗り越えて」に入り、乗り越える対象となる難題を表す。", "祝福": "祝いの言葉や恵みの意味で、乗り越える対象にはならないので合わない。", "余裕": "ゆとりの意味で、「多くの余裕を乗り越えて」では意味が通らない。", "散歩": "乗り越える対象にはならず、「多くの散歩を乗り越えて」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "困難"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足の困難がまだ続いていて、歩くと痛む。", "explanation": "ここは〈痛み〉の意味。「困難」は物事の難しさを表し、体の痛みを表す語ではないので合わない。"}, {"text": "この靴は困難で、履くと足が痛い。", "explanation": "ここは〈窮屈で合わない〉の意味。「困難」は進めにくさを表し、靴の履き心地には使わないので合わない。"}, {"text": "この祖母の形見の手紙は困難で、大切に保管している。", "explanation": "ここは〈貴重だ〉の意味。「困難」は品物の価値の高さを表さないので、大切な品には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39138, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困難", "is_correct": true, "explanation": "「困難にあう」で、困った状況に出くわす意味になり文に合う。"}, {"text": "目標", "is_correct": false, "explanation": "目指す地点の意味で、「目標にあう」は不自然で合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "書状の意味で、「手紙にあう」では意味が通らない。"}, {"text": "材料", "is_correct": false, "explanation": "物を作る素材の意味で、「材料にあう」は文として成り立たない。"}], "explanations": {"困難": "「困難にあう」で、困った状況に出くわす意味になり文に合う。", "目標": "目指す地点の意味で、「目標にあう」は不自然で合わない。", "手紙": "書状の意味で、「手紙にあう」では意味が通らない。", "材料": "物を作る素材の意味で、「材料にあう」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "困難"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事件の現場から、犯人の困難が見つかった。", "explanation": "ここは〈証拠〉の意味。「困難」は進めにくさを表し、証拠の意味では使わないので合わない。"}, {"text": "彼の言葉に困難がこみ上げて、思わず声を荒らげた。", "explanation": "ここは〈怒り〉の意味。「困難」は怒りの感情を表さないので合わない。"}, {"text": "この絵は色の困難が強すぎて、目が疲れる。", "explanation": "ここは〈色の鮮やかさ・刺激〉の意味。「困難」は色の強さを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39138, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "勉強と仕事の両立は、時間の確保が困難に場合も多い。", "corrected_sentence": "勉強と仕事の両立は、時間の確保が困難な場合も多い。", "error_description": "名詞「場合」を修飾するには連体形「困難な」が必要。「困難に」は連用形で、名詞に続けられないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39138, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は大きな困難に乗り越えて、夢を実現した。", "corrected_sentence": "彼女は大きな困難を乗り越えて、夢を実現した。", "error_description": "「乗り越える」は他動詞で、対象は助詞「を」で示す。「困難に」は誤りで、「困難を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "容易", "is_correct": true, "explanation": "「困難」の対義語として辞書に挙がり、物事を進めやすいことを表す。"}, {"text": "穏やか", "is_correct": false, "explanation": "性質が落ち着いている意味で、「困難」の対義語ではない。"}, {"text": "活発", "is_correct": false, "explanation": "盛んに動くさまを表し、「困難」との対義関係はない。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ない意味で、「困難」の対義語ではない。"}], "correct_answer": "容易", "explanations": {"容易": "「困難」の対義語として辞書に挙がり、物事を進めやすいことを表す。", "穏やか": "性質が落ち着いている意味で、「困難」の対義語ではない。", "活発": "盛んに動くさまを表し、「困難」との対義関係はない。", "静か": "音や動きが少ない意味で、「困難」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
