INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事をうまく進めるのが難しいこと。また、そのさま。", "primary_collocate": null, "pronunciation": "こんなん", "ipa": "koɴnaɴ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "困難", "complexity_tier": "T4", "furigana": "かつてはあんていしていたせいたいけいのサイクルが、げんだいぶんめいのけいざいかつどうによってゆがめられ、そのしゅうふくはきわめてこんなんなきょくめんをむかえている。", "sentence_source": "mined"}, {"text": "雪で道が閉ざされ、救助隊が現場へ向かうのは困難だった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "ゆきでみちがとざされ、きゅうじょたいがげんばへむかうのはこんなんだった。", "sentence_source": "generated"}, {"text": "資金が足りないため、計画の継続は困難だと判断された。", "target_word": "困難", "complexity_tier": "T3", "furigana": "しきんがたりないため、けいかくのけいぞくはこんなんだとはんだんされた。", "sentence_source": "generated"}, {"text": "視界が悪く、飛行機の着陸は困難な状況になった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "しかいがわるく、ひこうきのちゃくりくはこんなんなじょうきょうになった。", "sentence_source": "generated"}, {"text": "彼は困難な交渉をまとめ上げ、会社を危機から救った。", "target_word": "困難", "complexity_tier": "T3", "furigana": "かれはこんなんなこうしょうをまとめあげ、かいしゃをききからすくった。", "sentence_source": "generated"}, {"text": "人口が減る町で医師を確保することは、ますます困難になっている。", "target_word": "困難", "complexity_tier": "T3", "furigana": "じんこうがへるまちでいしをかくほすることは、ますますこんなんになっている。", "sentence_source": "generated"}, {"text": "仕事と育児を両立するのが困難で、退職を考える人も多い。", "target_word": "困難", "complexity_tier": "T3", "furigana": "しごととじいくをりょうりつするのがこんなんで、たいしょくをかんがえるひともおおい。", "sentence_source": "generated"}, {"text": "山頂付近は酸素が薄く、呼吸が困難になる登山者もいる。", "target_word": "困難", "complexity_tier": "T3", "furigana": "さんちょうふきんはさんそがうすく、こきゅうがこんなんになるとざんしゃもいる。", "sentence_source": "generated"}, {"text": "専門家でも、地震の正確な予知は困難とされている。", "target_word": "困難", "complexity_tier": "T3", "furigana": "せんもんかでも、じしんのせいかくなよちはこんなんとされている。", "sentence_source": "generated"}, {"text": "言葉の壁があって、外国で部屋を借りるのは困難だった。", "target_word": "困難", "complexity_tier": "T3", "furigana": "ことばのかべがあって、がいこくでへやをかりるのはこんなんだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "困難", "label": "語幹"}, {"form": "困難だ", "label": "断定形"}, {"form": "困難な", "label": "連体形"}, {"form": "困難に", "label": "連用形"}], "register": "formal", "sense_fingerprint": "物事を進めるのが難しい状態・さま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困難", "is_correct": true, "explanation": "「極めて〜な局面」に入り、修復の難しさを表す形容として文脈に合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "「極めて穏やかな局面」では、循環が歪められて修復が必要だという文脈と逆の意味になる。"}, {"text": "活発", "is_correct": false, "explanation": "「活発な局面」は動きが盛んな状態で、修復の困難さを述べる文とはつながらない。"}, {"text": "豊か", "is_correct": false, "explanation": "「豊かな局面」は内容が充実している意味で、生態系が壊れている文脈と合わない。"}], "explanations": {"困難": "「極めて〜な局面」に入り、修復の難しさを表す形容として文脈に合う。", "穏やか": "「極めて穏やかな局面」では、循環が歪められて修復が必要だという文脈と逆の意味になる。", "活発": "「活発な局面」は動きが盛んな状態で、修復の困難さを述べる文とはつながらない。", "豊か": "「豊かな局面」は内容が充実している意味で、生態系が壊れている文脈と合わない。"}, "sentence_index": 0, "correct_answer": "困難"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この石は極めて困難で、ハンマーで叩いても割れなかった。", "explanation": "ここは〈硬い〉の意味。「困難」は物事を進めにくいことを表し、物の硬さには使わないので合わない。"}, {"text": "隣家の犬の鳴き声が困難で、毎晩眠れずに困っている。", "explanation": "ここは〈厄介で迷惑だ〉の意味。「困難」は進めにくさを表すもので、騒音や迷惑を表す語ではないので合わない。"}, {"text": "あの店長は気難しくて、とても困難な人だ。", "explanation": "ここは〈扱いにくい性格〉の意味。「困難」は物事の難しさを表し、人の性格を言う語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困難", "is_correct": true, "explanation": "「するのが〜で」に入り、仕事と育児を両立することの難しさを表す。"}, {"text": "平坦", "is_correct": false, "explanation": "道や地面が平らな様子で、両立の難しさとは意味が合わない。"}, {"text": "清らか", "is_correct": false, "explanation": "澄んで汚れがないさまで、両立の話には合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "ぜいたくで派手なさまで、「両立するのが豪華で」では意味が通らない。"}], "explanations": {"困難": "「するのが〜で」に入り、仕事と育児を両立することの難しさを表す。", "平坦": "道や地面が平らな様子で、両立の難しさとは意味が合わない。", "清らか": "澄んで汚れがないさまで、両立の話には合わない。", "豪華": "ぜいたくで派手なさまで、「両立するのが豪華で」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "困難"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理は味が困難で、一口食べて残してしまった。", "explanation": "ここは〈まずい・口に合わない〉の意味。「困難」は進めにくさを表し、味の評価には使わないので合わない。"}, {"text": "彼の声は困難で、聞いていて心地よい。", "explanation": "ここは〈穏やかで心地よい〉の意味。「困難」は進めにくさを表し、声の心地よさには使わないので合わない。"}, {"text": "この香りは困難で、部屋中に広がっている。", "explanation": "ここは〈香りが強く漂う〉の意味。「困難」は物事の進めにくさを表し、香りの広がりには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪で道が閉ざされ、救助隊の進行は困難に状況が続いている。", "corrected_sentence": "雪で道が閉ざされ、救助隊の進行は困難な状況が続いている。", "error_description": "「困難」は形状詞なので、名詞「状況」を修飾するには連体形「困難な」が必要。「困難に」は連用形で、名詞に直接続けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "困難", "is_correct": true, "explanation": "「困難だった」の語幹の形で、文の「だった」に続けて正しく成立する。"}, {"text": "困難な", "is_correct": false, "explanation": "連体形は名詞の前に置く形。「困難なだった」となり文が成り立たない。"}, {"text": "困難だ", "is_correct": false, "explanation": "断定形の「だ」が「だった」と重なり、「困難だだった」となって不自然。"}, {"text": "困難に", "is_correct": false, "explanation": "連用形は「になる」などに続く形。「困難にだった」となり合わない。"}], "correct_form": "困難", "base_form": "困難", "form_label": "語幹", "sentence_index": 1, "explanations": {"困難": "「困難だった」の語幹の形で、文の「だった」に続けて正しく成立する。", "困難な": "連体形は名詞の前に置く形。「困難なだった」となり文が成り立たない。", "困難だ": "断定形の「だ」が「だった」と重なり、「困難だだった」となって不自然。", "困難に": "連用形は「になる」などに続く形。「困難にだった」となり合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39139, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で川が増水し、向こう岸へ渡るのは困難だ状況だった。", "corrected_sentence": "雨で川が増水し、向こう岸へ渡るのは困難な状況だった。", "error_description": "「困難」を名詞「状況」の前で使うには連体形「困難な」が必要。「困難だ」は断定形で、名詞の前には置けないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "困難に", "is_correct": true, "explanation": "「なる」に続く連用形で、「呼吸が困難になる」が成り立つ。"}, {"text": "困難で", "is_correct": false, "explanation": "連用中止の「で」は文を続ける形で、「困難でになる」となり「になる」に直接つながらない。"}, {"text": "困難だった", "is_correct": false, "explanation": "過去の断定形で、「困難だったになる」となり文が合わない。"}, {"text": "困難です", "is_correct": false, "explanation": "丁寧な断定形で、「困難ですになる」となり「になる」に続けられない。"}], "correct_form": "困難に", "base_form": "困難", "form_label": "連用形", "sentence_index": 7, "explanations": {"困難に": "「なる」に続く連用形で、「呼吸が困難になる」が成り立つ。", "困難で": "連用中止の「で」は文を続ける形で、「困難でになる」となり「になる」に直接つながらない。", "困難だった": "過去の断定形で、「困難だったになる」となり文が合わない。", "困難です": "丁寧な断定形で、「困難ですになる」となり「になる」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "急性", "is_correct": true, "explanation": "慢性の対義語。短期間で急に現れる病気の状態を指す"}, {"text": "持続", "is_correct": false, "explanation": "同じ状態が続くことを表すが、慢性の対義語ではない"}, {"text": "完治", "is_correct": false, "explanation": "病気が完全に治ること。慢性と対義の関係にはない"}, {"text": "再発", "is_correct": false, "explanation": "治ったあとに同じ病気が再び起こること。対義語ではない"}], "correct_answer": "急性", "explanations": {"急性": "慢性の対義語。短期間で急に現れる病気の状態を指す", "持続": "同じ状態が続くことを表すが、慢性の対義語ではない", "完治": "病気が完全に治ること。慢性と対義の関係にはない", "再発": "治ったあとに同じ病気が再び起こること。対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "急性", "is_correct": true, "explanation": "慢性の対義語。短期間で急に起こる病気の状態を指す"}, {"text": "回復", "is_correct": false, "explanation": "病気や体の状態が元に戻ること。慢性の対義語ではない"}, {"text": "改善", "is_correct": false, "explanation": "よい方向に改めること。慢性と対義の関係にはない"}, {"text": "悪化", "is_correct": false, "explanation": "状態が悪くなること。慢性の対義語とは辞書上の関係がない"}], "correct_answer": "急性", "explanations": {"急性": "慢性の対義語。短期間で急に起こる病気の状態を指す", "回復": "病気や体の状態が元に戻ること。慢性の対義語ではない", "改善": "よい方向に改めること。慢性と対義の関係にはない", "悪化": "状態が悪くなること。慢性の対義語とは辞書上の関係がない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "病気や問題が長い間ずっと続くこと。", "primary_collocate": null, "pronunciation": "まんせい", "ipa": "maɴseː", "syllable_count": 4, "sentences": [{"text": "祖父は慢性の病気があり、毎日薬を飲んでいます。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "祖父[そふ]は慢性[まんせい]の病気[びょうき]があり、毎日[まいにち]薬[くすり]を飲[の]んでいます。", "sentence_source": "generated"}, {"text": "慢性の頭痛に悩まされて、病院へ行った。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の頭痛[ずつう]に悩[なや]まされて、病院[びょういん]へ行[い]った。", "sentence_source": "generated"}, {"text": "この町では、慢性の水不足が続いている。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "この町[まち]では、慢性[まんせい]の水不足[みずぶそく]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "慢性のせきがなかなか治らない。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]のせきがなかなか治[なお]らない。", "sentence_source": "generated"}, {"text": "急に起こる病気と違い、慢性の病気は長く付き合う必要がある。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "急[きゅう]に起[お]こる病気[びょうき]と違[ちが]い、慢性[まんせい]の病気[びょうき]は長[なが]く付[つ]き合[あ]う必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "慢性の人手不足で、店は休みを増やせない。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の人手不足[ひとでぶそく]で、店[みせ]は休[やす]みを増[ふ]やせない。", "sentence_source": "generated"}, {"text": "風邪は数日で治るが、慢性の病気は何年も続く。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "風邪[かぜ]は数日[すうじつ]で治[なお]るが、慢性[まんせい]の病気[びょうき]は何年[なんねん]も続[つづ]く。", "sentence_source": "generated"}, {"text": "医者は「急性ではなく慢性ですから、焦らず治しましょう」と言った。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "医者[いしゃ]は「急性[きゅうせい]ではなく慢性[まんせい]ですから、焦[あせ]らず治[なお]しましょう」と言[い]った。", "sentence_source": "generated"}, {"text": "慢性の赤字に苦しむ会社が、事業を見直した。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の赤字[あかじ]に苦[くる]しむ会社[かいしゃ]が、事業[じぎょう]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "慢性の病気を持つ人のために、病院が教室を開いている。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の病気[びょうき]を持[も]つ人[ひと]のために、病院[びょういん]が教室[きょうしつ]を開[ひら]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢性", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気や問題が長く続いて治りにくいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢性", "is_correct": true, "explanation": "長く続く病気を表す語で、「祖父は慢性の病気があり」の空所に合う"}, {"text": "静粛", "is_correct": false, "explanation": "静かで騒がしくないこと。病気の種類を表す文脈には合わない"}, {"text": "寛大", "is_correct": false, "explanation": "心が広く、人をとがめないこと。病気の性質には使えない"}, {"text": "乱雑", "is_correct": false, "explanation": "散らかって整っていないこと。「乱雑の病気」は成り立たない"}], "explanations": {"慢性": "長く続く病気を表す語で、「祖父は慢性の病気があり」の空所に合う", "静粛": "静かで騒がしくないこと。病気の種類を表す文脈には合わない", "寛大": "心が広く、人をとがめないこと。病気の性質には使えない", "乱雑": "散らかって整っていないこと。「乱雑の病気」は成り立たない"}, "sentence_index": 0, "correct_answer": "慢性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は、慢性の事故があった。", "explanation": "ここは〈突発〉の意味（急に起こること）。慢性は長く続く病気や問題に使うので、一度きりの事故には合わない"}, {"text": "世界の慢性の平和を願う。", "explanation": "ここは〈永続〉の意味（いつまでも続くこと）。慢性は病気や困りごとの続き方を表すので、平和の性質には使えない"}, {"text": "慢性の努力で、夢をかなえた。", "explanation": "ここは〈地道〉の意味（こつこつ続けること）。慢性は病気や問題の続き方を表すので、努力の性質には使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢性", "is_correct": true, "explanation": "長く続く病気を表す語で、「慢性の病気は何年も続く」の空所に合う"}, {"text": "一時", "is_correct": false, "explanation": "しばらくの間だけであること。病気の長さを表す文脈で「一時の病気」は成り立たない"}, {"text": "不思議", "is_correct": false, "explanation": "説明しにくいこと。病気の種類を表す語としては合わない"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがないこと。病気の性質を表す語としては合わない"}], "explanations": {"慢性": "長く続く病気を表す語で、「慢性の病気は何年も続く」の空所に合う", "一時": "しばらくの間だけであること。病気の長さを表す文脈で「一時の病気」は成り立たない", "不思議": "説明しにくいこと。病気の種類を表す語としては合わない", "清潔": "汚れがないこと。病気の性質を表す語としては合わない"}, "sentence_index": 6, "correct_answer": "慢性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に慢性の頭痛がして、救急車を呼んだ。", "explanation": "ここは〈急性〉の意味（急に起こって短期間で治まること）。慢性は長く続く病気に使うので、突然の頭痛には合わない"}, {"text": "慢性の契約で、部屋を借りた。", "explanation": "ここは〈長期〉の意味（期間が長いこと）。慢性は病気や問題が続く様子を表すので、契約の期間には使えない"}, {"text": "慢性の商品が、人気を集めている。", "explanation": "ここは〈限定〉の意味（数量や期間が限られていること）。慢性は長く続く病気や問題の状態なので、商品の性質には使えない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は慢性に腰痛があり、毎日体操をしている。", "corrected_sentence": "祖母は慢性の腰痛があり、毎日体操をしている。", "error_description": "正しくは「慢性の腰痛」。慢性は名詞として「の」で後の名詞を修飾する。「慢性に」は誤りで、誤りは慢性に付く助詞", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39140, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪は数日で治るが、慢性な病気は何年も付き合う必要がある。", "corrected_sentence": "風邪は数日で治るが、慢性の病気は何年も付き合う必要がある。", "error_description": "正しくは「慢性の病気」。慢性は名詞なので、後ろの名詞を修飾するには「の」を付ける。「慢性な」は誤りで、誤りは慢性に付く語形", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "急性", "is_correct": true, "explanation": "慢性の対義語。急に起こって短期間で経過する病状を指し、「長期間続く」という文の意味と反対になる。"}, {"text": "完治", "is_correct": false, "explanation": "病気が元通りに治ることを表すが、慢性の対義語ではない。"}, {"text": "平凡", "is_correct": false, "explanation": "特に目立つところがないことを表し、慢性と対になる語ではない。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがないことを表し、病状の持続性とは対になる関係ではない。"}], "correct_answer": "急性", "explanations": {"急性": "慢性の対義語。急に起こって短期間で経過する病状を指し、「長期間続く」という文の意味と反対になる。", "完治": "病気が元通りに治ることを表すが、慢性の対義語ではない。", "平凡": "特に目立つところがないことを表し、慢性と対になる語ではない。", "清潔": "汚れがないことを表し、病状の持続性とは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "急性", "is_correct": true, "explanation": "慢性の対義語。急に起こって短期間で経過する病状を指し、「長期間続く肩こり」と反対の関係にある。"}, {"text": "回復", "is_correct": false, "explanation": "病気や体調が元に戻ることを表すが、慢性の対義語とは言えない。"}, {"text": "豊富", "is_correct": false, "explanation": "量が多いことを表し、病状の持続性とは対になる関係ではない。"}, {"text": "安静", "is_correct": false, "explanation": "体を休めることを表し、慢性の反対語ではない。"}], "correct_answer": "急性", "explanations": {"急性": "慢性の対義語。急に起こって短期間で経過する病状を指し、「長期間続く肩こり」と反対の関係にある。", "回復": "病気や体調が元に戻ることを表すが、慢性の対義語とは言えない。", "豊富": "量が多いことを表し、病状の持続性とは対になる関係ではない。", "安静": "体を休めることを表し、慢性の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ある状態や症状が長期間にわたって続くさま。", "primary_collocate": null, "pronunciation": "まんせい", "ipa": "maɴseː", "syllable_count": 4, "sentences": [{"text": "治療が遅れると、病気が慢性になることがある。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "治療[ちりょう]が遅[おく]れると、病気[びょうき]が慢性[まんせい]になることがある。", "sentence_source": "generated"}, {"text": "慢性の腰痛を和らげるため、毎朝ストレッチをしている。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の腰痛[ようつう]を和[やわ]らげるため、毎朝[まいあさ]ストレッチをしている。", "sentence_source": "generated"}, {"text": "慢性の疲れがたまって、休日も動けない。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の疲[つか]れがたまって、休日[きゅうじつ]も動[うご]けない。", "sentence_source": "generated"}, {"text": "慢性の症状には、長く続けられる治療が必要だ。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の症状[しょうじょう]には、長[なが]く続[つづ]けられる治療[ちりょう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "急に熱が出る病気ではなく、慢性の症状だと診断された。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "急[きゅう]に熱[ねつ]が出[で]る病気[びょうき]ではなく、慢性[まんせい]の症状[しょうじょう]だと診断[しんだん]された。", "sentence_source": "generated"}, {"text": "慢性の胃の病気を持つ彼は、食事に気をつけている。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の胃[い]の病気[びょうき]を持[も]つ彼[かれ]は、食事[しょくじ]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "空気の悪い町では、慢性の鼻づまりに悩む人が多い。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "空気[くうき]の悪[わる]い町[まち]では、慢性[まんせい]の鼻[はな]づまりに悩[なや]む人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "痛みが三か月以上続くと、慢性とされる。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "痛[いた]みが三[さん]か月[げつ]以上[いじょう]続[つづ]くと、慢性[まんせい]とされる。", "sentence_source": "generated"}, {"text": "慢性の不眠が続いているので、生活を見直した。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の不眠[ふみん]が続[つづ]いているので、生活[せいかつ]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "慢性の肩こりは、デスクワークが原因のことが多い。", "target_word": "慢性", "complexity_tier": "T3", "furigana": "慢性[まんせい]の肩[かた]こりは、デスクワークが原因[げんいん]のことが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢性", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "症状や状態が長期間続くようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfeebf62-af6f-48f5-b428-cf4bb79647d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢性", "is_correct": true, "explanation": "「病気が慢性になる」は、病気が長く続く状態に変わることを表し、文の意味に合う。"}, {"text": "健康", "is_correct": false, "explanation": "病気と健康は対立する状態なので、「病気が健康になる」とは言えず、文が成り立たない。"}, {"text": "自由", "is_correct": false, "explanation": "「病気が自由になる」という言い方は成り立たず、文脈に合わない。"}, {"text": "貴重", "is_correct": false, "explanation": "「貴重」は価値の高いものに使う語で、病気の状態の変化には使えない。"}], "explanations": {"慢性": "「病気が慢性になる」は、病気が長く続く状態に変わることを表し、文の意味に合う。", "健康": "病気と健康は対立する状態なので、「病気が健康になる」とは言えず、文が成り立たない。", "自由": "「病気が自由になる」という言い方は成り立たず、文脈に合わない。", "貴重": "「貴重」は価値の高いものに使う語で、病気の状態の変化には使えない。"}, "sentence_index": 0, "correct_answer": "慢性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "優勝して慢性を抱き、練習をやめてしまった。", "explanation": "慢性は〈慢心〉（思い上がり）の意味では使えない。その意味は「慢心」が担う。"}, {"text": "彼は遅刻の慢性犯だ、と皆に言われている。", "explanation": "慢性は〈常習〉（習慣的に繰り返すこと）の意味では使えない。その意味は「常習」が担う。"}, {"text": "古い橋が慢性のため通行止めになった。", "explanation": "慢性は〈老朽〉（古くて傷んでいること）の意味では使えない。その意味は「老朽」が担う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢性", "is_correct": true, "explanation": "「慢性の鼻づまり」は、長期間続く鼻の不調を表し、文の「悩む人が多い」に合う。"}, {"text": "平和", "is_correct": false, "explanation": "「平和の鼻づまり」という結びつきは成り立たず、鼻の状態を表せない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫」は体や物の頑丈さを指し、鼻づまりの状態を説明する語ではない。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華な鼻づまり」は意味をなさず、病状を説明する文脈に合わない。"}], "explanations": {"慢性": "「慢性の鼻づまり」は、長期間続く鼻の不調を表し、文の「悩む人が多い」に合う。", "平和": "「平和の鼻づまり」という結びつきは成り立たず、鼻の状態を表せない。", "丈夫": "「丈夫」は体や物の頑丈さを指し、鼻づまりの状態を説明する語ではない。", "豪華": "「豪華な鼻づまり」は意味をなさず、病状を説明する文脈に合わない。"}, "sentence_index": 6, "correct_answer": "慢性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の慢性に皆がうんざりした。", "explanation": "慢性は〈高慢〉（思い上がって人を見下すこと）の意味では使えない。その意味は「高慢」が担う。"}, {"text": "彼は慢性の力でこの店に通い続けている。", "explanation": "慢性は〈惰性〉（なんとなく同じことを続ける勢い）の意味では使えない。その意味は「惰性」が担う。"}, {"text": "この番組は慢性の表現ばかりで、新鮮味がない。", "explanation": "慢性は〈陳腐〉（古くさく新鮮味がないこと）の意味では使えない。その意味は「陳腐」が担う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "慢性を頭痛に悩まされて、仕事に集中できない。", "corrected_sentence": "慢性の頭痛に悩まされて、仕事に集中できない。", "error_description": "誤りは「慢性を」。慢性の後に続く助詞は「の」（慢性の頭痛）が正しく、「を」は目的語を示すため文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39141, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "慢性な寝不足が続いて、朝から頭がぼんやりする。", "corrected_sentence": "慢性の寝不足が続いて、朝から頭がぼんやりする。", "error_description": "誤りは「慢性な」。慢性は名詞なので名詞を修飾するときは「の」を使う（慢性の寝不足）。「慢性な」は不自然で、「慢性的な」とすれば正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebd9d86-a054-4644-a270-4ae2dfc4660c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「遅らせる」の目的語を示す「を」で、進行を対象にとる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「遅らせる」は目的語をとるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示し、遅らせる対象には使わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、目的語を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「遅らせる」の目的語を示す「を」で、進行を対象にとる。", "が": "主語を示すが、「遅らせる」は目的語をとるので合わない。", "に": "方向や相手を示し、遅らせる対象には使わない。", "で": "手段や場所を示し、目的語を示すことはできない。"}, "error_tags": {"が": "subject", "に": "target/direction", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「防ぐ」の目的語を示す「を」で、進行を対象にとる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すため、防ぐ対象を表す語としては合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、動詞「防ぐ」の目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すため、防ぐ対象を表す語としては合わない。"}], "correct_answer": "を", "explanations": {"を": "「防ぐ」の目的語を示す「を」で、進行を対象にとる。", "へ": "方向を示すため、防ぐ対象を表す語としては合わない。", "の": "連体修飾の「の」で、動詞「防ぐ」の目的語を示せない。", "より": "比較の基準を示すため、防ぐ対象を表す語としては合わない。"}, "error_tags": {"へ": "direction", "の": "attributive", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ことがらが、どんどんすすむこと。", "primary_collocate": null, "pronunciation": "しんこう", "ipa": "ɕiŋkoː", "syllable_count": 4, "sentences": [{"text": "工事の進行が順調で、予定より一週間早く終わりそうだ。", "target_word": "進行", "complexity_tier": "T3", "furigana": "工事(こうじ)の進行(しんこう)が順調(じゅんちょう)で、予定(よてい)より一週間(いっしゅうかん)早(はや)く終(お)わりそうだ。", "sentence_source": "generated"}, {"text": "病気の進行を遅らせるために、毎日薬を飲んでいる。", "target_word": "進行", "complexity_tier": "T3", "furigana": "病気(びょうき)の進行(しんこう)を遅(おく)らせるために、毎日(まいにち)薬(くすり)を飲(の)んでいる。", "sentence_source": "generated"}, {"text": "台風の進行が遅く、雨が三日も続いた。", "target_word": "進行", "complexity_tier": "T2", "furigana": "台風(たいふう)の進行(しんこう)が遅(おそ)く、雨(あめ)が三日(みっか)も続(つづ)いた。", "sentence_source": "generated"}, {"text": "作業の進行を妨げるものは、早めに取り除いておこう。", "target_word": "進行", "complexity_tier": "T3", "furigana": "作業(さぎょう)の進行(しんこう)を妨(さまた)げるものは、早(はや)めに取(と)り除(のぞ)いておこう。", "sentence_source": "generated"}, {"text": "物語の進行に合わせて、登場人物の関係も少しずつ変わっていく。", "target_word": "進行", "complexity_tier": "T4", "furigana": "物語(ものがたり)の進行(しんこう)に合(あ)わせて、登場人物(とうじょうじんぶつ)の関係(かんけい)も少(すこ)しずつ変(か)わっていく。", "sentence_source": "generated"}, {"text": "虫歯は進行すると、神経まで痛むことがある。", "target_word": "進行", "complexity_tier": "T3", "furigana": "虫歯(むしば)は進行(しんこう)すると、神経(しんけい)まで痛(いた)むことがある。", "sentence_source": "generated"}, {"text": "計画の進行が遅れているので、チーム全員で作業を見直した。", "target_word": "進行", "complexity_tier": "T3", "furigana": "計画(けいかく)の進行(しんこう)が遅(おく)れているので、チーム全員(ぜんいん)で作業(さぎょう)を見直(みなお)した。", "sentence_source": "generated"}, {"text": "近視の進行を防ぐには、目を休める時間が大切だ。", "target_word": "進行", "complexity_tier": "T3", "furigana": "近視(きんし)の進行(しんこう)を防(ふせ)ぐには、目(め)を休(やす)める時間(じかん)が大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "交渉は順調に進行しており、来月には合意できる見込みだ。", "target_word": "進行", "complexity_tier": "T4", "furigana": "交渉(こうしょう)は順調(じゅんちょう)に進行(しんこう)しており、来月(らいげつ)には合意(ごうい)できる見込(みこ)みだ。", "sentence_source": "generated"}, {"text": "プロジェクトの進行を、図にしてみんなに見せた。", "target_word": "進行", "complexity_tier": "T3", "furigana": "プロジェクトの進行(しんこう)を、図(ず)にしてみんなに見(み)せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進行", "label": "基本形"}, {"form": "進行する", "label": "終止形"}, {"form": "進行した", "label": "過去形"}, {"form": "進行して", "label": "て形"}, {"form": "進行しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "ことがらがどんどん先へ進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進行", "is_correct": true, "explanation": "ことがらがどんどん進む様子を表し、工事が順調に進む文脈に合う。"}, {"text": "余白", "is_correct": false, "explanation": "空いている部分を指し、工事の進み具合を表す語として文に合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の様子を指し、工事の経過を表す語として文に収まらない。"}, {"text": "床面積", "is_correct": false, "explanation": "建物の面積を指し、工事の進み具合とは結びつかない。"}], "explanations": {"進行": "ことがらがどんどん進む様子を表し、工事が順調に進む文脈に合う。", "余白": "空いている部分を指し、工事の進み具合を表す語として文に合わない。", "色彩": "色の様子を指し、工事の経過を表す語として文に収まらない。", "床面積": "建物の面積を指し、工事の進み具合とは結びつかない。"}, "sentence_index": 0, "correct_answer": "進行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来春は専門学校に進行する予定だ。", "explanation": "ここは〈進学〉の意味と取った誤用。進行は物事が先へ進むことで、学校へ上がる意味では使わない。"}, {"text": "優勝者には賞金を進行します。", "explanation": "ここは〈進呈〉の意味と取った誤用。進行はことがらが進む意味で、賞金を贈る意味では使わない。"}, {"text": "彼女は部署の進行を辞めて、転職した。", "explanation": "ここは〈退職〉の意味と取った誤用。進行はことがらの経過で、人が辞める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進行", "is_correct": true, "explanation": "ことがらが先へ進む様子を表し、計画が遅れている文脈に合う。"}, {"text": "香り", "is_correct": false, "explanation": "においを指し、計画の進み具合を表す語として文に収まらない。"}, {"text": "体積", "is_correct": false, "explanation": "物の大きさを指し、計画の経過とは結びつかない。"}, {"text": "重量", "is_correct": false, "explanation": "物の重さを指し、計画の進み具合を表す語ではない。"}], "explanations": {"進行": "ことがらが先へ進む様子を表し、計画が遅れている文脈に合う。", "香り": "においを指し、計画の進み具合を表す語として文に収まらない。", "体積": "物の大きさを指し、計画の経過とは結びつかない。", "重量": "物の重さを指し、計画の進み具合を表す語ではない。"}, "sentence_index": 6, "correct_answer": "進行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桜が進行した。", "explanation": "ここは〈開花〉の意味。進行はことがらが先へ進む変化で、花が咲く現象には使わない。"}, {"text": "お湯が進行した。", "explanation": "ここは〈沸騰〉の意味。進行はことがらの経過を表し、湯が沸く現象には使わない。"}, {"text": "ろうそくが進行した。", "explanation": "ここは〈点火〉の意味。進行は物事が先へ進むことで、火がともる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が続き、工事の進行を止まった。", "corrected_sentence": "雨が続き、工事の進行が止まった。", "error_description": "「止まる」は自動詞で主語を「が」で示す。「進行が止まった」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39142, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい計画の進行が順調した。", "corrected_sentence": "新しい計画の進行が順調だ。", "error_description": "「順調」は形容動詞なので「だ」と組む。「した」は誤った活用で、正しくは「順調だ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
