INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「妨げる」の目的語を示す「を」で、進行を対象にとる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「妨げる」は目的語をとるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示し、妨げる対象には使わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、目的語を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「妨げる」の目的語を示す「を」で、進行を対象にとる。", "が": "主語を示すが、「妨げる」は目的語をとるので合わない。", "に": "方向や相手を示し、妨げる対象には使わない。", "で": "手段や場所を示し、目的語を示すことはできない。"}, "error_tags": {"が": "subject", "に": "recipient/target", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が進んでいくこと。", "primary_collocate": null, "pronunciation": "しんこう", "ipa": "ɕiŋkoː", "syllable_count": 4, "sentences": [{"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "進行", "complexity_tier": "T5", "furigana": "指先(ゆびさき)を通(つう)じて伝(つた)わる生地(きじ)の微妙(びみょう)な弾力(だんりょく)や発酵(はっこう)の進行具合(しんこうぐあい)を唯一(ゆいいつ)の羅針盤(らしんばん)とし、彼(かれ)は温度(おんど)と湿度(しつど)という変数(へんすう)を緻密(ちみつ)に制御(せいぎょ)することで、微生物(びせいぶつ)という目(め)に見(み)えぬパートナーとの静(しず)かなる対話(たいわ)を試(こころ)みる。", "sentence_source": "mined"}, {"text": "新しい道路の工事は順調に進行しており、来月には完成する予定だ。", "target_word": "進行", "complexity_tier": "T3", "furigana": "新(あたら)しい道路(どうろ)の工事(こうじ)は順調(じゅんちょう)に進行(しんこう)しており、来月(らいげつ)には完成(かんせい)する予定(よてい)だ。", "sentence_source": "generated"}, {"text": "病気の進行が早いと、医者から説明を受けた。", "target_word": "進行", "complexity_tier": "T3", "furigana": "病気(びょうき)の進行(しんこう)が早(はや)いと、医者(いしゃ)から説明(せつめい)を受(う)けた。", "sentence_source": "generated"}, {"text": "雪のせいで作業の進行が遅れ、夜まで残業になった。", "target_word": "進行", "complexity_tier": "T3", "furigana": "雪(ゆき)のせいで作業(さぎょう)の進行(しんこう)が遅(おく)れ、夜(よる)まで残業(ざんぎょう)になった。", "sentence_source": "generated"}, {"text": "地球温暖化の進行を止めるには、世界の協力が必要だ。", "target_word": "進行", "complexity_tier": "T4", "furigana": "地球温暖化(ちきゅうおんだんか)の進行(しんこう)を止(と)めるには、世界(せかい)の協力(きょうりょく)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "話の進行に合わせて、スライドを一枚ずつ切り替えた。", "target_word": "進行", "complexity_tier": "T3", "furigana": "話(はなし)の進行(しんこう)に合(あ)わせて、スライドを一枚(いちまい)ずつ切(き)り替(か)えた。", "sentence_source": "generated"}, {"text": "手続きの進行が見えないと、客は不安になる。", "target_word": "進行", "complexity_tier": "T3", "furigana": "手続(てつづ)きの進行(しんこう)が見(み)えないと、客(きゃく)は不安(ふあん)になる。", "sentence_source": "generated"}, {"text": "試合の進行を妨げた観客は、会場の外に出された。", "target_word": "進行", "complexity_tier": "T4", "furigana": "試合(しあい)の進行(しんこう)を妨(さまた)げた観客(かんきゃく)は、会場(かいじょう)の外(そと)に出(だ)された。", "sentence_source": "generated"}, {"text": "彼の病気は進行していて、もう歩くのも難しい。", "target_word": "進行", "complexity_tier": "T3", "furigana": "彼(かれ)の病気(びょうき)は進行(しんこう)していて、もう歩(ある)くのも難(むずか)しい。", "sentence_source": "generated"}, {"text": "筋力の低下は年とともに進行する。", "target_word": "進行", "complexity_tier": "T3", "furigana": "筋力(きんりょく)の低下(ていか)は年(とし)とともに進行(しんこう)する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進行", "label": "基本形"}, {"form": "進行する", "label": "終止形"}, {"form": "進行した", "label": "過去形"}, {"form": "進行して", "label": "て形"}, {"form": "進行しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "物事が先へ進んでいくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 指先 (Zipf 3.6), 弾力 (Zipf 3.23), 羅針盤 (Zipf 3.09), 変数 (Zipf 3.63), 緻密 (Zipf 3.25), 微生物 (Zipf 3.52)']::text[], 'fec94350-78de-4e5d-8b16-b06d6deb20bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進行", "is_correct": true, "explanation": "物事が先へ進んでいく様子を表し、発酵が進む文脈に合う。"}, {"text": "解体", "is_correct": false, "explanation": "物を分けて壊すことを指し、発酵の進み具合の文脈には合わない。"}, {"text": "静止", "is_correct": false, "explanation": "動きが止まることを指し、発酵の進行を表す文とは矛盾する。"}, {"text": "残量", "is_correct": false, "explanation": "残っている分量を指し、発酵の進み具合を表す語としては文に合わない。"}], "explanations": {"進行": "物事が先へ進んでいく様子を表し、発酵が進む文脈に合う。", "解体": "物を分けて壊すことを指し、発酵の進み具合の文脈には合わない。", "静止": "動きが止まることを指し、発酵の進行を表す文とは矛盾する。", "残量": "残っている分量を指し、発酵の進み具合を表す語としては文に合わない。"}, "sentence_index": 0, "correct_answer": "進行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来春は大学に進行する予定だ。", "explanation": "ここは〈進学〉の意味と取った誤用。進行は物事が先へ進むことで、学校へ上がる意味では使わない。"}, {"text": "優勝者には記念品を進行します。", "explanation": "ここは〈進呈〉の意味と取った誤用。進行は物事の経過を表すので、物を贈る意味では使わない。"}, {"text": "彼は会社の進行を辞めた。", "explanation": "ここは〈退職〉の意味と取った誤用。進行は物事の経過で、人が辞める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進行", "is_correct": true, "explanation": "物事が先へ進んでいく様子を表し、手続きが進む文脈に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "色の様子を指し、手続きの進み具合を表す語として文に合わない。"}, {"text": "床面積", "is_correct": false, "explanation": "建物の面積を指し、手続きの経過とは結びつかない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分が失われる状態を指し、手続きの進み具合を表す語ではない。"}], "explanations": {"進行": "物事が先へ進んでいく様子を表し、手続きが進む文脈に合う。", "色彩": "色の様子を指し、手続きの進み具合を表す語として文に合わない。", "床面積": "建物の面積を指し、手続きの経過とは結びつかない。", "乾燥": "水分が失われる状態を指し、手続きの進み具合を表す語ではない。"}, "sentence_index": 6, "correct_answer": "進行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気温が進行した。", "explanation": "ここは〈上昇〉の意味。進行は物事が先へ進む変化を言い、数値が上がる変化には使わない。"}, {"text": "種が進行した。", "explanation": "ここは〈発芽〉の意味。進行は物事の経過を表し、種が芽を出す変化には使わない。"}, {"text": "人口が進行した。", "explanation": "ここは〈増加〉の意味。進行は物事が先へ進むことで、人数が増える変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業の進行を遅れている。", "corrected_sentence": "作業の進行が遅れている。", "error_description": "「遅れる」は主語を「が」で示す自動詞。「進行が遅れている」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39143, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交渉の進行が順調した。", "corrected_sentence": "交渉の進行が順調だ。", "error_description": "「順調」は形容動詞なので「だ」と組む。「した」は誤った活用で、正しくは「順調だ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df117243-75bd-4426-8437-0dd636b33d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ケーキの仕上げ」の「の」で、名詞同士をつなぐ連体修飾を表し、この文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「ケーキを仕上げ」は目的語の「を」になり、名詞修飾の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ケーキに仕上げに」と「に」が続いて不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「ケーキへ仕上げ」では名詞修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「ケーキの仕上げ」の「の」で、名詞同士をつなぐ連体修飾を表し、この文に合う。", "を": "「ケーキを仕上げ」は目的語の「を」になり、名詞修飾の文として成り立たない。", "に": "「ケーキに仕上げに」と「に」が続いて不自然になる。", "へ": "「へ」は方向を示す。「ケーキへ仕上げ」では名詞修飾にならない。"}, "error_tags": {"を": "目的語", "に": "位置・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「仕上げを行う」の「を」で、行為の対象を表し、この文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「仕上げに行う」は行為の対象を示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「仕上げと行う」は並列の意味になり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「仕上げへ行う」は行為の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「仕上げを行う」の「を」で、行為の対象を表し、この文に合う。", "に": "「仕上げに行う」は行為の対象を示せず、不自然。", "と": "「仕上げと行う」は並列の意味になり、文として成り立たない。", "へ": "「へ」は方向を示す。「仕上げへ行う」は行為の対象にならない。"}, "error_tags": {"に": "位置・対象", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを作るときに、最後にきれいに整えること。", "primary_collocate": null, "pronunciation": "しあげ", "ipa": "ɕiaɡe", "syllable_count": 3, "sentences": [{"text": "絵の仕上げに、細い筆で目を描き入れた。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "絵[え]の仕上[しあ]げに、細[ほそ]い筆[ふで]で目[め]を描[か]き入[い]れた。", "sentence_source": "generated"}, {"text": "ケーキの仕上げに、白いクリームと果物をのせます。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "ケーキの仕上[しあ]げに、白[しろ]いクリームと果物[くだもの]をのせます。", "sentence_source": "generated"}, {"text": "洋服の仕上げは、アイロンでしわをのばすことです。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "洋服[ようふく]の仕上[しあ]げは、アイロンでしわをのばすことです。", "sentence_source": "generated"}, {"text": "木の机は、やすりをかけるのが最後の仕上げだ。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "木[き]の机[つくえ]は、やすりをかけるのが最後[さいご]の仕上[しあ]げだ。", "sentence_source": "generated"}, {"text": "料理の仕上げに、ねぎを少しのせるときれいに見える。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "料理[りょうり]の仕上[しあ]げに、ねぎを少[すこ]しのせるときれいに見[み]える。", "sentence_source": "generated"}, {"text": "手作りのかばんは、仕上げのていねいさで見た目が大きく変わる。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "手作[てづく]りのかばんは、仕上[しあ]げのていねいさで見[み]た目[め]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "髪の仕上げにスプレーをかけると、形が崩れにくい。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "髪[かみ]の仕上[しあ]げにスプレーをかけると、形[かたち]が崩[くず]れにくい。", "sentence_source": "generated"}, {"text": "この工場では、車の最後の仕上げを手作業で行っている。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、車[くるま]の最後[さいご]の仕上[しあ]げを手作業[てさぎょう]で行[おこな]っている。", "sentence_source": "generated"}, {"text": "歯みがきの仕上げは、親が子どもの歯をみがく。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "歯[は]みがきの仕上[しあ]げは、親[おや]が子[こ]どもの歯[は]をみがく。", "sentence_source": "generated"}, {"text": "陶器は焼いたあと、表面をみがく仕上げが必要だ。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "陶器[とうき]は焼[や]いたあと、表面[ひょうめん]をみがく仕上[しあ]げが必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕上げ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物を作る最後にきれいに整える作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)','sentence 9 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)']::text[], 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕上げ", "is_correct": true, "explanation": "作品の最後に細部を整える段階を表し、「絵の仕上げに目を描き入れた」として自然。"}, {"text": "絵の具", "is_correct": false, "explanation": "画材の名前で、目を描き入れる段階を表す語として合わない。"}, {"text": "題名", "is_correct": false, "explanation": "作品の名前で、筆で目を描く作業の段階を表さないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取る作業で、絵に目を描き入れる文脈には合わない。"}], "explanations": {"仕上げ": "作品の最後に細部を整える段階を表し、「絵の仕上げに目を描き入れた」として自然。", "絵の具": "画材の名前で、目を描き入れる段階を表す語として合わない。", "題名": "作品の名前で、筆で目を描く作業の段階を表さないので合わない。", "掃除": "汚れを取る作業で、絵に目を描き入れる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "仕上げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スープの仕上げは、野菜を三時間煮込むことだ。", "explanation": "ここは〈煮込み〉の意味。煮込みは作る途中の大事な工程で、最後の段階を指す〈仕上げ〉とは言わないので合わない。"}, {"text": "料理の仕上げとして、野菜を洗って切っておく。", "explanation": "ここは〈下準備〉の意味。仕上げは最後の段階なので、洗って切る準備作業には合わない。"}, {"text": "店の仕上げは朝五時から始まる。", "explanation": "ここは〈仕込み〉の意味。仕上げは最後の段階なので、朝から始まる準備作業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕上げ", "is_correct": true, "explanation": "整える最後の段階を表し、「髪の仕上げにスプレーをかける」として自然。"}, {"text": "長さ", "is_correct": false, "explanation": "髪の長さは状態を表す語で、スプレーをかける段階を表さないので合わない。"}, {"text": "太さ", "is_correct": false, "explanation": "髪の太さは状態を表す語で、スプレーをかける段階を表さないので合わない。"}, {"text": "本数", "is_correct": false, "explanation": "髪の本数は数を表す語で、整える作業の段階を表さないので合わない。"}], "explanations": {"仕上げ": "整える最後の段階を表し、「髪の仕上げにスプレーをかける」として自然。", "長さ": "髪の長さは状態を表す語で、スプレーをかける段階を表さないので合わない。", "太さ": "髪の太さは状態を表す語で、スプレーをかける段階を表さないので合わない。", "本数": "髪の本数は数を表す語で、整える作業の段階を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "仕上げ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁は色を塗る前に、まず仕上げを塗っておく。", "explanation": "ここは〈下地〉の意味。仕上げは最後の段階なので、色を塗る前の下塗りには合わない。"}, {"text": "木の板は、まず仕上げをしてから形を整える。", "explanation": "ここは〈荒削り〉の意味。最初の大まかな加工は仕上げとは言わないので合わない。"}, {"text": "肉は焼く前に、塩で仕上げをしておく。", "explanation": "ここは〈下味〉の意味。仕上げは最後の段階なので、焼く前に味をつける下味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "スープを仕上げに、ねぎを少しのせます。", "corrected_sentence": "スープの仕上げに、ねぎを少しのせます。", "error_description": "「スープの仕上げ」の「の」が必要。「を」は動作の目的語を示すので、名詞「仕上げ」の前には使わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39144, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子の仕上げを作って、きれいに見せた。", "corrected_sentence": "椅子の仕上げをして、きれいに見せた。", "error_description": "「仕上げ」は「する」「行う」と組む。「作る」は不自然な組み合わせ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「仕上げをした」の「を」。仕上げは「した」の直接の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「仕上げがした」は文として成り立たず、「が」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「仕上げへした」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「仕上げよりした」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「仕上げをした」の「を」。仕上げは「した」の直接の目的語になる。", "が": "「仕上げがした」は文として成り立たず、「が」は合わない。", "へ": "方向を表すので、「仕上げへした」は意味が通らない。", "より": "比較を表すので、「仕上げよりした」とは続かない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
