INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の最後の段階で、細かいところを整えたり、完成度を高めたりすること。", "primary_collocate": null, "pronunciation": "しあげ", "ipa": "ɕiaɡe", "syllable_count": 3, "sentences": [{"text": "論文の提出が近いので、今週は仕上げの作業に追われている。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "論文[ろんぶん]の提出[ていしゅつ]が近[ちか]いので、今週[こんしゅう]は仕上[しあ]げの作業[さぎょう]に追[お]われている。", "sentence_source": "generated"}, {"text": "練習の最後に、本番と同じ通しで演奏して仕上げをした。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の最後[さいご]に、本番[ほんばん]と同[おな]じ通[とお]しで演奏[えんそう]して仕上[しあ]げをした。", "sentence_source": "generated"}, {"text": "試験前の仕上げに、間違えた問題をもう一度解き直した。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "試験[しけん]前[まえ]の仕上[しあ]げに、間違[まちが]えた問題[もんだい]をもう一度[いちど]解[と]き直[なお]した。", "sentence_source": "generated"}, {"text": "工事は仕上げの段階に入り、壁の細かい傷を直している。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "工事[こうじ]は仕上[しあ]げの段階[だんかい]に入[はい]り、壁[かべ]の細[こま]かい傷[きず]を直[なお]している。", "sentence_source": "generated"}, {"text": "報告書の仕上げでは、数字と誤字をもう一度確認する。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の仕上[しあ]げでは、数字[すうじ]と誤字[ごじ]をもう一度[いちど]確認[かくにん]する。", "sentence_source": "generated"}, {"text": "発表会まであと三日なので、今日から仕上げの練習に入る。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "発表会[はっぴょうかい]まであと三日[みっか]なので、今日[きょう]から仕上[しあ]げの練習[れんしゅう]に入[はい]る。", "sentence_source": "generated"}, {"text": "彼の作品は仕上げが細かく、遠くから見ても完成度が高い。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "彼[かれ]の作品[さくひん]は仕上[しあ]げが細[こま]かく、遠[とお]くから見[み]ても完成度[かんせいど]が高[たか]い。", "sentence_source": "generated"}, {"text": "企画書の内容は良いが、仕上げが雑で、読みにくい。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "企画書[きかくしょ]の内容[ないよう]は良[よ]いが、仕上[しあ]げが雑[ざつ]で、読[よ]みにくい。", "sentence_source": "generated"}, {"text": "大きな仕事ほど、仕上げに時間をかけることが大切だ。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "大[おお]きな仕事[しごと]ほど、仕上[しあ]げに時間[じかん]をかけることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "完成まであと少しなので、みんなで仕上げに取りかかろう。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "完成[かんせい]まであと少[すこ]しなので、みんなで仕上[しあ]げに取[と]りかかろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕上げ", "label": "基本形"}], "register": "標準", "sense_fingerprint": "物事の最終段階で細部を整え完成度を高める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 取りかかろ (Zipf 1.52)']::text[], 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕上げ", "is_correct": true, "explanation": "「仕上げの作業」は最終段階の作業を指し、締め切り前に追われる内容として自然に入る。"}, {"text": "中断", "is_correct": false, "explanation": "「中断の作業」は意味が通らず、作業に追われている文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は「作業」の内容にならず、「作業に追われている」と合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "結婚は作業の対象にならないので、この空欄には入らない。"}], "explanations": {"仕上げ": "「仕上げの作業」は最終段階の作業を指し、締め切り前に追われる内容として自然に入る。", "中断": "「中断の作業」は意味が通らず、作業に追われている文脈に合わない。", "散歩": "散歩は「作業」の内容にならず、「作業に追われている」と合わない。", "結婚": "結婚は作業の対象にならないので、この空欄には入らない。"}, "sentence_index": 0, "correct_answer": "仕上げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まず資料を集めるという仕上げの段階が、この仕事では一番大切だ。", "explanation": "ここは〈最初の段階〉の意味。仕上げは最後の段階や細部を整えることなので、資料集めには合わない。"}, {"text": "料理の仕上げとして、野菜を先に切っておく。", "explanation": "ここは〈下準備〉の意味。仕上げは最後の作業なので、先に行う野菜の切り分けには合わない。"}, {"text": "この事件の仕上げは、小さな誤解だった。", "explanation": "ここは〈発端〉の意味。仕上げは終わりの段階を指すので、事件の始まりを表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕上げ", "is_correct": true, "explanation": "「仕上げが細かく」は作品の仕上がりの細やかさを表し、完成度の文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が細かく」は意味が通らず、作品の説明にならない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便が細かく」は不自然で、作品の特徴を表せない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は作品の性質を表す語にならず、「細かく」と合わない。"}], "explanations": {"仕上げ": "「仕上げが細かく」は作品の仕上がりの細やかさを表し、完成度の文脈に合う。", "天気": "「天気が細かく」は意味が通らず、作品の説明にならない。", "郵便": "「郵便が細かく」は不自然で、作品の特徴を表せない。", "旅行": "旅行は作品の性質を表す語にならず、「細かく」と合わない。"}, "sentence_index": 6, "correct_answer": "仕上げ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新人の仕上げの時期は、雑用ばかりだった。", "explanation": "ここは〈下積み〉の意味。仕上げは最後の段階なので、雑用が多い初期の時期には合わない。"}, {"text": "練習の前に、選手の仕上げを決めておく。", "explanation": "ここは〈選手の配置〉の意味。仕上げは作業の最後に細部を整えることなので、人の配置を決める意味では使えない。"}, {"text": "明日の天気を仕上げておく。", "explanation": "ここは〈確認〉の意味。仕上げは作業の最後に細部を整えることなので、天気を確かめる行為には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今週は、論文の仕上げを追われている。", "corrected_sentence": "今週は、論文の仕上げに追われている。", "error_description": "「追われる」は「に」を取るので、仕上げに続く「を」が誤り。正しくは「仕上げに追われている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の仕上げな会議は、三時からだ。", "corrected_sentence": "来週の仕上げの会議は、三時からだ。", "error_description": "「仕上げ」は名詞なので、後ろの名詞を修飾するには「の」を使う。「な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「量る」は目的語に「を」を取るので、「薬品を慎重に量りました」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」では「量る」の対象が示せず、「薬品に慎重に量る」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「薬品で量る」は文の意味に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、量るのは先生なので、薬品を主語にすると合わない。"}], "correct_answer": "を", "explanations": {"を": "「量る」は目的語に「を」を取るので、「薬品を慎重に量りました」が正しい。", "に": "「に」では「量る」の対象が示せず、「薬品に慎重に量る」は成り立たない。", "で": "「で」は手段や場所を示すので、「薬品で量る」は文の意味に合わない。", "が": "「が」は主語を示すが、量るのは先生なので、薬品を主語にすると合わない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「入る」の主語は「薬品」なので、「薬品が目に入った」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らないので、「薬品を目に入った」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「薬品と目に入った」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「目に入る」は「に」で結ぶ定型なので合わない。"}], "correct_answer": "が", "explanations": {"が": "「入る」の主語は「薬品」なので、「薬品が目に入った」が正しい。", "を": "「入る」は目的語を取らないので、「薬品を目に入った」は不自然。", "と": "「と」は並列や相手を示すので、「薬品と目に入った」は意味が通らない。", "へ": "「へ」は方向を示すが、「目に入る」は「に」で結ぶ定型なので合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気を治したり、実験に使ったりする、特別なもののことです。", "primary_collocate": null, "pronunciation": "やくひん", "ipa": "jakɯçiɴ", "syllable_count": 4, "sentences": [{"text": "病院の棚には、たくさんの薬品が並んでいます。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "病院[びょういん]の棚[たな]には、たくさんの薬品[やくひん]が並[なら]んでいます。", "sentence_source": "generated"}, {"text": "理科の実験で、先生は薬品を慎重に量りました。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "理科[りか]の実験[じっけん]で、先生[せんせい]は薬品[やくひん]を慎重[しんちょう]に量[はか]りました。", "sentence_source": "generated"}, {"text": "この薬品は、子どもの手が届かない所に置いてください。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "この薬品[やくひん]は、子[こ]どもの手[て]が届[とど]かない所[ところ]に置[お]いてください。", "sentence_source": "generated"}, {"text": "薬品のにおいが強くて、部屋の窓を開けました。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "薬品[やくひん]のにおいが強[つよ]くて、部屋[へや]の窓[まど]を開[あ]けました。", "sentence_source": "generated"}, {"text": "実験が終わったら、使った薬品を元の棚に戻します。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "実験[じっけん]が終[お]わったら、使[つか]った薬品[やくひん]を元[もと]の棚[たな]に戻[もど]します。", "sentence_source": "generated"}, {"text": "薬品を間違えて混ぜると、危ないことがあります。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "薬品[やくひん]を間違[まちが]えて混[ま]ぜると、危[あぶ]ないことがあります。", "sentence_source": "generated"}, {"text": "研究所[けんきゅうじょ]では、病気[びょうき]を治[なお]す新[あたら]しい薬品[やくひん]を実験[じっけん]で試[ため]しています。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]では、病気[びょうき]を治[なお]す新[あたら]しい薬品[やくひん]を実験[じっけん]で試[ため]しています。", "sentence_source": "generated"}, {"text": "薬品が目に入ったので、すぐに水で洗いました。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "薬品[やくひん]が目[め]に入[はい]ったので、すぐに水[みず]で洗[あら]いました。", "sentence_source": "generated"}, {"text": "使[つか]い終[お]わって古[ふる]くなった薬品[やくひん]は、決[き]まった方法[ほうほう]で処分[しょぶん]します。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わって古[ふる]くなった薬品[やくひん]は、決[き]まった方法[ほうほう]で処分[しょぶん]します。", "sentence_source": "generated"}, {"text": "学校の理科室には、薬品の管理を決めたルールがあります。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "学校[がっこう]の理科室[りかしつ]には、薬品[やくひん]の管理[かんり]を決[き]めたルールがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "薬品", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気の治療や理科の実験に使う薬や液体などの物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: きゅうじょ (Zipf 1.61), じっけん (Zipf 1.68)']::text[], '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薬品", "is_correct": true, "explanation": "病院の棚に並ぶ薬や試薬を指す「薬品」が、文の内容に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合を表す語で、棚に並べる物ではないので合わない。"}, {"text": "症状", "is_correct": false, "explanation": "病気によって現れる体の様子を指し、棚に並ぶものではないので合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温かさの度合いを指し、棚に並ぶものではないので合わない。"}], "explanations": {"薬品": "病院の棚に並ぶ薬や試薬を指す「薬品」が、文の内容に合う。", "湿度": "空気中の水分の割合を表す語で、棚に並べる物ではないので合わない。", "症状": "病気によって現れる体の様子を指し、棚に並ぶものではないので合わない。", "体温": "体の温かさの度合いを指し、棚に並ぶものではないので合わない。"}, "sentence_index": 0, "correct_answer": "薬品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬品は、とてもおいしいので毎日食べています。", "explanation": "ここは〈食品〉の意味。おいしく食べる物は食品で、薬品は病気の治療や実験に使うので合わない。"}, {"text": "午後から薬品が降り出したので、傘をさして帰りました。", "explanation": "ここは〈雨〉の意味。降り出すのは雨で、化学物質の薬品は空から降らないので合わない。"}, {"text": "会議には、薬品が三人出席した。", "explanation": "ここは〈社員〉の意味。会議に出席するのは人で、薬品は物質なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薬品", "is_correct": true, "explanation": "病気を治す新しい薬品を実験で試す、という文の内容に合う。"}, {"text": "血圧", "is_correct": false, "explanation": "血管内の圧力を指し、実験で新しく試す対象ではないので合わない。"}, {"text": "脈拍", "is_correct": false, "explanation": "心臓の拍動の回数を指し、新しく試す対象ではないので合わない。"}, {"text": "呼吸", "is_correct": false, "explanation": "息を吸ったり吐いたりする働きを指し、試す対象ではないので合わない。"}], "explanations": {"薬品": "病気を治す新しい薬品を実験で試す、という文の内容に合う。", "血圧": "血管内の圧力を指し、実験で新しく試す対象ではないので合わない。", "脈拍": "心臓の拍動の回数を指し、新しく試す対象ではないので合わない。", "呼吸": "息を吸ったり吐いたりする働きを指し、試す対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "薬品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬品は、有名な画家が描いた作品です。", "explanation": "ここは〈作品〉の意味。絵や小説などは作品と言い、化学的な物質の薬品は合わない。"}, {"text": "来週の試合で、この薬品が二点目のゴールを決めた。", "explanation": "ここは〈選手〉の意味。ゴールを決めるのは選手で、化学物質の薬品は試合に出ないので合わない。"}, {"text": "寒いので、薬品を着て出かけました。", "explanation": "ここは〈衣服〉の意味。着るものは衣服で、薬品は身につけられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬品を入った瓶を棚に戻しました。", "corrected_sentence": "薬品が入った瓶を棚に戻しました。", "error_description": "「入る」は主語を取る動詞なので「薬品が入った」と「が」を使う。「を」は他動詞の目的語に使うので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薬品が量った後、ふたを閉めてください。", "corrected_sentence": "薬品を量った後、ふたを閉めてください。", "error_description": "「量る」は他動詞なので目的語の「薬品」に「を」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「研究」を「薬品の」で修飾する連体修飾なので、「薬品の研究」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「薬品が研究に費用をかける」では会社の行為にならない。"}, {"text": "を", "is_correct": false, "explanation": "「費用をかける」の目的語がすでにあるので、「を」を重ねると不自然。"}, {"text": "に", "is_correct": false, "explanation": "「薬品に研究に」と「に」が重なり、「薬品に」は文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「研究」を「薬品の」で修飾する連体修飾なので、「薬品の研究」が正しい。", "が": "「が」は主語を示すが、「薬品が研究に費用をかける」では会社の行為にならない。", "を": "「費用をかける」の目的語がすでにあるので、「を」を重ねると不自然。", "に": "「薬品に研究に」と「に」が重なり、「薬品に」は文脈に合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「排水に含まれる薬品」を文の話題として示すので、「は」が自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「薬品へ影響を与える」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "「含まれる」は受け身で目的語を取れないので、「を」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾なので、「薬品の、」と区切ると文の主語が立たない。"}], "correct_answer": "は", "explanations": {"は": "「排水に含まれる薬品」を文の話題として示すので、「は」が自然。", "へ": "「へ」は方向を示すが、「薬品へ影響を与える」は不自然。", "を": "「含まれる」は受け身で目的語を取れないので、「を」では文が成り立たない。", "の": "「の」は連体修飾なので、「薬品の、」と区切ると文の主語が立たない。"}, "error_tags": {"へ": "方向", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "化学的な性質を持つ物質で、医薬や工業など様々な分野で使用されるもの。", "primary_collocate": null, "pronunciation": "やくひん", "ipa": "jakɯçiɴ", "syllable_count": 4, "sentences": [{"text": "この工場では、医薬にも工業にも使う薬品を作っています。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、医薬[いやく]にも工業[こうぎょう]にも使[つか]う薬品[やくひん]を作[つく]っています。", "sentence_source": "generated"}, {"text": "その会社は、薬品の研究に多くの費用をかけている。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は、薬品[やくひん]の研究[けんきゅう]に多[おお]くの費用[ひよう]をかけている。", "sentence_source": "generated"}, {"text": "薬品の純度が低いと、製品の品質が落ちてしまう。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "薬品[やくひん]の純度[じゅんど]が低[ひく]いと、製品[せいひん]の品質[ひんしつ]が落[お]ちてしまう。", "sentence_source": "generated"}, {"text": "工場の薬品は、法律に従って厳しく保管されている。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "工場[こうじょう]の薬品[やくひん]は、法律[ほうりつ]に従[したが]って厳[きび]しく保管[ほかん]されている。", "sentence_source": "generated"}, {"text": "染料を落とすために、強い薬品を使って布を処理した。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "染料[せんりょう]を落[お]とすために、強[つよ]い薬品[やくひん]を使[つか]って布[ぬの]を処理[しょり]した。", "sentence_source": "generated"}, {"text": "研究者は薬品の性質を調べ、安全な使い方を報告した。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は薬品[やくひん]の性質[せいしつ]を調[しら]べ、安全[あんぜん]な使[つか]い方[かた]を報告[ほうこく]した。", "sentence_source": "generated"}, {"text": "輸入した薬品が、税関で検査を受けている。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]した薬品[やくひん]が、税関[ぜいかん]で検査[けんさ]を受[う]けている。", "sentence_source": "generated"}, {"text": "排水に含まれる薬品は、川の生き物に影響を与えることがある。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "排水[はいすい]に含[ふく]まれる薬品[やくひん]は、川[かわ]の生[い]き物[もの]に影響[えいきょう]を与[あた]えることがある。", "sentence_source": "generated"}, {"text": "薬品の取り扱いには、専門の資格が必要である。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "薬品[やくひん]の取[と]り扱[あつか]いには、専門[せんもん]の資格[しかく]が必要[ひつよう]である。", "sentence_source": "generated"}, {"text": "半導体の製造には、さまざまな薬品が欠かせない。", "target_word": "薬品", "complexity_tier": "T3", "furigana": "半導体[はんどうたい]の製造[せいぞう]には、さまざまな薬品[やくひん]が欠[か]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "薬品", "label": "基本形"}], "register": "formal", "sense_fingerprint": "医薬や工業で使われる化学的な物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薬品", "is_correct": true, "explanation": "医薬や工業に使う化学的な物質を指し、「作っています」に合う。"}, {"text": "純度", "is_correct": false, "explanation": "物質の混じりけのなさを表す語で、作る対象ではないので合わない。"}, {"text": "性質", "is_correct": false, "explanation": "物の特徴を表す語で、作る対象ではないので合わない。"}, {"text": "反応", "is_correct": false, "explanation": "化学変化そのものを指し、工場で作る対象ではないので合わない。"}], "explanations": {"薬品": "医薬や工業に使う化学的な物質を指し、「作っています」に合う。", "純度": "物質の混じりけのなさを表す語で、作る対象ではないので合わない。", "性質": "物の特徴を表す語で、作る対象ではないので合わない。", "反応": "化学変化そのものを指し、工場で作る対象ではないので合わない。"}, "sentence_index": 0, "correct_answer": "薬品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の薬品は、毎朝工場長に挨拶をする。", "explanation": "ここは〈社員〉の意味。挨拶をするのは人で、薬品は物質なので合わない。"}, {"text": "この工場では、薬品を組み立てて製品を作ります。", "explanation": "ここは〈部品〉の意味。組み立てて製品にするのは部品で、薬品は組み立てられないので合わない。"}, {"text": "工場の薬品は、春になると庭で花を咲かせる。", "explanation": "ここは〈木〉の意味。花を咲かせるのは植物で、薬品は咲かせられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薬品", "is_correct": true, "explanation": "税関で検査を受ける輸入品としての化学的な物質を指し、文に合う。"}, {"text": "沸点", "is_correct": false, "explanation": "液体が沸騰する温度を表す語で、輸入して検査を受ける対象ではないので合わない。"}, {"text": "濃度", "is_correct": false, "explanation": "物質に含まれる割合を表す語で、輸入品そのものを指さないので合わない。"}, {"text": "酸化", "is_correct": false, "explanation": "物質が酸素と結びつく変化を表す語で、輸入して検査を受ける対象ではないので合わない。"}], "explanations": {"薬品": "税関で検査を受ける輸入品としての化学的な物質を指し、文に合う。", "沸点": "液体が沸騰する温度を表す語で、輸入して検査を受ける対象ではないので合わない。", "濃度": "物質に含まれる割合を表す語で、輸入品そのものを指さないので合わない。", "酸化": "物質が酸素と結びつく変化を表す語で、輸入して検査を受ける対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "薬品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の畑で、薬品が赤く熟して甘くなった。", "explanation": "ここは〈果物〉の意味。赤く熟して甘くなるのは果物で、化学物質の薬品は熟さないので合わない。"}, {"text": "幼児の遊び相手として、薬品を用意した。", "explanation": "ここは〈玩具〉の意味。遊び相手にするものは玩具で、薬品は遊び道具にならないので合わない。"}, {"text": "さまざまな薬品を着て、作業する。", "explanation": "ここは〈作業着〉の意味。着るものは衣服で、薬品は身につけないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "半導体の工場では、薬品に漏れを防ぐ装置を設置した。", "corrected_sentence": "半導体の工場では、薬品の漏れを防ぐ装置を設置した。", "error_description": "「漏れ」を修飾するには「薬品の」と連体修飾の「の」が必要。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39147, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薬品が混ぜた後、よく振ってください。", "corrected_sentence": "薬品を混ぜた後、よく振ってください。", "error_description": "「混ぜる」は他動詞なので目的語の「薬品」に「を」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「河川の水」と連体修飾で水の所属を示し、「河川の水が増えた」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「増える」は目的語を取らないので、「を」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「河川が水が増えた」と主語が二つ重なり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「河川へ水が増えた」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「河川の水」と連体修飾で水の所属を示し、「河川の水が増えた」が正しい。", "を": "「増える」は目的語を取らないので、「を」は不自然。", "が": "「河川が水が増えた」と主語が二つ重なり、不自然。", "へ": "「へ」は方向を示すが、「河川へ水が増えた」は意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の対象を示す「を」で、「河川を見ると」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すが、「見る」の対象には使わないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「河川と見ると」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、「河川の見ると」では動詞の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「見る」の対象を示す「を」で、「河川を見ると」が正しい。", "に": "「に」は位置や相手を示すが、「見る」の対象には使わないので合わない。", "と": "「と」は並列を示すので、「河川と見ると」は意味が通らない。", "の": "「の」は名詞をつなぐもので、「河川の見ると」では動詞の対象にならない。"}, "error_tags": {"に": "位置・相手", "と": "並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面を流れる、長くて細い水の道です。", "primary_collocate": null, "pronunciation": "かせん", "ipa": "kaseɴ", "syllable_count": 3, "sentences": [{"text": "この町には、大きな河川が三本流れています。", "target_word": "河川", "complexity_tier": "T3", "furigana": "この町[まち]には、大[おお]きな河川[かせん]が三本[さんぼん]流[なが]れています。", "sentence_source": "generated"}, {"text": "雨がたくさん降って、河川の水が増えました。", "target_word": "河川", "complexity_tier": "T3", "furigana": "雨[あめ]がたくさん降[ふ]って、河川[かせん]の水[みず]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "河川の近くは危ないので、大雨の日は行かないでください。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]の近[ちか]くは危[あぶ]ないので、大雨[おおあめ]の日[ひ]は行[い]かないでください。", "sentence_source": "generated"}, {"text": "山から海まで、河川は長い道のように続いています。", "target_word": "河川", "complexity_tier": "T3", "furigana": "山[やま]から海[うみ]まで、河川[かせん]は長[なが]い道[みち]のように続[つづ]いています。", "sentence_source": "generated"}, {"text": "夏になると、河川で泳ぐ子どもたちが多くなります。", "target_word": "河川", "complexity_tier": "T3", "furigana": "夏[なつ]になると、河川[かせん]で泳[およ]ぐ子[こ]どもたちが多[おお]くなります。", "sentence_source": "generated"}, {"text": "河川がよごれると、魚がすめなくなります。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]がよごれると、魚[さかな]がすめなくなります。", "sentence_source": "generated"}, {"text": "市は河川のごみを拾う活動を始めました。", "target_word": "河川", "complexity_tier": "T3", "furigana": "市[し]は河川[かせん]のごみを拾[ひろ]う活動[かつどう]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "橋の上から河川を見ると、水がゆっくり流れていました。", "target_word": "河川", "complexity_tier": "T3", "furigana": "橋[はし]の上[うえ]から河川[かせん]を見[み]ると、水[みず]がゆっくり流[なが]れていました。", "sentence_source": "generated"}, {"text": "日本は山が多いので、短くて速い河川が多いです。", "target_word": "河川", "complexity_tier": "T3", "furigana": "日本[にほん]は山[やま]が多[おお]いので、短[みじか]くて速[はや]い河川[かせん]が多[おお]いです。", "sentence_source": "generated"}, {"text": "地図では、河川を青い線で表します。", "target_word": "河川", "complexity_tier": "T3", "furigana": "地図[ちず]では、河川[かせん]を青[あお]い線[せん]で表[あらわ]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "河川", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地面を流れる川や、その水の道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: よごれる (Zipf 1.26)']::text[], '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河川", "is_correct": true, "explanation": "町を流れる大きな水の道を指し、「三本流れています」に合う。"}, {"text": "山脈", "is_correct": false, "explanation": "連なった山の列を指し、町の中を流れるものではないので合わない。"}, {"text": "海岸", "is_correct": false, "explanation": "海と陸の境目を指し、流れるものではないので合わない。"}, {"text": "湖", "is_correct": false, "explanation": "陸地にたまった水を指し、三本に分かれて流れるものではないので合わない。"}], "explanations": {"河川": "町を流れる大きな水の道を指し、「三本流れています」に合う。", "山脈": "連なった山の列を指し、町の中を流れるものではないので合わない。", "海岸": "海と陸の境目を指し、流れるものではないので合わない。", "湖": "陸地にたまった水を指し、三本に分かれて流れるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "河川"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町では、河川が毎朝、渋滞で混みます。", "explanation": "ここは〈道路〉の意味。渋滞で混むのは道路で、水の流れである河川は合わない。"}, {"text": "私の河川は、毎朝駅まで走っています。", "explanation": "ここは〈人〉の意味。駅まで走るのは人で、水の流れである河川は走らないので合わない。"}, {"text": "夏になると、河川を食べて暑さをしのぎます。", "explanation": "ここは〈かき氷〉の意味。暑さをしのぐために食べるのは食べ物で、河川は食べられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河川", "is_correct": true, "explanation": "市がごみを拾う対象となる、大きな水の道を指し、文に合う。"}, {"text": "標高", "is_correct": false, "explanation": "海抜の高さを表す語で、市がごみを拾う対象ではないので合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、ごみを拾う対象ではないので合わない。"}, {"text": "気圧", "is_correct": false, "explanation": "空気の圧力を表す語で、ごみを拾う対象ではないので合わない。"}], "explanations": {"河川": "市がごみを拾う対象となる、大きな水の道を指し、文に合う。", "標高": "海抜の高さを表す語で、市がごみを拾う対象ではないので合わない。", "気温": "空気の温度を表す語で、ごみを拾う対象ではないので合わない。", "気圧": "空気の圧力を表す語で、ごみを拾う対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "河川"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来春、河川が新入生として入学する予定だ。", "explanation": "ここは〈学生〉の意味。入学するのは人で、水の流れである河川は入学しないので合わない。"}, {"text": "高さ百メートルの河川は、遠くからも見えます。", "explanation": "ここは〈滝〉の意味。高い所から落ちる水は滝で、流れる河川は高さで語らないので合わない。"}, {"text": "釘を打つとき、ハンマーの代わりに河川を使いました。", "explanation": "ここは〈道具〉の意味。ハンマーの代わりに使うのは道具で、河川は水の流れなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
