INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39148, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河川に渡るとき、橋を使いましょう。", "corrected_sentence": "河川を渡るとき、橋を使いましょう。", "error_description": "「渡る」は目的語に「を」を取るので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「水質」を「河川の」で修飾する連体修飾なので、「河川の水質」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「河川が水質は」と主語が二つ重なり、文の構造が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「河川を水質は」では目的語の位置づけが合わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「河川へ水質は」では文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「水質」を「河川の」で修飾する連体修飾なので、「河川の水質」が正しい。", "が": "「河川が水質は」と主語が二つ重なり、文の構造が成り立たない。", "を": "「河川を水質は」では目的語の位置づけが合わず、文が成り立たない。", "へ": "「へ」は方向を示すが、「河川へ水質は」では文の意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「河口」を「大きな河川の」で修飾する連体修飾なので、「大きな河川の河口」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「大きな河川に河口には」と「に」が重なり、文の構造が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「大きな河川で河口」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示すが、「できる」は目的語を取らないので不自然。"}], "correct_answer": "の", "explanations": {"の": "「河口」を「大きな河川の」で修飾する連体修飾なので、「大きな河川の河口」が正しい。", "に": "「大きな河川に河口には」と「に」が重なり、文の構造が合わない。", "で": "「で」は場所や手段を示すが、「大きな河川で河口」は意味が通らない。", "を": "「を」は他動詞の目的語を示すが、「できる」は目的語を取らないので不自然。"}, "error_tags": {"に": "位置", "で": "場所・手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水が流れる自然の道。川。", "primary_collocate": null, "pronunciation": "かせん", "ipa": "kaseɴ", "syllable_count": 3, "sentences": [{"text": "台風で河川が増水し、避難指示が出された。", "target_word": "河川", "complexity_tier": "T3", "furigana": "台風[たいふう]で河川[かせん]が増水[ぞうすい]し、避難[ひなん]指示[しじ]が出[だ]された。", "sentence_source": "generated"}, {"text": "河川の水質は、毎月調査されている。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]の水質[すいしつ]は、毎月[まいつき]調査[ちょうさ]されている。", "sentence_source": "generated"}, {"text": "この地域は河川が多く、昔から水運が発達した。", "target_word": "河川", "complexity_tier": "T3", "furigana": "この地域[ちいき]は河川[かせん]が多[おお]く、昔[むかし]から水運[すいうん]が発達[はったつ]した。", "sentence_source": "generated"}, {"text": "河川は、上流から下流へ土砂を運ぶ。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]は、上流[じょうりゅう]から下流[かりゅう]へ土砂[どしゃ]を運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "国は河川の堤防を高くする工事を進めている。", "target_word": "河川", "complexity_tier": "T3", "furigana": "国[くに]は河川[かせん]の堤防[ていぼう]を高[たか]くする工事[こうじ]を進[すす]めている。", "sentence_source": "generated"}, {"text": "河川の水を農業に利用する地域も多い。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]の水[みず]を農業[のうぎょう]に利用[りよう]する地域[ちいき]も多[おお]い。", "sentence_source": "generated"}, {"text": "都市を流れる河川には、生活排水が流れ込みやすい。", "target_word": "河川", "complexity_tier": "T3", "furigana": "都市[とし]を流[なが]れる河川[かせん]には、生活[せいかつ]排水[はいすい]が流[なが]れ込[こ]みやすい。", "sentence_source": "generated"}, {"text": "大きな河川の河口には、広い平野ができる。", "target_word": "河川", "complexity_tier": "T3", "furigana": "大[おお]きな河川[かせん]の河口[かこう]には、広[ひろ]い平野[へいや]ができる。", "sentence_source": "generated"}, {"text": "河川が氾濫したため、周辺の道路が通行止めになった。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]が氾濫[はんらん]したため、周辺[しゅうへん]の道路[どうろ]が通行止[つうこうど]めになった。", "sentence_source": "generated"}, {"text": "河川の近くに住む人は、ハザードマップを確認しておくとよい。", "target_word": "河川", "complexity_tier": "T3", "furigana": "河川[かせん]の近[ちか]くに住[す]む人[ひと]は、ハザードマップを確認[かくにん]しておくとよい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "河川", "label": "基本形"}], "register": "formal", "sense_fingerprint": "自然の水の流れとしての川。治水や水質など公的な話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河川", "is_correct": true, "explanation": "台風で水かさが増える、自然の水の流れを指し、文に合う。"}, {"text": "震度", "is_correct": false, "explanation": "地震の揺れの大きさを表す語で、台風で増水するものではないので合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気に含まれる水分の割合を表す語で、増水するものではないので合わない。"}, {"text": "気圧", "is_correct": false, "explanation": "空気の圧力を表す語で、増水するものではないので合わない。"}], "explanations": {"河川": "台風で水かさが増える、自然の水の流れを指し、文に合う。", "震度": "地震の揺れの大きさを表す語で、台風で増水するものではないので合わない。", "湿度": "空気に含まれる水分の割合を表す語で、増水するものではないので合わない。", "気圧": "空気の圧力を表す語で、増水するものではないので合わない。"}, "sentence_index": 0, "correct_answer": "河川"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河川は、毎晩交代で見回りをする。", "explanation": "ここは〈警備員〉の意味。見回りをするのは人で、水の流れである河川は行動しないので合わない。"}, {"text": "寒い朝、河川を着て学校へ出かけた。", "explanation": "ここは〈コート〉の意味。着るのは衣服で、河川は身につけられないので合わない。"}, {"text": "河川を弾いて、子どもたちに聞かせた。", "explanation": "ここは〈ピアノ〉の意味。弾くのは楽器で、河川は音を出す道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河川", "is_correct": true, "explanation": "都市を流れて生活排水が流れ込む、自然の水の流れを指し、文に合う。"}, {"text": "鉄道", "is_correct": false, "explanation": "線路を走る交通機関で、都市を流れて排水が流れ込むものではないので合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "電線を支える柱で、流れないので合わない。"}, {"text": "公園", "is_correct": false, "explanation": "市民が利用する場所で、流れるものではないので合わない。"}], "explanations": {"河川": "都市を流れて生活排水が流れ込む、自然の水の流れを指し、文に合う。", "鉄道": "線路を走る交通機関で、都市を流れて排水が流れ込むものではないので合わない。", "電柱": "電線を支える柱で、流れないので合わない。", "公園": "市民が利用する場所で、流れるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "河川"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河川を庭に植えて、春に花を咲かせる。", "explanation": "ここは〈球根〉の意味。庭に植えて花を咲かせるのは植物の球根で、河川は植えられないので合わない。"}, {"text": "河川に乗って、毎朝職場へ行く。", "explanation": "ここは〈電車〉の意味。乗って移動するのは乗り物で、河川は乗る対象ではないので合わない。"}, {"text": "河川を居間に置いて、くつろぐ。", "explanation": "ここは〈ソファ〉の意味。居間に置いてくつろぐのは家具で、河川は置けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河川を増水により、住民が避難した。", "corrected_sentence": "河川の増水により、住民が避難した。", "error_description": "「増水」を修飾するには「河川の」と連体修飾の「の」が必要。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39149, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河川を氾濫するおそれがあるので、注意してください。", "corrected_sentence": "河川が氾濫するおそれがあるので、注意してください。", "error_description": "「氾濫する」は自動詞なので主語「河川が」を使い、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『残留が心配』で、残留が心配の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "『残留を心配』と目的語にすると、心配する対象の形として不自然。"}, {"text": "に", "is_correct": false, "explanation": "『残留に心配』は心配の相手として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『残留で心配』は手段や場所の意味にならず、文が合わない。"}], "correct_answer": "が", "explanations": {"が": "『残留が心配』で、残留が心配の主語になる。", "を": "『残留を心配』と目的語にすると、心配する対象の形として不自然。", "に": "『残留に心配』は心配の相手として成り立たない。", "で": "『残留で心配』は手段や場所の意味にならず、文が合わない。"}, "error_tags": {"を": "目的格", "に": "対象", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除去", "is_correct": true, "explanation": "取り除く意味で、残っている状態と対になる関係にある。"}, {"text": "増殖", "is_correct": false, "explanation": "数が増える意味で、残るかどうかの対義にはならない。"}, {"text": "放置", "is_correct": false, "explanation": "そのまま手をつけずに置く意味で、残留とは対になる関係ではない。"}, {"text": "混入", "is_correct": false, "explanation": "外から入り込む意味で、残留と反対の関係にはない。"}], "correct_answer": "除去", "explanations": {"除去": "取り除く意味で、残っている状態と対になる関係にある。", "増殖": "数が増える意味で、残るかどうかの対義にはならない。", "放置": "そのまま手をつけずに置く意味で、残留とは対になる関係ではない。", "混入": "外から入り込む意味で、残留と反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『昔の薬が残留しています』で、薬が残留するという主語になる。"}, {"text": "と", "is_correct": false, "explanation": "『薬と残留しています』は並列の意味になり、文の述語が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『薬へ残留』は方向の意味になり、残る場所を表す文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、薬が残留するという文の骨組みに合わない。"}], "correct_answer": "が", "explanations": {"が": "『昔の薬が残留しています』で、薬が残留するという主語になる。", "と": "『薬と残留しています』は並列の意味になり、文の述語が成り立たない。", "へ": "『薬へ残留』は方向の意味になり、残る場所を表す文として不自然。", "より": "比較の意味になり、薬が残留するという文の骨組みに合わない。"}, "error_tags": {"と": "並列・共同", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "除去", "is_correct": true, "explanation": "取り除く意味で、洗っても残る汚れと対になる関係にある。"}, {"text": "発生", "is_correct": false, "explanation": "新しく生じる意味で、取り除く動きとは対義ではない。"}, {"text": "飛散", "is_correct": false, "explanation": "あたりに散らばる意味で、残る状態とは対になる関係ではない。"}, {"text": "出現", "is_correct": false, "explanation": "現れる意味で、残留と反対の関係にはない。"}], "correct_answer": "除去", "explanations": {"除去": "取り除く意味で、洗っても残る汚れと対になる関係にある。", "発生": "新しく生じる意味で、取り除く動きとは対義ではない。", "飛散": "あたりに散らばる意味で、残る状態とは対になる関係ではない。", "出現": "現れる意味で、残留と反対の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ずっとそこにありつづけること。", "primary_collocate": null, "pronunciation": "ざんりゅう", "ipa": "dzaɴɾʲɯː", "syllable_count": 4, "sentences": [{"text": "野菜に農薬の残留がないか、検査しています。", "target_word": "残留", "complexity_tier": "T3", "furigana": "野菜[やさい]に農薬[のうやく]の残留[ざんりゅう]がないか、検査[けんさ]しています。", "sentence_source": "generated"}, {"text": "洗剤の残留が心配なので、お皿を水でよくすすぎます。", "target_word": "残留", "complexity_tier": "T3", "furigana": "洗剤[せんざい]の残留[ざんりゅう]が心配[しんぱい]なので、お皿[さら]を水[みず]でよくすすぎます。", "sentence_source": "generated"}, {"text": "食べ物に薬の残留があると、体に悪いことがあります。", "target_word": "残留", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]に薬[くすり]の残留[ざんりゅう]があると、体[からだ]に悪[わる]いことがあります。", "sentence_source": "generated"}, {"text": "池の水に油が残留しているので、魚が元気がありません。", "target_word": "残留", "complexity_tier": "T3", "furigana": "池[いけ]の水[みず]に油[あぶら]が残留[ざんりゅう]しているので、魚[さかな]が元気[げんき]がありません。", "sentence_source": "generated"}, {"text": "工場の煙が残留して、空気がなかなかきれいになりません。", "target_word": "残留", "complexity_tier": "T3", "furigana": "工場[こうじょう]の煙[けむり]が残留[ざんりゅう]して、空気[くうき]がなかなかきれいになりません。", "sentence_source": "generated"}, {"text": "換気をしても、台所に焦げくさいにおいが残留していた。", "target_word": "残留", "complexity_tier": "T3", "furigana": "換気[かんき]をしても、台所[だいどころ]に焦[こ]げくさいにおいが残留[ざんりゅう]していた。", "sentence_source": "generated"}, {"text": "部屋に残留したにおいを消すため、窓を開けました。", "target_word": "残留", "complexity_tier": "T3", "furigana": "部屋[へや]に残留[ざんりゅう]したにおいを消[け]すため、窓[まど]を開[あ]けました。", "sentence_source": "generated"}, {"text": "川の底の泥には、昔の薬が残留しています。", "target_word": "残留", "complexity_tier": "T3", "furigana": "川[かわ]の底[そこ]の泥[どろ]には、昔[むかし]の薬[くすり]が残留[ざんりゅう]しています。", "sentence_source": "generated"}, {"text": "手に残留した洗剤で、肌が荒れてしまいました。", "target_word": "残留", "complexity_tier": "T3", "furigana": "手[て]に残留[ざんりゅう]した洗剤[せんざい]で、肌[はだ]が荒[あ]れてしまいました。", "sentence_source": "generated"}, {"text": "残留する成分が少ない野菜を選んで買います。", "target_word": "残留", "complexity_tier": "T3", "furigana": "残留[ざんりゅう]する成分[せいぶん]が少[すく]ない野菜[やさい]を選[えら]んで買[か]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残留", "label": "基本形"}, {"form": "残留する", "label": "動詞形"}], "register": "neutral", "sense_fingerprint": "物やにおいなどが、取り除いたあともそこに残ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "ここは〈残留〉。取り除いたあとも農薬が野菜に残っているかを表し、文に合う。"}, {"text": "保存", "is_correct": false, "explanation": "物を長く置いておく意味。農薬が野菜に残るかどうかの文には合わない。"}, {"text": "栽培", "is_correct": false, "explanation": "作物を育てる意味。農薬と結びつかず、文が成り立たない。"}, {"text": "解毒", "is_correct": false, "explanation": "毒を消す意味。農薬が残っているかを確かめる文には合わない。"}], "explanations": {"残留": "ここは〈残留〉。取り除いたあとも農薬が野菜に残っているかを表し、文に合う。", "保存": "物を長く置いておく意味。農薬が野菜に残るかどうかの文には合わない。", "栽培": "作物を育てる意味。農薬と結びつかず、文が成り立たない。", "解毒": "毒を消す意味。農薬が残っているかを確かめる文には合わない。"}, "sentence_index": 0, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スマホの電池の残留が少なくなったので、充電した。", "explanation": "ここは〈残量〉の意味。電池などにあと何程残っているかは残量と言い、残留は取り除いたあとに残る物に使うので合わない。"}, {"text": "今日は仕事が多く、残留手当がついた。", "explanation": "ここは〈残業手当〉の意味。終業後の仕事に対して出る手当は残業手当と言い、残留は場所にとどまる意味で合わない。"}, {"text": "口座の残留を確かめたら、思ったより少なかった。", "explanation": "ここは〈残高〉の意味。預金の金額は残高と言い、残留は物や成分が残る場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "ここは〈残留〉。窓を開ける前から部屋に残っているにおいを表し、文に合う。"}, {"text": "発注", "is_correct": false, "explanation": "品物を注文する意味で、においを表す文には合わない。"}, {"text": "採取", "is_correct": false, "explanation": "資料として取り集める意味で、におい自体の状態には合わない。"}, {"text": "放流", "is_correct": false, "explanation": "生き物を川や海に流す意味で、部屋のにおいには合わない。"}], "explanations": {"残留": "ここは〈残留〉。窓を開ける前から部屋に残っているにおいを表し、文に合う。", "発注": "品物を注文する意味で、においを表す文には合わない。", "採取": "資料として取り集める意味で、におい自体の状態には合わない。", "放流": "生き物を川や海に流す意味で、部屋のにおいには合わない。"}, "sentence_index": 6, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人気の舞台は、チケットの残留がわずかになっていた。", "explanation": "ここは〈残席〉の意味。座席や券の空きを指す語で、残留は残った成分などに使うので合わない。"}, {"text": "旅の残留を惜しみながら、帰りの電車に乗った。", "explanation": "ここは〈名残〉の意味。去ったあとに心に残るものを指す語で、残留は物や成分に使うので合わない。"}, {"text": "会社は権利を残留して、契約を結んだ。", "explanation": "ここは〈留保〉の意味。権利を手元に残しておく場合は留保と言い、残留とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この皿からは、洗剤を残留がほとんど見つからなかった。", "corrected_sentence": "この皿からは、洗剤の残留がほとんど見つからなかった。", "error_description": "残留は洗剤の残った物を表すので『の』で修飾する。『を』にすると残留が目的語のようになり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39150, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鍋を洗ったあとも、焦げを残留が少し見える。", "corrected_sentence": "鍋を洗ったあとも、焦げの残留が少し見える。", "error_description": "残留は焦げの残った物を表すので『の』で修飾する。『を』にすると目的語になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『土壌に残留した』で、土壌の中に残っているという場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "『土壌を残留した農薬』は目的語にしてしまい、残留の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『土壌へ残留した』は移動の方向の意味になり、残っている場所を表さない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、残留の場所を示す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "『土壌に残留した』で、土壌の中に残っているという場所を表す。", "を": "『土壌を残留した農薬』は目的語にしてしまい、残留の文として成り立たない。", "へ": "『土壌へ残留した』は移動の方向の意味になり、残っている場所を表さない。", "より": "比較の意味になり、残留の場所を示す文には合わない。"}, "error_tags": {"を": "目的格", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『体内に残留した薬』で、体の中に残っている場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "『体内が残留した薬』は主語になってしまい、体の中に残る文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "『体内と残留した薬』は並列の意味になり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の意味になり、体内に残っているという状態を表す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "『体内に残留した薬』で、体の中に残っている場所を表す。", "が": "『体内が残留した薬』は主語になってしまい、体の中に残る文として不自然。", "と": "『体内と残留した薬』は並列の意味になり、文が成り立たない。", "から": "起点の意味になり、体内に残っているという状態を表す文には合わない。"}, "error_tags": {"が": "主格", "と": "並列・共同", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある場所に長くとどまること。また、物事があとまで残ること。", "primary_collocate": null, "pronunciation": "ざんりゅう", "ipa": "dzaɴɾʲɯː", "syllable_count": 4, "sentences": [{"text": "事故のあと、現場には有害物質が残留していた。", "target_word": "残留", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、現場[げんば]には有害[ゆうがい]物質[ぶっしつ]が残留[ざんりゅう]していた。", "sentence_source": "generated"}, {"text": "土壌に残留した農薬が、作物に吸収されるおそれがある。", "target_word": "残留", "complexity_tier": "T3", "furigana": "土壌[どじょう]に残留[ざんりゅう]した農薬[のうやく]が、作物[さくもつ]に吸収[きゅうしゅう]されるおそれがある。", "sentence_source": "generated"}, {"text": "彼は定年後も会社に残留し、後輩の指導を続けた。", "target_word": "残留", "complexity_tier": "T3", "furigana": "彼[かれ]は定年後[ていねんご]も会社[かいしゃ]に残留[ざんりゅう]し、後輩[こうはい]の指導[しどう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "戦後の混乱の影響は、社会に長く残留した。", "target_word": "残留", "complexity_tier": "T3", "furigana": "戦後[せんご]の混乱[こんらん]の影響[えいきょう]は、社会[しゃかい]に長[なが]く残留[ざんりゅう]した。", "sentence_source": "generated"}, {"text": "台風が停滞し、湿った空気が上空に残留している。", "target_word": "残留", "complexity_tier": "T3", "furigana": "台風[たいふう]が停滞[ていたい]し、湿[しめ]った空気[くうき]が上空[じょうくう]に残留[ざんりゅう]している。", "sentence_source": "generated"}, {"text": "食品に残留する薬の基準が、国によって定められている。", "target_word": "残留", "complexity_tier": "T3", "furigana": "食品[しょくひん]に残留[ざんりゅう]する薬[くすり]の基準[きじゅん]が、国[くに]によって定[さだ]められている。", "sentence_source": "generated"}, {"text": "放射性物質が残留した地域では、除染が続いている。", "target_word": "残留", "complexity_tier": "T3", "furigana": "放射性[ほうしゃせい]物質[ぶっしつ]が残留[ざんりゅう]した地域[ちいき]では、除染[じょせん]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "体内に残留した薬は、検査で見つかることがある。", "target_word": "残留", "complexity_tier": "T3", "furigana": "体内[たいない]に残留[ざんりゅう]した薬[くすり]は、検査[けんさ]で見[み]つかることがある。", "sentence_source": "generated"}, {"text": "交渉の結果、部隊は現地に残留することが決まった。", "target_word": "残留", "complexity_tier": "T3", "furigana": "交渉[こうしょう]の結果[けっか]、部隊[ぶたい]は現地[げんち]に残留[ざんりゅう]することが決[き]まった。", "sentence_source": "generated"}, {"text": "洗浄が不十分だと、機械に汚れが残留して故障の原因になる。", "target_word": "残留", "complexity_tier": "T3", "furigana": "洗浄[せんじょう]が不十分[ふじゅうぶん]だと、機械[きかい]に汚[よご]れが残留[ざんりゅう]して故障[こしょう]の原因[げんいん]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残留", "label": "基本形"}, {"form": "残留する", "label": "動詞形"}], "register": "formal", "sense_fingerprint": "人や物質がある場所に長くとどまること、また影響などがあとまで残ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "ここは〈残留〉。事故のあとも有害物質が現場に残っていた状態を表し、文に合う。"}, {"text": "採取", "is_correct": false, "explanation": "資料として取り集める意味で、有害物質が現場にあった状態には合わない。"}, {"text": "販売", "is_correct": false, "explanation": "売る意味で、有害物質が現場にある状態を表す文には合わない。"}, {"text": "作成", "is_correct": false, "explanation": "新しく作る意味で、現場にあった物質の状態とは結びつかない。"}], "explanations": {"残留": "ここは〈残留〉。事故のあとも有害物質が現場に残っていた状態を表し、文に合う。", "採取": "資料として取り集める意味で、有害物質が現場にあった状態には合わない。", "販売": "売る意味で、有害物質が現場にある状態を表す文には合わない。", "作成": "新しく作る意味で、現場にあった物質の状態とは結びつかない。"}, "sentence_index": 0, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家賃の残留が三か月続き、部屋を出されることになった。", "explanation": "ここは〈滞納〉の意味。期限までに払わず未払いのまま遅れることは滞納と言い、残留は合わない。"}, {"text": "会議が半年残留した。", "explanation": "ここは〈延長〉の意味。予定の期間を先まで伸ばすことは延長と言い、残留は合わない。"}, {"text": "予算の残留を、次年度に回した。", "explanation": "ここは〈残余〉の意味。使い切らずに余った分を指す語で、残留はお金の残りには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残留", "is_correct": true, "explanation": "ここは〈残留〉。物質が地域に残っているという状態を表し、除染の文に合う。"}, {"text": "購入", "is_correct": false, "explanation": "買い入れる意味で、物質が地域に残る状態とは合わない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録する意味で、地域に物質がある状態には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "届ける意味で、物質が地域に残ることを表す文には合わない。"}], "explanations": {"残留": "ここは〈残留〉。物質が地域に残っているという状態を表し、除染の文に合う。", "購入": "買い入れる意味で、物質が地域に残る状態とは合わない。", "録音": "音を記録する意味で、地域に物質がある状態には合わない。", "配達": "届ける意味で、物質が地域に残ることを表す文には合わない。"}, "sentence_index": 6, "correct_answer": "残留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔の残留を残す町並みを歩いた。", "explanation": "ここは〈面影〉の意味。昔の姿をしのばせるものを指す語で、残留は物や成分に使うので合わない。"}, {"text": "夏の残留を惜しみながら、海から帰った。", "explanation": "ここは〈名残〉の意味。去ったあとに心に残るものを指す語で、残留はここでは使わないので合わない。"}, {"text": "この洞窟は残留が長く、声が何度も返ってくる。", "explanation": "ここは〈残響〉の意味。音が鳴りやんだあとに響く現象を指す語で、残留は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "跡地には、有害物質の残留に確認された。", "corrected_sentence": "跡地には、有害物質の残留が確認された。", "error_description": "残留は『確認された』の主語なので『が』が正しい。『に』にすると確認する相手のようになり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39151, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いタンクの底では、油の残留を見つかった。", "corrected_sentence": "古いタンクの底では、油の残留が見つかった。", "error_description": "『見つかった』は残留が主語になる形なので『が』が正しい。『を』にすると目的語になり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
