INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『水生の小さな虫』で、水の中で暮らす小さな虫を修飾する。"}, {"text": "に", "is_correct": false, "explanation": "『水生に小さな虫』は場所や対象の意味になり、修飾関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の意味になり、水生の小さな虫を修飾する形として合わない。"}, {"text": "が", "is_correct": false, "explanation": "主格の意味になり、水生が小さな虫の主語になる文として不自然。"}], "correct_answer": "の", "explanations": {"の": "『水生の小さな虫』で、水の中で暮らす小さな虫を修飾する。", "に": "『水生に小さな虫』は場所や対象の意味になり、修飾関係が成り立たない。", "から": "起点の意味になり、水生の小さな虫を修飾する形として合わない。", "が": "主格の意味になり、水生が小さな虫の主語になる文として不自然。"}, "error_tags": {"に": "場所・対象", "から": "起点", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水の中に住む生き物のこと。", "primary_collocate": null, "pronunciation": "すいせい", "ipa": "sɯiseː", "syllable_count": 4, "sentences": [{"text": "この池には、水生の生き物がたくさんすんでいます。", "target_word": "水生", "complexity_tier": "T3", "furigana": "この池[いけ]には、水生[すいせい]の生[い]き物[もの]がたくさんすんでいます。", "sentence_source": "generated"}, {"text": "カエルの子どもは水生で、大きくなると陸に上がります。", "target_word": "水生", "complexity_tier": "T3", "furigana": "カエルの子[こ]どもは水生[すいせい]で、大[おお]きくなると陸[りく]に上[あ]がります。", "sentence_source": "generated"}, {"text": "魚やカニは水生なので、水がないと生きられません。", "target_word": "水生", "complexity_tier": "T3", "furigana": "魚[さかな]やカニは水生[すいせい]なので、水[みず]がないと生[い]きられません。", "sentence_source": "generated"}, {"text": "水生の生き物は、えらで息をするものが多いです。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の生[い]き物[もの]は、えらで息[いき]をするものが多[おお]いです。", "sentence_source": "generated"}, {"text": "川の水がよごれると、水生の生き物が少なくなります。", "target_word": "水生", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]がよごれると、水生[すいせい]の生[い]き物[もの]が少[すく]なくなります。", "sentence_source": "generated"}, {"text": "理科の授業で、水生の生き物を虫めがねで観察しました。", "target_word": "水生", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、水生[すいせい]の生[い]き物[もの]を虫[むし]めがねで観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "ヤゴは水生で、大人になるとトンボになります。", "target_word": "水生", "complexity_tier": "T3", "furigana": "ヤゴは水生[すいせい]で、大人[おとな]になるとトンボになります。", "sentence_source": "generated"}, {"text": "水生の小さな虫は、魚のえさになります。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の小[ちい]さな虫[むし]は、魚[さかな]のえさになります。", "sentence_source": "generated"}, {"text": "陸で暮らす生き物と水生の生き物を、ノートに分けて書きました。", "target_word": "水生", "complexity_tier": "T3", "furigana": "陸[りく]で暮[く]らす生[い]き物[もの]と水生[すいせい]の生[い]き物[もの]を、ノートに分[わ]けて書[か]きました。", "sentence_source": "generated"}, {"text": "水槽には、水生の貝やエビを入れて育てています。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水槽[すいそう]には、水生[すいせい]の貝[かい]やエビを入[い]れて育[そだ]てています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水生", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "魚やカニなど、水の中で暮らす生き物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水生", "is_correct": true, "explanation": "ここは〈水生〉。水の中に住む生き物を表し、池の生き物の文に合う。"}, {"text": "水質", "is_correct": false, "explanation": "水の性質や状態を表す語で、生き物を修飾する文には合わない。"}, {"text": "水力", "is_correct": false, "explanation": "水の流れの力を表す語で、生き物を修飾する文には合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水を供給する設備の意味で、池の生き物を表す文には合わない。"}], "explanations": {"水生": "ここは〈水生〉。水の中に住む生き物を表し、池の生き物の文に合う。", "水質": "水の性質や状態を表す語で、生き物を修飾する文には合わない。", "水力": "水の流れの力を表す語で、生き物を修飾する文には合わない。", "水道": "水を供給する設備の意味で、池の生き物を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "水生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は水生高校で、魚の育て方を学んだ。", "explanation": "ここは〈水産〉の意味。漁業や水産物に関する学校や産業を指すので、水の中で暮らす生き物を表す水生とは合わない。"}, {"text": "この絵の具は水生なので、水で洗い流せる。", "explanation": "ここは〈水性〉の意味。水を溶かす性質の塗料や筆記具を指す語で、生き物を表す水生とは別の語なので合わない。"}, {"text": "この山の森は、町の水生になっている。", "explanation": "ここは〈水源〉の意味。水がわき出す場所を指すので、生き物を表す水生は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水生", "is_correct": true, "explanation": "ここは〈水生〉。ヤゴが水の中で暮らすことを表し、文に合う。"}, {"text": "水族", "is_correct": false, "explanation": "水の中の生き物の集まりを指す語で、ヤゴを修飾する文には合わない。"}, {"text": "水温", "is_correct": false, "explanation": "水の温度を表す語で、ヤゴの暮らしを述べる文には合わない。"}, {"text": "水量", "is_correct": false, "explanation": "水の量を表す語で、ヤゴの暮らしを述べる文には合わない。"}], "explanations": {"水生": "ここは〈水生〉。ヤゴが水の中で暮らすことを表し、文に合う。", "水族": "水の中の生き物の集まりを指す語で、ヤゴを修飾する文には合わない。", "水温": "水の温度を表す語で、ヤゴの暮らしを述べる文には合わない。", "水量": "水の量を表す語で、ヤゴの暮らしを述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "水生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で川の水生が起き、町は大騒ぎになった。", "explanation": "ここは〈水害〉の意味。大水による被害を指すので、水の中で暮らす生き物を表す水生とは合わない。"}, {"text": "大雨が降ったので、水生を開けて川の水を流した。", "explanation": "ここは〈水門〉の意味。水の量を調節する設備を指すので、生き物を表す水生は合わない。"}, {"text": "川の水生が強く、ボートは進めなかった。", "explanation": "ここは〈水流〉の意味。水が流れる勢いを指すので、生き物を表す水生とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ザリガニは水生に、池の中でよく暮らしている。", "corrected_sentence": "ザリガニは水生で、池の中でよく暮らしている。", "error_description": "名詞『水生』は『で』で続ける。『に』にすると文の述語が成り立たず、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、池の水生に生き物を観察した。", "corrected_sentence": "夏休みに、池の水生の生き物を観察した。", "error_description": "『水生』は『生き物』を修飾するので『の』が必要。『に』にすると生き物を修飾できず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陸生", "is_correct": true, "explanation": "陸の上で生活する性質を表し、水中で生活する性質の水生と対になる。"}, {"text": "水中", "is_correct": false, "explanation": "水の中にある場所を表す語で、水生と対になる関係ではない。"}, {"text": "海中", "is_correct": false, "explanation": "海の中を表す語で、水の中で生活する性質と対になる関係ではない。"}, {"text": "水産", "is_correct": false, "explanation": "漁業や水産物に関する語で、生活の性質を表す水生とは対になる関係ではない。"}], "correct_answer": "陸生", "explanations": {"陸生": "陸の上で生活する性質を表し、水中で生活する性質の水生と対になる。", "水中": "水の中にある場所を表す語で、水生と対になる関係ではない。", "海中": "海の中を表す語で、水の中で生活する性質と対になる関係ではない。", "水産": "漁業や水産物に関する語で、生活の性質を表す水生とは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陸生", "is_correct": true, "explanation": "陸の上で生活する性質を表し、水中で生活する性質の水生と対になる。"}, {"text": "地上", "is_correct": false, "explanation": "地面の上を表す語で、水中で生活する性質と対になる関係ではない。"}, {"text": "空中", "is_correct": false, "explanation": "空の中を表す語で、生活の性質を表す水生とは対になる関係ではない。"}, {"text": "山中", "is_correct": false, "explanation": "山の中を表す語で、水中で生活する性質と対になる関係ではない。"}], "correct_answer": "陸生", "explanations": {"陸生": "陸の上で生活する性質を表し、水中で生活する性質の水生と対になる。", "地上": "地面の上を表す語で、水中で生活する性質と対になる関係ではない。", "空中": "空の中を表す語で、生活の性質を表す水生とは対になる関係ではない。", "山中": "山の中を表す語で、水中で生活する性質と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "水中で生活する生物に関すること。また、水中に生息するさま。", "primary_collocate": null, "pronunciation": "すいせい", "ipa": "sɯiseː", "syllable_count": 4, "sentences": [{"text": "カワセミは魚を食べるが、水生ではなく鳥類である。", "target_word": "水生", "complexity_tier": "T3", "furigana": "カワセミは魚[さかな]を食[た]べるが、水生[すいせい]ではなく鳥類[ちょうるい]である。", "sentence_source": "generated"}, {"text": "この甲虫は幼虫の時期だけ水生で、成虫になると陸上で暮らす。", "target_word": "水生", "complexity_tier": "T3", "furigana": "この甲虫[こうちゅう]は幼虫[ようちゅう]の時期[じき]だけ水生[すいせい]で、成虫[せいちゅう]になると陸上[りくじょう]で暮[く]らす。", "sentence_source": "generated"}, {"text": "水生の昆虫は、川の水質の良し悪しを示す指標になる。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の昆虫[こんちゅう]は、川[かわ]の水質[すいしつ]の良[よ]し悪[あ]しを示[しめ]す指標[しひょう]になる。", "sentence_source": "generated"}, {"text": "クジラは水生の哺乳類だが、肺で呼吸する。", "target_word": "水生", "complexity_tier": "T3", "furigana": "クジラは水生[すいせい]の哺乳類[ほにゅうるい]だが、肺[はい]で呼吸[こきゅう]する。", "sentence_source": "generated"}, {"text": "水生の生活に適応して、足がひれのような形になった。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の生活[せいかつ]に適応[てきおう]して、足[あし]がひれのような形[かたち]になった。", "sentence_source": "generated"}, {"text": "湖の水生の微生物を調べ、生態系の変化を記録した。", "target_word": "水生", "complexity_tier": "T3", "furigana": "湖[みずうみ]の水生[すいせい]の微生物[びせいぶつ]を調[しら]べ、生態系[せいたいけい]の変化[へんか]を記録[きろく]した。", "sentence_source": "generated"}, {"text": "イモリは幼生のときは水生で、えら呼吸をする。", "target_word": "水生", "complexity_tier": "T3", "furigana": "イモリは幼生[ようせい]のときは水生[すいせい]で、えら呼吸[こきゅう]をする。", "sentence_source": "generated"}, {"text": "水生の種は、乾燥に弱いものが多い。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の種[しゅ]は、乾燥[かんそう]に弱[よわ]いものが多[おお]い。", "sentence_source": "generated"}, {"text": "調査では、水生の生物の種類が昨年より減っていた。", "target_word": "水生", "complexity_tier": "T3", "furigana": "調査[ちょうさ]では、水生[すいせい]の生物[せいぶつ]の種類[しゅるい]が昨年[さくねん]より減[へ]っていた。", "sentence_source": "generated"}, {"text": "水生の生活をする動物は、体が流線形になりやすい。", "target_word": "水生", "complexity_tier": "T3", "furigana": "水生[すいせい]の生活[せいかつ]をする動物[どうぶつ]は、体[からだ]が流線形[りゅうせんけい]になりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水生", "label": "基本形"}], "register": "formal", "sense_fingerprint": "生物が水中で生活しているという性質や、そのようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水生", "is_correct": true, "explanation": "ここは〈水生〉。水中で生活する性質を表し、カワセミは水中では暮らさないという文に合う。"}, {"text": "水質", "is_correct": false, "explanation": "水の性質を表す語で、生活の性質を述べる文には合わない。"}, {"text": "水量", "is_correct": false, "explanation": "水の量を表す語で、生活の性質を述べる文には合わない。"}, {"text": "水道", "is_correct": false, "explanation": "水を供給する設備の意味で、生き物の性質を表す文には合わない。"}], "explanations": {"水生": "ここは〈水生〉。水中で生活する性質を表し、カワセミは水中では暮らさないという文に合う。", "水質": "水の性質を表す語で、生活の性質を述べる文には合わない。", "水量": "水の量を表す語で、生活の性質を述べる文には合わない。", "水道": "水を供給する設備の意味で、生き物の性質を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "水生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この港町は水生業が盛んで、朝から活気がある。", "explanation": "ここは〈水産〉の意味。漁業など水産業を指す語で、水中で生活する性質を表す水生とは合わない。"}, {"text": "水生バスに乗って、川の景色を楽しんだ。", "explanation": "ここは〈水上〉の意味。水面の上にあることを指すので、水中で生活する性質の水生とは合わない。"}, {"text": "水生発電で、この町の電気の一部をまかなっている。", "explanation": "ここは〈水力〉の意味。水の流れの力を指すので、生活の性質を表す水生とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水生", "is_correct": true, "explanation": "ここは〈水生〉。幼生のときは水中で生活することを表し、文に合う。"}, {"text": "水族", "is_correct": false, "explanation": "水中の生き物の集まりを指す語で、生活の性質を述べる文には合わない。"}, {"text": "水流", "is_correct": false, "explanation": "水の流れを表す語で、生活の性質を述べる文には合わない。"}, {"text": "水温", "is_correct": false, "explanation": "水の温度を表す語で、生活の性質を述べる文には合わない。"}], "explanations": {"水生": "ここは〈水生〉。幼生のときは水中で生活することを表し、文に合う。", "水族": "水中の生き物の集まりを指す語で、生活の性質を述べる文には合わない。", "水流": "水の流れを表す語で、生活の性質を述べる文には合わない。", "水温": "水の温度を表す語で、生活の性質を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "水生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洪水で村が水生して、家が流された。", "explanation": "ここは〈水没〉の意味。水におおわれて沈むことを指すので、水中で生活する性質の水生とは合わない。"}, {"text": "白い水生のワンピースを着て、出かけた。", "explanation": "ここは〈水玉〉の意味。丸い模様を指す語で、生活の性質を表す水生とは合わない。"}, {"text": "この薬は水生で、水に溶けやすい。", "explanation": "ここは〈水溶性〉の意味。水に溶ける性質を指すので、水中で生活する性質の水生とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マスは水生を、冷たくてきれいな川を好む。", "corrected_sentence": "マスは水生で、冷たくてきれいな川を好む。", "error_description": "『水生』は状態を表す語なので『で』で続ける。『を』にすると目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39153, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ウナギは水生を生活を送るが、卵は海で産まれる。", "corrected_sentence": "ウナギは水生の生活を送るが、卵は海で産まれる。", "error_description": "『水生』は『生活』を修飾するので『の』が必要。『を』にすると目的語になり、『生活を送る』との関係が崩れて文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ここは主題を示す「は」。漁業を取り上げて定義を述べている。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「漁業を、〜仕事です」では主題にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向。「漁業へ」では定義の主題を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点。「漁業から」では定義の主題にならない。"}], "correct_answer": "は", "explanations": {"は": "ここは主題を示す「は」。漁業を取り上げて定義を述べている。", "を": "「を」は目的語。「漁業を、〜仕事です」では主題にならず文が成り立たない。", "へ": "「へ」は方向。「漁業へ」では定義の主題を示せない。", "から": "「から」は起点。「漁業から」では定義の主題にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "ここは手段の「で」。漁業という手段で貝を取ったことを表す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。「漁業が取った」では漁業が貝を取る主体になり、手段にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点。「漁業に取った」では手段を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較。「漁業より取った」では比較の文にならない。"}], "correct_answer": "で", "explanations": {"で": "ここは手段の「で」。漁業という手段で貝を取ったことを表す。", "が": "「が」は主語。「漁業が取った」では漁業が貝を取る主体になり、手段にならない。", "に": "「に」は帰着点。「漁業に取った」では手段を表せない。", "より": "「より」は比較。「漁業より取った」では比較の文にならない。"}, "error_tags": {"が": "主語", "に": "帰着点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "海や川で魚や貝などの生き物を取って食べ物やお金にする仕事です。", "primary_collocate": null, "pronunciation": "ぎょぎょう", "ipa": "ɡʲoɡʲoː", "syllable_count": 3, "sentences": [{"text": "この町では、多くの人が漁業で生活しています。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "この町[まち]では、多[おお]くの人[ひと]が漁業[ぎょぎょう]で生活[せいかつ]しています。", "sentence_source": "generated"}, {"text": "漁業は、海や川で魚をとる仕事です。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "漁業[ぎょぎょう]は、海[うみ]や川[かわ]で魚[さかな]をとる仕事[しごと]です。", "sentence_source": "generated"}, {"text": "祖父は五十年間、漁業を続けてきました。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "祖父[そふ]は五十年間[ごじゅうねんかん]、漁業[ぎょぎょう]を続[つづ]けてきました。", "sentence_source": "generated"}, {"text": "漁業が盛んな港には、毎朝新しい魚が届きます。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "漁業[ぎょぎょう]が盛[さか]んな港[みなと]には、毎朝[まいあさ]新[あたら]しい魚[さかな]が届[とど]きます。", "sentence_source": "generated"}, {"text": "魚が減ると、漁業をする人の収入も少なくなります。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "魚[さかな]が減[へ]ると、漁業[ぎょぎょう]をする人[ひと]の収入[しゅうにゅう]も少[すく]なくなります。", "sentence_source": "generated"}, {"text": "台風が近づくと、漁業は休みになります。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づくと、漁業[ぎょぎょう]は休[やす]みになります。", "sentence_source": "generated"}, {"text": "私は大きくなったら、父と同じ漁業をしたいです。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "私[わたし]は大[おお]きくなったら、父[ちち]と同[おな]じ漁業[ぎょぎょう]をしたいです。", "sentence_source": "generated"}, {"text": "漁業で取った貝は、市場で売られます。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "漁業[ぎょぎょう]で取[と]った貝[かい]は、市場[いちば]で売[う]られます。", "sentence_source": "generated"}, {"text": "海がよごれて、漁業に困っている町もあります。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "海[うみ]がよごれて、漁業[ぎょぎょう]に困[こま]っている町[まち]もあります。", "sentence_source": "generated"}, {"text": "漁業の船は、夜明け前に港を出ます。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "漁業[ぎょぎょう]の船[ふね]は、夜明[よあ]け前[まえ]に港[みなと]を出[で]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "漁業", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "海や川で魚や貝をとって生活する仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漁業", "is_correct": true, "explanation": "「で生活」の手段として漁業を指す。海で魚を取る仕事なので文に合う。"}, {"text": "漁具", "is_correct": false, "explanation": "漁具は漁で使う道具の名前で、生活の手段にはならない。"}, {"text": "漁獲", "is_correct": false, "explanation": "漁獲は取れた量を指す語で、仕事の手段としては言えない。"}, {"text": "魚市場", "is_correct": false, "explanation": "魚市場は売買の場所で、そこで生活するという文にはならない。"}], "explanations": {"漁業": "「で生活」の手段として漁業を指す。海で魚を取る仕事なので文に合う。", "漁具": "漁具は漁で使う道具の名前で、生活の手段にはならない。", "漁獲": "漁獲は取れた量を指す語で、仕事の手段としては言えない。", "魚市場": "魚市場は売買の場所で、そこで生活するという文にはならない。"}, "sentence_index": 0, "correct_answer": "漁業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は漁業で、家族と海釣りを楽しみました。", "explanation": "ここは趣味の釣りの意味。漁業は生活のための仕事を指すので、遊びの海釣りには使わない。"}, {"text": "この工場では、鮭の漁業を缶詰にして出荷しています。", "explanation": "ここは〈水産加工業〉の意味。缶詰にして出荷するのは加工業で、獲る仕事の漁業は缶詰にできない。"}, {"text": "今朝は漁業を大きな箱いっぱいに取って、市場へ運びました。", "explanation": "ここは〈漁獲〉の意味。箱に取って運ぶのは獲れた魚で、産業の漁業は取れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漁業", "is_correct": true, "explanation": "父と同じ仕事を表す名前で、「をしたい」の目的語になる。"}, {"text": "漁港", "is_correct": false, "explanation": "漁港は場所の名前で、「をしたい」の対象にはならない。"}, {"text": "水産物", "is_correct": false, "explanation": "水産物は売り物の品物で、「をしたい」の仕事にはならない。"}, {"text": "漁船", "is_correct": false, "explanation": "漁船は道具で、「父と同じ〜をしたい」の仕事にはならない。"}], "explanations": {"漁業": "父と同じ仕事を表す名前で、「をしたい」の目的語になる。", "漁港": "漁港は場所の名前で、「をしたい」の対象にはならない。", "水産物": "水産物は売り物の品物で、「をしたい」の仕事にはならない。", "漁船": "漁船は道具で、「父と同じ〜をしたい」の仕事にはならない。"}, "sentence_index": 6, "correct_answer": "漁業"}, "level_6": {"correct_sentence_index": 5, "wrong_sentences": [{"text": "この店では、新鮮な漁業を売っています。", "explanation": "ここは〈水産物〉の意味。店で売るのは魚などの品物で、産業の漁業は売り物にならない。"}, {"text": "父は毎朝、漁業の広い海へ船を出しています。", "explanation": "ここは〈漁場〉の意味。船を出す先は漁場で、産業の漁業は場所にならない。"}, {"text": "漁業が港に戻ってきて、魚を降ろしました。", "explanation": "ここは〈漁船〉の意味。港へ戻って魚を降ろすのは船で、産業の漁業は動かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "漁業を生活する人は、年々減っている。", "corrected_sentence": "漁業で生活する人は、年々減っている。", "error_description": "「生活する」は「で」を取る。「を」は誤りで、正しくは「漁業で生活する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39156, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漁業を営まる家が、この浜には多い。", "corrected_sentence": "漁業を営む家が、この浜には多い。", "error_description": "「営む」は名詞を修飾する形で「営む家」となる。「営まる」は存在しない誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "ここは「漁業の持続」を結ぶ「の」。名詞同士をつないでいる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「漁業を持続が」では名詞同士を結べない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向。「漁業へ持続」では持続の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点。「漁業から持続」では結びつかない。"}], "correct_answer": "の", "explanations": {"の": "ここは「漁業の持続」を結ぶ「の」。名詞同士をつないでいる。", "を": "「を」は目的語。「漁業を持続が」では名詞同士を結べない。", "へ": "「へ」は方向。「漁業へ持続」では持続の対象を示せない。", "から": "「から」は起点。「漁業から持続」では結びつかない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "ここは被害を受ける相手を示す「に」。下流の漁業が被害を受けた先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「被害を」と重なり「漁業を被害を与えた」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列。「漁業と被害を与えた」では相手が並ばない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較。「漁業より被害を与えた」では比較文にならない。"}], "correct_answer": "に", "explanations": {"に": "ここは被害を受ける相手を示す「に」。下流の漁業が被害を受けた先を表す。", "を": "「を」は目的語。「被害を」と重なり「漁業を被害を与えた」は成り立たない。", "と": "「と」は並列。「漁業と被害を与えた」では相手が並ばない。", "より": "「より」は比較。「漁業より被害を与えた」では比較文にならない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "海や湖、川などで、魚や貝などを獲る仕事や産業。", "primary_collocate": null, "pronunciation": "ぎょぎょう", "ipa": "ɡʲoɡʲoː", "syllable_count": 3, "sentences": [{"text": "日本の漁業は、高齢化と後継者不足という課題を抱えている。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "日本[にほん]の漁業[ぎょぎょう]は、高齢化[こうれいか]と後継者[こうけいしゃ]不足[ぶそく]という課題[かだい]を抱[かか]えている。", "sentence_source": "generated"}, {"text": "乱獲により資源が減り、漁業の持続が難しくなっている。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "乱獲[らんかく]により資源[しげん]が減[へ]り、漁業[ぎょぎょう]の持続[じぞく]が難[むずか]しくなっている。", "sentence_source": "generated"}, {"text": "内陸の湖でも、小規模な漁業が営まれている。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "内陸[ないりく]の湖[みずうみ]でも、小規模[しょうきぼ]な漁業[ぎょぎょう]が営[いとな]まれている。", "sentence_source": "generated"}, {"text": "燃料費が上がり、漁業の経営は厳しさを増した。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "燃料費[ねんりょうひ]が上[あ]がり、漁業[ぎょぎょう]の経営[けいえい]は厳[きび]しさを増[ま]した。", "sentence_source": "generated"}, {"text": "政府は漁業を支えるため、補助金の制度を設けた。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "政府[せいふ]は漁業[ぎょぎょう]を支[ささ]えるため、補助金[ほじょきん]の制度[せいど]を設[もう]けた。", "sentence_source": "generated"}, {"text": "水産加工業と並んで、漁業はこの地域の主要産業である。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "水産[すいさん]加工業[かこうぎょう]と並[なら]んで、漁業[ぎょぎょう]はこの地域[ちいき]の主要[しゅよう]産業[さんぎょう]である。", "sentence_source": "generated"}, {"text": "温暖化で海水温が上がり、漁業に影響が出ている。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "温暖化[おんだんか]で海水温[かいすいおん]が上[あ]がり、漁業[ぎょぎょう]に影響[えいきょう]が出[で]ている。", "sentence_source": "generated"}, {"text": "河川の汚染は、下流の漁業に深刻な被害を与えた。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "河川[かせん]の汚染[おせん]は、下流[かりゅう]の漁業[ぎょぎょう]に深刻[しんこく]な被害[ひがい]を与[あた]えた。", "sentence_source": "generated"}, {"text": "養殖が広がり、漁業のあり方は大きく変わりつつある。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "養殖[ようしょく]が広[ひろ]がり、漁業[ぎょぎょう]のあり方[かた]は大[おお]きく変[か]わりつつある。", "sentence_source": "generated"}, {"text": "漁業で獲れる魚の量は、年によって大きく変動する。", "target_word": "漁業", "complexity_tier": "T3", "furigana": "漁業[ぎょぎょう]で獲[と]れる魚[さかな]の量[りょう]は、年[とし]によって大[おお]きく変動[へんどう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "漁業", "label": "基本形"}], "register": "formal", "sense_fingerprint": "水産物を獲る産業。経済や政策の話題で使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漁業", "is_correct": true, "explanation": "高齢化や後継者不足の課題を抱える産業として、主語に入る。"}, {"text": "漁具", "is_correct": false, "explanation": "漁具は道具で、高齢化や後継者不足の課題を抱えるとは言えない。"}, {"text": "漁網", "is_correct": false, "explanation": "漁網は網の名前で、後継者不足の課題を抱える主語にならない。"}, {"text": "漁獲量", "is_correct": false, "explanation": "漁獲量は数量で、後継者が不足するという文には合わない。"}], "explanations": {"漁業": "高齢化や後継者不足の課題を抱える産業として、主語に入る。", "漁具": "漁具は道具で、高齢化や後継者不足の課題を抱えるとは言えない。", "漁網": "漁網は網の名前で、後継者不足の課題を抱える主語にならない。", "漁獲量": "漁獲量は数量で、後継者が不足するという文には合わない。"}, "sentence_index": 0, "correct_answer": "漁業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "燃料費が上がり、漁業は魚の缶詰を値上げした。", "explanation": "ここは〈水産加工業〉の意味。缶詰を作って売るのは加工業で、魚を獲る産業の漁業とは違う。"}, {"text": "燃料費が上がり、漁業の広い海まで船を進めるしかなくなった。", "explanation": "ここは〈漁場〉の意味。船を進める先は漁場で、産業の漁業は行き先にならない。"}, {"text": "燃料費が上がり、漁業は週末の楽しみから遠のいた。", "explanation": "ここは趣味の釣りの意味。漁業は仕事としての産業で、週末の楽しみには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漁業", "is_correct": true, "explanation": "水産加工業と並ぶこの地域の主要産業として、主語になる。"}, {"text": "漁港", "is_correct": false, "explanation": "漁港は場所の名前で、主要産業の代わりにはならない。"}, {"text": "漁船", "is_correct": false, "explanation": "漁船は道具の名前で、主要産業の代わりにはならない。"}, {"text": "漁場", "is_correct": false, "explanation": "漁場は場所の名前で、主要産業の代わりにはならない。"}], "explanations": {"漁業": "水産加工業と並ぶこの地域の主要産業として、主語になる。", "漁港": "漁港は場所の名前で、主要産業の代わりにはならない。", "漁船": "漁船は道具の名前で、主要産業の代わりにはならない。", "漁場": "漁場は場所の名前で、主要産業の代わりにはならない。"}, "sentence_index": 6, "correct_answer": "漁業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "漁業は、朝早く船に乗って海へ出る人のことです。", "explanation": "ここは〈漁師〉の意味。船に乗って海へ出る人は漁師で、産業の漁業は人を指さない。"}, {"text": "市場では、朝に獲れた漁業を一箱ずつ並べています。", "explanation": "ここは〈水産物〉の意味。箱に並べて売るのは魚などの品物で、産業の漁業は並べられない。"}, {"text": "漁業が港に戻り、魚を降ろしました。", "explanation": "ここは〈漁船〉の意味。港へ戻って魚を降ろすのは船で、産業の漁業は動かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "漁業に働く人が年々減っている。", "corrected_sentence": "漁業で働く人が年々減っている。", "error_description": "「働く」の場所を表す助詞は「で」。「に」は誤りで、正しくは「漁業で働く」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39157, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "漁業に携わって人は、台風の被害を受けやすい。", "corrected_sentence": "漁業に携わる人は、台風の被害を受けやすい。", "error_description": "「携わる」は名詞を修飾する形。「携わって」は連用形で、人を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食物を食べてみた」の目的語を示す「を」で、食べる対象が食物であることを表す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると「食物が食べてみた」となり、食べる人が示されず不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す「に」にすると「食物に食べてみた」となり、食べる対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は食べる対象にならず、「食物へ食べてみた」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「食物を食べてみた」の目的語を示す「を」で、食べる対象が食物であることを表す。", "が": "主語の「が」にすると「食物が食べてみた」となり、食べる人が示されず不自然。", "に": "位置や相手を示す「に」にすると「食物に食べてみた」となり、食べる対象を示せない。", "へ": "方向を示す「へ」は食べる対象にならず、「食物へ食べてみた」は成り立たない。"}, "error_tags": {"が": "主語の誤り", "に": "位置・相手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食物を残さず食べる」の目的語を示す「を」で、残さず食べる対象が食物であることを表す。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」にすると「食物と残さず食べる」となり、目的語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」にすると「食物より残さず食べる」となり、食べる対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」にすると「食物で残さず食べる」となり、食べる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「食物を残さず食べる」の目的語を示す「を」で、残さず食べる対象が食物であることを表す。", "と": "並列の「と」にすると「食物と残さず食べる」となり、目的語を示せない。", "より": "比較の「より」にすると「食物より残さず食べる」となり、食べる対象を示せない。", "で": "手段や場所の「で」にすると「食物で残さず食べる」となり、食べる対象を示せない。"}, "error_tags": {"と": "並列の誤り", "より": "比較の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべもの", "primary_collocate": null, "pronunciation": "しょくもつ", "ipa": "ɕokɯmotsɯ", "syllable_count": 4, "sentences": [{"text": "食物は冷蔵庫に入れて、新鮮なうちに食べましょう。", "target_word": "食物", "complexity_tier": "T3", "furigana": "食物[しょくもつ]は冷蔵庫[れいぞうこ]に入[い]れて、新鮮[しんせん]なうちに食[た]べましょう。", "sentence_source": "generated"}, {"text": "旅行先で、初めて見る食物を食べてみた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]で、初[はじ]めて見[み]る食物[しょくもつ]を食[た]べてみた。", "sentence_source": "generated"}, {"text": "山の動物は、冬になると食物が少なくなる。", "target_word": "食物", "complexity_tier": "T3", "furigana": "山[やま]の動物[どうぶつ]は、冬[ふゆ]になると食物[しょくもつ]が少[すく]なくなる。", "sentence_source": "generated"}, {"text": "夏は食物がいたみやすいので、気をつけたい。", "target_word": "食物", "complexity_tier": "T3", "furigana": "夏[なつ]は食物[しょくもつ]がいたみやすいので、気[き]をつけたい。", "sentence_source": "generated"}, {"text": "犬に人間の食物をあげてはいけません。", "target_word": "食物", "complexity_tier": "T3", "furigana": "犬[いぬ]に人間[にんげん]の食物[しょくもつ]をあげてはいけません。", "sentence_source": "generated"}, {"text": "祭りの屋台には、いろいろな食物が並んでいた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "祭[まつ]りの屋台[やたい]には、いろいろな食物[しょくもつ]が並[なら]んでいた。", "sentence_source": "generated"}, {"text": "鳥は雪の上に落ちた食物を探していた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "鳥[とり]は雪[ゆき]の上[うえ]に落[お]ちた食物[しょくもつ]を探[さが]していた。", "sentence_source": "generated"}, {"text": "食物を残さず食べるように、先生に言われた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "食物[しょくもつ]を残[のこ]さず食[た]べるように、先生[せんせい]に言[い]われた。", "sentence_source": "generated"}, {"text": "この博物館では、昔の人々の食物の保存方法について学ぶことができる。", "target_word": "食物", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]では、昔[むかし]の人々[ひとびと]の食物[しょくもつ]の保存方法[ほぞんほうほう]について学[まな]ぶことができる。", "sentence_source": "generated"}, {"text": "災害にそなえて、水と食物を家に用意している。", "target_word": "食物", "complexity_tier": "T3", "furigana": "災害[さいがい]にそなえて、水[みず]と食物[しょくもつ]を家[いえ]に用意[ようい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食物", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "食べるもの全般、食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "食べるもの全般を指し、冷蔵庫に入れて新鮮なうちに食べるという文に合う。"}, {"text": "食器", "is_correct": false, "explanation": "皿などの道具で、食べるものではないので新鮮なうちに食べるという文に合わない。"}, {"text": "洗剤", "is_correct": false, "explanation": "汚れを落とす液体で、食べる対象にはならないので文が成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "体や物を洗う用品で、食べるものではないので文の主語として合わない。"}], "explanations": {"食物": "食べるもの全般を指し、冷蔵庫に入れて新鮮なうちに食べるという文に合う。", "食器": "皿などの道具で、食べるものではないので新鮮なうちに食べるという文に合わない。", "洗剤": "汚れを落とす液体で、食べる対象にはならないので文が成り立たない。", "石鹸": "体や物を洗う用品で、食べるものではないので文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この食物で、ノートに書いた間違いを消した。", "explanation": "字を消す道具の話で、食べ物としての食物は字を消す対象に合わない。"}, {"text": "この食物を壁に塗ると、きれいな色に変わる。", "explanation": "壁に塗って色を変える材料の話で、食べ物としての食物は塗る対象に合わない。"}, {"text": "この食物は、居間の机として置いてある。", "explanation": "部屋に置いて使う家具の話で、食べ物としての食物は家具に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "食べるもの全般を指し、鳥が雪の上に落ちた食べ物を探すという文に合う。"}, {"text": "雷", "is_correct": false, "explanation": "空で起こる放電現象で、鳥が探す対象にはならない。"}, {"text": "夕日", "is_correct": false, "explanation": "夕方の太陽で、鳥が雪の上で探す対象としては文が成り立たない。"}, {"text": "霧", "is_correct": false, "explanation": "空気中の細かい水滴で、鳥が落ちたものを探すという文の目的語にはならない。"}], "explanations": {"食物": "食べるもの全般を指し、鳥が雪の上に落ちた食べ物を探すという文に合う。", "雷": "空で起こる放電現象で、鳥が探す対象にはならない。", "夕日": "夕方の太陽で、鳥が雪の上で探す対象としては文が成り立たない。", "霧": "空気中の細かい水滴で、鳥が落ちたものを探すという文の目的語にはならない。"}, "sentence_index": 6, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏は冷たい食物をよく飲む。", "explanation": "飲むものを指す話で、食べ物としての食物は飲む対象にならない。"}, {"text": "庭に食物をまいて、きれいな砂の道を作る。", "explanation": "庭に敷いて道を作る材料の話で、食べ物としての食物は道の材料に合わない。"}, {"text": "お守りの食物を、大事に神棚に飾っている。", "explanation": "神棚に飾る護符の話で、食べ物としての食物は神棚の飾りに合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は、新鮮な食物が毎朝仕入れている。", "corrected_sentence": "この店は、新鮮な食物を毎朝仕入れている。", "error_description": "「仕入れる」の目的語に付く助詞が「が」になっている。「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39158, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では、山の食物に集めて冬に備える。", "corrected_sentence": "この地域では、山の食物を集めて冬に備える。", "error_description": "「集める」の目的語に付く助詞が「に」になっている。「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「食物に困る」の「に」。困る対象を示すので、「人々は食物に困った」と自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「困る」は目的語に「を」を取らないので、「食物を困った」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「食物が困った」は食物が困る主語になり、人々が困ったという文脈と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「食物と困った」は並列の形になり、困った対象を示せないので不自然。"}], "correct_answer": "に", "explanations": {"に": "「食物に困る」の「に」。困る対象を示すので、「人々は食物に困った」と自然に続く。", "を": "「困る」は目的語に「を」を取らないので、「食物を困った」は不自然。", "が": "「食物が困った」は食物が困る主語になり、人々が困ったという文脈と合わない。", "と": "「食物と困った」は並列の形になり、困った対象を示せないので不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手に入れてきた」の目的語を示す「を」。食物を手に入れてきた、という自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「手に入れる」は目的語に「を」を取るので、「食物が」は主語になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「食物に手に入れる」は手に入れる対象を「に」で示す形にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、手に入れる対象を表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「手に入れてきた」の目的語を示す「を」。食物を手に入れてきた、という自然な文になる。", "が": "「手に入れる」は目的語に「を」を取るので、「食物が」は主語になり不自然。", "に": "「食物に手に入れる」は手に入れる対象を「に」で示す形にならず、不自然。", "へ": "「へ」は方向を示し、手に入れる対象を表せないので合わない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間が生きるために食べるもの", "primary_collocate": null, "pronunciation": "しょくもつ", "ipa": "ɕokɯmotsɯ", "syllable_count": 4, "sentences": [{"text": "人間は食物と水がなければ、生きていけない。", "target_word": "食物", "complexity_tier": "T3", "furigana": "人間[にんげん]は食物[しょくもつ]と水[みず]がなければ、生[い]きていけない。", "sentence_source": "generated"}, {"text": "戦争で畑が焼かれ、人々は食物に困った。", "target_word": "食物", "complexity_tier": "T3", "furigana": "戦争[せんそう]で畑[はたけ]が焼[や]かれ、人々[ひとびと]は食物[しょくもつ]に困[こま]った。", "sentence_source": "generated"}, {"text": "世界には、十分な食物を手に入れられない人がいる。", "target_word": "食物", "complexity_tier": "T3", "furigana": "世界[せかい]には、十分[じゅうぶん]な食物[しょくもつ]を手[て]に入[い]れられない人[ひと]がいる。", "sentence_source": "generated"}, {"text": "食物から体に必要な栄養をとっている。", "target_word": "食物", "complexity_tier": "T3", "furigana": "食物[しょくもつ]から体[からだ]に必要[ひつよう]な栄養[えいよう]をとっている。", "sentence_source": "generated"}, {"text": "大雨で作物が育たず、国中で食物が足りなくなった。", "target_word": "食物", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で作物[さくもつ]が育[そだ]たず、国中[くにじゅう]で食物[しょくもつ]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "登山では、軽くて栄養のある食物を持っていく。", "target_word": "食物", "complexity_tier": "T3", "furigana": "登山[とざん]では、軽[かる]くて栄養[えいよう]のある食物[しょくもつ]を持[も]っていく。", "sentence_source": "generated"}, {"text": "難民キャンプに、食物と毛布が届けられた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "難民[なんみん]キャンプに、食物[しょくもつ]と毛布[もうふ]が届[とど]けられた。", "sentence_source": "generated"}, {"text": "昔の人は、狩りや農業で食物を手に入れてきた。", "target_word": "食物", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、狩[か]りや農業[のうぎょう]で食物[しょくもつ]を手[て]に入[い]れてきた。", "sentence_source": "generated"}, {"text": "食物をとらないと、体の力がなくなる。", "target_word": "食物", "complexity_tier": "T3", "furigana": "食物[しょくもつ]をとらないと、体[からだ]の力[ちから]がなくなる。", "sentence_source": "generated"}, {"text": "寒い島では、育つ食物の種類が少ない。", "target_word": "食物", "complexity_tier": "T3", "furigana": "寒[さむ]い島[しま]では、育[そだ]つ食物[しょくもつ]の種類[しゅるい]が少[すく]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食物", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "人が生きるために必要な食べ物、食糧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "「人間は食物と水がなければ生きていけない」で、生存に必要な食べ物を表し自然に入る。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は生きるために食べるものではないので、「辞書と水がなければ」は意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は生存に必要なものではないので、「時計と水がなければ」は成り立たない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は生きるための必需品ではないので、この空所には入らない。"}], "explanations": {"食物": "「人間は食物と水がなければ生きていけない」で、生存に必要な食べ物を表し自然に入る。", "辞書": "辞書は生きるために食べるものではないので、「辞書と水がなければ」は意味が通らない。", "時計": "時計は生存に必要なものではないので、「時計と水がなければ」は成り立たない。", "雑誌": "雑誌は生きるための必需品ではないので、この空所には入らない。"}, "sentence_index": 0, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食物の時間は、家族そろって楽しみたい。", "explanation": "ここは〈食事〉の意味。食物は食べ物そのものを指し、食べる時間を表す使い方はしないので合わない。"}, {"text": "母は毎朝、食物を飲んで家を出た。", "explanation": "飲むものを指す話で、食べ物としての食物は飲む対象にならないので合わない。"}, {"text": "朝は食物がわかなくて、何も食べなかった。", "explanation": "ここは〈食欲〉の意味。「食欲がわく・わかない」と言うので、食物を主語にする形では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "「難民キャンプに届けられた」物資で、毛布と並ぶ支援品として自然に入る。"}, {"text": "国境", "is_correct": false, "explanation": "国境は届けられる物ではないので、「国境と毛布が届けられた」は意味をなさない。"}, {"text": "大学", "is_correct": false, "explanation": "大学は物資ではないので、「大学と毛布が届けられた」は成り立たない。"}, {"text": "算数", "is_correct": false, "explanation": "算数は支援物資にならないので、この文の空所には入らない。"}], "explanations": {"食物": "「難民キャンプに届けられた」物資で、毛布と並ぶ支援品として自然に入る。", "国境": "国境は届けられる物ではないので、「国境と毛布が届けられた」は意味をなさない。", "大学": "大学は物資ではないので、「大学と毛布が届けられた」は成り立たない。", "算数": "算数は支援物資にならないので、この文の空所には入らない。"}, "sentence_index": 6, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、食物を一枚ずつ配ってから授業を始めた。", "explanation": "一枚ずつ配るのは紙の書類で、食べ物としての食物は合わない。"}, {"text": "魚を食べて食物になり、三日間寝込んだ。", "explanation": "ここは〈食中毒〉の意味。食物は食べ物そのものを指し、体調を崩した病気の状態は表さないので合わない。"}, {"text": "食物にお茶を飲んだ。", "explanation": "ここは〈食後〉の意味。食べ終わった後の時間を指すので、食べ物そのものを表す食物では言い換えられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海が荒れて、漁師は食物に手に入れられなかった。", "corrected_sentence": "海が荒れて、漁師は食物を手に入れられなかった。", "error_description": "助詞の誤り。「手に入れる」は目的語に「を」を取るので、「食物に」は誤り。正しくは「食物を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの日、村人たちは食物が分け合った。", "corrected_sentence": "祭りの日、村人たちは食物を分け合った。", "error_description": "助詞の誤り。「分け合う」は目的語に「を」を取るので、「食物が」は誤り。正しくは「食物を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "ここは「体内の水」を結ぶ「の」。体内に属する水を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「体内を水が」では名詞同士を結べない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較。「体内より水」では所属を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向。「体内へ水」では所属関係にならない。"}], "correct_answer": "の", "explanations": {"の": "ここは「体内の水」を結ぶ「の」。体内に属する水を表す。", "を": "「を」は目的語。「体内を水が」では名詞同士を結べない。", "より": "「より」は比較。「体内より水」では所属を示せない。", "へ": "「へ」は方向。「体内へ水」では所属関係にならない。"}, "error_tags": {"を": "目的語", "より": "比較", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "ここは「体内の熱」を結ぶ「の」。体内に属する熱を表す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列。「体内と熱」では所属を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「体内を熱を逃がす」では目的語が重なり文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所。「体内で熱」では所属の意味が出ない。"}], "correct_answer": "の", "explanations": {"の": "ここは「体内の熱」を結ぶ「の」。体内に属する熱を表す。", "と": "「と」は並列。「体内と熱」では所属を示せない。", "を": "「を」は目的語。「体内を熱を逃がす」では目的語が重なり文が成り立たない。", "で": "「で」は場所。「体内で熱」では所属の意味が出ない。"}, "error_tags": {"と": "並列", "を": "目的語", "で": "場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物のからだの、中側のこと。", "primary_collocate": null, "pronunciation": "たいない", "ipa": "tainai", "syllable_count": 4, "sentences": [{"text": "食べ物は、体内で少しずつ分解されて、力になります。", "target_word": "体内", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]は、体内[たいない]で少[すこ]しずつ分解[ぶんかい]されて、力[ちから]になります。", "sentence_source": "generated"}, {"text": "体内の水が足りなくなると、のどがかわきます。", "target_word": "体内", "complexity_tier": "T3", "furigana": "体内[たいない]の水[みず]が足[た]りなくなると、のどがかわきます。", "sentence_source": "generated"}, {"text": "薬は、飲んでから体内に広がります。", "target_word": "体内", "complexity_tier": "T3", "furigana": "薬[くすり]は、飲[の]んでから体内[たいない]に広[ひろ]がります。", "sentence_source": "generated"}, {"text": "運動すると、体内があたたかくなります。", "target_word": "体内", "complexity_tier": "T3", "furigana": "運動[うんどう]すると、体内[たいない]があたたかくなります。", "sentence_source": "generated"}, {"text": "血は、体内をぐるぐる回っています。", "target_word": "体内", "complexity_tier": "T3", "furigana": "血[ち]は、体内[たいない]をぐるぐる回[まわ]っています。", "sentence_source": "generated"}, {"text": "体内に入った菌と、体は戦います。", "target_word": "体内", "complexity_tier": "T3", "furigana": "体内[たいない]に入[はい]った菌[きん]と、体[からだ]は戦[たたか]います。", "sentence_source": "generated"}, {"text": "魚の体内には、浮き袋という袋があります。", "target_word": "体内", "complexity_tier": "T3", "furigana": "魚[さかな]の体内[たいない]には、浮[う]き袋[ぶくろ]という袋[ふくろ]があります。", "sentence_source": "generated"}, {"text": "暑い日は、体内の熱を逃がすために汗が出ます。", "target_word": "体内", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、体内[たいない]の熱[ねつ]を逃[に]がすために汗[あせ]が出[で]ます。", "sentence_source": "generated"}, {"text": "ご飯を食べないと、体内の栄養が足りなくなります。", "target_word": "体内", "complexity_tier": "T3", "furigana": "ご飯[はん]を食[た]べないと、体内[たいない]の栄養[えいよう]が足[た]りなくなります。", "sentence_source": "generated"}, {"text": "犬の体内にも、人と同じように血が流れています。", "target_word": "体内", "complexity_tier": "T3", "furigana": "犬[いぬ]の体内[たいない]にも、人[ひと]と同[おな]じように血[ち]が流[なが]れています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体内", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人や動物のからだの中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: かわき (Zipf 1.96)']::text[], '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "食べ物が分解される場所として体内を指す。"}, {"text": "体重", "is_correct": false, "explanation": "体重は重さの量で、分解される場所にはならない。"}, {"text": "体力", "is_correct": false, "explanation": "体力は能力で、分解される場所にはならない。"}, {"text": "体毛", "is_correct": false, "explanation": "体毛は毛で、分解される場所にはならない。"}], "explanations": {"体内": "食べ物が分解される場所として体内を指す。", "体重": "体重は重さの量で、分解される場所にはならない。", "体力": "体力は能力で、分解される場所にはならない。", "体毛": "体毛は毛で、分解される場所にはならない。"}, "sentence_index": 0, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体内は、食べ物を消化する大切な器官です。", "explanation": "ここは〈内臓〉の意味。体内は場所の名前で器官ではないので、器官の説明には使えない。"}, {"text": "体内は、食べ物を溶かしてためておく袋です。", "explanation": "ここは〈胃〉の意味。体内は空間の名前で、食べ物をためる袋の役目は言えない。"}, {"text": "体内は、体の外側を覆って守っています。", "explanation": "ここは〈皮膚〉の意味。体内は内側を指すので、外側を覆って守る働きは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "魚の中にある浮き袋の場所として体内を指す。"}, {"text": "体液", "is_correct": false, "explanation": "体液は液体の名前で、浮き袋がある場所にはならない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は温度で、袋がある場所にはならない。"}, {"text": "体色", "is_correct": false, "explanation": "体色は色で、袋がある場所にはならない。"}], "explanations": {"体内": "魚の中にある浮き袋の場所として体内を指す。", "体液": "体液は液体の名前で、浮き袋がある場所にはならない。", "体温": "体温は温度で、袋がある場所にはならない。", "体色": "体色は色で、袋がある場所にはならない。"}, "sentence_index": 6, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬の体内は、毛で覆われています。", "explanation": "ここは〈体〉の意味。毛で覆われているのは外側で、体内は内側なので合わない。"}, {"text": "体内は、血を全身に送るポンプです。", "explanation": "ここは〈心臓〉の意味。血を送るポンプは器官で、体内は空間の名前なので合わない。"}, {"text": "体内は、体を支える硬い組織です。", "explanation": "ここは〈骨〉の意味。体を支える硬い組織は骨で、体内は空間を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬は体内を分解され、効き目が出る。", "corrected_sentence": "薬は体内で分解され、効き目が出る。", "error_description": "分解が行われる場所は「で」で示す。「を」は誤りで、正しくは「体内で分解され」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体内で熱が発生しると、汗が出る。", "corrected_sentence": "体内で熱が発生すると、汗が出る。", "error_description": "「発生する」の仮定の形は「発生すると」。「発生しると」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "ここは侵入先を示す「に」。ウイルスが入り込む先が体内。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「体内を侵入」では侵入の対象にできない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体。「体内の侵入」では動詞の侵入に続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列。「体内と侵入」では侵入先にならない。"}], "correct_answer": "に", "explanations": {"に": "ここは侵入先を示す「に」。ウイルスが入り込む先が体内。", "を": "「を」は目的語。「体内を侵入」では侵入の対象にできない。", "の": "「の」は連体。「体内の侵入」では動詞の侵入に続かない。", "と": "「と」は並列。「体内と侵入」では侵入先にならない。"}, "error_tags": {"を": "目的語", "の": "連体", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "ここは取り込み先を示す「に」。酸素が取り込まれる先が体内。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。「体内が取り込まれた」では体内が取り込む主体になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較。「体内より取り込まれた」では比較文にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。受身の「取り込まれた」に「を」は続かず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "ここは取り込み先を示す「に」。酸素が取り込まれる先が体内。", "が": "「が」は主語。「体内が取り込まれた」では体内が取り込む主体になる。", "より": "「より」は比較。「体内より取り込まれた」では比較文にならない。", "を": "「を」は目的語。受身の「取り込まれた」に「を」は続かず文が成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動物や人間の、からだの内部。", "primary_collocate": null, "pronunciation": "たいない", "ipa": "tainai", "syllable_count": 4, "sentences": [{"text": "摂取した薬物は、肝臓で分解されて体内から排出される。", "target_word": "体内", "complexity_tier": "T3", "furigana": "摂取[せっしゅ]した薬物[やくぶつ]は、肝臓[かんぞう]で分解[ぶんかい]されて体内[たいない]から排出[はいしゅつ]される。", "sentence_source": "generated"}, {"text": "ウイルスが体内に侵入すると、免疫反応が起こる。", "target_word": "体内", "complexity_tier": "T3", "furigana": "ウイルスが体内[たいない]に侵入[しんにゅう]すると、免疫[めんえき]反応[はんのう]が起[お]こる。", "sentence_source": "generated"}, {"text": "人間の体内では、約三十七度の温度が保たれている。", "target_word": "体内", "complexity_tier": "T3", "furigana": "人間[にんげん]の体内[たいない]では、約[やく]三十七度[さんじゅうななど]の温度[おんど]が保[たも]たれている。", "sentence_source": "generated"}, {"text": "検査のため、カメラを体内に入れて胃の様子を調べた。", "target_word": "体内", "complexity_tier": "T3", "furigana": "検査[けんさ]のため、カメラを体内[たいない]に入[い]れて胃[い]の様子[ようす]を調[しら]べた。", "sentence_source": "generated"}, {"text": "水銀は魚の体内に蓄積されやすい。", "target_word": "体内", "complexity_tier": "T3", "furigana": "水銀[すいぎん]は魚[さかな]の体内[たいない]に蓄積[ちくせき]されやすい。", "sentence_source": "generated"}, {"text": "寄生虫が動物の体内で成長することもある。", "target_word": "体内", "complexity_tier": "T3", "furigana": "寄生虫[きせいちゅう]が動物[どうぶつ]の体内[たいない]で成長[せいちょう]することもある。", "sentence_source": "generated"}, {"text": "運動によって、体内の脂肪が燃焼される。", "target_word": "体内", "complexity_tier": "T3", "furigana": "運動[うんどう]によって、体内[たいない]の脂肪[しぼう]が燃焼[ねんしょう]される。", "sentence_source": "generated"}, {"text": "体内に取り込まれた酸素は、血液によって全身へ運ばれる。", "target_word": "体内", "complexity_tier": "T3", "furigana": "体内[たいない]に取[と]り込[こ]まれた酸素[さんそ]は、血液[けつえき]によって全身[ぜんしん]へ運[はこ]ばれる。", "sentence_source": "generated"}, {"text": "毒が体内に回る前に、医師が処置を行った。", "target_word": "体内", "complexity_tier": "T3", "furigana": "毒[どく]が体内[たいない]に回[まわ]る前[まえ]に、医師[いし]が処置[しょち]を行[おこな]った。", "sentence_source": "generated"}, {"text": "哺乳類の多くは、母親の体内で子を育てる。", "target_word": "体内", "complexity_tier": "T3", "furigana": "哺乳類[ほにゅうるい]の多[おお]くは、母親[ははおや]の体内[たいない]で子[こ]を育[そだ]てる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体内", "label": "基本形"}], "register": "formal", "sense_fingerprint": "医学や生物学の話題で言う、動物や人間のからだの内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '209b78b4-771f-4013-a7d3-03928529d54b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "薬が排出される元の場所として体内を指す。"}, {"text": "体重", "is_correct": false, "explanation": "体重は重さで、排出の起点にはならない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は温度で、排出の起点にはならない。"}, {"text": "体毛", "is_correct": false, "explanation": "体毛は毛で、排出の起点にはならない。"}], "explanations": {"体内": "薬が排出される元の場所として体内を指す。", "体重": "体重は重さで、排出の起点にはならない。", "体温": "体温は温度で、排出の起点にはならない。", "体毛": "体毛は毛で、排出の起点にはならない。"}, "sentence_index": 0, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古いエンジンの体内では、オイルが循環しています。", "explanation": "ここは〈内部〉の意味。体内は生き物の体に使う語で、機械には言わない。"}, {"text": "臓器を移植する手術で、体内を取り出しました。", "explanation": "ここは〈内臓〉の意味。取り出すのは内臓そのもので、体内は空間の名前なので取り出せない。"}, {"text": "体内は、胃の中を映す細い器具です。", "explanation": "ここは〈内視鏡〉の意味。器具の名前で、体の内側を指す体内は道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "脂肪がある場所として体内を指す。"}, {"text": "体色", "is_correct": false, "explanation": "体色は色で、脂肪がある場所にはならない。"}, {"text": "体長", "is_correct": false, "explanation": "体長は長さで、脂肪がある場所にはならない。"}, {"text": "体調", "is_correct": false, "explanation": "体調は健康状態で、脂肪がある場所にはならない。"}], "explanations": {"体内": "脂肪がある場所として体内を指す。", "体色": "体色は色で、脂肪がある場所にはならない。", "体長": "体長は長さで、脂肪がある場所にはならない。", "体調": "体調は健康状態で、脂肪がある場所にはならない。"}, "sentence_index": 6, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母親の体内は、子に栄養を与える白い液体です。", "explanation": "ここは〈母乳〉の意味。体内は場所で、栄養を与える白い液体は母乳なので合わない。"}, {"text": "鳥の体内は、卵を守るための場所です。", "explanation": "ここは〈巣〉の意味。卵を守る場所は巣で、体の内側を指す体内は場所の役をしない。"}, {"text": "体内は、赤ちゃんが育つ袋です。", "explanation": "ここは〈子宮〉の意味。赤ちゃんが育つ袋は子宮で、体内は袋の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寄生虫は動物の体内に成長する。", "corrected_sentence": "寄生虫は動物の体内で成長する。", "error_description": "成長が行われる場所は「で」で示す。「に」は誤りで、正しくは「体内で成長する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39161, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "細菌が体内に侵入しると、炎症が起こる。", "corrected_sentence": "細菌が体内に侵入すると、炎症が起こる。", "error_description": "「侵入する」の仮定の形は「侵入すると」。「侵入しると」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823afda4-11a5-4525-90be-dec1f2c94e09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体助詞。『遠隔の山村』で『山村』を修飾する正しい形"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『遠隔が山村』では名詞同士がつながらない"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『遠隔を』に続く動詞がなく、山村とも結べない"}, {"text": "に", "is_correct": false, "explanation": "場所・到達点を示す。『遠隔に山村』では意味が通らない"}], "correct_answer": "の", "explanations": {"の": "連体助詞。『遠隔の山村』で『山村』を修飾する正しい形", "が": "主語を示す。『遠隔が山村』では名詞同士がつながらない", "を": "目的語を示す。『遠隔を』に続く動詞がなく、山村とも結べない", "に": "場所・到達点を示す。『遠隔に山村』では意味が通らない"}, "error_tags": {"が": "主格（主語）", "を": "目的語", "に": "位置・到達点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体助詞。『遠隔の地』で『地』を修飾する正しい形"}, {"text": "へ", "is_correct": false, "explanation": "方向・到達点を示す。『遠隔へ地から届いた』では『地』を修飾できず、届いた手紙の出どころとしても成り立たない"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す。『遠隔より地』と続けると、比べる対象がなく文が成り立たない"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。『遠隔と地』と並べると一つの場所を表せず、『地から』の修飾にならない"}], "correct_answer": "の", "explanations": {"の": "連体助詞。『遠隔の地』で『地』を修飾する正しい形", "へ": "方向・到達点を示す。『遠隔へ地から届いた』では『地』を修飾できず、届いた手紙の出どころとしても成り立たない", "より": "比較の基準を示す。『遠隔より地』と続けると、比べる対象がなく文が成り立たない", "と": "並列を示す。『遠隔と地』と並べると一つの場所を表せず、『地から』の修飾にならない"}, "error_tags": {"へ": "方向・到達点", "より": "比較", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "遠く離れた場所のこと。", "primary_collocate": null, "pronunciation": "えんかく", "ipa": "eŋkaku", "syllable_count": 4, "sentences": [{"text": "遠隔の島に住む家族と、毎晩ビデオ通話で話します。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の島[しま]に住[す]む家族[かぞく]と、毎晩[まいばん]ビデオ通話[つうわ]で話[はな]します。", "sentence_source": "generated"}, {"text": "祖父は遠隔の山村で一人で暮らしています。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "祖父[そふ]は遠隔[えんかく]の山村[さんそん]で一人[ひとり]で暮[く]らしています。", "sentence_source": "generated"}, {"text": "遠隔の村から送られた写真を見て、みんな驚きました。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の村[むら]から送[おく]られた写真[しゃしん]を見[み]て、みんな驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "遠隔の山あいにある工場なので、毎朝のバスは早い時間に出ます。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の山あい[やまあい]にある工場[こうじょう]なので、毎朝[まいあさ]のバスは早[はや]い時間[じかん]に出[で]ます。", "sentence_source": "generated"}, {"text": "彼は遠隔の離島に住んでいるため、会議にはいつも画面で参加します。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "彼[かれ]は遠隔[えんかく]の離島[りとう]に住[す]んでいるため、会議[かいぎ]にはいつも画面[がめん]で参加[さんか]します。", "sentence_source": "generated"}, {"text": "遠隔の町まで荷物を届けるには、三日かかります。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の町[まち]まで荷物[にもつ]を届[とど]けるには、三日[みっか]かかります。", "sentence_source": "generated"}, {"text": "遠隔の土地に住んでいても、親友の気持ちはよく分かります。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の土地[とち]に住[す]んでいても、親友[しんゆう]の気持[きも]ちはよく分[わ]かります。", "sentence_source": "generated"}, {"text": "遠隔の地から届いた手紙には、雪の話が書いてありました。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の地[ち]から届[とど]いた手紙[てがみ]には、雪[ゆき]の話[はなし]が書[か]いてありました。", "sentence_source": "generated"}, {"text": "通信が切れて、遠隔の仲間と連絡が取れなくなった。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "通信[つうしん]が切[き]れて、遠隔[えんかく]の仲間[なかま]と連絡[れんらく]が取[と]れなくなった。", "sentence_source": "generated"}, {"text": "遠隔の地に暮らす娘に、毎月荷物を送っています。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の地[ち]に暮[く]らす娘[むすめ]に、毎月[まいつき]荷物[にもつ]を送[おく]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠隔", "label": "基本形"}], "register": "中立", "sense_fingerprint": "遠く離れた場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遠隔", "is_correct": true, "explanation": "『遠く離れた場所』の意味で、島の位置を表すので合う"}, {"text": "遠慮", "is_correct": false, "explanation": "『控えめにすること』の意味で、島の位置は表せないので合わない"}, {"text": "契約", "is_correct": false, "explanation": "取り決めの意味で、島を修飾する語にはならないので合わない"}, {"text": "体温", "is_correct": false, "explanation": "身体の熱の意味で、島の位置の説明にならないので合わない"}], "explanations": {"遠隔": "『遠く離れた場所』の意味で、島の位置を表すので合う", "遠慮": "『控えめにすること』の意味で、島の位置は表せないので合わない", "契約": "取り決めの意味で、島を修飾する語にはならないので合わない", "体温": "身体の熱の意味で、島の位置の説明にならないので合わない"}, "sentence_index": 0, "correct_answer": "遠隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遠隔の昔、この村は栄えていました。", "explanation": "ここは〈遠い（時間的に隔たった）〉の意味。『遠隔』は場所の隔たりを表すので、時間の隔たりには使わない"}, {"text": "彼は遠隔せずに、料理をたくさん食べました。", "explanation": "ここは〈遠慮〉の意味（控えること）。『遠隔』は場所の隔たりを指す語で、態度は表さない"}, {"text": "この町から駅までの遠隔は、十キロです。", "explanation": "ここは〈距離〉の意味。『遠隔』は離れた場所を指す語で、道のりの長さの主語にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠隔", "is_correct": true, "explanation": "『遠く離れた場所』の意味で、土地の位置を表すので合う"}, {"text": "寿命", "is_correct": false, "explanation": "生物が生きられる期間の意味で、土地を修飾しないので合わない"}, {"text": "名刺", "is_correct": false, "explanation": "個人の連絡先を記した紙の意味で、土地の説明にならないので合わない"}, {"text": "水温", "is_correct": false, "explanation": "水の温度の意味で、土地を修飾しないので合わない"}], "explanations": {"遠隔": "『遠く離れた場所』の意味で、土地の位置を表すので合う", "寿命": "生物が生きられる期間の意味で、土地を修飾しないので合わない", "名刺": "個人の連絡先を記した紙の意味で、土地の説明にならないので合わない", "水温": "水の温度の意味で、土地を修飾しないので合わない"}, "sentence_index": 6, "correct_answer": "遠隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームは来月、遠隔で関西へ行く予定です。", "explanation": "ここは〈遠征〉の意味（遠くへ出かけて試合や活動をすること）。『遠隔』は場所を指す語で、移動の仕方は表せない"}, {"text": "遠隔漁業の船が、一か月ぶりに帰ってきました。", "explanation": "ここは〈遠洋〉の意味（沖合の遠い海）。『遠隔』は離れた場所を指す語で、海域の種類は表せない"}, {"text": "ドアの遠隔を広げてください。", "explanation": "ここは〈間隔〉の意味（物と物の隙間）。『遠隔』は離れた場所を指す語で、隙間の広さは表せない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遠隔を村に住む友人と、毎週手紙を交換しています。", "corrected_sentence": "遠隔の村に住む友人と、毎週手紙を交換しています。", "error_description": "『遠隔』に続く助詞が『を』になっている。『遠隔の村』と名詞を修飾する『の』が正しい。『を』では目的語になり、文が成り立たない", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠隔が地で働く父から、毎月電話がかかってきます。", "corrected_sentence": "遠隔の地で働く父から、毎月電話がかかってきます。", "error_description": "『遠隔』と『地』をつなぐ助詞が『が』になっている。『遠隔の地』と名詞を修飾する『の』が正しく、『が』では文が成り立たない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体助詞。『遠隔の山あい』で『山あい』を修飾する正しい形"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。『遠隔が山あい』では名詞同士がつながらない"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『遠隔を』に続く動詞がない"}, {"text": "に", "is_correct": false, "explanation": "位置を示す。『遠隔に山あいにある』では意味が通らない"}], "correct_answer": "の", "explanations": {"の": "連体助詞。『遠隔の山あい』で『山あい』を修飾する正しい形", "が": "主語を示す。『遠隔が山あい』では名詞同士がつながらない", "を": "目的語を示す。『遠隔を』に続く動詞がない", "に": "位置を示す。『遠隔に山あいにある』では意味が通らない"}, "error_tags": {"が": "主格（主語）", "を": "目的語", "に": "位置・到達点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体助詞。『遠隔の土地』で『土地』を修飾する正しい形"}, {"text": "へ", "is_correct": false, "explanation": "方向・到達点を示す。『遠隔へ土地に住む』では場所の修飾にならず、『住む』の向かう先としても不自然"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す。『遠隔より土地』では比べる対象が立たず、文が成り立たない"}, {"text": "と", "is_correct": false, "explanation": "並列を示す。『遠隔と土地』と並べると一つの場所を表せず、『土地に』の修飾にならない"}], "correct_answer": "の", "explanations": {"の": "連体助詞。『遠隔の土地』で『土地』を修飾する正しい形", "へ": "方向・到達点を示す。『遠隔へ土地に住む』では場所の修飾にならず、『住む』の向かう先としても不自然", "より": "比較の基準を示す。『遠隔より土地』では比べる対象が立たず、文が成り立たない", "と": "並列を示す。『遠隔と土地』と並べると一つの場所を表せず、『土地に』の修飾にならない"}, "error_tags": {"へ": "方向・到達点", "より": "比較", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地理的に離れた場所。", "primary_collocate": null, "pronunciation": "えんかく", "ipa": "eŋkaku", "syllable_count": 4, "sentences": [{"text": "遠隔の島では、船が週に一度しか来ません。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の島[しま]では、船[ふね]が週[しゅう]に一度[いちど]しか来[き]ません。", "sentence_source": "generated"}, {"text": "この村は都会から見ると、遠隔の山あいにあります。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "この村[むら]は都会[とかい]から見[み]ると、遠隔[えんかく]の山あい[やまあい]にあります。", "sentence_source": "generated"}, {"text": "遠隔の地に学校を建てる計画が進んでいます。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の地[ち]に学校[がっこう]を建[た]てる計画[けいかく]が進[すす]んでいます。", "sentence_source": "generated"}, {"text": "遠隔の小さな港町で、魚を買いました。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の小[ちい]さな港町[みなとまち]で、魚[さかな]を買[か]いました。", "sentence_source": "generated"}, {"text": "地図で見ると、あの島は遠隔の地にあり、本土とは橋でつながっていません。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、あの島[しま]は遠隔[えんかく]の地[ち]にあり、本土[ほんど]とは橋[はし]でつながっていません。", "sentence_source": "generated"}, {"text": "遠隔の山あいでは、冬に雪で道が通れなくなります。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の山[やま]あいでは、冬[ふゆ]に雪[ゆき]で道[みち]が通[とお]れなくなります。", "sentence_source": "generated"}, {"text": "遠隔の研究所まで、ヘリコプターで行きました。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の研究所[けんきゅうじょ]まで、ヘリコプターで行[い]きました。", "sentence_source": "generated"}, {"text": "遠隔の土地に住む人々は、自分たちで野菜を育てています。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の土地[とち]に住[す]む人々[ひとびと]は、自分[じぶん]たちで野菜[やさい]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "遠隔の谷間にある集落なので、車がないと不便です。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の谷間[たにま]にある集落[しゅうらく]なので、車[くるま]がないと不便[ふべん]です。", "sentence_source": "generated"}, {"text": "遠隔の海に浮かぶ島で、珍しい鳥を見ました。", "target_word": "遠隔", "complexity_tier": "T3", "furigana": "遠隔[えんかく]の海[うみ]に浮[う]かぶ島[しま]で、珍[めずら]しい鳥[とり]を見[み]ました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠隔", "label": "基本形"}], "register": "中立", "sense_fingerprint": "地理的に離れた場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遠隔", "is_correct": true, "explanation": "『地理的に離れた場所』の意味で、島の位置を表すので合う"}, {"text": "食欲", "is_correct": false, "explanation": "食べたいと思う気持ちの意味で、島の説明にならないので合わない"}, {"text": "紅茶", "is_correct": false, "explanation": "飲み物の名前で、島を修飾しないので合わない"}, {"text": "保険", "is_correct": false, "explanation": "万一に備える制度の意味で、島の位置を表せないので合わない"}], "explanations": {"遠隔": "『地理的に離れた場所』の意味で、島の位置を表すので合う", "食欲": "食べたいと思う気持ちの意味で、島の説明にならないので合わない", "紅茶": "飲み物の名前で、島を修飾しないので合わない", "保険": "万一に備える制度の意味で、島の位置を表せないので合わない"}, "sentence_index": 0, "correct_answer": "遠隔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "遠隔の将来を、みんなで考えました。", "explanation": "ここは〈遠い（時間的に先の）〉の意味。『遠隔』は場所の隔たりを表すので、時間の隔たりには使わない"}, {"text": "家から学校までの遠隔は、徒歩で十分です。", "explanation": "ここは〈距離〉の意味。『遠隔』は場所を指す語で、道のりの長さは表せない"}, {"text": "来週、遠隔で海へ行きます。", "explanation": "ここは〈遠足〉の意味（学校などの校外での行事）。『遠隔』は場所を指す語で、行事の種類は表せない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遠隔", "is_correct": true, "explanation": "『地理的に離れた場所』の意味で、研究所の位置を表すので合う"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚の意味で、研究所を修飾しないので合わない"}, {"text": "包丁", "is_correct": false, "explanation": "料理に使う刃物の意味で、研究所の説明にならないので合わない"}, {"text": "雑誌", "is_correct": false, "explanation": "定期的に出版される本の意味で、研究所を修飾しないので合わない"}], "explanations": {"遠隔": "『地理的に離れた場所』の意味で、研究所の位置を表すので合う", "眠気": "眠たい感覚の意味で、研究所を修飾しないので合わない", "包丁": "料理に使う刃物の意味で、研究所の説明にならないので合わない", "雑誌": "定期的に出版される本の意味で、研究所を修飾しないので合わない"}, "sentence_index": 6, "correct_answer": "遠隔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遠隔航海の船が、港に戻ってきました。", "explanation": "ここは〈遠洋〉の意味（沖合の遠い海）。『遠隔』は離れた場所を指す語で、海の種類を表す語にはならない"}, {"text": "この道の遠隔を広げてください。", "explanation": "ここは〈幅〉の意味。『遠隔』は離れた場所を指す語で、道の広さは表せない"}, {"text": "彼との心の遠隔が、少しずつ縮まりました。", "explanation": "ここは〈心の距離〉の意味（気持ちの隔たり）。『遠隔』は場所の隔たりを表す語で、気持ちの隔たりには使わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遠隔に村では、ヘリコプターで荷物を運びます。", "corrected_sentence": "遠隔の村では、ヘリコプターで荷物を運びます。", "error_description": "『遠隔』に続く助詞が『に』になっている。名詞を修飾する『の』が正しく、『に』では『村』とつながらない", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39163, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠隔を海に面した町では、漁師が朝早く出かけます。", "corrected_sentence": "遠隔の海に面した町では、漁師が朝早く出かけます。", "error_description": "『遠隔』に続く助詞が『を』になっている。名詞を修飾する『の』が正しく、『を』では『海に面した町』とつながらない", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
