INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39164, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "わるいことをするのを、てつだうこと。", "primary_collocate": null, "pronunciation": "かたん", "ipa": "katan", "syllable_count": 3, "sentences": [{"text": "友だちのいたずらに加担して、先生にしかられた。", "target_word": "加担", "complexity_tier": "T3", "furigana": "友[とも]だちのいたずらに加担[かたん]して、先生[せんせい]にしかられた。", "sentence_source": "generated"}, {"text": "うそをついた弟に加担すると、私もうそつきになってしまう。", "target_word": "加担", "complexity_tier": "T3", "furigana": "うそをついた弟[おとうと]に加担[かたん]すると、私[わたし]もうそつきになってしまう。", "sentence_source": "generated"}, {"text": "万引きに加担した少年は、店の人に謝った。", "target_word": "加担", "complexity_tier": "T3", "furigana": "万引[まんび]きに加担[かたん]した少年[しょうねん]は、店[みせ]の人[ひと]に謝[あやま]った。", "sentence_source": "generated"}, {"text": "悪いことだと知りながら加担したので、言いわけはできない。", "target_word": "加担", "complexity_tier": "T3", "furigana": "悪[わる]いことだと知[し]りながら加担[かたん]したので、言[い]いわけはできない。", "sentence_source": "generated"}, {"text": "彼はいじめに加担したことを、今でも後悔している。", "target_word": "加担", "complexity_tier": "T3", "furigana": "彼[かれ]はいじめに加担[かたん]したことを、今[いま]でも後悔[こうかい]している。", "sentence_source": "generated"}, {"text": "泥棒に加担する人は、同じように罪になる。", "target_word": "加担", "complexity_tier": "T3", "furigana": "泥棒[どろぼう]に加担[かたん]する人[ひと]は、同[おな]じように罪[つみ]になる。", "sentence_source": "generated"}, {"text": "私は友だちのカンニングに加担したくないので、はっきり断った。", "target_word": "加担", "complexity_tier": "T3", "furigana": "私[わたし]は友[とも]だちのカンニングに加担[かたん]したくないので、はっきり断[ことわ]った。", "sentence_source": "generated"}, {"text": "くやしいが、仲間のけんかに加担したのは事実だ。", "target_word": "加担", "complexity_tier": "T3", "furigana": "くやしいが、仲間[なかま]のけんかに加担[かたん]したのは事実[じじつ]だ。", "sentence_source": "generated"}, {"text": "悪いことに加担しない勇気を持つのは、むずかしいが大切だ。", "target_word": "加担", "complexity_tier": "T3", "furigana": "悪[わる]いことに加担[かたん]しない勇気[ゆうき]を持[も]つのは、むずかしいが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "ごみの不法投棄に加担した業者が、町から注意を受けた。", "target_word": "加担", "complexity_tier": "T3", "furigana": "ごみの不法投棄[ふほうとうき]に加担[かたん]した業者[ぎょうしゃ]が、町[まち]から注意[ちゅうい]を受[う]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加担", "label": "基本形"}, {"form": "加担する", "label": "辞書形"}, {"form": "加担して", "label": "て形"}, {"form": "加担した", "label": "た形"}], "register": "標準", "sense_fingerprint": "悪いことを手伝う、仲間になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39164, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加担", "is_correct": true, "explanation": "「いたずらに加担して」は、いたずらを手伝う意味で文が成り立つ。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩はいたずらに関わる行為ではなく、「いたずらに」と続かない。"}, {"text": "結婚", "is_correct": false, "explanation": "結婚は「いたずらに」と結びつかず、文脈に合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行はいたずらの手伝いにならず、文の意味が通らない。"}], "explanations": {"加担": "「いたずらに加担して」は、いたずらを手伝う意味で文が成り立つ。", "散歩": "散歩はいたずらに関わる行為ではなく、「いたずらに」と続かない。", "結婚": "結婚は「いたずらに」と結びつかず、文脈に合わない。", "旅行": "旅行はいたずらの手伝いにならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "加担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちの散歩に加担して、道を覚えた。", "explanation": "ここは〈同行〉の意味。加担は悪事に手を貸すことで、散歩に付き合う意味では使わない。"}, {"text": "新しいプロジェクトに加担して、企画を考えた。", "explanation": "ここは〈関与〉の意味。加担は悪事に手を貸すことなので、正当な企画への関わりには使えない。"}, {"text": "報告書の作成に加担して、締め切りを守った。", "explanation": "ここは〈担当〉の意味。加担は悪事に関わることなので、正当な業務には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39164, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加担", "is_correct": true, "explanation": "「カンニングに加担したくない」は、カンニングを手伝いたくないという意味で自然に成り立つ。"}, {"text": "雑談", "is_correct": false, "explanation": "「カンニングに雑談したくない」は意味が通らず、文に合わない。"}, {"text": "中断", "is_correct": false, "explanation": "「カンニングに中断したくない」は成り立たず、文脈に合わない。"}, {"text": "外出", "is_correct": false, "explanation": "外出はカンニングの対象にならず、「に」で続かない。"}], "explanations": {"加担": "「カンニングに加担したくない」は、カンニングを手伝いたくないという意味で自然に成り立つ。", "雑談": "「カンニングに雑談したくない」は意味が通らず、文に合わない。", "中断": "「カンニングに中断したくない」は成り立たず、文脈に合わない。", "外出": "外出はカンニングの対象にならず、「に」で続かない。"}, "sentence_index": 6, "correct_answer": "加担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チームの加担に全力を注いだ。", "explanation": "ここは〈応援〉の意味。加担は悪事を手伝う意味なので、チームを応援する場面では使えない。"}, {"text": "悪いことを止めるよう、友だちに加担した。", "explanation": "ここは〈注意〉の意味。加担は悪事に手を貸すことで、止めるための行為とは合わない。"}, {"text": "母の料理に加担して、皿を並べた。", "explanation": "ここは〈手伝い〉の意味。加担は悪いことを手伝う意味なので、家事の手伝いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39164, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの悪ふざけを加担した。", "corrected_sentence": "友だちの悪ふざけに加担した。", "error_description": "「加担」は「に」で手伝う相手や対象を示すので、「を」は誤り。正しくは「に加担した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39164, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちの悪事に加担しないかった。", "corrected_sentence": "友だちの悪事に加担しなかった。", "error_description": "過去の否定は「しなかった」。「しないかった」は活用の誤りで、「加担しない」の部分が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
