INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39165, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある悪事や問題行為に、積極的または消極的に関与すること。", "primary_collocate": null, "pronunciation": "かたん", "ipa": "katan", "syllable_count": 3, "sentences": [{"text": "彼は会社の不正に加担したとして、責任を問われた。", "target_word": "加担", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の不正[ふせい]に加担[かたん]したとして、責任[せきにん]を問[と]われた。", "sentence_source": "generated"}, {"text": "詐欺に加担した疑いで、男が逮捕された。", "target_word": "加担", "complexity_tier": "T3", "furigana": "詐欺[さぎ]に加担[かたん]した疑[うたが]いで、男[おとこ]が逮捕[たいほ]された。", "sentence_source": "generated"}, {"text": "自分で手を下さなくても、黙って見過ごせば消極的な加担と言われる。", "target_word": "加担", "complexity_tier": "T3", "furigana": "自分[じぶん]で手[て]を下[くだ]さなくても、黙[だま]って見過[みす]ごせば消極的[しょうきょくてき]な加担[かたん]と言[い]われる。", "sentence_source": "generated"}, {"text": "彼女は不正を知りながら、上司の指示に従って加担してしまった。", "target_word": "加担", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は不正[ふせい]を知[し]りながら、上司[じょうし]の指示[しじ]に従[したが]って加担[かたん]してしまった。", "sentence_source": "generated"}, {"text": "組織的な犯行に加担した者は、全員が処分を受けた。", "target_word": "加担", "complexity_tier": "T3", "furigana": "組織的[そしきてき]な犯行[はんこう]に加担[かたん]した者[もの]は、全員[ぜんいん]が処分[しょぶん]を受[う]けた。", "sentence_source": "generated"}, {"text": "危険な計画に加担することを、彼はきっぱり拒んだ。", "target_word": "加担", "complexity_tier": "T3", "furigana": "危険[きけん]な計画[けいかく]に加担[かたん]することを、彼[かれ]はきっぱり拒[こば]んだ。", "sentence_source": "generated"}, {"text": "情報を隠すことも、不正への加担になりうる。", "target_word": "加担", "complexity_tier": "T3", "furigana": "情報[じょうほう]を隠[かく]すことも、不正[ふせい]への加担[かたん]になりうる。", "sentence_source": "generated"}, {"text": "裁判では、被告がどの程度加担したかが争点になった。", "target_word": "加担", "complexity_tier": "T3", "furigana": "裁判[さいばん]では、被告[ひこく]がどの程度[ていど]加担[かたん]したかが争点[そうてん]になった。", "sentence_source": "generated"}, {"text": "事件への加担を否定した社員は、証拠を出して無実を訴えた。", "target_word": "加担", "complexity_tier": "T3", "furigana": "事件[じけん]への加担[かたん]を否定[ひてい]した社員[しゃいん]は、証拠[しょうこ]を出[だ]して無実[むじつ]を訴[うった]えた。", "sentence_source": "generated"}, {"text": "悪事に加担する意図はなかったと、本人は説明している。", "target_word": "加担", "complexity_tier": "T3", "furigana": "悪事[あくじ]に加担[かたん]する意図[いと]はなかったと、本人[ほんにん]は説明[せつめい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "加担", "label": "基本形"}, {"form": "加担する", "label": "辞書形"}, {"form": "加担して", "label": "て形"}, {"form": "加担した", "label": "た形"}], "register": "標準", "sense_fingerprint": "悪事や問題行為に積極的・消極的に関わる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39165, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加担", "is_correct": true, "explanation": "「会社の不正に加担した」は不正に関与した意味で、責任を問われる文脈に合う。"}, {"text": "外出", "is_correct": false, "explanation": "「会社の不正に外出した」は意味が通らず、不正の文脈に合わない。"}, {"text": "雑談", "is_correct": false, "explanation": "「会社の不正に雑談した」は成り立たず、責任を問われる文脈と合わない。"}, {"text": "中断", "is_correct": false, "explanation": "「会社の不正に中断した」は不自然で、不正への関与を表せない。"}], "explanations": {"加担": "「会社の不正に加担した」は不正に関与した意味で、責任を問われる文脈に合う。", "外出": "「会社の不正に外出した」は意味が通らず、不正の文脈に合わない。", "雑談": "「会社の不正に雑談した」は成り立たず、責任を問われる文脈と合わない。", "中断": "「会社の不正に中断した」は不自然で、不正への関与を表せない。"}, "sentence_index": 0, "correct_answer": "加担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不正を調べるため、すぐに加担した。", "explanation": "ここは〈調査〉の意味。加担は不正に関わることなので、不正を調べる行動には合わない。"}, {"text": "不正の監視に加担して、報告書をまとめた。", "explanation": "ここは〈監視〉の意味。加担は不正に関わる意味なので、取り締まりのための監視には使えない。"}, {"text": "新しいサークルに加担した。", "explanation": "ここは〈参加〉の意味。加担は悪事に関わる意味なので、正当な活動への参加には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39165, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加担", "is_correct": true, "explanation": "「不正への加担」は不正に関わることを表し、情報を隠す行為の文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「不正への散歩」は不自然で、不正に関わる意味を表せない。"}, {"text": "旅行", "is_correct": false, "explanation": "「不正への旅行」は意味が通らず、文脈に合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "「不正への結婚」は成り立たず、文の内容に合わない。"}], "explanations": {"加担": "「不正への加担」は不正に関わることを表し、情報を隠す行為の文脈に合う。", "散歩": "「不正への散歩」は不自然で、不正に関わる意味を表せない。", "旅行": "「不正への旅行」は意味が通らず、文脈に合わない。", "結婚": "「不正への結婚」は成り立たず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "加担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新製品の開発に加担して、試作品を作った。", "explanation": "ここは〈開発〉の意味。加担は不正への関与を表し、正当な開発作業には使わない。"}, {"text": "悪事に加担するため、警察に通報した。", "explanation": "ここは〈阻止〉の意味。加担は悪事に関わることなので、阻止のための通報とは合わない。"}, {"text": "町の募金に加担した。", "explanation": "ここは〈寄付〉の意味。加担は悪事に関わる意味で、善意の寄付には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39165, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社の裏金を加担した社員は、処分された。", "corrected_sentence": "会社の裏金に加担した社員は、処分された。", "error_description": "「加担」は「に」で関わる対象を示すので、「を」は誤り。正しくは「に加担した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39165, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事件に加担しないかった社員は、処分されなかった。", "corrected_sentence": "事件に加担しなかった社員は、処分されなかった。", "error_description": "過去の否定は「しなかった」。「しないかった」は活用の誤りで、「加担しない」の部分が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「知りたがる」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示すので、「知りたがる」の対象には使えない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、知りたい内容を指すことができない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、ここでは知りたい対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「知りたがる」の目的語を示す。", "に": "「に」は方向や相手を示すので、「知りたがる」の対象には使えない。", "から": "「から」は起点を示すので、知りたい内容を指すことができない。", "と": "「と」は並列や引用を示すので、ここでは知りたい対象を示せない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "から": "起点", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「知る」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「知る」の対象には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、知る対象には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、「知る」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「知る」の目的語を示す。", "が": "「が」は主語を示すが、「知る」の対象には使えない。", "へ": "「へ」は方向を示すので、知る対象には合わない。", "の": "「の」は名詞どうしをつなぐもので、「知る」の目的語にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当のありさまや状態のことです。", "primary_collocate": null, "pronunciation": "じったい", "ipa": "dʑittai", "syllable_count": 4, "sentences": [{"text": "ニュースだけでは、この町の実態はわかりません。", "target_word": "実態", "complexity_tier": "T3", "furigana": "ニュースだけでは、この町[まち]の実態[じったい]はわかりません。", "sentence_source": "generated"}, {"text": "先生は、生徒の生活の実態を知りたがっています。", "target_word": "実態", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の生活[せいかつ]の実態[じったい]を知[し]りたがっています。", "sentence_source": "generated"}, {"text": "うわさと実態は、まったく違いました。", "target_word": "実態", "complexity_tier": "T3", "furigana": "うわさと実態[じったい]は、まったく違[ちが]いました。", "sentence_source": "generated"}, {"text": "この店の実態を知って、私は驚きました。", "target_word": "実態", "complexity_tier": "T3", "furigana": "この店[みせ]の実態[じったい]を知[し]って、私[わたし]は驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "会社の実態を知らずに、就職を決めてしまいました。", "target_word": "実態", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の実態[じったい]を知[し]らずに、就職[しゅうしょく]を決[き]めてしまいました。", "sentence_source": "generated"}, {"text": "新聞は、工場で働く人たちの実態を伝えました。", "target_word": "実態", "complexity_tier": "T3", "furigana": "新聞[しんぶん]は、工場[こうじょう]で働[はたら]く人[ひと]たちの実態[じったい]を伝[つた]えました。", "sentence_source": "generated"}, {"text": "外から見るだけでは、あの団体の実態はわかりません。", "target_word": "実態", "complexity_tier": "T3", "furigana": "外[そと]から見[み]るだけでは、あの団体[だんたい]の実態[じったい]はわかりません。", "sentence_source": "generated"}, {"text": "町の実態を知るために、一週間ほど住んでみました。", "target_word": "実態", "complexity_tier": "T3", "furigana": "町[まち]の実態[じったい]を知[し]るために、一週間[いっしゅうかん]ほど住[す]んでみました。", "sentence_source": "generated"}, {"text": "学校の実態を、親に知らせる必要があります。", "target_word": "実態", "complexity_tier": "T3", "furigana": "学校[がっこう]の実態[じったい]を、親[おや]に知[し]らせる必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "写真と実態が違うので、お客さんが怒っています。", "target_word": "実態", "complexity_tier": "T3", "furigana": "写真[しゃしん]と実態[じったい]が違[ちが]うので、お客[きゃく]さんが怒[おこ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実態", "label": "基本形"}], "register": "neutral (polite です・ます style)", "sense_fingerprint": "外からは見えにくい、物事の本当のありさま。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実態", "is_correct": true, "explanation": "正解。「町の本当の状態」を表すので、「わかりません」の対象として合う。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人や物の高さを表すので、町の様子の説明には使えない。"}, {"text": "体調", "is_correct": false, "explanation": "体調は人の体の調子を表すので、町には当てはまらない。"}, {"text": "学歴", "is_correct": false, "explanation": "学歴は人の学んだ経歴を表すので、町の状態の説明には合わない。"}], "explanations": {"実態": "正解。「町の本当の状態」を表すので、「わかりません」の対象として合う。", "身長": "身長は人や物の高さを表すので、町の様子の説明には使えない。", "体調": "体調は人の体の調子を表すので、町には当てはまらない。", "学歴": "学歴は人の学んだ経歴を表すので、町の状態の説明には合わない。"}, "sentence_index": 0, "correct_answer": "実態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画を見終わったあと、みんなの実態を聞いてみました。", "explanation": "ここは〈感想〉の意味。実態は物事の本当の状態を指すので、人の意見や感想には使えない。"}, {"text": "今夜の実態はカレーにしました。", "explanation": "ここは〈献立〉の意味。実態は物事の状態を指すので、食事の内容を決めることには使わない。"}, {"text": "その理論の実態を三つ挙げてください。", "explanation": "ここは〈実例〉の意味。実態は数えて挙げるものではないので、例を挙げる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実態", "is_correct": true, "explanation": "正解。「あの団体の本当の状態」を表すので、「わかりません」に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や動物の重さを表すので、団体の様子には使えない。"}, {"text": "性別", "is_correct": false, "explanation": "性別は人の区分を表すので、団体の状態の説明には合わない。"}, {"text": "血液型", "is_correct": false, "explanation": "血液型は人の血液の分類なので、団体には当てはまらない。"}], "explanations": {"実態": "正解。「あの団体の本当の状態」を表すので、「わかりません」に合う。", "体重": "体重は人や動物の重さを表すので、団体の様子には使えない。", "性別": "性別は人の区分を表すので、団体の状態の説明には合わない。", "血液型": "血液型は人の血液の分類なので、団体には当てはまらない。"}, "sentence_index": 6, "correct_answer": "実態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この選手は十年間で多くの実態を残しました。", "explanation": "ここは〈実績〉の意味。実態は状態を指すので、「残す」ものではない。"}, {"text": "このパソコンの実態は高いです。", "explanation": "ここは〈性能〉の意味。実態は物事のありさまを指し、機械の性能の高さには使えない。"}, {"text": "この選手は大事な試合で実態を発揮しました。", "explanation": "ここは〈実力〉の意味。「発揮する」は能力に使う言葉で、実態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テレビだけでは、この村の実態をわかりません。", "corrected_sentence": "テレビだけでは、この村の実態はわかりません。", "error_description": "「わかる」の主題は「は」で示す。「実態を」にすると目的語になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査の結果から、この地域の実態を明らかになりました。", "corrected_sentence": "調査の結果から、この地域の実態が明らかになりました。", "error_description": "「明らかになる」は主語を「が」で示す。「を」は目的語を示すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「明らかになる」の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果や方向を示すので、「明らかになる」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、主語を示すことができない。"}], "correct_answer": "が", "explanations": {"が": "正解。「明らかになる」の主語を示す。", "に": "「に」は結果や方向を示すので、「明らかになる」の主語にはならない。", "と": "「と」は並列や引用を示すので、主語にはならない。", "へ": "「へ」は方向を示すので、主語を示すことができない。"}, "error_tags": {"が": "主語", "に": "結果・方向", "と": "並列・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「働く人」と「実態」をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すので、名詞どうしをつなぐ位置には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここでは名詞をつなげない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、人と実態をつなぐことができない。"}], "correct_answer": "の", "explanations": {"の": "正解。「働く人」と「実態」をつなぐ。", "を": "「を」は動作の対象を示すので、名詞どうしをつなぐ位置には合わない。", "より": "「より」は比較を示すので、ここでは名詞をつなげない。", "で": "「で」は手段や場所を示すので、人と実態をつなぐことができない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の実際の状態や中身。見かけやうわさではなく、実際にある様子。", "primary_collocate": null, "pronunciation": "じったい", "ipa": "dʑittai", "syllable_count": 4, "sentences": [{"text": "見かけはよくても、その会社の実態は赤字続きだ。", "target_word": "実態", "complexity_tier": "T3", "furigana": "見[み]かけはよくても、その会社[かいしゃ]の実態[じったい]は赤字[あかじ]続[つづ]きだ。", "sentence_source": "generated"}, {"text": "調査によって、高齢者の暮らしの実態が明らかになった。", "target_word": "実態", "complexity_tier": "T3", "furigana": "調査[ちょうさ]によって、高齢者[こうれいしゃ]の暮[く]らしの実態[じったい]が明[あき]らかになった。", "sentence_source": "generated"}, {"text": "うわさが広まったが、実態はそれほど深刻ではなかった。", "target_word": "実態", "complexity_tier": "T3", "furigana": "うわさが広[ひろ]まったが、実態[じったい]はそれほど深刻[しんこく]ではなかった。", "sentence_source": "generated"}, {"text": "制度はあっても、実態が伴っていない。", "target_word": "実態", "complexity_tier": "T3", "furigana": "制度[せいど]はあっても、実態[じったい]が伴[ともな]っていない。", "sentence_source": "generated"}, {"text": "彼の話を聞いて、業界の実態がよく見えてきた。", "target_word": "実態", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]を聞[き]いて、業界[ぎょうかい]の実態[じったい]がよく見[み]えてきた。", "sentence_source": "generated"}, {"text": "名前は立派だが、実態はただの小さな店だ。", "target_word": "実態", "complexity_tier": "T3", "furigana": "名前[なまえ]は立派[りっぱ]だが、実態[じったい]はただの小[ちい]さな店[みせ]だ。", "sentence_source": "generated"}, {"text": "記者は現場を訪ね、被害の実態を報告した。", "target_word": "実態", "complexity_tier": "T3", "furigana": "記者[きしゃ]は現場[げんば]を訪[たず]ね、被害[ひがい]の実態[じったい]を報告[ほうこく]した。", "sentence_source": "generated"}, {"text": "数字だけでは、働く人の実態はとらえきれない。", "target_word": "実態", "complexity_tier": "T3", "furigana": "数字[すうじ]だけでは、働[はたら]く人[ひと]の実態[じったい]はとらえきれない。", "sentence_source": "generated"}, {"text": "実態を知らない人ほど、簡単に意見を言う。", "target_word": "実態", "complexity_tier": "T3", "furigana": "実態[じったい]を知[し]らない人[ひと]ほど、簡単[かんたん]に意見[いけん]を言[い]う。", "sentence_source": "generated"}, {"text": "このデータは、子どもたちの生活の実態を示している。", "target_word": "実態", "complexity_tier": "T3", "furigana": "このデータは、子[こ]どもたちの生活[せいかつ]の実態[じったい]を示[しめ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実態", "label": "基本形"}], "register": "written/formal (plain だ・である style)", "sense_fingerprint": "見かけ・名目・うわさと対比される、物事の実際の中身。報道や調査の文脈で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実態", "is_correct": true, "explanation": "正解。「会社の実際の状態」を表すので、「赤字続き」と合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表すので、会社の状態を述べる文には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を表すので、会社の経営状態を述べる文には使えない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の高さを表すので、会社の状態には当てはまらない。"}], "explanations": {"実態": "正解。「会社の実際の状態」を表すので、「赤字続き」と合う。", "天気": "天気は空模様を表すので、会社の状態を述べる文には合わない。", "季節": "季節は時期を表すので、会社の経営状態を述べる文には使えない。", "身長": "身長は人の高さを表すので、会社の状態には当てはまらない。"}, "sentence_index": 0, "correct_answer": "実態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の実態を先生に出した。", "explanation": "ここは〈報告書〉の意味。実態は状態であり、書類のように提出するものではない。"}, {"text": "彼は実態で勝ち取った。", "explanation": "ここは〈実力〉の意味。「実力で勝つ」を、状態を表す実態に置き換えると不自然になる。"}, {"text": "私は町に明るい実態を抱いた。", "explanation": "ここは〈印象〉の意味。「抱く」は印象や感情に使い、実態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実態", "is_correct": true, "explanation": "正解。「被害の本当の状態」を報告する文に合う。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度なので、被害を報告する文には使えない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や動物の重さなので、被害の報告には合わない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は生まれた日を表すので、被害の報告には当てはまらない。"}], "explanations": {"実態": "正解。「被害の本当の状態」を報告する文に合う。", "気温": "気温は空気の温度なので、被害を報告する文には使えない。", "体重": "体重は人や動物の重さなので、被害の報告には合わない。", "誕生日": "誕生日は生まれた日を表すので、被害の報告には当てはまらない。"}, "sentence_index": 6, "correct_answer": "実態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、実態を破ったことを謝った。", "explanation": "ここは〈約束〉の意味。約束は破るものだが、実態は破れるものではない。"}, {"text": "その社員は今年の実態を達成した。", "explanation": "ここは〈目標〉の意味。目標は達成するものだが、実態は達成できるものではない。"}, {"text": "その社員は実態を果たした。", "explanation": "ここは〈義務〉の意味。「果たす」は義務や役割に使い、実態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の資料だけでは、その工場の実態を見えてこない。", "corrected_sentence": "会議の資料だけでは、その工場の実態は見えてこない。", "error_description": "「見えてくる」は自動詞なので、目的語の「を」は合わない。実態は「は」で主題を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この調査は、若者の暮らしの実態に示している。", "corrected_sentence": "この調査は、若者の暮らしの実態を示している。", "error_description": "「示す」は目的語に「を」を取る。「に」にすると、文が不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ふく」の目的語を示す「を」で、机の表面をふくという自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "「表面が」は主語を示すので、ふく動作の対象にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「表面と」は並列を示し、ふく対象を表せないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「表面より」は比較や起点を示すが、ふく対象を表せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ふく」の目的語を示す「を」で、机の表面をふくという自然な文になる。", "が": "「表面が」は主語を示すので、ふく動作の対象にならず不自然。", "と": "「表面と」は並列を示し、ふく対象を表せないので不自然。", "より": "「表面より」は比較や起点を示すが、ふく対象を表せず文が成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「表面の塗料」と表面に塗られた塗料を修飾する「の」で、自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「表面を塗料がはがれていた」は文が成り立たず、不自然。"}, {"text": "だ", "is_correct": false, "explanation": "「表面だ塗料」は名詞に続く「だ」の形が不正で、文が成り立たない。"}, {"text": "な", "is_correct": false, "explanation": "「表面な塗料」は「な」が名詞と名詞の間に入るため、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「表面の塗料」と表面に塗られた塗料を修飾する「の」で、自然に続く。", "を": "「表面を塗料がはがれていた」は文が成り立たず、不自然。", "だ": "「表面だ塗料」は名詞に続く「だ」の形が不正で、文が成り立たない。", "な": "「表面な塗料」は「な」が名詞と名詞の間に入るため、文が成り立たない。"}, "error_tags": {"を": "目的語", "だ": "断定", "な": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの外側の部分のこと。", "primary_collocate": null, "pronunciation": "ひょうめん", "ipa": "çoːmeɴ", "syllable_count": 4, "sentences": [{"text": "池の表面が、朝の寒さで薄く凍った。", "target_word": "表面", "complexity_tier": "T3", "furigana": "池[いけ]の表面[ひょうめん]が、朝[あさ]の寒[さむ]さで薄[うす]く凍[こお]った。", "sentence_source": "generated"}, {"text": "机の表面をふくと、ほこりがとれた。", "target_word": "表面", "complexity_tier": "T3", "furigana": "机[つくえ]の表面[ひょうめん]をふくと、ほこりがとれた。", "sentence_source": "generated"}, {"text": "月の表面には、たくさんのくぼみがある。", "target_word": "表面", "complexity_tier": "T3", "furigana": "月[つき]の表面[ひょうめん]には、たくさんのくぼみがある。", "sentence_source": "generated"}, {"text": "このボールは表面がざらざらして、すべりにくい。", "target_word": "表面", "complexity_tier": "T3", "furigana": "このボールは表面[ひょうめん]がざらざらして、すべりにくい。", "sentence_source": "generated"}, {"text": "鍋の表面に、油が浮いている。", "target_word": "表面", "complexity_tier": "T3", "furigana": "鍋[なべ]の表面[ひょうめん]に、油[あぶら]が浮[う]いている。", "sentence_source": "generated"}, {"text": "りんごの表面を水でよく洗ってから食べる。", "target_word": "表面", "complexity_tier": "T3", "furigana": "りんごの表面[ひょうめん]を水[みず]でよく洗[あら]ってから食[た]べる。", "sentence_source": "generated"}, {"text": "海の表面は穏やかでも、深いところは流れが速い。", "target_word": "表面", "complexity_tier": "T3", "furigana": "海[うみ]の表面[ひょうめん]は穏[おだ]やかでも、深[ふか]いところは流[なが]れが速[はや]い。", "sentence_source": "generated"}, {"text": "古い壁は、表面の塗料がはがれていた。", "target_word": "表面", "complexity_tier": "T3", "furigana": "古[ふる]い壁[かべ]は、表面[ひょうめん]の塗料[とりょう]がはがれていた。", "sentence_source": "generated"}, {"text": "地球の表面の七割は、海でおおわれている。", "target_word": "表面", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の表面[ひょうめん]の七割[ななわり]は、海[うみ]でおおわれている。", "sentence_source": "generated"}, {"text": "氷の表面が溶けて、道がすべりやすくなった。", "target_word": "表面", "complexity_tier": "T3", "furigana": "氷[こおり]の表面[ひょうめん]が溶[と]けて、道[みち]がすべりやすくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ものの外に出ている面、一番外側の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ざらざら (Zipf 2.37)']::text[], 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表面", "is_correct": true, "explanation": "池の外側の面である水面が凍るという文で、「表面が凍った」は自然に成り立つ。"}, {"text": "色", "is_correct": false, "explanation": "池の色は凍る主体にならないので、「池の色が凍った」は意味が通らない。"}, {"text": "形", "is_correct": false, "explanation": "池の形が凍るという表現は成り立たず、朝の寒さの文脈とも合わない。"}, {"text": "音", "is_correct": false, "explanation": "池の音が凍ったという表現は成り立たないので、この空所には入らない。"}], "explanations": {"表面": "池の外側の面である水面が凍るという文で、「表面が凍った」は自然に成り立つ。", "色": "池の色は凍る主体にならないので、「池の色が凍った」は意味が通らない。", "形": "池の形が凍るという表現は成り立たず、朝の寒さの文脈とも合わない。", "音": "池の音が凍ったという表現は成り立たないので、この空所には入らない。"}, "sentence_index": 0, "correct_answer": "表面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の表面にボールを入れた。", "explanation": "表面は外側の面なので、ボールを入れる（中に入れる）文とは合わず不自然。"}, {"text": "池の表面の柵を、子どもが乗り越えた。", "explanation": "柵は水の外側に立つもので、水の面を指す表面と組み合わせると位置関係が成り立たない。"}, {"text": "この地名の表面は、まだ決まっていない。", "explanation": "地名は名称であって物の面ではないので、「地名の表面」は意味が成り立たず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表面", "is_correct": true, "explanation": "海の外側の面を指し、「海の表面は穏やかでも」と穏やかさの対比として自然。"}, {"text": "名前", "is_correct": false, "explanation": "海の名前は穏やかさとつながらず、「海の名前は穏やかでも」は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "海の値段は穏やかさと関係がなく、この文の空所には入らない。"}, {"text": "重さ", "is_correct": false, "explanation": "海の重さは穏やかかどうかの対比にならず、文が成り立たない。"}], "explanations": {"表面": "海の外側の面を指し、「海の表面は穏やかでも」と穏やかさの対比として自然。", "名前": "海の名前は穏やかさとつながらず、「海の名前は穏やかでも」は意味が通らない。", "値段": "海の値段は穏やかさと関係がなく、この文の空所には入らない。", "重さ": "海の重さは穏やかかどうかの対比にならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "表面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱の表面は、古い手紙だった。", "explanation": "表面は外側の面で、中身の古い手紙とは結びつかず不自然。"}, {"text": "彼の表面が急に高くなった。", "explanation": "人の表面が高くなるという言い方は成り立たず、物の外側の面の意味と合わない。"}, {"text": "この電池は表面が長い。", "explanation": "電池の表面は外側の面で、使える時間の長さを表せないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓ガラスの表面を、雨のしずくがついている。", "corrected_sentence": "窓ガラスの表面に、雨のしずくがついている。", "error_description": "助詞の誤り。付着する場所は「に」で示すので、「表面を」は誤り。正しくは「表面に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39168, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の表面を、細かい傷がついた。", "corrected_sentence": "机の表面に、細かい傷がついた。", "error_description": "助詞の誤り。傷がつく場所は「に」で示すので、「を」は誤り。正しくは「表面に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「やめる」の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所・相手や結果を示すので、「やめる」の対象には使えない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここではやめる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、やめる対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「やめる」の対象を示す。", "に": "「に」は場所・相手や結果を示すので、「やめる」の対象には使えない。", "より": "「より」は比較を示すので、ここではやめる対象を示せない。", "と": "「と」は並列や引用を示すので、やめる対象にはならない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "より": "比較", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「購買で、町の店は元気になった」の手段や原因を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、この文には目的語になる動詞がない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、「購買の」だけでは文の成分にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、購買を原因や手段として示せない。"}], "correct_answer": "で", "explanations": {"で": "正解。「購買で、町の店は元気になった」の手段や原因を示す。", "を": "「を」は目的語を示すが、この文には目的語になる動詞がない。", "の": "「の」は名詞をつなぐもので、「購買の」だけでは文の成分にならない。", "へ": "「へ」は方向を示すので、購買を原因や手段として示せない。"}, "error_tags": {"で": "手段・原因", "を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを買うこと。", "primary_collocate": null, "pronunciation": "こうばい", "ipa": "koːbai", "syllable_count": 4, "sentences": [{"text": "年末は、人々の購買が増える時期です。", "target_word": "購買", "complexity_tier": "T3", "furigana": "年末[ねんまつ]は、人々[ひとびと]の購買[こうばい]が増[ふ]える時期[じき]です。", "sentence_source": "generated"}, {"text": "値段が高いと、購買をやめる人が多いです。", "target_word": "購買", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]いと、購買[こうばい]をやめる人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "広告を見て、購買を決める人もいます。", "target_word": "購買", "complexity_tier": "T3", "furigana": "広告[こうこく]を見[み]て、購買[こうばい]を決[き]める人[ひと]もいます。", "sentence_source": "generated"}, {"text": "給料が上がると、人々の購買は活発になります。", "target_word": "購買", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]が上[あ]がると、人々[ひとびと]の購買[こうばい]は活発[かっぱつ]になります。", "sentence_source": "generated"}, {"text": "雨の日は、店での購買が少なくなります。", "target_word": "購買", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、店[みせ]での購買[こうばい]が少[すく]なくなります。", "sentence_source": "generated"}, {"text": "若い人の購買は、ネットに移っています。", "target_word": "購買", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]の購買[こうばい]は、ネットに移[うつ]っています。", "sentence_source": "generated"}, {"text": "安売りの日は、購買する人で店が混みます。", "target_word": "購買", "complexity_tier": "T3", "furigana": "安売[やすう]りの日[ひ]は、購買[こうばい]する人[ひと]で店[みせ]が混[こ]みます。", "sentence_source": "generated"}, {"text": "外国からの旅行者の購買で、町の店は元気になりました。", "target_word": "購買", "complexity_tier": "T3", "furigana": "外国[がいこく]からの旅行者[りょこうしゃ]の購買[こうばい]で、町[まち]の店[みせ]は元気[げんき]になりました。", "sentence_source": "generated"}, {"text": "景気が悪くなると、購買を控える家が増えます。", "target_word": "購買", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、購買[こうばい]を控[ひか]える家[いえ]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "店は、お客さんの購買を増やすために安売りをしました。", "target_word": "購買", "complexity_tier": "T3", "furigana": "店[みせ]は、お客[きゃく]さんの購買[こうばい]を増[ふ]やすために安売[やすう]りをしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "購買", "label": "基本形"}, {"form": "購買する", "label": "サ変動詞形"}, {"form": "購買した", "label": "過去形"}], "register": "neutral (polite です・ます style)", "sense_fingerprint": "お客さんや人々がものを買うこと。店や景気の話で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "購買", "is_correct": true, "explanation": "正解。「人々の購買が増える」は、買う行動が増える時期を表す。"}, {"text": "身長", "is_correct": false, "explanation": "身長は人の体の高さなので、季節の変化とは結びつかない。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ているときの姿勢を表すので、人々の増える対象にはならない。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指の模様を表すので、増える時期の対象としては成り立たない。"}], "explanations": {"購買": "正解。「人々の購買が増える」は、買う行動が増える時期を表す。", "身長": "身長は人の体の高さなので、季節の変化とは結びつかない。", "寝相": "寝相は寝ているときの姿勢を表すので、人々の増える対象にはならない。", "指紋": "指紋は指の模様を表すので、増える時期の対象としては成り立たない。"}, "sentence_index": 0, "correct_answer": "購買"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レジで購買を払いました。", "explanation": "ここは〈代金〉の意味。購買は買う行為を指し、払うお金の額にはならない。"}, {"text": "ついに購買が見つかりました。", "explanation": "ここは〈買い手〉の意味。購買は買う行為なので、買う人を表すことはできない。"}, {"text": "店員が新しい購買を棚に並べました。", "explanation": "ここは〈商品〉の意味。購買は行為なので、棚に並べる物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "購買", "is_correct": true, "explanation": "正解。「購買する人で店が混む」の形で、買いに来る人を表す。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は授業や行事に来ないことなので、店が混む理由にはならない。"}, {"text": "遅刻", "is_correct": false, "explanation": "遅刻は時間に遅れることなので、店が混む理由として成り立たない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は仕事を辞めさせることなので、店が混む理由には当てはまらない。"}], "explanations": {"購買": "正解。「購買する人で店が混む」の形で、買いに来る人を表す。", "欠席": "欠席は授業や行事に来ないことなので、店が混む理由にはならない。", "遅刻": "遅刻は時間に遅れることなので、店が混む理由として成り立たない。", "解雇": "解雇は仕事を辞めさせることなので、店が混む理由には当てはまらない。"}, "sentence_index": 6, "correct_answer": "購買"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地域は購買が強いです。", "explanation": "ここは〈購買力〉の意味。購買は行為なので「強い」とは言えず、力を表す購買力が必要になる。"}, {"text": "店は新商品の購買を出しました。", "explanation": "ここは〈広告〉の意味。広告は出すものだが、購買は行為で出すことはできない。"}, {"text": "商品に購買を付けました。", "explanation": "ここは〈値札〉の意味。値札は付けるものだが、購買は物に付けられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボーナスが出ると、家族の購買が一気に増やしました。", "corrected_sentence": "ボーナスが出ると、家族の購買が一気に増えました。", "error_description": "「購買が」は主語なので、自動詞「増える」を使う。「増やした」は他動詞で、主語と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は、客の購買を増えるために新しい棚を置きました。", "corrected_sentence": "この店は、客の購買を増やすために新しい棚を置きました。", "error_description": "「増やす」は他動詞で目的語「を」と合う。「増える」は自動詞なので、「を」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
