INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「影響する」の対象を示す。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「影響する」の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、動詞「影響する」の対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「影響する」の対象には使えない。"}], "correct_answer": "に", "explanations": {"に": "正解。「影響する」の対象を示す。", "より": "「より」は比較を示すので、「影響する」の対象にはならない。", "の": "「の」は名詞をつなぐもので、動詞「影響する」の対象にはならない。", "で": "「で」は手段や場所を示すので、「影響する」の対象には使えない。"}, "error_tags": {"に": "対象", "より": "比較", "の": "連体修飾", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "品物を買うこと。また、買うという行為や行動。", "primary_collocate": null, "pronunciation": "こうばい", "ipa": "koːbai", "syllable_count": 4, "sentences": [{"text": "消費者の購買は、季節によって大きく変わる。", "target_word": "購買", "complexity_tier": "T3", "furigana": "消費者[しょうひしゃ]の購買[こうばい]は、季節[きせつ]によって大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "新商品が出ると、若者の購買が一気に増えた。", "target_word": "購買", "complexity_tier": "T3", "furigana": "新商品[しんしょうひん]が出[で]ると、若者[わかもの]の購買[こうばい]が一気[いっき]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "値引きは、購買を促すための方法の一つだ。", "target_word": "購買", "complexity_tier": "T3", "furigana": "値引[ねび]きは、購買[こうばい]を促[うなが]すための方法[ほうほう]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "彼女は購買を決める前に、必ず口コミを読む。", "target_word": "購買", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は購買[こうばい]を決[き]める前[まえ]に、必[かなら]ず口[くち]コミを読[よ]む。", "sentence_source": "generated"}, {"text": "税金が上がり、家庭の購買が冷え込んだ。", "target_word": "購買", "complexity_tier": "T3", "furigana": "税金[ぜいきん]が上[あ]がり、家庭[かてい]の購買[こうばい]が冷[ひ]え込[こ]んだ。", "sentence_source": "generated"}, {"text": "通信販売では、スマートフォンでの購買が主流になっている。", "target_word": "購買", "complexity_tier": "T3", "furigana": "通信[つうしん]販売[はんばい]では、スマートフォンでの購買[こうばい]が主流[しゅりゅう]になっている。", "sentence_source": "generated"}, {"text": "実際に購買したのは、見に来た客の半分以下だった。", "target_word": "購買", "complexity_tier": "T3", "furigana": "実際[じっさい]に購買[こうばい]したのは、見[み]に来[き]た客[きゃく]の半分[はんぶん]以下[いか]だった。", "sentence_source": "generated"}, {"text": "色や形だけでなく、香りも購買に影響する。", "target_word": "購買", "complexity_tier": "T3", "furigana": "色[いろ]や形[かたち]だけでなく、香[かお]りも購買[こうばい]に影響[えいきょう]する。", "sentence_source": "generated"}, {"text": "品物の購買は、よく考えてから決めたい。", "target_word": "購買", "complexity_tier": "T3", "furigana": "品物[しなもの]の購買[こうばい]は、よく考[かんが]えてから決[き]めたい。", "sentence_source": "generated"}, {"text": "店は、客の購買を増やすために広告を出した。", "target_word": "購買", "complexity_tier": "T3", "furigana": "店[みせ]は、客[きゃく]の購買[こうばい]を増[ふ]やすために広告[こうこく]を出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "購買", "label": "基本形"}, {"form": "購買する", "label": "サ変動詞形"}, {"form": "購買した", "label": "過去形"}], "register": "written/formal (plain だ・である style)", "sense_fingerprint": "消費者が品物を買う行為・行動。販売・経済・マーケティングの文脈で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "購買", "is_correct": true, "explanation": "正解。「消費者の購買」は、季節によって変わる買う行為を表す。"}, {"text": "血液型", "is_correct": false, "explanation": "血液型は人の血液の分類なので、季節によって変わるものではない。"}, {"text": "骨格", "is_correct": false, "explanation": "骨格は体の骨組みを表すので、消費者の行動には当てはまらない。"}, {"text": "年輪", "is_correct": false, "explanation": "年輪は木の成長の跡を表すので、消費者の話には合わない。"}], "explanations": {"購買": "正解。「消費者の購買」は、季節によって変わる買う行為を表す。", "血液型": "血液型は人の血液の分類なので、季節によって変わるものではない。", "骨格": "骨格は体の骨組みを表すので、消費者の行動には当てはまらない。", "年輪": "年輪は木の成長の跡を表すので、消費者の話には合わない。"}, "sentence_index": 0, "correct_answer": "購買"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "抽選で、購買が当たった。", "explanation": "ここは〈景品〉の意味。購買は買う行為なので、くじで当たる物にはならない。"}, {"text": "運動のしすぎで、体力の購買が減った。", "explanation": "ここは〈消費〉（使って減らす）の意味。購買は買うことなので、体力を減らす文には使えない。"}, {"text": "店で試食を配るかわりに、購買を配った。", "explanation": "ここは〈見本品〉の意味。購買は買うという行為なので、無料で配ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "購買", "is_correct": true, "explanation": "正解。「実際に購買したのは」は、実際に買った人の行為を表す。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定を後ろにずらすことなので、客の行動の説明には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は点数をつけることなので、見に来た客の話には当てはまらない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は機器や設備を調べることなので、客の行動には合わない。"}], "explanations": {"購買": "正解。「実際に購買したのは」は、実際に買った人の行為を表す。", "延期": "延期は予定を後ろにずらすことなので、客の行動の説明には合わない。", "採点": "採点は点数をつけることなので、見に来た客の話には当てはまらない。", "点検": "点検は機器や設備を調べることなので、客の行動には合わない。"}, "sentence_index": 6, "correct_answer": "購買"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レストランで、窓際の席の購買を取った。", "explanation": "ここは〈予約〉の意味。席を押さえるのは予約であり、買う行為では席は取れない。"}, {"text": "来週、購買を開く予定だ。", "explanation": "ここは〈会議〉の意味。「開く」は会議や催しに使い、買う行為には使わない。"}, {"text": "担当者が申請を購買した。", "explanation": "ここは〈承認〉の意味。申請は承認するものであり、購買という行為を申請に対して行うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の終わりは、地元の店での購買を落ち込む。", "corrected_sentence": "夏の終わりは、地元の店での購買が落ち込む。", "error_description": "「落ち込む」は自動詞なので、主語の「が」を取る。「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新製品の発表で、若い世代の購買に急に伸びた。", "corrected_sentence": "新製品の発表で、若い世代の購買が急に伸びた。", "error_description": "「伸びる」は主語に「が」を取る。「に」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「議論になった」の「に」。議論という状態に変化したことを示し、自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は結果を「に」で示すので、「議論を、なった」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「議論がなった」は主語とともに変化を表す形にならず、結果の意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「議論でなった」は変化の結果を表せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「議論になった」の「に」。議論という状態に変化したことを示し、自然に続く。", "を": "「なる」は結果を「に」で示すので、「議論を、なった」は不自然。", "が": "「議論がなった」は主語とともに変化を表す形にならず、結果の意味にならない。", "で": "「で」は手段や場所を示すので、「議論でなった」は変化の結果を表せず不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「議論に加わる」の「に」。加わる先を示すので、自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「加わる」は「に」で先を示すので、「議論を加わる」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「議論と加わる」は加わる相手を示す形にならず、成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「議論が加わる」は議論が主語になり、人が加わる文脈と合わない。"}], "correct_answer": "に", "explanations": {"に": "「議論に加わる」の「に」。加わる先を示すので、自然に続く。", "を": "「加わる」は「に」で先を示すので、「議論を加わる」は不自然。", "と": "「議論と加わる」は加わる相手を示す形にならず、成り立たない。", "が": "「議論が加わる」は議論が主語になり、人が加わる文脈と合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "みんなで話し合うこと。", "primary_collocate": null, "pronunciation": "ぎろん", "ipa": "ɡiɾoɴ", "syllable_count": 3, "sentences": [{"text": "クラスで文化祭の出し物について議論した。", "target_word": "議論", "complexity_tier": "T3", "furigana": "クラスで文化祭[ぶんかさい]の出[だ]し物[もの]について議論[ぎろん]した。", "sentence_source": "generated"}, {"text": "会議では、予算について長い議論になった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、予算[よさん]について長[なが]い議論[ぎろん]になった。", "sentence_source": "generated"}, {"text": "家族みんなで旅行先を議論して、海に決めた。", "target_word": "議論", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなで旅行先[りょこうさき]を議論[ぎろん]して、海[うみ]に決[き]めた。", "sentence_source": "generated"}, {"text": "議論が長引いて、昼ご飯の時間を過ぎてしまった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "議論[ぎろん]が長引[ながび]いて、昼[ひる]ご飯[はん]の時間[じかん]を過[す]ぎてしまった。", "sentence_source": "generated"}, {"text": "先生は生徒たちの議論を、静かに聞いていた。", "target_word": "議論", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]たちの議論[ぎろん]を、静[しず]かに聞[き]いていた。", "sentence_source": "generated"}, {"text": "町の人たちが、公園の使い方を議論している。", "target_word": "議論", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちが、公園[こうえん]の使[つか]い方[かた]を議論[ぎろん]している。", "sentence_source": "generated"}, {"text": "意見が分かれて、議論はなかなかまとまらなかった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "意見[いけん]が分[わ]かれて、議論[ぎろん]はなかなかまとまらなかった。", "sentence_source": "generated"}, {"text": "司会者は、全員が議論に加わるように声をかけた。", "target_word": "議論", "complexity_tier": "T3", "furigana": "司会者[しかいしゃ]は、全員[ぜんいん]が議論[ぎろん]に加[くわ]わるように声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "夜まで議論したが、結論は出なかった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "夜[よる]まで議論[ぎろん]したが、結論[けつろん]は出[で]なかった。", "sentence_source": "generated"}, {"text": "部活の練習時間をめぐって、部員の間で議論が起きた。", "target_word": "議論", "complexity_tier": "T3", "furigana": "部活[ぶかつ]の練習時間[れんしゅうじかん]をめぐって、部員[ぶいん]の間[あいだ]で議論[ぎろん]が起[お]きた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "議論", "label": "基本形"}, {"form": "議論する", "label": "する動詞形"}, {"form": "議論した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "複数の人が意見を出して話し合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "議論", "is_correct": true, "explanation": "「文化祭の出し物について議論した」で、みんなで話し合う行為として自然に成り立つ。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は「する」で動作にできないので、「包丁について包丁した」は成り立たない。"}, {"text": "富士山", "is_correct": false, "explanation": "富士山は「する」で動作にならないので、空所に入ると文が成り立たない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は動作の名詞ではないので、「電車について電車した」は意味が通らない。"}], "explanations": {"議論": "「文化祭の出し物について議論した」で、みんなで話し合う行為として自然に成り立つ。", "包丁": "包丁は「する」で動作にできないので、「包丁について包丁した」は成り立たない。", "富士山": "富士山は「する」で動作にならないので、空所に入ると文が成り立たない。", "電車": "電車は動作の名詞ではないので、「電車について電車した」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "議論"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "話を聞きながら、議論を打った。", "explanation": "「議論を打つ」は相槌の言い方ではなく、話し合いを指す議論とは結びつかないので不自然。"}, {"text": "朝、教室に入ると、先生に笑顔で議論した。", "explanation": "挨拶を表す言い方に議論は使えず、笑顔の挨拶と話し合いの議論は結びつかないので不自然。"}, {"text": "来週の月曜日、部長は議論を開いた。", "explanation": "議論は話し合いそのものなので、「議論を開く」は会や場を指す言い方として成り立たず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "議論", "is_correct": true, "explanation": "「議論はなかなかまとまらなかった」の主語で、意見が分かれた後の話し合いとして自然。"}, {"text": "花火", "is_correct": false, "explanation": "花火はまとまる対象ではないので、「花火はなかなかまとまらなかった」は成り立たない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は話し合いの結果としてまとまる物ではないので、この文には入らない。"}, {"text": "銀行", "is_correct": false, "explanation": "銀行は意見がまとまるという文脈に合わず、文が成り立たない。"}], "explanations": {"議論": "「議論はなかなかまとまらなかった」の主語で、意見が分かれた後の話し合いとして自然。", "花火": "花火はまとまる対象ではないので、「花火はなかなかまとまらなかった」は成り立たない。", "辞書": "辞書は話し合いの結果としてまとまる物ではないので、この文には入らない。", "銀行": "銀行は意見がまとまるという文脈に合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "議論"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、近所で犬の議論をした。", "explanation": "「犬の議論」は犬と歩く散歩を指さず、話し合いの議論とは結びつかないので不自然。"}, {"text": "会議が終わって、議論をついた。", "explanation": "「議論をつく」とは言えず、ため息の言い方と話し合いの議論は結びつかないので不自然。"}, {"text": "壁に議論を飾った。", "explanation": "議論は物ではないので壁に飾る対象にならず、「議論を飾る」は成り立たず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部員たちは大会の日程をめぐって議論に続けた。", "corrected_sentence": "部員たちは大会の日程をめぐって議論を続けた。", "error_description": "助詞の誤り。「続ける」は目的語に「を」を取るので、「議論に」は誤り。正しくは「議論を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39172, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の提案に、生徒たちは議論が重ねた。", "corrected_sentence": "先生の提案に、生徒たちは議論を重ねた。", "error_description": "助詞の誤り。「重ねる」は目的語に「を」を取るので、「議論が」は誤り。正しくは「議論を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「議論が続いている」の主語を示す「が」。議論を主語にした自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「議論を、国会で続いている」は続く主語にならず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「議論の、国会で続いている」は主語の位置に連体の「の」が入るため、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「議論と、国会で続いている」は並列の形になり、続く主語が一つにまとまらない。"}], "correct_answer": "が", "explanations": {"が": "「議論が続いている」の主語を示す「が」。議論を主語にした自然な文になる。", "を": "「議論を、国会で続いている」は続く主語にならず、不自然。", "の": "「議論の、国会で続いている」は主語の位置に連体の「の」が入るため、文が成り立たない。", "と": "「議論と、国会で続いている」は並列の形になり、続く主語が一つにまとまらない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「議論が広がっている」の主語を示す「が」。議論が広がるという自然な文になる。"}, {"text": "や", "is_correct": false, "explanation": "「議論や広がっている」は「や」が並列の一方を示すため、もう一方がなく文が成り立たない。"}, {"text": "か", "is_correct": false, "explanation": "「議論か広がっている」は選択を表す「か」が主語として続かず、不自然。"}, {"text": "ね", "is_correct": false, "explanation": "「議論ね広がっている」は文末の終助詞で、主語の位置には入らず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「議論が広がっている」の主語を示す「が」。議論が広がるという自然な文になる。", "や": "「議論や広がっている」は「や」が並列の一方を示すため、もう一方がなく文が成り立たない。", "か": "「議論か広がっている」は選択を表す「か」が主語として続かず、不自然。", "ね": "「議論ね広がっている」は文末の終助詞で、主語の位置には入らず、文が成り立たない。"}, "error_tags": {"や": "並列の不完成", "か": "選択の不適合", "ね": "終助詞の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるテーマについて意見を述べ合い、論じ合うこと。", "primary_collocate": null, "pronunciation": "ぎろん", "ipa": "ɡiɾoɴ", "syllable_count": 3, "sentences": [{"text": "環境問題をテーマに、専門家が議論を交わした。", "target_word": "議論", "complexity_tier": "T4", "furigana": "環境問題[かんきょうもんだい]をテーマに、専門家[せんもんか]が議論[ぎろん]を交[か]わした。", "sentence_source": "generated"}, {"text": "新しい法律の是非をめぐる議論が、国会で続いている。", "target_word": "議論", "complexity_tier": "T4", "furigana": "新[あたら]しい法律[ほうりつ]の是非[ぜひ]をめぐる議論[ぎろん]が、国会[こっかい]で続[つづ]いている。", "sentence_source": "generated"}, {"text": "教育のあり方について、活発な議論が行われた。", "target_word": "議論", "complexity_tier": "T4", "furigana": "教育[きょういく]のあり方[かた]について、活発[かっぱつ]な議論[ぎろん]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "この論文は、長年続いてきた議論に終止符を打った。", "target_word": "議論", "complexity_tier": "T4", "furigana": "この論文[ろんぶん]は、長年[ながねん]続[つづ]いてきた議論[ぎろん]に終止符[しゅうしふ]を打[う]った。", "sentence_source": "generated"}, {"text": "授業では、原子力発電の問題を議論する時間があった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]では、原子力発電[げんしりょくはつでん]の問題[もんだい]を議論[ぎろん]する時間[じかん]があった。", "sentence_source": "generated"}, {"text": "討論会では、賛成派と反対派が議論を戦わせた。", "target_word": "議論", "complexity_tier": "T4", "furigana": "討論会[とうろんかい]では、賛成派[さんせいは]と反対派[はんたいは]が議論[ぎろん]を戦[たたか]わせた。", "sentence_source": "generated"}, {"text": "議論の中心は、税金をどう使うかという点だった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "議論[ぎろん]の中心[ちゅうしん]は、税金[ぜいきん]をどう使[つか]うかという点[てん]だった。", "sentence_source": "generated"}, {"text": "ネット上でも、新しい技術をめぐる議論が広がっている。", "target_word": "議論", "complexity_tier": "T4", "furigana": "ネット上[じょう]でも、新[あたら]しい技術[ぎじゅつ]をめぐる議論[ぎろん]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "彼の発言をきっかけに、議論が一気に深まった。", "target_word": "議論", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]をきっかけに、議論[ぎろん]が一気[いっき]に深[ふか]まった。", "sentence_source": "generated"}, {"text": "専門家の間では、その説の正しさについて議論が分かれている。", "target_word": "議論", "complexity_tier": "T4", "furigana": "専門家[せんもんか]の間[あいだ]では、その説[せつ]の正[ただ]しさについて議論[ぎろん]が分[わ]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "議論", "label": "基本形"}, {"form": "議論する", "label": "する動詞形"}, {"form": "議論した", "label": "過去形"}], "register": "やや硬い", "sense_fingerprint": "あるテーマをめぐって意見を述べ合い論じ合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "議論", "is_correct": true, "explanation": "「議論を交わした」は意見を述べ合う意味で、テーマを論じる文に自然に入る。"}, {"text": "写真", "is_correct": false, "explanation": "「写真を交わす」は成り立たないので、この空所には入らない。"}, {"text": "地図", "is_correct": false, "explanation": "「地図を交わす」は不自然で、専門家がテーマを論じる文と合わない。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車を交わす」は成り立たず、文の意味が通らない。"}], "explanations": {"議論": "「議論を交わした」は意見を述べ合う意味で、テーマを論じる文に自然に入る。", "写真": "「写真を交わす」は成り立たないので、この空所には入らない。", "地図": "「地図を交わす」は不自然で、専門家がテーマを論じる文と合わない。", "自転車": "「自転車を交わす」は成り立たず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "議論"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "キッチンで、材料の重さを議論した。", "explanation": "「議論」は話し合いの意味で、重さを量る計量の動作には使えず不自然。"}, {"text": "コンサートの最後に、ピアノを議論した。", "explanation": "「ピアノを議論する」は楽器の演奏とは結びつかず、話し合いの議論は使えないので不自然。"}, {"text": "キャンプで、ろうそくに議論した。", "explanation": "火をつける動作に議論は使わず、「ろうそくに議論した」は成り立たず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "議論", "is_correct": true, "explanation": "文頭の「議論の中心」で、話し合いの要点を指し、税金の使い方の文に自然に続く。"}, {"text": "風船", "is_correct": false, "explanation": "風船には論点の中心がないので、「風船の中心は税金をどう使うかという点」は成り立たない。"}, {"text": "缶詰", "is_correct": false, "explanation": "缶詰は議論の中心にはならないので、この文の空所には入らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは話の中心にならず、税金の使い方の文と合わない。"}], "explanations": {"議論": "文頭の「議論の中心」で、話し合いの要点を指し、税金の使い方の文に自然に続く。", "風船": "風船には論点の中心がないので、「風船の中心は税金をどう使うかという点」は成り立たない。", "缶詰": "缶詰は議論の中心にはならないので、この文の空所には入らない。", "夕焼け": "夕焼けは話の中心にならず、税金の使い方の文と合わない。"}, "sentence_index": 6, "correct_answer": "議論"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "休日は、デパートで議論を買った。", "explanation": "議論は商品ではなくお店で買えるものではないので、「議論を買う」は不自然。"}, {"text": "友達に議論を書いた。", "explanation": "議論は書いて渡すものではなく、「議論を書いた」は手紙の文として成り立たず不自然。"}, {"text": "寝ながら、議論を言った。", "explanation": "寝言は無意識の発話で、「議論を言った」は話し合いの議論と結びつかず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の再開発をめぐって、住民が議論に重ねた。", "corrected_sentence": "市の再開発をめぐって、住民が議論を重ねた。", "error_description": "助詞の誤り。「重ねる」は目的語に「を」を取るので、「議論に」は誤り。正しくは「議論を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の将来について、議論を白熱した。", "corrected_sentence": "町の将来について、議論が白熱した。", "error_description": "助詞の誤り。「白熱する」は主語の状態を表すので、「議論が」と主語を示す「が」を使う。「議論を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「現状では」の「で」。「では」で今の状況を取り立てる。"}, {"text": "を", "is_correct": false, "explanation": "「現状を」は目的語になるが、ここは状況を取り立てる文で目的語の位置がない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「現状が」は「は」と続かず、「現状がは」は不自然。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」。並べる名詞が続かず、「現状や」は「は」とも続かない。"}], "correct_answer": "で", "explanations": {"で": "「現状では」の「で」。「では」で今の状況を取り立てる。", "を": "「現状を」は目的語になるが、ここは状況を取り立てる文で目的語の位置がない。", "が": "主語の「が」。「現状が」は「は」と続かず、「現状がは」は不自然。", "や": "並列の「や」。並べる名詞が続かず、「現状や」は「は」とも続かない。"}, "error_tags": {"を": "目的語", "が": "主語", "や": "並列"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「現状の」の「の」。「現状のまま」と続けて、今の状態が変わらないことを表す。"}, {"text": "に", "is_correct": false, "explanation": "「現状に」は対象や到達を示すが、「まま」と続かず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「現状が」は主語を示すが、「まま」の前では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「現状より」は比較の意味になり、「まま」と続かない。"}], "correct_answer": "の", "explanations": {"の": "「現状の」の「の」。「現状のまま」と続けて、今の状態が変わらないことを表す。", "に": "「現状に」は対象や到達を示すが、「まま」と続かず不自然。", "が": "「現状が」は主語を示すが、「まま」の前では文が成り立たない。", "より": "「現状より」は比較の意味になり、「まま」と続かない。"}, "error_tags": {"に": "対象・到達", "が": "主語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今のこと。", "primary_collocate": null, "pronunciation": "げんじょう", "ipa": "ɡendʑoː", "syllable_count": 4, "sentences": [{"text": "現状では、駅まで歩くしかありません。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]では、駅[えき]まで歩[ある]くしかありません。", "sentence_source": "generated"}, {"text": "現状に満足せず、もっと勉強したいです。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]に満足[まんぞく]せず、もっと勉強[べんきょう]したいです。", "sentence_source": "generated"}, {"text": "まず、会社の現状を教えてください。", "target_word": "現状", "complexity_tier": "T3", "furigana": "まず、会社[かいしゃ]の現状[げんじょう]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "私は現状を変えたくて、引っ越しを決めました。", "target_word": "現状", "complexity_tier": "T3", "furigana": "私[わたし]は現状[げんじょう]を変[か]えたくて、引[ひ]っ越[こ]しを決[き]めました。", "sentence_source": "generated"}, {"text": "現状では、このクラスに留学生は三人います。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]では、このクラスに留学生[りゅうがくせい]は三人[さんにん]います。", "sentence_source": "generated"}, {"text": "病気の現状を医者がていねいに説明してくれました。", "target_word": "現状", "complexity_tier": "T3", "furigana": "病気[びょうき]の現状[げんじょう]を医者[いしゃ]がていねいに説明[せつめい]してくれました。", "sentence_source": "generated"}, {"text": "現状を知ってから、これからのことを考えましょう。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]を知[し]ってから、これからのことを考[かんが]えましょう。", "sentence_source": "generated"}, {"text": "現状のままでは、夏の試合に勝てません。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]のままでは、夏[なつ]の試合[しあい]に勝[か]てません。", "sentence_source": "generated"}, {"text": "現状は少し大変ですが、来月にはよくなります。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]は少[すこ]し大変[たいへん]ですが、来月[らいげつ]にはよくなります。", "sentence_source": "generated"}, {"text": "現状で、使える部屋はこの二つだけです。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]で、使[つか]える部屋[へや]はこの二[ふた]つだけです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現状", "label": "基本形"}], "register": "neutral (polite です・ます style)", "sense_fingerprint": "今のありさま。これからの話と比べて「いま」の様子を言う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現状", "is_correct": true, "explanation": "「今のこと」の意味。「現状では」で今の状況から話を始める文脈に合う。"}, {"text": "感想", "is_correct": false, "explanation": "感想は意見を表す語で、「では、駅まで歩くしかありません」と続かない。"}, {"text": "返事", "is_correct": false, "explanation": "返事は相手への応答を表す語で、徒歩の必要性を述べる文に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書を表す語で、「では」で徒歩の話を導く文に合わない。"}], "explanations": {"現状": "「今のこと」の意味。「現状では」で今の状況から話を始める文脈に合う。", "感想": "感想は意見を表す語で、「では、駅まで歩くしかありません」と続かない。", "返事": "返事は相手への応答を表す語で、徒歩の必要性を述べる文に合わない。", "手紙": "手紙は文書を表す語で、「では」で徒歩の話を導く文に合わない。"}, "sentence_index": 0, "correct_answer": "現状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事の現状に着いたら、まず安全帽をかぶってください。", "explanation": "ここは〈現場〉の意味。現状は今の状態を表し、人が着く場所にはならないので合わない。"}, {"text": "来年の現状は、毎日英語で話すことです。", "explanation": "ここは〈目標〉の意味。現状は今のことなので、未来の目標を言う文には使えない。"}, {"text": "現状の時刻は、朝の九時五分です。", "explanation": "ここは〈現在〉の意味で時点を言う。現状は状態を表すので、時刻には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現状", "is_correct": true, "explanation": "「今のこと」を知る対象として自然で、「これからのこと」と対比される。"}, {"text": "足音", "is_correct": false, "explanation": "足音は音を表す語で、知ったうえで将来を考える文の対象として不自然。"}, {"text": "花火", "is_correct": false, "explanation": "花火は行事や物を表す語で、「知る」の対象として文が成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便用品を表す語で、知ったうえで将来を考える文と合わない。"}], "explanations": {"現状": "「今のこと」を知る対象として自然で、「これからのこと」と対比される。", "足音": "足音は音を表す語で、知ったうえで将来を考える文の対象として不自然。", "花火": "花火は行事や物を表す語で、「知る」の対象として文が成り立たない。", "切手": "切手は郵便用品を表す語で、知ったうえで将来を考える文と合わない。"}, "sentence_index": 6, "correct_answer": "現状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空に現状が光っている。", "explanation": "ここは〈星〉のような目に見える対象の位置。現状は状態を表すので、光る物にはならない。"}, {"text": "晴れた日に、現状を干した。", "explanation": "ここは〈洗濯物〉のような物の位置。現状は抽象的な状態なので、干すことはできない。"}, {"text": "夏祭りで現状を打ち上げた。", "explanation": "ここは〈花火〉のような行事の対象。現状は状態を表すので、打ち上げられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "現状を、この道は車が通れません。", "corrected_sentence": "現状では、この道は車が通れません。", "error_description": "「現状」に続く助詞の誤り。「現状を」は目的語になるが、ここは状況を取り立てる文なので「現状では」が正しい。「では」で今の状況を取り立てる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39174, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "現状を作るには、まず計画が必要だ。", "corrected_sentence": "現状を変えるには、まず計画が必要だ。", "error_description": "「現状」と結びつく動詞の誤り。「作る」は物を生み出す動詞で、状態には使わない。正しくは「変える」（現状を変える）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「理解する」の目的語を示す「を」。「現状を正しく理解」で正しい。"}, {"text": "に", "is_correct": false, "explanation": "「理解する」の対象は「を」で示すので、「現状に正しく理解」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「現状が正しく理解」は主語が理解する動作をしないため不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。「現状と正しく理解」は並べる相手がなく不自然。"}], "correct_answer": "を", "explanations": {"を": "「理解する」の目的語を示す「を」。「現状を正しく理解」で正しい。", "に": "「理解する」の対象は「を」で示すので、「現状に正しく理解」は不自然。", "が": "主語の「が」。「現状が正しく理解」は主語が理解する動作をしないため不自然。", "と": "並列の「と」。「現状と正しく理解」は並べる相手がなく不自然。"}, "error_tags": {"に": "対象", "が": "主語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「伝える」の目的語を示す「を」。「現状を伝える」で、内容を知らせる意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「現状が伝える」は、現状が何かを伝えるという意味になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。伝える相手は「に」で示すので、現状は伝える先にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「現状より伝える」は比べる対象がなく不自然。"}], "correct_answer": "を", "explanations": {"を": "「伝える」の目的語を示す「を」。「現状を伝える」で、内容を知らせる意味になる。", "が": "主語の「が」。「現状が伝える」は、現状が何かを伝えるという意味になり不自然。", "へ": "方向を示す「へ」。伝える相手は「に」で示すので、現状は伝える先にならない。", "より": "比較の「より」。「現状より伝える」は比べる対象がなく不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今、実際にある状態や事情。", "primary_collocate": null, "pronunciation": "げんじょう", "ipa": "ɡendʑoː", "syllable_count": 4, "sentences": [{"text": "政府は、被災地の現状を調べるために職員を送った。", "target_word": "現状", "complexity_tier": "T3", "furigana": "政府[せいふ]は、被災地[ひさいち]の現状[げんじょう]を調[しら]べるために職員[しょくいん]を送[おく]った。", "sentence_source": "generated"}, {"text": "現状を正しく理解しなければ、解決策は見つからない。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]を正[ただ]しく理解[りかい]しなければ、解決策[かいけつさく]は見[み]つからない。", "sentence_source": "generated"}, {"text": "現状の設備では、新しい機械を動かすことができない。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]の設備[せつび]では、新[あたら]しい機械[きかい]を動[うご]かすことができない。", "sentence_source": "generated"}, {"text": "会議では、会社の現状について厳しい意見が出た。", "target_word": "現状", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、会社[かいしゃ]の現状[げんじょう]について厳[きび]しい意見[いけん]が出[で]た。", "sentence_source": "generated"}, {"text": "現状は厳しいが、希望を捨てるつもりはない。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]は厳[きび]しいが、希望[きぼう]を捨[す]てるつもりはない。", "sentence_source": "generated"}, {"text": "川の水が減っている現状を、市民に知らせるべきだ。", "target_word": "現状", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が減[へ]っている現状[げんじょう]を、市民[しみん]に知[し]らせるべきだ。", "sentence_source": "generated"}, {"text": "現状を考えると、今年の計画は無理がある。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]を考[かんが]えると、今年[ことし]の計画[けいかく]は無理[むり]がある。", "sentence_source": "generated"}, {"text": "学校の現状を伝えるため、校長が記者会見を開いた。", "target_word": "現状", "complexity_tier": "T3", "furigana": "学校[がっこう]の現状[げんじょう]を伝[つた]えるため、校長[こうちょう]が記者[きしゃ]会見[かいけん]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "現状に合わせて、規則を見直すことになった。", "target_word": "現状", "complexity_tier": "T3", "furigana": "現状[げんじょう]に合[あ]わせて、規則[きそく]を見直[みなお]すことになった。", "sentence_source": "generated"}, {"text": "多くの店が閉まっている現状に、住民は不安を感じている。", "target_word": "現状", "complexity_tier": "T3", "furigana": "多[おお]くの店[みせ]が閉[し]まっている現状[げんじょう]に、住民[じゅうみん]は不安[ふあん]を感[かん]じている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現状", "label": "基本形"}], "register": "written/formal (plain だ・である style)", "sense_fingerprint": "今、実際にある状態や事情。問題の把握・分析・改善の文脈で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d892d9d-8eff-463a-a0ef-366628b4b1ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現状", "is_correct": true, "explanation": "「今、実際にある状態」の意味。被災地の今の状態を調べる対象として合う。"}, {"text": "足音", "is_correct": false, "explanation": "足音は音を表す語で、被災地の状態を調べる対象にならない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便用品を表す語で、被災地の状態を調べる対象にならない。"}, {"text": "ため息", "is_correct": false, "explanation": "ため息は息を表す語で、被災地の状態を調べる対象にならない。"}], "explanations": {"現状": "「今、実際にある状態」の意味。被災地の今の状態を調べる対象として合う。", "足音": "足音は音を表す語で、被災地の状態を調べる対象にならない。", "切手": "切手は郵便用品を表す語で、被災地の状態を調べる対象にならない。", "ため息": "ため息は息を表す語で、被災地の状態を調べる対象にならない。"}, "sentence_index": 0, "correct_answer": "現状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "現状の社会を目指して、みんなで努力している。", "explanation": "ここは〈理想〉の意味。現状は今の姿を表し、目指す目標にはならないので合わない。"}, {"text": "長年の現状を叶えた。", "explanation": "ここは〈夢〉の意味。現状は実現させる対象ではないので、叶えるとは言えない。"}, {"text": "友達に現状を申し込んだ。", "explanation": "ここは〈結婚〉の意味。現状は申し込む対象ではないので、申し込めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現状", "is_correct": true, "explanation": "「今、実際にある状態」の意味。今の状態を考えて計画の可否を判断する文に合う。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は人の指の跡を表す語で、計画の可否を考える対象にならない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は筆記具を表す語で、計画の可否を考える対象にならない。"}, {"text": "海老", "is_correct": false, "explanation": "海老は食べ物を表す語で、計画の可否を考える対象にならない。"}], "explanations": {"現状": "「今、実際にある状態」の意味。今の状態を考えて計画の可否を判断する文に合う。", "指紋": "指紋は人の指の跡を表す語で、計画の可否を考える対象にならない。", "鉛筆": "鉛筆は筆記具を表す語で、計画の可否を考える対象にならない。", "海老": "海老は食べ物を表す語で、計画の可否を考える対象にならない。"}, "sentence_index": 6, "correct_answer": "現状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布に現状を入れた。", "explanation": "ここは〈現金〉の意味。「げんきん」と取り違えやすいが、現状は状態を表すので、財布に入れて持ち歩く物にはならない。"}, {"text": "週末に現状に出かけた。", "explanation": "ここは〈旅行〉のような出かける先や行動の意味。現状は場所ではないので出かけられない。"}, {"text": "寒い部屋の現状を開けた。", "explanation": "ここは〈窓〉のような物の意味。現状は開けられるものではないので、開けるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "現状が正しく把握することが、解決の第一歩だ。", "corrected_sentence": "現状を正しく把握することが、解決の第一歩だ。", "error_description": "「現状」に続く助詞の誤り。「把握する」は目的語に「を」をとるので、「現状を」が正しい。「が」は主語を示すため、ここでは成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39175, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "現状を演奏して、改善策を考える。", "corrected_sentence": "現状を分析して、改善策を考える。", "error_description": "「現状」と結びつく動詞の誤り。「演奏する」は音楽を奏でる動詞で、状態には使えない。正しくは「分析する」（現状を分析する）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd234e68-7b32-4a49-a6da-5c6ee8827977') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」は対象を「を」で取るので、所在の直後は「を」になる。"}, {"text": "に", "is_correct": false, "explanation": "「所在に調べる」は成り立たない。調べる対象を示す「を」が必要。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、調べられる対象の位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、調べる対象を表す所在には合わない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」は対象を「を」で取るので、所在の直後は「を」になる。", "に": "「所在に調べる」は成り立たない。調べる対象を示す「を」が必要。", "が": "「が」は主語を示すので、調べられる対象の位置には入らない。", "で": "「で」は手段や場所を示すので、調べる対象を表す所在には合わない。"}, "error_tags": {"に": "対象を表す格助詞の誤り", "が": "主語を表す格助詞の誤り", "で": "手段・場所を表す格助詞の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わかる」は主語に「が」を取るので、所在の直後は「が」になる。"}, {"text": "を", "is_correct": false, "explanation": "「わかる」は対象に「を」を取らないので、ここでは不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、わかるという状態の主語には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は所在を主語にした「わかる」とは続かず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「わかる」は主語に「が」を取るので、所在の直後は「が」になる。", "を": "「わかる」は対象に「を」を取らないので、ここでは不自然。", "へ": "「へ」は方向を示すので、わかるという状態の主語には使えない。", "に": "「に」は所在を主語にした「わかる」とは続かず、文が成り立たない。"}, "error_tags": {"を": "対象を表す格助詞の誤り", "へ": "方向を表す格助詞の誤り", "に": "わかる の主語・相手を表す格助詞の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがどこにあるか、という場所。", "primary_collocate": null, "pronunciation": "しょざい", "ipa": "ɕozai", "syllable_count": 3, "sentences": [{"text": "落とした財布の所在がまだ分からない。", "target_word": "所在", "complexity_tier": "T3", "furigana": "落[お]とした財布[さいふ]の所在[しょざい]がまだ分[わ]からない。", "sentence_source": "generated"}, {"text": "警察は行方不明の犬の所在を調べています。", "target_word": "所在", "complexity_tier": "T3", "furigana": "警察[けいさつ]は行方不明[ゆくえふめい]の犬[いぬ]の所在[しょざい]を調[しら]べています。", "sentence_source": "generated"}, {"text": "古い地図には、その寺の所在がはっきり書かれていない。", "target_word": "所在", "complexity_tier": "T3", "furigana": "古[ふる]い地図[ちず]には、その寺[てら]の所在[しょざい]がはっきり書[か]かれていない。", "sentence_source": "generated"}, {"text": "大事な書類の所在を、母に電話して聞いた。", "target_word": "所在", "complexity_tier": "T3", "furigana": "大事[だいじ]な書類[しょるい]の所在[しょざい]を、母[はは]に電話[でんわ]して聞[き]いた。", "sentence_source": "generated"}, {"text": "飼い主は猫の所在がわからなくて、一晩中さがした。", "target_word": "所在", "complexity_tier": "T3", "furigana": "飼[か]い主[ぬし]は猫[ねこ]の所在[しょざい]がわからなくて、一晩中[ひとばんじゅう]さがした。", "sentence_source": "generated"}, {"text": "先生は、貸した本の所在を生徒にたずねた。", "target_word": "所在", "complexity_tier": "T3", "furigana": "先生[せんせい]は、貸[か]した本[ほん]の所在[しょざい]を生徒[せいと]にたずねた。", "sentence_source": "generated"}, {"text": "鍵の所在を知っている人は、手をあげてください。", "target_word": "所在", "complexity_tier": "T3", "furigana": "鍵[かぎ]の所在[しょざい]を知[し]っている人[ひと]は、手[て]をあげてください。", "sentence_source": "generated"}, {"text": "山で迷った友だちの所在がやっとわかって、みんな安心した。", "target_word": "所在", "complexity_tier": "T3", "furigana": "山[やま]で迷[まよ]った友[とも]だちの所在[しょざい]がやっとわかって、みんな安心[あんしん]した。", "sentence_source": "generated"}, {"text": "展示されていた絵の所在は、今も不明です。", "target_word": "所在", "complexity_tier": "T3", "furigana": "展示[てんじ]されていた絵[え]の所在[しょざい]は、今[いま]も不明[ふめい]です。", "sentence_source": "generated"}, {"text": "倉庫の荷物は、所在が分かるように番号をつけてある。", "target_word": "所在", "complexity_tier": "T3", "furigana": "倉庫[そうこ]の荷物[にもつ]は、所在[しょざい]が分[わ]かるように番号[ばんごう]をつけてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "所在", "label": "基本形"}], "register": "標準", "sense_fingerprint": "所在=物や人がどこにあるか、いるかという居場所・ありか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所在", "is_correct": true, "explanation": "「ありか・居場所」の意味。財布がどこにあるか分からないという文に合う。"}, {"text": "所属", "is_correct": false, "explanation": "組織や団体に属することを表す。財布の居場所を述べる文には合わない。"}, {"text": "所蔵", "is_correct": false, "explanation": "美術館や図書館などが物を持っていることを表す。落とし物の文には合わない。"}, {"text": "所得", "is_correct": false, "explanation": "収入のことを表す。財布がどこにあるかを述べる文とは結びつかない。"}], "explanations": {"所在": "「ありか・居場所」の意味。財布がどこにあるか分からないという文に合う。", "所属": "組織や団体に属することを表す。財布の居場所を述べる文には合わない。", "所蔵": "美術館や図書館などが物を持っていることを表す。落とし物の文には合わない。", "所得": "収入のことを表す。財布がどこにあるかを述べる文とは結びつかない。"}, "sentence_index": 0, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この土地は父の所在だ。", "explanation": "ここは〈所有〉（持ち主であること）の意味。所在は場所を指すので、土地の持ち主を言う文には使えない。"}, {"text": "税金は所在に応じて決まる。", "explanation": "ここは〈所得〉（収入）の意味。所在は場所を指すので、収入に応じて決まるという文には合わない。"}, {"text": "医師の所在によると、骨に異常はないそうだ。", "explanation": "ここは〈所見〉（検査や診察に基づく判断）の意味。所在は場所を指すので、診断の内容を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所在", "is_correct": true, "explanation": "「ありか」の意味。鍵がどこにあるかを知っている人を指す文に合う。"}, {"text": "所望", "is_correct": false, "explanation": "望むことを表す。鍵の場所を知っているという文には合わない。"}, {"text": "所管", "is_correct": false, "explanation": "管轄することを表す。鍵の場所を知っている文とは合わない。"}, {"text": "所帯", "is_correct": false, "explanation": "世帯や家計のことを表す。鍵の場所を述べる文では意味が通らない。"}], "explanations": {"所在": "「ありか」の意味。鍵がどこにあるかを知っている人を指す文に合う。", "所望": "望むことを表す。鍵の場所を知っているという文には合わない。", "所管": "管轄することを表す。鍵の場所を知っている文とは合わない。", "所帯": "世帯や家計のことを表す。鍵の場所を述べる文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その政治家の所在は、国民の怒りを買った。", "explanation": "ここは〈所業〉（行い・しわざ）の意味。所在は場所を指すので、人の行いを表す文には合わない。"}, {"text": "明日は所在があるので、会議には出られない。", "explanation": "ここは〈所用〉（用事）の意味。所在は場所を指すので、用事があるという文には合わない。"}, {"text": "私はこの会社の所在です。", "explanation": "ここは〈所属〉（組織に属すること）の意味。所在は物や人がどこにあるかを指すので、会社の一員であることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転んだ子どもの所在に、先生が確かめた。", "corrected_sentence": "転んだ子どもの所在を、先生が確かめた。", "error_description": "「確かめる」は目的語に「を」を取る。「所在に」は誤りで、「所在を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39176, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の所在に、家族みんなで探した。", "corrected_sentence": "祖母の所在を、家族みんなで探した。", "error_description": "「探す」は目的語に「を」を取る。「所在に」は誤りで、「所在を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39177, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「話し合われた」の主語を示す「が」。所在の直後に入る。"}, {"text": "を", "is_correct": false, "explanation": "「話し合う」は対象に「を」を取らないので、ここでは不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、主語の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、主語を表す位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「話し合われた」の主語を示す「が」。所在の直後に入る。", "を": "「話し合う」は対象に「を」を取らないので、ここでは不自然。", "に": "「に」は相手や場所を示すので、主語の位置には合わない。", "で": "「で」は手段や場所を示すので、主語を表す位置には入らない。"}, "error_tags": {"を": "対象を表す格助詞の誤り", "に": "相手・場所を表す格助詞の誤り", "で": "手段・場所を表す格助詞の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
