INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39177, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が存在する位置や、責任などのある場所。", "primary_collocate": null, "pronunciation": "しょざい", "ipa": "ɕozai", "syllable_count": 3, "sentences": [{"text": "この事故の責任の所在をはっきりさせたい。", "target_word": "所在", "complexity_tier": "T3", "furigana": "この事故[じこ]の責任[せきにん]の所在[しょざい]をはっきりさせたい。", "sentence_source": "generated"}, {"text": "会議では、問題の責任の所在が話し合われた。", "target_word": "所在", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、問題[もんだい]の責任[せきにん]の所在[しょざい]が話[はな]し合[あ]われた。", "sentence_source": "generated"}, {"text": "決める権限の所在があいまいで、仕事が進まない。", "target_word": "所在", "complexity_tier": "T3", "furigana": "決[き]める権限[けんげん]の所在[しょざい]があいまいで、仕事[しごと]が進[すす]まない。", "sentence_source": "generated"}, {"text": "責任の所在が分からないままでは、同じ失敗をくり返す。", "target_word": "所在", "complexity_tier": "T3", "furigana": "責任[せきにん]の所在[しょざい]が分[わ]からないままでは、同[おな]じ失敗[しっぱい]をくり返[かえ]す。", "sentence_source": "generated"}, {"text": "社長は、ミスの原因の所在を調べるよう部下に命じた。", "target_word": "所在", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、ミスの原因[げんいん]の所在[しょざい]を調[しら]べるよう部下[ぶか]に命[めい]じた。", "sentence_source": "generated"}, {"text": "この記事は、国の権力の所在を鋭く問いかけている。", "target_word": "所在", "complexity_tier": "T3", "furigana": "この記事[きじ]は、国[くに]の権力[けんりょく]の所在[しょざい]を鋭[するど]く問[と]いかけている。", "sentence_source": "generated"}, {"text": "契約書には、費用を払う責任の所在が書かれている。", "target_word": "所在", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]には、費用[ひよう]を払[はら]う責任[せきにん]の所在[しょざい]が書[か]かれている。", "sentence_source": "generated"}, {"text": "裁判では、土地の権利の所在が争われた。", "target_word": "所在", "complexity_tier": "T3", "furigana": "裁判[さいばん]では、土地[とち]の権利[けんり]の所在[しょざい]が争[あらそ]われた。", "sentence_source": "generated"}, {"text": "誰が決めたのかという意思決定の所在が見えない会社は不安だ。", "target_word": "所在", "complexity_tier": "T3", "furigana": "誰[だれ]が決[き]めたのかという意思決定[いしけってい]の所在[しょざい]が見[み]えない会社[かいしゃ]は不安[ふあん]だ。", "sentence_source": "generated"}, {"text": "調査の結果、故障の原因の所在は古い機械だとわかった。", "target_word": "所在", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の結果[けっか]、故障[こしょう]の原因[げんいん]の所在[しょざい]は古[ふる]い機械[きかい]だとわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "所在", "label": "基本形"}], "register": "硬め（文章語）", "sense_fingerprint": "所在=責任・権限・原因など抽象的なものがどこにあるか、その帰属先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所在", "is_correct": true, "explanation": "「責任や権限がどこにあるか」の意味。責任を明らかにしたいという文に合う。"}, {"text": "所望", "is_correct": false, "explanation": "望むことを表す。責任の帰属を述べる文には合わない。"}, {"text": "所有", "is_correct": false, "explanation": "持っていることを表す。責任を明らかにする文とは意味が合わない。"}, {"text": "所属", "is_correct": false, "explanation": "組織に属することを表す。責任の所在をはっきりさせる文では意味が通らない。"}], "explanations": {"所在": "「責任や権限がどこにあるか」の意味。責任を明らかにしたいという文に合う。", "所望": "望むことを表す。責任の帰属を述べる文には合わない。", "所有": "持っていることを表す。責任を明らかにする文とは意味が合わない。", "所属": "組織に属することを表す。責任の所在をはっきりさせる文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社の株は社長の所在だ。", "explanation": "ここは〈所有〉（持ち主であること）の意味。所在は帰属先や場所を指すが、株の持ち主を言う意味はない。"}, {"text": "一年間の所在を税務署に申告する。", "explanation": "ここは〈所得〉（一年間に得た収入）の意味。所在は位置や帰属先を指すので、収入を税務署に申告する文には合わない。"}, {"text": "彼女は所在が美しく、誰からも好かれる。", "explanation": "ここは〈所作〉（身のこなし）の意味。所在は位置や帰属先を指すので、立ち居ふるまいの美しさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所在", "is_correct": true, "explanation": "「責任の帰属先」の意味。費用を払う責任がどこにあるかが書かれているという文に合う。"}, {"text": "所蔵", "is_correct": false, "explanation": "美術館などが物を持つことを表す。責任の内容を述べる文には合わない。"}, {"text": "所得", "is_correct": false, "explanation": "収入のことを表す。費用を払う責任とは結びつかない。"}, {"text": "所要", "is_correct": false, "explanation": "必要な時間やものを表す。責任の内容が書かれている文と合わない。"}], "explanations": {"所在": "「責任の帰属先」の意味。費用を払う責任がどこにあるかが書かれているという文に合う。", "所蔵": "美術館などが物を持つことを表す。責任の内容を述べる文には合わない。", "所得": "収入のことを表す。費用を払う責任とは結びつかない。", "所要": "必要な時間やものを表す。責任の内容が書かれている文と合わない。"}, "sentence_index": 6, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの役人の所在は許しがたい。", "explanation": "ここは〈所業〉（行い・しわざ）の意味。所在は場所や帰属先を指すので、人の行いを評価する文には合わない。"}, {"text": "鑑定の所在によると、その絵は本物だ。", "explanation": "ここは〈所見〉（調べて得た判断）の意味。所在は場所を指すので、鑑定の判断を述べる文には合わない。"}, {"text": "完成までの所在は三日です。", "explanation": "ここは〈所要〉（かかる時間）の意味。所在は場所を指すので、期間を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
