INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "責任の所在に、社長が確かめた。", "corrected_sentence": "責任の所在を、社長が確かめた。", "error_description": "「確かめる」は目的語に「を」を取る。「所在に」は誤りで、「所在を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明確", "is_correct": true, "explanation": "はっきりしていて定まっている意味で、〈はっきりしない〉曖昧の対義語として辞書に載る。"}, {"text": "簡単", "is_correct": false, "explanation": "手間がかからない意味で、曖昧の対義語ではない。"}, {"text": "静か", "is_correct": false, "explanation": "物音がしない様子で、曖昧とは対義関係にない。"}, {"text": "丁寧", "is_correct": false, "explanation": "行き届いている様子で、曖昧の対義語ではない。"}], "correct_answer": "明確", "explanations": {"明確": "はっきりしていて定まっている意味で、〈はっきりしない〉曖昧の対義語として辞書に載る。", "簡単": "手間がかからない意味で、曖昧の対義語ではない。", "静か": "物音がしない様子で、曖昧とは対義関係にない。", "丁寧": "行き届いている様子で、曖昧の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明確", "is_correct": true, "explanation": "はっきりして定まっている意味で、〈はっきりしない〉曖昧の対義語として辞書に載る。"}, {"text": "清潔", "is_correct": false, "explanation": "汚れがない状態を表し、曖昧の対義語ではない。"}, {"text": "元気", "is_correct": false, "explanation": "活力がある様子で、曖昧とは対義関係にない。"}, {"text": "豪快", "is_correct": false, "explanation": "大きく勢いのある様子で、曖昧の対義語ではない。"}], "correct_answer": "明確", "explanations": {"明確": "はっきりして定まっている意味で、〈はっきりしない〉曖昧の対義語として辞書に載る。", "清潔": "汚れがない状態を表し、曖昧の対義語ではない。", "元気": "活力がある様子で、曖昧とは対義関係にない。", "豪快": "大きく勢いのある様子で、曖昧の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "はっきりしていないこと。", "primary_collocate": null, "pronunciation": "あいまい", "ipa": "aimai", "syllable_count": 4, "sentences": [{"text": "彼の返事は曖昧で、よくわかりませんでした。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "彼[かれ]の返事[へんじ]は曖昧[あいまい]で、よくわかりませんでした。", "sentence_source": "generated"}, {"text": "曖昧な言い方をすると、相手が困ります。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "曖昧[あいまい]な言[い]い方[かた]をすると、相手[あいて]が困[こま]ります。", "sentence_source": "generated"}, {"text": "場所の説明が曖昧だったので、道に迷いました。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "場所[ばしょ]の説明[せつめい]が曖昧[あいまい]だったので、道[みち]に迷[まよ]いました。", "sentence_source": "generated"}, {"text": "記憶が曖昧で、名前を思い出せません。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "記憶[きおく]が曖昧[あいまい]で、名前[なまえ]を思[おも]い出[だ]せません。", "sentence_source": "generated"}, {"text": "曖昧な説明では、だれも動けません。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "曖昧[あいまい]な説明[せつめい]では、だれも動[うご]けません。", "sentence_source": "generated"}, {"text": "先生は曖昧な答えを許さなかった。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "先生[せんせい]は曖昧[あいまい]な答[こた]えを許[ゆる]さなかった。", "sentence_source": "generated"}, {"text": "日時が曖昧なままでは、予約ができません。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "日時[にちじ]が曖昧[あいまい]なままでは、予約[よやく]ができません。", "sentence_source": "generated"}, {"text": "彼女は理由を曖昧にして、帰ってしまった。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は理由[りゆう]を曖昧[あいまい]にして、帰[かえ]ってしまった。", "sentence_source": "generated"}, {"text": "約束の内容が曖昧だと、あとでけんかになる。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "約束[やくそく]の内容[ないよう]が曖昧[あいまい]だと、あとでけんかになる。", "sentence_source": "generated"}, {"text": "曖昧な文章は、読む人を迷わせる。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "曖昧[あいまい]な文章[ぶんしょう]は、読[よ]む人[ひと]を迷[まよ]わせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "曖昧だ", "label": "終止形"}, {"form": "曖昧な", "label": "連体形"}, {"form": "曖昧で", "label": "連用形"}, {"form": "曖昧に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "言葉や記憶や説明がはっきりしていない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "はっきりしないことを表し、「よくわからなかった」と文脈が合う。"}, {"text": "豪華", "is_correct": false, "explanation": "派手で立派な様子を表す語で、返事の不明瞭さとは結びつかず文が通らない。"}, {"text": "新鮮", "is_correct": false, "explanation": "鮮度がよい、目新しいという意味で、返事の内容を表すには合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "壊れにくい様子を表す語で、返事の説明としては不自然。"}], "explanations": {"曖昧": "はっきりしないことを表し、「よくわからなかった」と文脈が合う。", "豪華": "派手で立派な様子を表す語で、返事の不明瞭さとは結びつかず文が通らない。", "新鮮": "鮮度がよい、目新しいという意味で、返事の内容を表すには合わない。", "頑丈": "壊れにくい様子を表す語で、返事の説明としては不自然。"}, "sentence_index": 0, "correct_answer": "曖昧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このガラスは曖昧で、向こう側がまったく見えない。", "explanation": "〈曖昧〉は内容や区別がはっきりしないことを表す。光を通さない物の状態を言うには〈不透明〉を使うので、ここでは合わない。"}, {"text": "この写真は曖昧で、写っている人が一目で誰かわかる。", "explanation": "〈曖昧〉は内容や区別がはっきりしないことを表す。鮮明で一目でわかる様子を言うには〈鮮明〉を使うので、ここでは合わない。"}, {"text": "寝不足で頭が曖昧で、授業の内容が頭に入らなかった。", "explanation": "〈曖昧〉は物事の区別がはっきりしないことを表す。人の頭の働きが鈍い様子には〈ぼんやり〉を使うので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "日時がはっきりしないという意味で、「予約ができない」と文脈が合う。"}, {"text": "派手", "is_correct": false, "explanation": "目立つ様子を表す語で、日時の状態を表すには合わない。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色彩がはっきりしている様子で、日時には当てはまらない。"}, {"text": "器用", "is_correct": false, "explanation": "手先がうまい様子を表す語で、日時の状態とは関係がない。"}], "explanations": {"曖昧": "日時がはっきりしないという意味で、「予約ができない」と文脈が合う。", "派手": "目立つ様子を表す語で、日時の状態を表すには合わない。", "鮮やか": "色彩がはっきりしている様子で、日時には当てはまらない。", "器用": "手先がうまい様子を表す語で、日時の状態とは関係がない。"}, "sentence_index": 6, "correct_answer": "曖昧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "川の水が曖昧で、底の石がまったく見えない。", "explanation": "〈曖昧〉は内容や区別の不明瞭さに使う語。水の濁りを言うには〈濁る〉を使うので、ここでは合わない。"}, {"text": "壁の色が曖昧で、新築のころの白さがまったく残っていない。", "explanation": "〈曖昧〉は物事の区別がはっきりしないことを表す。表面の色が沈んで冴えない状態には〈くすむ〉を使うので、ここでは合わない。"}, {"text": "風邪で喉をいため、声が曖昧になって歌えなかった。", "explanation": "〈曖昧〉は内容の不明瞭さを表す。声が出にくく掠れた状態には〈かすれる〉を使うので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の説明は曖昧な、だれも理解できなかった。", "corrected_sentence": "彼の説明は曖昧で、だれも理解できなかった。", "error_description": "『曖昧』は形状詞なので、文を続けるには『で』が必要。『な』は連体形で、ここでは後に名詞がなく文が切れてしまうため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "語幹そのもの。文中では直後に「な」が続く形の基になる部分。"}, {"text": "曖昧だ", "is_correct": false, "explanation": "終止形。文中の「曖昧な」の位置には、断定の形としては入らない。"}, {"text": "曖昧で", "is_correct": false, "explanation": "連用形。「で」で文を続ける形で、名詞修飾の位置には合わない。"}, {"text": "曖昧に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞を直接修飾する位置には合わない。"}], "correct_form": "曖昧", "base_form": "曖昧だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"曖昧": "語幹そのもの。文中では直後に「な」が続く形の基になる部分。", "曖昧だ": "終止形。文中の「曖昧な」の位置には、断定の形としては入らない。", "曖昧で": "連用形。「で」で文を続ける形で、名詞修飾の位置には合わない。", "曖昧に": "連用形。動詞や形容詞を修飾する形で、名詞を直接修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39178, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先方の日時が曖昧ままでは、予約の手続きが進められない。", "corrected_sentence": "先方の日時が曖昧なままでは、予約の手続きが進められない。", "error_description": "『曖昧なまま』の『な』が必要。『曖昧まま』は語幹に『まま』を直接続けた誤りで、自然な日本語にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "語幹。文中では「曖昧に」の基になる部分。"}, {"text": "曖昧な", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「理由を〜にして」の位置には入らない。"}, {"text": "曖昧だった", "is_correct": false, "explanation": "過去の断定形。「理由を〜にして」の位置には文法的に入らない。"}, {"text": "曖昧ならば", "is_correct": false, "explanation": "仮定の形。文が成り立たず、ここでは使えない。"}], "correct_form": "曖昧", "base_form": "曖昧だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"曖昧": "語幹。文中では「曖昧に」の基になる部分。", "曖昧な": "連体形。名詞を修飾する形で、「理由を〜にして」の位置には入らない。", "曖昧だった": "過去の断定形。「理由を〜にして」の位置には文法的に入らない。", "曖昧ならば": "仮定の形。文が成り立たず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明確", "is_correct": true, "explanation": "はっきりして定まっている意味で、〈どちらとも決められない〉曖昧の対義語として辞書に載る。"}, {"text": "華やか", "is_correct": false, "explanation": "目立って美しい様子で、曖昧の対義語ではない。"}, {"text": "素直", "is_correct": false, "explanation": "人の性格を表す語で、曖昧とは対義関係にない。"}, {"text": "手軽", "is_correct": false, "explanation": "簡単で負担が少ない様子で、曖昧の対義語ではない。"}], "correct_answer": "明確", "explanations": {"明確": "はっきりして定まっている意味で、〈どちらとも決められない〉曖昧の対義語として辞書に載る。", "華やか": "目立って美しい様子で、曖昧の対義語ではない。", "素直": "人の性格を表す語で、曖昧とは対義関係にない。", "手軽": "簡単で負担が少ない様子で、曖昧の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
