INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の区別や状態がはっきりせず、どちらとも決められない様子。", "primary_collocate": null, "pronunciation": "あいまい", "ipa": "aimai", "syllable_count": 4, "sentences": [{"text": "二つの色の境目が曖昧で、どちらとも言えない。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "二[ふた]つの色[いろ]の境目[さかいめ]が曖昧[あいまい]で、どちらとも言[い]えない。", "sentence_source": "generated"}, {"text": "夢と現実の区別が曖昧になってきた。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "夢[ゆめ]と現実[げんじつ]の区別[くべつ]が曖昧[あいまい]になってきた。", "sentence_source": "generated"}, {"text": "仕事と遊びの線引きが曖昧な職場です。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "仕事[しごと]と遊[あそ]びの線引[せんび]きが曖昧[あいまい]な職場[しょくば]です。", "sentence_source": "generated"}, {"text": "彼は賛成とも反対とも取れる曖昧な態度をとった。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "彼[かれ]は賛成[さんせい]とも反対[はんたい]とも取[と]れる曖昧[あいまい]な態度[たいど]をとった。", "sentence_source": "generated"}, {"text": "判定が曖昧で、勝ち負けを決められなかった。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "判定[はんてい]が 曖昧[あいまい]で、勝[か]ち負[ま]けを決[き]められなかった。", "sentence_source": "generated"}, {"text": "空が晴れか曇りか曖昧な天気だった。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "空[そら]が晴[は]れか曇[くも]りか曖昧[あいまい]な天気[てんき]だった。", "sentence_source": "generated"}, {"text": "責任の所在が曖昧なので、だれも謝らない。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "責任[せきにん]の所在[しょざい]が曖昧[あいまい]なので、だれも謝[あやま]らない。", "sentence_source": "generated"}, {"text": "自分の気持ちが曖昧で、どちらを選ぶか決められない。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "自分[じぶん]の気持[きも]ちが曖昧[あいまい]で、どちらを選[えら]ぶか決[き]められない。", "sentence_source": "generated"}, {"text": "この言葉は意味が曖昧で、二通りに読める。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "この言葉[ことば]は意味[いみ]が曖昧[あいまい]で、二通[ふたとお]りに読[よ]める。", "sentence_source": "generated"}, {"text": "境界が曖昧な土地は、争いのもとになる。", "target_word": "曖昧", "complexity_tier": "T3", "furigana": "境界[きょうかい]が曖昧[あいまい]な土地[とち]は、争[あらそ]いのもとになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "曖昧だ", "label": "終止形"}, {"form": "曖昧な", "label": "連体形"}, {"form": "曖昧で", "label": "連用形"}, {"form": "曖昧に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "区別や状態がはっきりせずどちらとも決められない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "色の境目がはっきりせず、どちらとも言えないという文脈に合う。"}, {"text": "豪華", "is_correct": false, "explanation": "派手で立派な様子で、境目の状態には当てはまらない。"}, {"text": "新鮮", "is_correct": false, "explanation": "鮮度や目新しさを表し、色の境目の説明には合わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "壊れにくい様子で、境目の状態とは関係がない。"}], "explanations": {"曖昧": "色の境目がはっきりせず、どちらとも言えないという文脈に合う。", "豪華": "派手で立派な様子で、境目の状態には当てはまらない。", "新鮮": "鮮度や目新しさを表し、色の境目の説明には合わない。", "頑丈": "壊れにくい様子で、境目の状態とは関係がない。"}, "sentence_index": 0, "correct_answer": "曖昧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このボールは曖昧で、高く弾む。", "explanation": "〈曖昧〉は区別や状態の不明瞭さを表す。弾む性質には〈弾力がある〉を使うので、ここでは合わない。"}, {"text": "この部屋は曖昧で、ほこり一つない。", "explanation": "〈曖昧〉は区別や状態が定まらないことを表す。きれいな状態を言うには〈清潔〉を使うので、ここでは合わない。"}, {"text": "この地域は水が曖昧で、一年中緑が絶えない。", "explanation": "〈曖昧〉は物事の区別や状態がはっきりしないことを表す。水が豊富な様子には〈豊か〉を使うので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "責任の所在がはっきりせず、だれも謝らないという文脈に合う。"}, {"text": "大らか", "is_correct": false, "explanation": "細かいことにこだわらない性格を表し、責任の所在の説明には合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "荒っぽい振る舞いを表し、責任の所在とは関係がない。"}, {"text": "上品", "is_correct": false, "explanation": "品があることを表す語で、責任の所在の状態には当てはまらない。"}], "explanations": {"曖昧": "責任の所在がはっきりせず、だれも謝らないという文脈に合う。", "大らか": "細かいことにこだわらない性格を表し、責任の所在の説明には合わない。", "乱暴": "荒っぽい振る舞いを表し、責任の所在とは関係がない。", "上品": "品があることを表す語で、責任の所在の状態には当てはまらない。"}, "sentence_index": 6, "correct_answer": "曖昧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この衣類は曖昧で、すぐに畳める。", "explanation": "〈曖昧〉は区別や状態が定まらないことを表す。洗ったあとの衣類の乾いた状態には〈乾燥〉を使うので、ここでは合わない。"}, {"text": "このケーキは曖昧で、子どもに人気がある。", "explanation": "〈曖昧〉は内容の不明瞭さを表す語。味が甘いことを言うには〈甘い〉を使うので、ここでは合わない。"}, {"text": "荷物が曖昧で、一人では運べなかった。", "explanation": "〈曖昧〉は区別がはっきりしないことを表す。目方が多いことを言うには〈重い〉を使うので、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この契約の条件は曖昧を、どちらの解釈もできる。", "corrected_sentence": "この契約の条件は曖昧で、どちらの解釈もできる。", "error_description": "『曖昧』は形状詞なので、後ろは『で』で続ける。『を』は目的語を表す助詞で、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "語幹そのもの。文中では「になってきた」の前に「に」の形で現れる部分の基になる。"}, {"text": "曖昧だ", "is_correct": false, "explanation": "終止形で、「になってきた」と続く位置には入らない。"}, {"text": "曖昧な", "is_correct": false, "explanation": "連体形で、名詞を修飾する形。ここでは使えない。"}, {"text": "曖昧で", "is_correct": false, "explanation": "連用形で文を続ける形。「になってきた」の前には入らない。"}], "correct_form": "曖昧", "base_form": "曖昧だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"曖昧": "語幹そのもの。文中では「になってきた」の前に「に」の形で現れる部分の基になる。", "曖昧だ": "終止形で、「になってきた」と続く位置には入らない。", "曖昧な": "連体形で、名詞を修飾する形。ここでは使えない。", "曖昧で": "連用形で文を続ける形。「になってきた」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "判断が曖昧ままでは、どちらの案にも賛成できない。", "corrected_sentence": "判断が曖昧なままでは、どちらの案にも賛成できない。", "error_description": "『曖昧なまま』の『な』を落とすと、語幹に『まま』が直接続く誤りになる。『な』が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "曖昧", "is_correct": true, "explanation": "語幹。文中では「で」の前に現れる部分の基になる。"}, {"text": "曖昧に", "is_correct": false, "explanation": "連用形で、動詞を修飾する形。「気持ちが〜で」の位置には入らない。"}, {"text": "曖昧だった", "is_correct": false, "explanation": "過去の断定形で、文中の位置に合わない。"}, {"text": "曖昧ならば", "is_correct": false, "explanation": "仮定の形で、「で、どちらを選ぶか」と続く文には入らない。"}], "correct_form": "曖昧", "base_form": "曖昧だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"曖昧": "語幹。文中では「で」の前に現れる部分の基になる。", "曖昧に": "連用形で、動詞を修飾する形。「気持ちが〜で」の位置には入らない。", "曖昧だった": "過去の断定形で、文中の位置に合わない。", "曖昧ならば": "仮定の形で、「で、どちらを選ぶか」と続く文には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「道を模索した」で、探す対象の道を示す。"}, {"text": "に", "is_correct": false, "explanation": "「道に模索した」では場所や対象を示す「に」になり、模索の対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「道が模索した」では道が主語になり、探す主体として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を示すので、探す対象を示す「を」とは合わない。"}], "correct_answer": "を", "explanations": {"を": "「道を模索した」で、探す対象の道を示す。", "に": "「道に模索した」では場所や対象を示す「に」になり、模索の対象を表せない。", "が": "「道が模索した」では道が主語になり、探す主体として不自然。", "へ": "「へ」は向かう方向を示すので、探す対象を示す「を」とは合わない。"}, "error_tags": {"に": "場所・対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作戦を模索して」で、探す対象の作戦を示す。"}, {"text": "から", "is_correct": false, "explanation": "「作戦から模索して」は起点を示すことになり、探す対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、探す対象を示す格にならない。"}, {"text": "の", "is_correct": false, "explanation": "「作戦の模索して」は名詞をつなぐ「の」になり、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「作戦を模索して」で、探す対象の作戦を示す。", "から": "「作戦から模索して」は起点を示すことになり、探す対象を表せない。", "より": "「より」は比較の基準を示すので、探す対象を示す格にならない。", "の": "「作戦の模索して」は名詞をつなぐ「の」になり、文として成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを見つけようとして、あちこちを探すこと。", "primary_collocate": null, "pronunciation": "もさく", "ipa": "mosaku", "syllable_count": 3, "sentences": [{"text": "彼は暗闇の中で出口を模索した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "彼[かれ]は暗闇[くらやみ]の中[なか]で出口[でぐち]を模索[もさく]した。", "sentence_source": "generated"}, {"text": "道に迷った私たちは、駅へ戻る道を模索した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]った私[わたし]たちは、駅[えき]へ戻[もど]る道[みち]を模索[もさく]した。", "sentence_source": "generated"}, {"text": "彼女は住む場所を模索して、いくつもの町を回った。", "target_word": "模索", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は住[す]む場所[ばしょ]を模索[もさく]して、いくつもの町[まち]を回[まわ]った。", "sentence_source": "generated"}, {"text": "地図がないので、山の中で宿への近道を模索した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "地図[ちず]がないので、山[やま]の中[なか]で宿[やど]への近道[ちかみち]を模索[もさく]した。", "sentence_source": "generated"}, {"text": "会社は新しい市場を模索して、海外にも人を送った。", "target_word": "模索", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい市場[しじょう]を模索[もさく]して、海外[かいがい]にも人[ひと]を送[おく]った。", "sentence_source": "generated"}, {"text": "母は娘に合う学校を模索し、見学を重ねた。", "target_word": "模索", "complexity_tier": "T3", "furigana": "母[はは]は娘[むすめ]に合[あ]う学校[がっこう]を模索[もさく]し、見学[けんがく]を重[かさ]ねた。", "sentence_source": "generated"}, {"text": "彼は自分に合う趣味を模索して、いろいろな教室に通った。", "target_word": "模索", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]に合[あ]う趣味[しゅみ]を模索[もさく]して、いろいろな教室[きょうしつ]に通[かよ]った。", "sentence_source": "generated"}, {"text": "チームは勝てる作戦を模索して、何度も試合を見直した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "チームは勝[か]てる作戦[さくせん]を模索[もさく]して、何度[なんど]も試合[しあい]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "私は引っ越し先を模索したが、なかなか決まらなかった。", "target_word": "模索", "complexity_tier": "T3", "furigana": "私[わたし]は引[ひ]っ越[こ]し先[さき]を模索[もさく]したが、なかなか決[き]まらなかった。", "sentence_source": "generated"}, {"text": "先生は生徒が興味を持つ話題を模索した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]が興味[きょうみ]を持[も]つ話題[わだい]を模索[もさく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "模索", "label": "名詞形"}, {"form": "模索する", "label": "辞書形"}, {"form": "模索した", "label": "過去形"}, {"form": "模索して", "label": "て形"}, {"form": "模索している", "label": "進行形"}], "register": "やや硬い書き言葉（常体）", "sense_fingerprint": "見つけたいもの（場所・道・相手など）を求めて、あちこち探し回ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模索", "is_correct": true, "explanation": "「出口を模索した」で、手探りで出口を探す意味になり、文脈に合う。"}, {"text": "入浴", "is_correct": false, "explanation": "「出口を入浴した」は成り立たず、文の意味が通らない。"}, {"text": "感謝", "is_correct": false, "explanation": "「出口を感謝した」は目的語として成り立たず、文が不自然になる。"}, {"text": "同意", "is_correct": false, "explanation": "「出口を同意した」は意味をなさず、探す行為を表せない。"}], "explanations": {"模索": "「出口を模索した」で、手探りで出口を探す意味になり、文脈に合う。", "入浴": "「出口を入浴した」は成り立たず、文の意味が通らない。", "感謝": "「出口を感謝した」は目的語として成り立たず、文が不自然になる。", "同意": "「出口を同意した」は意味をなさず、探す行為を表せない。"}, "sentence_index": 0, "correct_answer": "模索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、窓を開けて部屋の空気を模索した。", "explanation": "ここは〈換気〉の意味。空気を入れ替える行為で、探すものがある模索とは合わない。"}, {"text": "辞書で知りたい単語を模索した。", "explanation": "ここは〈検索〉の意味。辞書やデータの中から目的の情報を調べる行為は検索で、模索とは言わない。"}, {"text": "夕方、川沿いを模索して歩いた。", "explanation": "ここは〈散策〉の意味。目的もなくのんびり歩くことは散策で、探すものがある模索とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模索", "is_correct": true, "explanation": "「趣味を模索して」で、合う趣味を探す意味になり、文脈に合う。"}, {"text": "避難", "is_correct": false, "explanation": "「趣味を避難して」は成り立たず、文の意味が通らない。"}, {"text": "乾杯", "is_correct": false, "explanation": "「趣味を乾杯して」は意味をなさない。"}, {"text": "改築", "is_correct": false, "explanation": "「趣味を改築して」は対象として合わず、文が不自然になる。"}], "explanations": {"模索": "「趣味を模索して」で、合う趣味を探す意味になり、文脈に合う。", "避難": "「趣味を避難して」は成り立たず、文の意味が通らない。", "乾杯": "「趣味を乾杯して」は意味をなさない。", "改築": "「趣味を改築して」は対象として合わず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "模索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "逃げた車を模索して、ずっと後ろから追った。", "explanation": "ここは〈追跡〉の意味。動いて逃げる相手を後ろから追いかける行為で、模索とは合わない。"}, {"text": "整備士は、いつもどおりエンジンを模索した。", "explanation": "ここは〈点検〉の意味。決まった箇所を調べて確かめる行為で、探し方が定まらない模索とは合わない。"}, {"text": "先生は答案を模索して、点数をつけた。", "explanation": "ここは〈採点〉の意味。答案の正誤を見て点数をつける行為で、答えや方法を手探りする模索とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は新しい部屋に模索した。", "corrected_sentence": "私は新しい部屋を模索した。", "error_description": "「模索した」の対象は「を」で示す。「部屋に」と書くと格が誤りになり、正しくは「部屋を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39180, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの計画を模索を決めた。", "corrected_sentence": "夏休みの計画を模索して決めた。", "error_description": "「模索を決めた」は誤り。「模索」に格助詞「を」を付けて動詞「決めた」に直接つなぐことはできず、動詞の「模索して」（て形）でつなぐ必要がある。正しくは「模索して決めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「働き方の模索」で、働き方を探すことを表す連体修飾の「の」になる。"}, {"text": "が", "is_correct": false, "explanation": "「働き方が模索が始まっている」では主語が二重になり、「働き方の模索」という修飾関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「働き方に模索」では場所や相手を示す「に」になり、模索との修飾関係が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「働き方へ模索」では方向を示す「へ」になり、名詞どうしの修飾関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「働き方の模索」で、働き方を探すことを表す連体修飾の「の」になる。", "が": "「働き方が模索が始まっている」では主語が二重になり、「働き方の模索」という修飾関係が成り立たない。", "に": "「働き方に模索」では場所や相手を示す「に」になり、模索との修飾関係が合わない。", "へ": "「働き方へ模索」では方向を示す「へ」になり、名詞どうしの修飾関係が成り立たない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「対策を模索している」で、探す対象の対策を示す。"}, {"text": "から", "is_correct": false, "explanation": "「対策から模索している」は起点を示すことになり、探す対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、探す対象を示す格にならない。"}, {"text": "の", "is_correct": false, "explanation": "「対策の模索している」は名詞をつなぐ「の」になり、文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「対策を模索している」で、探す対象の対策を示す。", "から": "「対策から模索している」は起点を示すことになり、探す対象を表せない。", "より": "「より」は比較の基準を示すので、探す対象を示す格にならない。", "の": "「対策の模索している」は名詞をつなぐ「の」になり、文として成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "はっきりしない答えや方法を、試したり考えたりしながら探すこと。", "primary_collocate": null, "pronunciation": "もさく", "ipa": "mosaku", "syllable_count": 3, "sentences": [{"text": "解決の方法がわからず、社長は毎日模索を続けている。", "target_word": "模索", "complexity_tier": "T3", "furigana": "解決[かいけつ]の方法[ほうほう]がわからず、社長[しゃちょう]は毎日[まいにち]模索[もさく]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "新しい働き方の模索が、多くの会社で始まっている。", "target_word": "模索", "complexity_tier": "T3", "furigana": "新[あたら]しい働[はたら]き方[かた]の模索[もさく]が、多[おお]くの会社[かいしゃ]で始[はじ]まっている。", "sentence_source": "generated"}, {"text": "彼は自分の進む道を模索する日々を送った。", "target_word": "模索", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の進[すす]む道[みち]を模索[もさく]する日々[ひび]を送[おく]った。", "sentence_source": "generated"}, {"text": "正解のない問題なので、試行錯誤しながら模索するしかない。", "target_word": "模索", "complexity_tier": "T3", "furigana": "正解[せいかい]のない問題[もんだい]なので、試行錯誤[しこうさくご]しながら模索[もさく]するしかない。", "sentence_source": "generated"}, {"text": "研究チームは治療法を模索し、何度も実験をやり直した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは治療法[ちりょうほう]を模索[もさく]し、何度[なんど]も実験[じっけん]をやり直[なお]した。", "sentence_source": "generated"}, {"text": "子育ての方法を模索する親が増えている。", "target_word": "模索", "complexity_tier": "T3", "furigana": "子育[こそだ]ての方法[ほうほう]を模索[もさく]する親[おや]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "バンドは自分たちらしい音楽を模索し、曲作りを重ねた。", "target_word": "模索", "complexity_tier": "T3", "furigana": "バンドは自分[じぶん]たちらしい音楽[おんがく]を模索[もさく]し、曲作[きょくづく]りを重[かさ]ねた。", "sentence_source": "generated"}, {"text": "市は人口減少への対策を模索している。", "target_word": "模索", "complexity_tier": "T3", "furigana": "市[し]は人口減少[じんこうげんしょう]への対策[たいさく]を模索[もさく]している。", "sentence_source": "generated"}, {"text": "失敗するたびに、彼は別のやり方を模索した。", "target_word": "模索", "complexity_tier": "T3", "furigana": "失敗[しっぱい]するたびに、彼[かれ]は別[べつ]のやり方[かた]を模索[もさく]した。", "sentence_source": "generated"}, {"text": "将来の夢が決まらず、まだ模索の時期だ。", "target_word": "模索", "complexity_tier": "T3", "furigana": "将来[しょうらい]の夢[ゆめ]が決[き]まらず、まだ模索[もさく]の時期[じき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "模索", "label": "名詞形"}, {"form": "模索する", "label": "辞書形"}, {"form": "模索した", "label": "過去形"}, {"form": "模索して", "label": "て形"}, {"form": "模索している", "label": "進行形"}], "register": "やや硬い書き言葉（常体）", "sense_fingerprint": "正解や進め方が見えない問題について、試行錯誤しながら手がかりを探ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模索", "is_correct": true, "explanation": "「毎日模索を続けている」で、答えや方法を手探りで探し続ける意味になり、文に合う。"}, {"text": "辞任", "is_correct": false, "explanation": "「毎日辞任を続けている」は成り立たず、文の意味が通らない。"}, {"text": "返金", "is_correct": false, "explanation": "「毎日返金を続けている」は主語の社長の行動として不自然で、文脈に合わない。"}, {"text": "同意", "is_correct": false, "explanation": "「毎日同意を続けている」は意味が通らず、解決の方法を探す文脈に合わない。"}], "explanations": {"模索": "「毎日模索を続けている」で、答えや方法を手探りで探し続ける意味になり、文に合う。", "辞任": "「毎日辞任を続けている」は成り立たず、文の意味が通らない。", "返金": "「毎日返金を続けている」は主語の社長の行動として不自然で、文脈に合わない。", "同意": "「毎日同意を続けている」は意味が通らず、解決の方法を探す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "模索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の草木を毎朝模索して、水をやった。", "explanation": "ここは〈水やり〉の意味。決まった作業として水を与える行為で、答えや方法を探る模索とは合わない。"}, {"text": "行方不明の子どもを、警察が模索している。", "explanation": "ここは〈捜索〉の意味。人や物を組織的に探す場合は捜索を使い、模索は答えや方法を探るときに使う。"}, {"text": "提出の前に、答案の欄に名前を模索して書いた。", "explanation": "ここは〈記入〉の意味。決まった欄に書き込む行為で、答えや方法を探る模索とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模索", "is_correct": true, "explanation": "「音楽を模索し」で、自分たちらしい音楽を探す意味になり、文脈に合う。"}, {"text": "配送", "is_correct": false, "explanation": "「音楽を配送し」は成り立たず、文の意味が通らない。"}, {"text": "退席", "is_correct": false, "explanation": "「音楽を退席し」は目的語として成り立たず、文が不自然になる。"}, {"text": "解雇", "is_correct": false, "explanation": "「音楽を解雇し」は意味をなさず、曲作りの文脈に合わない。"}], "explanations": {"模索": "「音楽を模索し」で、自分たちらしい音楽を探す意味になり、文脈に合う。", "配送": "「音楽を配送し」は成り立たず、文の意味が通らない。", "退席": "「音楽を退席し」は目的語として成り立たず、文が不自然になる。", "解雇": "「音楽を解雇し」は意味をなさず、曲作りの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "模索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机の上の書類を模索して、いらないものを捨てた。", "explanation": "ここは〈整理〉の意味。並んだものを片付ける行為で、答えや方法を探る模索とは合わない。"}, {"text": "レジの金額を模索して、合計を出した。", "explanation": "ここは〈計算〉の意味。数字を足して合計を出す行為で、答えや方法を手探りする模索とは合わない。"}, {"text": "ケーキを模索して、一つずつ箱に包んだ。", "explanation": "ここは〈包装〉の意味。商品を箱や袋に包む行為で、答えや方法を手探りする模索とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は解決の方法を模索に続けている。", "corrected_sentence": "社長は解決の方法を模索し続けている。", "error_description": "「模索に続けている」は誤り。「続ける」を付けるには、名詞「模索」を動詞の連用形「模索し」にして「模索し続けている」とする。「に」は入らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39181, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは新しい計画を模索が決めた。", "corrected_sentence": "私たちは新しい計画を模索して決めた。", "error_description": "「模索が決めた」は誤り。主語を示す「が」は「決めた」の動作主にならず、動詞「模索して」（て形）でつなぐ必要がある。正しくは「模索して決めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インセンティブがあると」の存在の主語を示す「が」で、文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は「が」で存在を示すので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「インセンティブにあると」は場所の意味になり、存在の文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「インセンティブのあると」は文法が崩れ、ここでは「が」が必要。"}], "correct_answer": "が", "explanations": {"が": "「インセンティブがあると」の存在の主語を示す「が」で、文が成立する。", "を": "「ある」は「が」で存在を示すので、「を」は合わない。", "に": "「インセンティブにあると」は場所の意味になり、存在の文として不自然。", "の": "「インセンティブのあると」は文法が崩れ、ここでは「が」が必要。"}, "error_tags": {"を": "目的語", "に": "着点", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
