INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをがんばる気持ちを強くするための、ごほうびやはげましのこと。", "primary_collocate": null, "pronunciation": "いんせんてぃぶ", "ipa": "iɴseɴtibɯ", "syllable_count": 4, "sentences": [{"text": "毎日勉強するために、自分へのインセンティブを決めました。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "毎日[まいにち]勉強[べんきょう]するために、自分[じぶん]へのインセンティブを決[き]めました。", "sentence_source": "generated"}, {"text": "ごほうびというインセンティブがあると、がんばれます。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "ごほうびというインセンティブがあると、がんばれます。", "sentence_source": "generated"}, {"text": "先生は宿題を出した子にシールをあげて、インセンティブにしています。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "先生[せんせい]は宿題[しゅくだい]を出[だ]した子[こ]にシールをあげて、インセンティブにしています。", "sentence_source": "generated"}, {"text": "インセンティブがないと、やる気が出ません。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "インセンティブがないと、やる気[き]が出[で]ません。", "sentence_source": "generated"}, {"text": "サッカーの練習を続けるインセンティブは、試合に勝つ喜びです。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "サッカーの練習[れんしゅう]を続[つづ]けるインセンティブは、試合[しあい]に勝[か]つ喜[よろこ]びです。", "sentence_source": "generated"}, {"text": "弟には、おやつがいちばんのインセンティブです。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "弟[おとうと]には、おやつがいちばんのインセンティブです。", "sentence_source": "generated"}, {"text": "毎日走ったら好きなケーキを食べると決めて、インセンティブにしました。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "毎日[まいにち]走[はし]ったら好[す]きなケーキを食[た]べると決[き]めて、インセンティブにしました。", "sentence_source": "generated"}, {"text": "このクラスでは、本を読むとポイントがもらえるインセンティブがあります。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "このクラスでは、本[ほん]を読[よ]むとポイントがもらえるインセンティブがあります。", "sentence_source": "generated"}, {"text": "ほめられることも、子どもにはインセンティブになります。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "ほめられることも、子[こ]どもにはインセンティブになります。", "sentence_source": "generated"}, {"text": "インセンティブが大きいほど、みんな熱心に働きます。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "インセンティブが大[おお]きいほど、みんな熱心[ねっしん]に働[はたら]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インセンティブ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "がんばる気持ちを強めるごほうびやはげまし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インセンティブ", "is_correct": true, "explanation": "「自分へのインセンティブを決める」は、がんばるための報酬を決めるという意味で文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「自分への天井を決める」は意味が通らず、勉強の動機付けにならない。"}, {"text": "玄関", "is_correct": false, "explanation": "「自分への玄関を決める」は勉強の動機付けにならず、文脈に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「自分への冷蔵庫を決める」は勉強の報酬として成立しない。"}], "explanations": {"インセンティブ": "「自分へのインセンティブを決める」は、がんばるための報酬を決めるという意味で文に合う。", "天井": "「自分への天井を決める」は意味が通らず、勉強の動機付けにならない。", "玄関": "「自分への玄関を決める」は勉強の動機付けにならず、文脈に合わない。", "冷蔵庫": "「自分への冷蔵庫を決める」は勉強の報酬として成立しない。"}, "sentence_index": 0, "correct_answer": "インセンティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに、大学のインセンティブに参加しました。", "explanation": "ここは〈インターン〉の意味。参加するのは実習や職場体験で、報酬のインセンティブは参加する対象ではない。"}, {"text": "冬になるとインセンティブが流行します。", "explanation": "ここは〈インフルエンザ〉の意味。流行するのは病気で、報酬のインセンティブは流行しない。"}, {"text": "仕事が多くて、インセンティブがたまります。", "explanation": "ここは〈ストレス〉の意味。たまるのは心の負担で、やる気を起こす報酬のインセンティブとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インセンティブ", "is_correct": true, "explanation": "「〜をインセンティブにする」は、がんばる動機として扱うという意味で文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気にする」は、走る決心の動機として意味が通らない。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "「ネクタイにする」は、ケーキを食べる決めごととは関係ない。"}, {"text": "洗剤", "is_correct": false, "explanation": "「洗剤にする」は、走る目標を立てる文脈に合わない。"}], "explanations": {"インセンティブ": "「〜をインセンティブにする」は、がんばる動機として扱うという意味で文に合う。", "天気": "「天気にする」は、走る決心の動機として意味が通らない。", "ネクタイ": "「ネクタイにする」は、ケーキを食べる決めごととは関係ない。", "洗剤": "「洗剤にする」は、走る目標を立てる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "インセンティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有名な俳優がインセンティブに答えた。", "explanation": "ここは〈インタビュー〉の意味。答えるのは質問で、報酬のインセンティブは答えるものではない。"}, {"text": "インセンティブが整えば、町の生活はもっと便利になる。", "explanation": "ここは〈インフラ〉の意味。整えるのは道路や水道などの基盤で、報酬のインセンティブには当てはまらない。"}, {"text": "アプリのインセンティブが終わるまで、少し待ってください。", "explanation": "ここは〈インストール〉の意味。アプリの導入が終わるのを待つ場面で、報酬の意味のインセンティブは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ほめることは、子どもにとってよいインセンティブがなります。", "corrected_sentence": "ほめることは、子どもにとってよいインセンティブになります。", "error_description": "「なる」は「に」で結果を示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ポイントが貯まると、インセンティブでなります。", "corrected_sentence": "ポイントが貯まると、インセンティブになります。", "error_description": "「なる」の結果は「に」で示す。「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「インセンティブが必要です」の主語を示す「が」で、文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "「必要」は目的語をとらないので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「インセンティブと必要です」は文が成立せず、ここでは「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「必要」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「インセンティブが必要です」の主語を示す「が」で、文が成立する。", "を": "「必要」は目的語をとらないので、「を」は合わない。", "と": "「インセンティブと必要です」は文が成立せず、ここでは「が」が必要。", "へ": "「へ」は方向を示し、「必要」の主語にはならない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人に特定の行動を促すために与えられる、外的な動機付けとなる報酬や刺激。", "primary_collocate": null, "pronunciation": "いんせんてぃぶ", "ipa": "iɴseɴtibɯ", "syllable_count": 4, "sentences": [{"text": "会社は売り上げに応じて、社員にインセンティブを支払います。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は売[う]り上[あ]げに応[おう]じて、社員[しゃいん]にインセンティブを支払[しはら]います。", "sentence_source": "generated"}, {"text": "金銭的なインセンティブだけでは、長く続けるのは難しいです。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "金銭的[きんせんてき]なインセンティブだけでは、長[なが]く続[つづ]けるのは難[むずか]しいです。", "sentence_source": "generated"}, {"text": "省エネを進めるため、国は補助金というインセンティブを用意しました。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "省[しょう]エネを進[すす]めるため、国[くに]は補助金[ほじょきん]というインセンティブを用意[ようい]しました。", "sentence_source": "generated"}, {"text": "新しい制度では、成果を出した人にインセンティブが与えられます。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]では、成果[せいか]を出[だ]した人[ひと]にインセンティブが与[あた]えられます。", "sentence_source": "generated"}, {"text": "税金が安くなるインセンティブがあるので、電気自動車が売れています。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "税金[ぜいきん]が安[やす]くなるインセンティブがあるので、電気自動車[でんきじどうしゃ]が売[う]れています。", "sentence_source": "generated"}, {"text": "店はインセンティブを出して、客に早めの予約を促しました。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "店[みせ]はインセンティブを出[だ]して、客[きゃく]に早[はや]めの予約[よやく]を促[うなが]しました。", "sentence_source": "generated"}, {"text": "インセンティブがあっても、仕事の内容が合わなければ続きません。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "インセンティブがあっても、仕事[しごと]の内容[ないよう]が合[あ]わなければ続[つづ]きません。", "sentence_source": "generated"}, {"text": "社員の行動を変えるには、適切なインセンティブが必要です。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "社員[しゃいん]の行動[こうどう]を変[か]えるには、適切[てきせつ]なインセンティブが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "営業部では、月ごとにインセンティブが支給されます。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "営業部[えいぎょうぶ]では、月[つき]ごとにインセンティブが支給[しきゅう]されます。", "sentence_source": "generated"}, {"text": "研究者にとって、お金より自由な時間が大きなインセンティブになります。", "target_word": "インセンティブ", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]にとって、お金[かね]より自由[じゆう]な時間[じかん]が大[おお]きなインセンティブになります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インセンティブ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "特定の行動を促すために外から与えられる報酬や刺激", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インセンティブ", "is_correct": true, "explanation": "「社員にインセンティブを支払う」は、成果に応じた報酬を渡すという意味で文に合う。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "「社員に歯ブラシを支払う」は意味が通らず、報酬の文脈に合わない。"}, {"text": "玄関", "is_correct": false, "explanation": "「社員に玄関を支払う」は意味が通らず、売り上げの話とも結びつかない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「社員に冷蔵庫を支払う」は、売り上げに応じた支払いとして成立しない。"}], "explanations": {"インセンティブ": "「社員にインセンティブを支払う」は、成果に応じた報酬を渡すという意味で文に合う。", "歯ブラシ": "「社員に歯ブラシを支払う」は意味が通らず、報酬の文脈に合わない。", "玄関": "「社員に玄関を支払う」は意味が通らず、売り上げの話とも結びつかない。", "冷蔵庫": "「社員に冷蔵庫を支払う」は、売り上げに応じた支払いとして成立しない。"}, "sentence_index": 0, "correct_answer": "インセンティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末はインセンティブに参加して、地域の掃除をしました。", "explanation": "ここは〈ボランティア〉の意味。参加するのは活動であり、報酬の意味のインセンティブは参加する対象にならない。"}, {"text": "プリンターのインセンティブが切れたので、新しいものを買いました。", "explanation": "ここは〈インク〉の意味。切れるのはインクで、報酬のインセンティブは切れる対象にならない。"}, {"text": "部屋のインセンティブを変えて、明るくした。", "explanation": "ここは〈インテリア〉の意味。部屋を飾る品物を変える文で、報酬のインセンティブは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インセンティブ", "is_correct": true, "explanation": "「インセンティブがあっても」は、報酬という条件があっても、の意味で文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井があっても、仕事は続かない」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気があっても、仕事の内容が合わない」の話にはならず、文脈に合わない。"}, {"text": "ネクタイ", "is_correct": false, "explanation": "「ネクタイがあっても、仕事が続くかどうか」の条件にはならない。"}], "explanations": {"インセンティブ": "「インセンティブがあっても」は、報酬という条件があっても、の意味で文に合う。", "天井": "「天井があっても、仕事は続かない」は意味が通らない。", "天気": "「天気があっても、仕事の内容が合わない」の話にはならず、文脈に合わない。", "ネクタイ": "「ネクタイがあっても、仕事が続くかどうか」の条件にはならない。"}, "sentence_index": 6, "correct_answer": "インセンティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家は夜中にインセンティブが浮かぶことがあります。", "explanation": "ここは〈インスピレーション〉の意味。浮かぶのはひらめきで、報酬のインセンティブは浮かばない。"}, {"text": "玄関でインセンティブが鳴ったので、ドアを開けた。", "explanation": "ここは〈インターホン〉の意味。鳴るのは呼び出しの機器で、報酬のインセンティブは鳴らない。"}, {"text": "今日はインセンティブが遅くて困った。", "explanation": "ここは〈インターネット〉の意味。遅いのは回線の速さで、報酬のインセンティブは速さを問われない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "給料を上げるより、インセンティブに工夫するほうが効果的です。", "corrected_sentence": "給料を上げるより、インセンティブを工夫するほうが効果的です。", "error_description": "「工夫する」の対象は「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39183, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社員は月ごとにインセンティブが受け取ります。", "corrected_sentence": "社員は月ごとにインセンティブを受け取ります。", "error_description": "「受け取る」の対象は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
