INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39184, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "いろいろ考えたあとで、最後にそうなること。", "primary_collocate": null, "pronunciation": "けっきょく", "ipa": "kekkʲoku", "syllable_count": 4, "sentences": [{"text": "いろいろ迷いましたが、結局、赤いかばんを買いました。", "target_word": "結局", "complexity_tier": "T3", "furigana": "いろいろ迷[まよ]いましたが、結局[けっきょく]、赤[あか]いかばんを買[か]いました。", "sentence_source": "generated"}, {"text": "結局、雨が強くなって、旅行は中止になりました。", "target_word": "結局", "complexity_tier": "T3", "furigana": "結局[けっきょく]、雨[あめ]が強[つよ]くなって、旅行[りょこう]は中止[ちゅうし]になりました。", "sentence_source": "generated"}, {"text": "何度も相談したけれど、結局、自分で決めました。", "target_word": "結局", "complexity_tier": "T3", "furigana": "何度[なんど]も相談[そうだん]したけれど、結局[けっきょく]、自分[じぶん]で決[き]めました。", "sentence_source": "generated"}, {"text": "結局、あの映画は見に行かないことにした。", "target_word": "結局", "complexity_tier": "T3", "furigana": "結局[けっきょく]、あの映画[えいが]は見[み]に行[い]かないことにした。", "sentence_source": "generated"}, {"text": "長い間考えて、結局、国へ帰ることにしました。", "target_word": "結局", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]考[かんが]えて、結局[けっきょく]、国[くに]へ帰[かえ]ることにしました。", "sentence_source": "generated"}, {"text": "昼まで待ったのに、結局、彼は来ませんでした。", "target_word": "結局", "complexity_tier": "T3", "furigana": "昼[ひる]まで待[ま]ったのに、結局[けっきょく]、彼[かれ]は来[き]ませんでした。", "sentence_source": "generated"}, {"text": "あちこち探して、結局、鍵は机の上にあった。", "target_word": "結局", "complexity_tier": "T3", "furigana": "あちこち探[さが]して、結局[けっきょく]、鍵[かぎ]は机[つくえ]の上[うえ]にあった。", "sentence_source": "generated"}, {"text": "悩んだ末、結局、母に本当のことを話した。", "target_word": "結局", "complexity_tier": "T3", "furigana": "悩[なや]んだ末[すえ]、結局[けっきょく]、母[はは]に本当[ほんとう]のことを話[はな]した。", "sentence_source": "generated"}, {"text": "安い店を回ったが、結局、最初の店が一番安かった。", "target_word": "結局", "complexity_tier": "T3", "furigana": "安[やす]い店[みせ]を回[まわ]ったが、結局[けっきょく]、最初[さいしょ]の店[みせ]が一番[いちばん]安[やす]かった。", "sentence_source": "generated"}, {"text": "結局、私たちは家で静かに過ごすことにした。", "target_word": "結局", "complexity_tier": "T3", "furigana": "結局[けっきょく]、私[わたし]たちは家[いえ]で静[しず]かに過[す]ごすことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結局", "label": "基本形"}], "register": "中立", "sense_fingerprint": "あれこれのあげく最後にそうなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb283b17-20b7-4256-8fec-2876a22e66e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結局", "is_correct": true, "explanation": "迷ったあとに最後にそうなったことを表す副詞で、「迷いましたが、結局、買いました」の流れに合う。"}, {"text": "たとえば", "is_correct": false, "explanation": "例を挙げる語。迷ったあとの結果を述べる文には合わない。"}, {"text": "ずっと", "is_correct": false, "explanation": "長く続く様子を表す。「迷いながらずっと買いました」は意味が通らない。"}, {"text": "同時に", "is_correct": false, "explanation": "同じ時であることを表す。迷ったあとの結果という流れに合わない。"}], "explanations": {"結局": "迷ったあとに最後にそうなったことを表す副詞で、「迷いましたが、結局、買いました」の流れに合う。", "たとえば": "例を挙げる語。迷ったあとの結果を述べる文には合わない。", "ずっと": "長く続く様子を表す。「迷いながらずっと買いました」は意味が通らない。", "同時に": "同じ時であることを表す。迷ったあとの結果という流れに合わない。"}, "sentence_index": 0, "correct_answer": "結局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の結局は来月に発表される予定です。", "explanation": "ここは名詞の〈最終的な結論〉の意味。今回の定義は副詞の〈迷ったあげく最後に〉なので、名詞の使い方として合わない。"}, {"text": "初めて会った瞬間、結局友だちになった。", "explanation": "ここは〈さっそく・すぐに〉の意味で使っているが、結局は長い経過の末に行き着く結果を表す。一瞬の出会いには合わない。"}, {"text": "裁判官は結局を下した。", "explanation": "ここは名詞の〈結論〉の使い方。結論なら「下す」と続くが、今回の定義は副詞の〈迷ったあげく最後に〉なので、副詞としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結局", "is_correct": true, "explanation": "最後にそうなった結果を表す副詞。探したあげく鍵が見つかった流れに合う。"}, {"text": "一気に", "is_correct": false, "explanation": "一度に行う様子を表す。鍵の場所を述べる文には合わない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "はっきり決める様子を表す。場所を示す文には合わない。"}, {"text": "せっせと", "is_correct": false, "explanation": "熱心に励む様子を表す。「鍵は机の上にあった」と続かない。"}], "explanations": {"結局": "最後にそうなった結果を表す副詞。探したあげく鍵が見つかった流れに合う。", "一気に": "一度に行う様子を表す。鍵の場所を述べる文には合わない。", "きっぱり": "はっきり決める様子を表す。場所を示す文には合わない。", "せっせと": "熱心に励む様子を表す。「鍵は机の上にあった」と続かない。"}, "sentence_index": 6, "correct_answer": "結局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この物語の結局は、とても悲しい。", "explanation": "ここは〈結末〉の意味。結末は物語の終わりを指すが、結局は迷ったあとの結果を表す副詞なので、この名詞的な使い方は合わない。"}, {"text": "結局を見て作戦を判断した。", "explanation": "ここは〈大局〉の意味。大局は全体の状況を見ることを指すが、結局は最終的な結果を表すので、全体を見渡す文には合わない。"}, {"text": "試合の結局は、三対一でした。", "explanation": "名詞の〈結果・結論〉の意味。副詞の結局（迷ったあげく）とは別の使い方で、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "結局が、雨が降ったので家で過ごしました。", "corrected_sentence": "結局は、雨が降ったので家で過ごしました。", "error_description": "誤りは「結局」に続く助詞。正しくは「は」で、「が」は主語を示すため副詞の「結局」には続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "結局の、彼女が来なかったと分かりました。", "corrected_sentence": "結局は、彼女が来なかったと分かりました。", "error_description": "誤りは「結局」に続く助詞。正しくは「は」で話題を示す。「の」では続かず、文が成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddd5e03f-556d-4aef-8eea-1c8a277d9572') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
