INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39186, 3, 'prompt1_core', '{"pos": "代名詞", "semantic_class": "function", "definition": "自分の意志で、人に促されずに行うさま。", "primary_collocate": null, "pronunciation": "みずから", "ipa": "mizɯkaɾa", "syllable_count": 4, "sentences": [{"text": "彼は自らの失敗を認めた。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "彼(かれ)は自(みずか)らの失敗(しっぱい)を認(みと)めた。", "sentence_source": "generated"}, {"text": "自らを守るために、情報を集めた。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "自(みずか)らを守(まも)るために、情報(じょうほう)を集(あつ)めた。", "sentence_source": "generated"}, {"text": "社長は自ら現場へ行って、話を聞いた。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "社長(しゃちょう)は自(みずか)ら現場(げんば)へ行(い)って、話(はなし)を聞(き)いた。", "sentence_source": "generated"}, {"text": "自らの力で道を切り開きたい。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "自(みずか)らの力(ちから)で道(みち)を切(き)り開(ひら)きたい。", "sentence_source": "generated"}, {"text": "失敗したときは、まず自らを責めがちだ。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "失敗(しっぱい)したときは、まず自(みずか)らを責(せ)めがちだ。", "sentence_source": "generated"}, {"text": "彼女は自らの意見をはっきり述べた。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は自(みずか)らの意見(いけん)をはっきり述(の)べた。", "sentence_source": "generated"}, {"text": "自ら選んだ道なので、後悔はしない。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "自(みずか)ら選(えら)んだ道(みち)なので、後悔(こうかい)はしない。", "sentence_source": "generated"}, {"text": "王は自ら兵を率いて城を出た。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "王(おう)は自(みずか)ら兵(へい)を率(ひき)いて城(しろ)を出(で)た。", "sentence_source": "generated"}, {"text": "自らの経験を、後輩に話した。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "自(みずか)らの経験(けいけん)を、後輩(こうはい)に話(はな)した。", "sentence_source": "generated"}, {"text": "人に頼らず、自ら考えて行動しなさい。", "target_word": "自ら", "complexity_tier": "T3", "furigana": "人(ひと)に頼(たよ)らず、自(みずか)ら考(かんが)えて行動(こうどう)しなさい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自ら", "label": "基本形"}, {"form": "自らの", "label": "連体形"}, {"form": "自らを", "label": "目的格"}], "register": "文章語", "sense_fingerprint": "自分自身を指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 切り開き (Zipf 2.45)']::text[], 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39186, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自ら", "is_correct": true, "explanation": "文中の形。「彼は自らの失敗を認めた」で、本人が自分の失敗を認めた意味が自然。"}, {"text": "これ", "is_correct": false, "explanation": "「これの失敗を認めた」は指示語の使い方として不自然で、人の行為を述べる文に合わない。"}, {"text": "あれ", "is_correct": false, "explanation": "「あれの失敗を認めた」は指す対象が曖昧で、本人の失敗を認めた文として成り立たない。"}, {"text": "そこ", "is_correct": false, "explanation": "「そこの失敗を認めた」は場所を指す語で、人の失敗の話には合わない。"}], "explanations": {"自ら": "文中の形。「彼は自らの失敗を認めた」で、本人が自分の失敗を認めた意味が自然。", "これ": "「これの失敗を認めた」は指示語の使い方として不自然で、人の行為を述べる文に合わない。", "あれ": "「あれの失敗を認めた」は指す対象が曖昧で、本人の失敗を認めた文として成り立たない。", "そこ": "「そこの失敗を認めた」は場所を指す語で、人の失敗の話には合わない。"}, "sentence_index": 0, "correct_answer": "自ら"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間がたてば、傷は自ら治る。", "explanation": "ここは〈自然に〉の場面。〈自ら〉は意志を持つ人が自分から行う意味で、傷のように自然に変化するものには合わない。"}, {"text": "彼は自ら参加させられた。", "explanation": "ここは〈無理やり〉の場面。強いられた行為には、自分の意志でという〈自ら〉の意味が合わない。"}, {"text": "この本は自ら読みやすい。", "explanation": "ここは〈もともと〉の場面。読みやすさは本の性質で、本人の意志を表す〈自ら〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39186, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自ら", "is_correct": true, "explanation": "文中の形。「自ら選んだ道なので」で、本人が自分で選んだ意味が自然。"}, {"text": "私", "is_correct": false, "explanation": "「私選んだ道なので」は助詞がなく、文として成り立たない。"}, {"text": "彼", "is_correct": false, "explanation": "「彼選んだ道なので」は助詞がなく、主語も示せず文として通らない。"}, {"text": "君", "is_correct": false, "explanation": "「君選んだ道なので」は助詞がなく、文の骨組みが成り立たない。"}], "explanations": {"自ら": "文中の形。「自ら選んだ道なので」で、本人が自分で選んだ意味が自然。", "私": "「私選んだ道なので」は助詞がなく、文として成り立たない。", "彼": "「彼選んだ道なので」は助詞がなく、主語も示せず文として通らない。", "君": "「君選んだ道なので」は助詞がなく、文の骨組みが成り立たない。"}, "sentence_index": 6, "correct_answer": "自ら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の前で、彼は自ら昔の友人に会った。", "explanation": "ここは〈たまたま〉の場面。出会いは偶然なので、本人の意志を表す〈自ら〉とは合わない。"}, {"text": "雨が降ってきたので、彼は自ら傘を借りてもらった。", "explanation": "ここは〈してもらう〉の場面。自分の意志で行う〈自ら〉と、人に世話をされる文は両立しない。"}, {"text": "彼は風邪をひいて、自ら熱を出した。", "explanation": "ここは〈発症する〉の場面。病気になるのは本人の意志ではないため、〈自ら〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39186, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は自らを過ちを素直に認めた。", "corrected_sentence": "彼女は自らの過ちを素直に認めた。", "error_description": "「自らの過ち」の「の」を「を」に変えると、目的語が二つ続いて文が成り立たない。「自らの」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39186, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は自らな意志で、留学先を選んだ。", "corrected_sentence": "彼は自らの意志で、留学先を選んだ。", "error_description": "「自らな」の「な」は誤り。名詞「意志」を修飾するには「自らの」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「因果があると」で、因果が主語として存在を表す。文の骨組みに合う。"}, {"text": "を", "is_correct": false, "explanation": "目的格の助詞。「因果を〜にある」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の助詞。「因果で言われている」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。「因果へある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「因果があると」で、因果が主語として存在を表す。文の骨組みに合う。", "を": "目的格の助詞。「因果を〜にある」は文が成り立たない。", "で": "手段・場所の助詞。「因果で言われている」は意味が通らない。", "へ": "方向の助詞。「因果へある」は意味が通らない。"}, "error_tags": {"を": "目的格の助詞。「因果を〜にある」は文が成り立たない", "で": "手段・場所の助詞。「因果で言われている」は意味が通らない", "へ": "方向の助詞。「因果へある」は意味が通らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「因果があるとは言い切れない」で、因果が存在する主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "場所・時の助詞。「間に」を入れ替えると文の骨組みが崩れる。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。「より〜あるとは」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞。「因果から〜あるとは」は主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「因果があるとは言い切れない」で、因果が存在する主語を示す。", "に": "場所・時の助詞。「間に」を入れ替えると文の骨組みが崩れる。", "より": "比較の助詞。「より〜あるとは」は意味が通らない。", "から": "起点の助詞。「因果から〜あるとは」は主語として成り立たない。"}, "error_tags": {"に": "場所・時の助詞。「間に」を入れ替えると文の骨組みが崩れる", "より": "比較の助詞。「より〜あるとは」は意味が通らない", "から": "起点の助詞。「因果から〜あるとは」は主語として成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが別のことを引き起こすという、そのつながりのこと。", "primary_collocate": null, "pronunciation": "いんが", "ipa": "iŋɡa", "syllable_count": 3, "sentences": [{"text": "二つの出来事の因果を調べました。", "target_word": "因果", "complexity_tier": "T3", "furigana": "二[ふた]つの出来事[できごと]の因果[いんが]を調[しら]べました。", "sentence_source": "generated"}, {"text": "運動と健康のあいだには、因果があると言われている。", "target_word": "因果", "complexity_tier": "T3", "furigana": "運動と健康のあいだには、[因果|いんが]があると言われている。", "sentence_source": "generated"}, {"text": "事故の因果は、まだはっきりしていない。", "target_word": "因果", "complexity_tier": "T3", "furigana": "事故[じこ]の因果[いんが]は、まだはっきりしていない。", "sentence_source": "generated"}, {"text": "この薬と病気の回復に、因果があるかどうかを調べた。", "target_word": "因果", "complexity_tier": "T3", "furigana": "この薬[くすり]と病気[びょうき]の回復[かいふく]に、因果[いんが]があるかどうかを調[しら]べた。", "sentence_source": "generated"}, {"text": "科学者は、雨と洪水の因果を説明した。", "target_word": "因果", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、雨[あめ]と洪水[こうずい]の因果[いんが]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "睡眠不足と失敗の因果は、だれでもわかる。", "target_word": "因果", "complexity_tier": "T3", "furigana": "睡眠[すいみん]不足[ぶそく]と失敗[しっぱい]の因果[いんが]は、だれでもわかる。", "sentence_source": "generated"}, {"text": "因果がわからないと、問題は直せない。", "target_word": "因果", "complexity_tier": "T3", "furigana": "因果[いんが]がわからないと、問題[もんだい]は直[なお]せない。", "sentence_source": "generated"}, {"text": "努力と成功の間に、因果があるとは言い切れない。", "target_word": "因果", "complexity_tier": "T3", "furigana": "努力[どりょく]と成功[せいこう]の間[あいだ]に、因果[いんが]があるとは言[い]い切[き]れない。", "sentence_source": "generated"}, {"text": "二つの事件に因果はないと、警察は考えている。", "target_word": "因果", "complexity_tier": "T3", "furigana": "二[ふた]つの事件[じけん]に因果[いんが]はないと、警察[けいさつ]は考[かんが]えている。", "sentence_source": "generated"}, {"text": "原因を探して、因果をたどってみよう。", "target_word": "因果", "complexity_tier": "T3", "furigana": "原因[げんいん]を探[さが]して、因果[いんが]をたどってみよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "因果", "label": "基本形"}, {"form": "因果が", "label": "主格"}, {"form": "因果を", "label": "目的格"}, {"form": "因果の", "label": "連体"}], "register": "formal", "sense_fingerprint": "一つの事が別の事を引き起こすつながり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因果", "is_correct": true, "explanation": "「二つの出来事の因果を調べる」は原因と結果のつながりを調べる意味で合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹を調べる」は意味が通らない。空腹は調べる対象ではない。"}, {"text": "満足", "is_correct": false, "explanation": "「満足を調べる」は自然な言い方ではなく、出来事の関係を述べる文には合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息を調べる」は出来事の関係の文に合わない。"}], "explanations": {"因果": "「二つの出来事の因果を調べる」は原因と結果のつながりを調べる意味で合う。", "空腹": "「空腹を調べる」は意味が通らない。空腹は調べる対象ではない。", "満足": "「満足を調べる」は自然な言い方ではなく、出来事の関係を述べる文には合わない。", "寝息": "「寝息を調べる」は出来事の関係の文に合わない。"}, "sentence_index": 0, "correct_answer": "因果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちとの因果が切れて、部屋で泣いた。", "explanation": "ここでは人どうしの縁の意味になり、原因と結果のつながりとしての「因果」ではない。"}, {"text": "この店の因果は、料理がおいしいことだ。", "explanation": "料理のおいしさは良い点であり、原因と結果のつながりを指す「因果」とは合わない。"}, {"text": "彼女は、毎朝の因果をきちんと守っている。", "explanation": "「因果」は決まりごとや規則を指す語ではないので、「守る」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因果", "is_correct": true, "explanation": "「因果がわからないと、問題は直せない」は原因と結果のつながりを指すので、「因果」が入る。"}, {"text": "好物", "is_correct": false, "explanation": "「好物がわからないと」は問題を直す文脈と結びつかない。"}, {"text": "雑音", "is_correct": false, "explanation": "「雑音がわからないと」は意味が通らない。"}, {"text": "花粉", "is_correct": false, "explanation": "「花粉がわからないと」は問題を直す文脈と合わない。"}], "explanations": {"因果": "「因果がわからないと、問題は直せない」は原因と結果のつながりを指すので、「因果」が入る。", "好物": "「好物がわからないと」は問題を直す文脈と結びつかない。", "雑音": "「雑音がわからないと」は意味が通らない。", "花粉": "「花粉がわからないと」は問題を直す文脈と合わない。"}, "sentence_index": 6, "correct_answer": "因果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "原因を探して、因果を捨ててみよう。", "explanation": "ここは「因縁」の意味。「因縁を断つ」とは言えても、原因と結果のつながりとしての「因果」は捨てられない。"}, {"text": "原因を探して、因果を数えてみよう。", "explanation": "「数える」は「例」「回数」など数えられる物に使う。因果は数えられない抽象的なつながりなので、ここでは合わない。"}, {"text": "原因を探して、因果を飲んでみよう。", "explanation": "ここは「薬」の意味で言う語が要る。「飲む」は薬や液体に使い、因果は飲めない抽象的なつながりなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の原因を調べる前に、因果が確かめた。", "corrected_sentence": "事故の原因を調べる前に、因果を確かめた。", "error_description": "「確かめる」は他動詞で、「因果」は目的語の「を」が必要。「が」は主語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39188, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "因果が理解しないと、問題は直せない。", "corrected_sentence": "因果を理解しないと、問題は直せない。", "error_description": "「理解する」は他動詞で、「因果」は目的語の「を」が必要。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈考える〉の目的語は〈を〉。〈因果を考える〉で、出来事の因果関係について考える意味になる。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉だと因果が主語になり、「因果が考えること」は不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉では「因果に考える」となり、考える対象を示す形として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すが、「因果へ考える」は対象を示せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "〈考える〉の目的語は〈を〉。〈因果を考える〉で、出来事の因果関係について考える意味になる。", "が": "〈が〉だと因果が主語になり、「因果が考えること」は不自然になる。", "に": "〈に〉では「因果に考える」となり、考える対象を示す形として成り立たない。", "へ": "〈へ〉は方向を表すが、「因果へ考える」は対象を示せず文が成り立たない。"}, "error_tags": {"が": "subject", "に": "wrong_case", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈説明する〉の目的語は〈を〉。〈事件の因果を説明する〉で、事件の原因と結果を話す意味になる。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉では名詞同士をつなぐだけで、「事件の因果の、順番に説明した」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や引用を表すが、「事件の因果と、順番に説明した」は説明の対象を示せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を表すため、「事件の因果より説明した」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "〈説明する〉の目的語は〈を〉。〈事件の因果を説明する〉で、事件の原因と結果を話す意味になる。", "の": "〈の〉では名詞同士をつなぐだけで、「事件の因果の、順番に説明した」は文として成り立たない。", "と": "〈と〉は並列や引用を表すが、「事件の因果と、順番に説明した」は説明の対象を示せず不自然。", "より": "〈より〉は比較を表すため、「事件の因果より説明した」は意味が通らない。"}, "error_tags": {"の": "genitive", "と": "coordination", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "原因と結果の関係。ある物事が他の物事を生み出す、その結びつき。", "primary_collocate": null, "pronunciation": "いんが", "ipa": "iŋɡa", "syllable_count": 3, "sentences": [{"text": "事故の因果を、図で表した。", "target_word": "因果", "complexity_tier": "T3", "furigana": "事故の因果《いんが》を、図で表した。", "sentence_source": "generated"}, {"text": "歴史の勉強では、出来事の因果を考えることが大切だ。", "target_word": "因果", "complexity_tier": "T3", "furigana": "歴史[れきし]の勉強[べんきょう]では、出来事[できごと]の因果[いんが]を考[かんが]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "悪い食事と病気の因果は、研究で示された。", "target_word": "因果", "complexity_tier": "T3", "furigana": "悪[わる]い食事[しょくじ]と病気[びょうき]の因果[いんが]は、研究[けんきゅう]で示[しめ]された。", "sentence_source": "generated"}, {"text": "この小説は、人の行いの因果を描いている。", "target_word": "因果", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、人[ひと]の行[おこな]いの因果[いんが]を描[えが]いている。", "sentence_source": "generated"}, {"text": "値上げと客の減少に因果があるとは限らない。", "target_word": "因果", "complexity_tier": "T3", "furigana": "値上[ねあ]げと客[きゃく]の減少[げんしょう]に因果[いんが]があるとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "因果を知れば、同じ失敗は防げる。", "target_word": "因果", "complexity_tier": "T3", "furigana": "因果[いんが]を知[し]れば、同[おな]じ失敗[しっぱい]は防[ふせ]げる。", "sentence_source": "generated"}, {"text": "偶然か因果か、まだ判断できない。", "target_word": "因果", "complexity_tier": "T3", "furigana": "偶然[ぐうぜん]か因果[いんが]か、まだ判断[はんだん]できない。", "sentence_source": "generated"}, {"text": "彼は事件の因果を、順番に説明した。", "target_word": "因果", "complexity_tier": "T3", "furigana": "彼[かれ]は事件[じけん]の因果[いんが]を、順番[じゅんばん]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "気温と売り上げの因果を調べる授業を受けた。", "target_word": "因果", "complexity_tier": "T3", "furigana": "気温[きおん]と売[う]り上[あ]げの因果[いんが]を調[しら]べる授業[じゅぎょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "ものごとの因果を考える習慣が、彼を成長させた。", "target_word": "因果", "complexity_tier": "T3", "furigana": "ものごとの因果[いんが]を考[かんが]える習慣[しゅうかん]が、彼[かれ]を成長[せいちょう]させた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "因果", "label": "基本形"}, {"form": "因果が", "label": "主格"}, {"form": "因果を", "label": "目的格"}, {"form": "因果の", "label": "連体"}], "register": "formal", "sense_fingerprint": "原因と結果の関係、物事を生み出す結びつき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因果", "is_correct": true, "explanation": "「事故の因果」は事故の原因と結果の関係を指し、図で表す対象として合う。"}, {"text": "性格", "is_correct": false, "explanation": "性格は人の気質を表す語で、「事故の性格を図で表した」は意味が通らない。"}, {"text": "期待", "is_correct": false, "explanation": "期待は将来への望みを表す語で、事故の関係を図にするという文脈に合わない。"}, {"text": "習慣", "is_correct": false, "explanation": "習慣は繰り返される行動の型で、「事故の習慣を図で表した」は不自然で原因と結果の関係を指さない。"}], "explanations": {"因果": "「事故の因果」は事故の原因と結果の関係を指し、図で表す対象として合う。", "性格": "性格は人の気質を表す語で、「事故の性格を図で表した」は意味が通らない。", "期待": "期待は将来への望みを表す語で、事故の関係を図にするという文脈に合わない。", "習慣": "習慣は繰り返される行動の型で、「事故の習慣を図で表した」は不自然で原因と結果の関係を指さない。"}, "sentence_index": 0, "correct_answer": "因果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の因果は、九州の小さな村だ。", "explanation": "ここは〈出身〉の意味。因果は原因と結果の関係で、人の出身地は指さない。"}, {"text": "この金属は因果が硬く、加工しにくい。", "explanation": "ここは〈性質〉の意味。因果は原因と結果の結びつきで、金属の硬さなどの性質は指さない。"}, {"text": "この映画の因果は、とても悲しかった。", "explanation": "ここは〈結末〉の意味。因果は原因と結果の関係で、物語の終わり方は結末と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因果", "is_correct": true, "explanation": "「偶然か因果か」は、偶然か原因と結果の関係かを問う並びで、正しく成り立つ。"}, {"text": "名誉", "is_correct": false, "explanation": "名誉は人の評価や誉れを表す語で、偶然との対比として判断の対象にならない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は色合いを表す語で、偶然との対比として判断の対象にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生物が生きられる期間を表す語で、「偶然か寿命か」という並べ方は意味をなさない。"}], "explanations": {"因果": "「偶然か因果か」は、偶然か原因と結果の関係かを問う並びで、正しく成り立つ。", "名誉": "名誉は人の評価や誉れを表す語で、偶然との対比として判断の対象にならない。", "色彩": "色彩は色合いを表す語で、偶然との対比として判断の対象にならない。", "寿命": "寿命は生物が生きられる期間を表す語で、「偶然か寿命か」という並べ方は意味をなさない。"}, "sentence_index": 6, "correct_answer": "因果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この二人は良好な因果を保っている。", "explanation": "ここは〈関係〉の意味。因果は原因と結果の結びつきを指し、人同士の良好な関係とは言わない。"}, {"text": "この機械は因果が優れていて、使いやすい。", "explanation": "ここは〈機能〉の意味。因果は結びつきを表す語で、機械のはたらきの優劣には使わない。"}, {"text": "試験の因果が、今日発表された。", "explanation": "ここは〈結果〉の意味。因果は原因と結果の関係そのもので、発表される試験の結果は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの現象の因果に調べるのが研究の目的だ。", "corrected_sentence": "二つの現象の因果を調べるのが研究の目的だ。", "error_description": "〈調べる〉の目的語は〈を〉。〈因果に〉では助詞が誤りで、正しくは〈因果を〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39189, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新薬の効果と副作用の因果を、医師が数えた。", "corrected_sentence": "新薬の効果と副作用の因果を、医師が説明した。", "error_description": "〈因果〉は数えるものではなく説明するもの。〈数えた〉は〈説明した〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野蛮", "is_correct": true, "explanation": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す"}, {"text": "都会", "is_correct": false, "explanation": "「田舎」の対義語で、文明の対義語ではない"}, {"text": "芸術", "is_correct": false, "explanation": "文明と対をなす語として辞書に挙がらないので不適"}, {"text": "民族", "is_correct": false, "explanation": "人々の集団を指す語で、文明と対になる語ではない"}], "correct_answer": "野蛮", "explanations": {"野蛮": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す", "都会": "「田舎」の対義語で、文明の対義語ではない", "芸術": "文明と対をなす語として辞書に挙がらないので不適", "民族": "人々の集団を指す語で、文明と対になる語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野蛮", "is_correct": true, "explanation": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す"}, {"text": "田舎", "is_correct": false, "explanation": "「都会」の対義語で、文明の対義語ではない"}, {"text": "伝統", "is_correct": false, "explanation": "「革新」の対義語で、文明と対になる語ではない"}, {"text": "方言", "is_correct": false, "explanation": "地域の言葉を指し、文明の対義語としては挙がらない"}], "correct_answer": "野蛮", "explanations": {"野蛮": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す", "田舎": "「都会」の対義語で、文明の対義語ではない", "伝統": "「革新」の対義語で、文明と対になる語ではない", "方言": "地域の言葉を指し、文明の対義語としては挙がらない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間の生活や文化が進んで、とても便利で複雑になった社会のしくみのことです。", "primary_collocate": null, "pronunciation": "ぶんめい", "ipa": "bɯmmeː", "syllable_count": 4, "sentences": [{"text": "文明が発達すると、人の暮らしは便利になる。", "target_word": "文明", "complexity_tier": "T2", "furigana": "ぶんめいがはったつすると、ひとのくらしはべんりになる。", "sentence_source": "generated"}, {"text": "学校の授業で、人類最初の文明について習った。", "target_word": "文明", "complexity_tier": "T3", "furigana": "がっこうのじゅぎょうで、じんるいさいしょのぶんめいについてならった。", "sentence_source": "generated"}, {"text": "古い文明の遺跡を見に、家族でペルーへ行きたい。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ふるいぶんめいのいせきをみに、かぞくでペルーへいきたい。", "sentence_source": "generated"}, {"text": "文明の進歩のおかげで、私たちは遠くの人とすぐに話せる。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ぶんめいのしんぽのおかげで、わたしたちはとおくのひととすぐにはなせる。", "sentence_source": "generated"}, {"text": "昔の文明は、大きな川の近くで生まれることが多かった。", "target_word": "文明", "complexity_tier": "T3", "furigana": "むかしのぶんめいは、おおきなかわのちかくでうまれることがおおかった。", "sentence_source": "generated"}, {"text": "便利な機械が増えるのは、文明が進んだ結果だ。", "target_word": "文明", "complexity_tier": "T3", "furigana": "べんりなきかいがふえるのは、ぶんめいがすすんだけっかだ。", "sentence_source": "generated"}, {"text": "祖父は「文明の利器に頼りすぎるな」とよく言う。", "target_word": "文明", "complexity_tier": "T3", "furigana": "そふは「ぶんめいのりきにたよりすぎるな」とよくいう。", "sentence_source": "generated"}, {"text": "島の人々は、都会の文明とは離れた静かな生活を送っている。", "target_word": "文明", "complexity_tier": "T3", "furigana": "しまのひとびとは、とかいのぶんめいとははなれたしずかなせいかつをおくっている。", "sentence_source": "generated"}, {"text": "この本は、マヤの文明の人々の暮らしをやさしく説明している。", "target_word": "文明", "complexity_tier": "T3", "furigana": "このほんは、マヤのぶんめいのひとびとのくらしをやさしくせつめいしている。", "sentence_source": "generated"}, {"text": "文明が栄えた町も、水がなくなると人が去ってしまった。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ぶんめいがさかえたまちも、みずがなくなるとひとがさってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文明", "label": "基本形"}], "register": "標準・中立", "sense_fingerprint": "生活や文化が進み便利で複雑になった社会のしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "「文明が発達すると」の文明。生活や文化が進んだ社会のしくみを指し、文脈に合う"}, {"text": "季節", "is_correct": false, "explanation": "「季節が発達する」とは言わず、空所に入らない"}, {"text": "身長", "is_correct": false, "explanation": "人の背丈を指し、「身長が発達する」とは言えない"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを指し、「体重が発達する」と続けられない"}], "explanations": {"文明": "「文明が発達すると」の文明。生活や文化が進んだ社会のしくみを指し、文脈に合う", "季節": "「季節が発達する」とは言わず、空所に入らない", "身長": "人の背丈を指し、「身長が発達する」とは言えない", "体重": "体の重さを指し、「体重が発達する」と続けられない"}, "sentence_index": 0, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この犬は文明の性格がおとなしくて、人によく懐く。", "explanation": "ここは〈性格〉の意味。文明は社会のしくみで、犬の性格には使わないので合わない"}, {"text": "この歌は、文明のメロディーがとても美しい。", "explanation": "ここは〈メロディー〉の意味。文明は社会のしくみで、曲の旋律を指さないので合わない"}, {"text": "母は文明を三時間かけて煮込み、家族に出した。", "explanation": "ここは〈料理〉の意味。文明は食べ物ではなく、煮込んだり出したりできないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "「文明の利器」の文明。科学技術や社会の進歩を指し、文脈に合う"}, {"text": "方言", "is_correct": false, "explanation": "地域の言葉を指し、「方言の利器」とは言えない"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指し、「天気の利器」と続けられない"}, {"text": "色彩", "is_correct": false, "explanation": "色の取り合わせを指し、「色彩の利器」とは言わない"}], "explanations": {"文明": "「文明の利器」の文明。科学技術や社会の進歩を指し、文脈に合う", "方言": "地域の言葉を指し、「方言の利器」とは言えない", "天気": "空模様を指し、「天気の利器」と続けられない", "色彩": "色の取り合わせを指し、「色彩の利器」とは言わない"}, "sentence_index": 6, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この文明は、水がなくなると枯れてしまう。", "explanation": "ここは〈植物〉の意味。文明は社会のしくみで、植物が枯れる話には使わないので合わない"}, {"text": "明日の文明は、午後から雨になるでしょう。", "explanation": "ここは〈天気〉の意味。文明は社会の総体で、空模様の予報には使わないので合わない"}, {"text": "この文明は、子どもが読みやすいように、やさしい言葉で書かれている。", "explanation": "ここは〈教科書〉の意味。文明は書物ではないので、書かれているとは言わないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "文明を進んだ社会では、交通網が整っている。", "corrected_sentence": "文明が進んだ社会では、交通網が整っている。", "error_description": "『進む』は自動詞なので主語に『が』を使う。『を』は誤りで、正しくは『文明が進んだ』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39190, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古代の人々は、川のほとりに文明に築いた。", "corrected_sentence": "古代の人々は、川のほとりに文明を築いた。", "error_description": "『築く』の対象は『を』で示す。『に』では目的語が立たず誤り。正しくは『文明を築いた』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野蛮", "is_correct": true, "explanation": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す"}, {"text": "文化", "is_correct": false, "explanation": "文明と近い語で、文明を構成する要素。対義語としては挙がらない"}, {"text": "都会", "is_correct": false, "explanation": "「田舎」の対義語で、文明の対義語ではない"}, {"text": "民族", "is_correct": false, "explanation": "人々の集団を指す語で、文明と対になる語ではない"}], "correct_answer": "野蛮", "explanations": {"野蛮": "「文明」の対義語。文明が進んだ状態に対して、未開で粗野な状態を指す", "文化": "文明と近い語で、文明を構成する要素。対義語としては挙がらない", "都会": "「田舎」の対義語で、文明の対義語ではない", "民族": "人々の集団を指す語で、文明と対になる語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
