INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人間が築いてきた、高度な技術や文化、社会制度などを含む、人間の生活や考え方の総体。", "primary_collocate": null, "pronunciation": "ぶんめい", "ipa": "bɯmmeː", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "文明", "complexity_tier": "T5", "furigana": "かつてはあんていしていたせいたいけいのサイクルが、げんだいぶんめいのけいざいかつどうによってゆがめられ、そのしゅうふくはきわめてこんなんなきょくめんをむかえている。", "sentence_source": "mined"}, {"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "文明", "complexity_tier": "T4", "furigana": "われわれは、このふかぎゃくてきなへんかのれんさをどううけとめるべきか、ぶんめいのそんぞくをかけてばっぽんてきなてんかんをせまられているのである。", "sentence_source": "mined"}, {"text": "古代エジプトの文明は、ナイル川の恵みの上に栄えた。", "target_word": "文明", "complexity_tier": "T3", "furigana": "こだいエジプトのぶんめいは、ナイルがわのめぐみのうえにさかえた。", "sentence_source": "generated"}, {"text": "文明が進むにつれて、人々の暮らしは便利になったが、自然は少しずつ失われていった。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ぶんめいがすすむにつれて、ひとびとのくらしはべんりになったが、しぜんはすこしずつうしなわれていった。", "sentence_source": "generated"}, {"text": "長い歴史をもつ文明が、戦争や気候の変化によって滅びることもある。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ながいれきしをもつぶんめいが、せんそうやきこうのへんかによってほろびることもある。", "sentence_source": "generated"}, {"text": "川のそばで生まれた文明は、農業の発達によって大きく発展した。", "target_word": "文明", "complexity_tier": "T3", "furigana": "かわのそばでうまれたぶんめいは、のうぎょうのはったつによっておおきくはってんした。", "sentence_source": "generated"}, {"text": "遺跡から発掘された土器は、この地に高度な文明があったことを物語っている。", "target_word": "文明", "complexity_tier": "T3", "furigana": "いせきからはっくつされたどきは、このちにこうどなぶんめいがあったことをものがたっている。", "sentence_source": "generated"}, {"text": "現代の文明は電気に頼りきっているため、停電が長く続くと社会が止まってしまう。", "target_word": "文明", "complexity_tier": "T3", "furigana": "げんだいのぶんめいはでんきにたよりきっているため、ていでんがながくつづくとしゃかいがとまってしまう。", "sentence_source": "generated"}, {"text": "異なる文明が出会うとき、そこには交流だけでなく対立も生まれる。", "target_word": "文明", "complexity_tier": "T3", "furigana": "ことなるぶんめいがであうとき、そこにはこうりゅうだけでなくたいりつもうまれる。", "sentence_source": "generated"}, {"text": "博物館で、メソポタミアの文明について書かれた展示を見た。", "target_word": "文明", "complexity_tier": "T3", "furigana": "はくぶつかんで、メソポタミアのぶんめいについてかかれたてんじをみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "文明", "label": "基本形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "技術・文化・制度を含む人間社会の総体としての文明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "「現代文明の経済活動」の文明。社会全体の仕組みを指し、文脈に合う"}, {"text": "言語", "is_correct": false, "explanation": "「現代言語の経済活動」とは言えず、経済活動の修飾にならない"}, {"text": "季節", "is_correct": false, "explanation": "時期を指し、「現代季節の経済活動」と続けられない"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指し、経済活動を修飾する語として成立しない"}], "explanations": {"文明": "「現代文明の経済活動」の文明。社会全体の仕組みを指し、文脈に合う", "言語": "「現代言語の経済活動」とは言えず、経済活動の修飾にならない", "季節": "時期を指し、「現代季節の経済活動」と続けられない", "天気": "空模様を指し、経済活動を修飾する語として成立しない"}, "sentence_index": 0, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は文明が豊富で、パソコンの修理を一人でこなす。", "explanation": "ここは〈技術〉の意味。文明は社会全体の総体で、個人の腕前には使わないので合わない"}, {"text": "この店は文明の品ぞろえが豊富で、地元の客に人気だ。", "explanation": "ここは〈商品〉の意味。文明は社会の総体で、店の品ぞろえには使わないので合わない"}, {"text": "祖母は、長年の文明で漬け物を上手に作る。", "explanation": "ここは〈知恵〉の意味。文明は社会の仕組みで、個人の経験から生まれる知恵には使わないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "「高度な文明があった」の文明。土器が物語る社会の水準として自然"}, {"text": "年齢", "is_correct": false, "explanation": "「高度な年齢」とは言えず、空所に入らない"}, {"text": "身長", "is_correct": false, "explanation": "人の背の高さを指し、「高度な身長」と続けられない"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを指し、「高度な体重」とは言わない"}], "explanations": {"文明": "「高度な文明があった」の文明。土器が物語る社会の水準として自然", "年齢": "「高度な年齢」とは言えず、空所に入らない", "身長": "人の背の高さを指し、「高度な身長」と続けられない", "体重": "体の重さを指し、「高度な体重」とは言わない"}, "sentence_index": 6, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この文明は、使い方を覚えると便利だ。", "explanation": "ここは〈道具〉の意味。文明は社会全体の総体で、個々の道具は指さないので合わない"}, {"text": "この文明は、戦争の悲しさを描いた名作だ。", "explanation": "ここは〈作品〉の意味。文明は社会の総体で、作品として名作と呼ぶものではないので合わない"}, {"text": "この村では、正月に餅をつく文明が今も残っている。", "explanation": "ここは〈風習〉の意味。正月の餅つきのような習わしは風習と言い、文明は社会全体の仕組みや技術の総体を指すので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古代文明に研究するため、現地の遺跡を調べた。", "corrected_sentence": "古代文明を研究するため、現地の遺跡を調べた。", "error_description": "『研究する』の対象は『を』で示す。『に』では目的語が立たず誤り。正しくは『文明を研究する』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39191, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その文明を、大きな川のほとりで栄えた。", "corrected_sentence": "その文明は、大きな川のほとりで栄えた。", "error_description": "『栄える』は自動詞で『を』を取らない。文明は主題の『は』で示し、正しくは『その文明は』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「植える」は目的語に「を」を取るので、苗の直後は「を」になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、植える対象の位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、植える対象を表すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「植える」は目的語に「を」を取るので、苗の直後は「を」になる。", "が": "「が」は主語を示すので、植える対象の位置には入らない。", "へ": "「へ」は方向を示すので、植える対象を表すことはできない。", "より": "「より」は比較を示すので、ここでは意味が通らない。"}, "error_tags": {"が": "主語を表す格助詞の誤り", "へ": "方向を表す格助詞の誤り", "より": "比較を表す格助詞の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「植えない」は目的語に「を」を取るので、野菜の直後は「を」になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、植える対象の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、野菜と植えるという形にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所有や修飾を示すので、目的語の位置には使えない。"}], "correct_answer": "を", "explanations": {"を": "「植えない」は目的語に「を」を取るので、野菜の直後は「を」になる。", "で": "「で」は手段や場所を示すので、植える対象の位置には入らない。", "と": "「と」は相手や並列を示すので、野菜と植えるという形にはならない。", "の": "「の」は所有や修飾を示すので、目的語の位置には使えない。"}, "error_tags": {"で": "手段・場所を表す格助詞の誤り", "と": "相手・並列を表す格助詞の誤り", "の": "所有・修飾を表す格助詞の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "土の中に根を入れて、そこから大きくなるようにする。", "primary_collocate": null, "pronunciation": "うえる", "ipa": "ɯeɾɯ", "syllable_count": 3, "sentences": [{"text": "春になったら、庭にチューリップの球根を植える。", "target_word": "植える", "complexity_tier": "T3", "furigana": "春[はる]になったら、庭[にわ]にチューリップの球根[きゅうこん]を植[う]える。", "sentence_source": "generated"}, {"text": "祖父は毎年、畑にトマトの苗を植えています。", "target_word": "植えて", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎年[まいとし]、畑[はたけ]にトマトの苗[なえ]を植[う]えています。", "sentence_source": "generated"}, {"text": "学校の前に桜の木を植えたので、来年は花が見られる。", "target_word": "植えた", "complexity_tier": "T3", "furigana": "学校[がっこう]の前[まえ]に桜[さくら]の木[き]を植[う]えたので、来年[らいねん]は花[はな]が見[み]られる。", "sentence_source": "generated"}, {"text": "雨の日に木を植えると、根がつきやすい。", "target_word": "植えると", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]に木[き]を植[う]えると、根[ね]がつきやすい。", "sentence_source": "generated"}, {"text": "花の苗を植えて、毎朝水をやっています。", "target_word": "植えて", "complexity_tier": "T3", "furigana": "花[はな]の苗[なえ]を植[う]えて、毎朝[まいあさ]水[みず]をやっています。", "sentence_source": "generated"}, {"text": "海の近くには、風を防ぐために松を植えることが多い。", "target_word": "植える", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くには、風[かぜ]を防[ふせ]ぐために松[まつ]を植[う]えることが多[おお]い。", "sentence_source": "generated"}, {"text": "子どもたちは公園の隅に、ひまわりを植えた。", "target_word": "植えた", "complexity_tier": "T3", "furigana": "子[こ]どもたちは公園[こうえん]の隅[すみ]に、ひまわりを植[う]えた。", "sentence_source": "generated"}, {"text": "日当たりの悪い場所には、野菜を植えないほうがいい。", "target_word": "植えない", "complexity_tier": "T3", "furigana": "日当[ひあ]たりの悪[わる]い場所[ばしょ]には、野菜[やさい]を植[う]えないほうがいい。", "sentence_source": "generated"}, {"text": "土をやわらかくしてから、苗をていねいに植えましょう。", "target_word": "植えましょう", "complexity_tier": "T3", "furigana": "土[つち]をやわらかくしてから、苗[なえ]をていねいに植[う]えましょう。", "sentence_source": "generated"}, {"text": "山に木を植える活動に、友だちと参加した。", "target_word": "植える", "complexity_tier": "T3", "furigana": "山[やま]に木[き]を植[う]える活動[かつどう]に、友[とも]だちと参加[さんか]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植える", "label": "終止形"}, {"form": "植えます", "label": "丁寧形"}, {"form": "植えた", "label": "過去形"}, {"form": "植えて", "label": "て形"}, {"form": "植えない", "label": "否定形"}, {"form": "植えれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "植える=苗・種・木などを土に入れて根づかせ育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植える", "is_correct": true, "explanation": "「土に入れて育てる」の意味。球根を庭に入れるという文に合う。"}, {"text": "咲く", "is_correct": false, "explanation": "花が開く意味で、球根を目的語に取れない。"}, {"text": "飛ばす", "is_correct": false, "explanation": "物を飛ばす意味で、球根を庭に入れる文には合わない。"}, {"text": "折る", "is_correct": false, "explanation": "物を折る意味で、球根を植える文とは意味が合わない。"}], "explanations": {"植える": "「土に入れて育てる」の意味。球根を庭に入れるという文に合う。", "咲く": "花が開く意味で、球根を目的語に取れない。", "飛ばす": "物を飛ばす意味で、球根を庭に入れる文には合わない。", "折る": "物を折る意味で、球根を植える文とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "植える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬が庭に骨を植えた。", "explanation": "ここは〈埋める〉の意味。植えるは苗や種を育てるために土に入れる行為で、物を地中に隠す文には合わない。"}, {"text": "花瓶に花を植えた。", "explanation": "ここは〈差す〉（花を容器に挿す）の意味。植えるは土に根を張らせる行為なので、花瓶の文には合わない。"}, {"text": "蚊が私の腕を植えた。", "explanation": "ここは〈刺す〉の意味。植えるは植物を土に入れて育てることなので、虫が肌を刺す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植えた", "is_correct": true, "explanation": "「土に入れて育てる」の過去形。ひまわりを公園の隅に入れた文に合う。"}, {"text": "歌った", "is_correct": false, "explanation": "声を出す行為を表す。ひまわりを目的語に取れないので文が成り立たない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "大きな声を出す意味で、ひまわりとは結びつかない。"}, {"text": "笑った", "is_correct": false, "explanation": "笑う意味で、目的語の「を」を取らないので文に入らない。"}], "explanations": {"植えた": "「土に入れて育てる」の過去形。ひまわりを公園の隅に入れた文に合う。", "歌った": "声を出す行為を表す。ひまわりを目的語に取れないので文が成り立たない。", "叫んだ": "大きな声を出す意味で、ひまわりとは結びつかない。", "笑った": "笑う意味で、目的語の「を」を取らないので文に入らない。"}, "sentence_index": 6, "correct_answer": "植えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに庭を植えて、池を作った。", "explanation": "ここは〈掘る〉の意味。植えるは苗や種を土に入れる行為で、地面を掘り返す文には合わない。"}, {"text": "壁にポスターを植えた。", "explanation": "ここは〈貼る〉の意味。植えるは植物を土に根づかせる行為で、紙を表面にくっつける文には合わない。"}, {"text": "床に絨毯を植えた。", "explanation": "ここは〈敷く〉の意味。植えるは植物を土に根づかせる行為で、布を床に広げる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑に大根の種に植えてから、水をやる。", "corrected_sentence": "畑に大根の種を植えてから、水をやる。", "error_description": "「植える」は目的語に「を」を取る。「種に植える」は誤りで、「種を植える」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植えて", "is_correct": true, "explanation": "「植えています」の「植えて」。て形で「〜ています」の進行を作る形。"}, {"text": "植える", "is_correct": false, "explanation": "終止形。「植えています」とは続かず、て形の位置には入らない。"}, {"text": "植えよう", "is_correct": false, "explanation": "意志形。「〜ています」の前には続けられず、文の形が合わない。"}, {"text": "植えましょう", "is_correct": false, "explanation": "丁寧な勧誘の形。「植えています」の「ています」と続かず、文に合わない。"}], "correct_form": "植えて", "base_form": "植える", "form_label": "て形", "sentence_index": 1, "explanations": {"植えて": "「植えています」の「植えて」。て形で「〜ています」の進行を作る形。", "植える": "終止形。「植えています」とは続かず、て形の位置には入らない。", "植えよう": "意志形。「〜ています」の前には続けられず、文の形が合わない。", "植えましょう": "丁寧な勧誘の形。「植えています」の「ています」と続かず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の隅に、ミントの苗を植えでおいた。", "corrected_sentence": "庭の隅に、ミントの苗を植えておいた。", "error_description": "て形は「植えて」。「植えで」は濁点の誤りで、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植えない", "is_correct": true, "explanation": "否定形。「植えないほうがいい」と勧める文に合う。"}, {"text": "植えよう", "is_correct": false, "explanation": "意志形。「〜ほうがいい」の前には続かず、文が成り立たない。"}, {"text": "植えます", "is_correct": false, "explanation": "丁寧形で、否定の勧めの文脈と合わない。"}, {"text": "植えれば", "is_correct": false, "explanation": "仮定形で、「ほうがいい」の文とは形が合わない。"}], "correct_form": "植えない", "base_form": "植える", "form_label": "否定形", "sentence_index": 7, "explanations": {"植えない": "否定形。「植えないほうがいい」と勧める文に合う。", "植えよう": "意志形。「〜ほうがいい」の前には続かず、文が成り立たない。", "植えます": "丁寧形で、否定の勧めの文脈と合わない。", "植えれば": "仮定形で、「ほうがいい」の文とは形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「はさみを取る」の目的語を表し、「取って」の直前に入る格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「はさみに取って」は成り立たず、取る対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「はさみが取って」でははさみが動作主になり、文の意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「はさみへ取って」は方向を表すが、取る対象として不自然。"}], "correct_answer": "を", "explanations": {"を": "「はさみを取る」の目的語を表し、「取って」の直前に入る格助詞。", "に": "「はさみに取って」は成り立たず、取る対象を表せない。", "が": "「はさみが取って」でははさみが動作主になり、文の意味が合わない。", "へ": "「はさみへ取って」は方向を表すが、取る対象として不自然。"}, "error_tags": {"に": "着点・相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人が取ってくれました」の主語を表す格助詞で、「取って」の直前に入る。"}, {"text": "で", "is_correct": false, "explanation": "「人で取ってくれました」は手段や場所として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「人へ取ってくれました」は方向として不自然で、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「人の取ってくれました」は文として成り立たず、連体修飾にもならない。"}], "correct_answer": "が", "explanations": {"が": "「人が取ってくれました」の主語を表す格助詞で、「取って」の直前に入る。", "で": "「人で取ってくれました」は手段や場所として成り立たない。", "へ": "「人へ取ってくれました」は方向として不自然で、文が成り立たない。", "の": "「人の取ってくれました」は文として成り立たず、連体修飾にもならない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を手でつかんで、自分の方に動かすこと。", "primary_collocate": null, "pronunciation": "とる", "ipa": "toɾɯ", "syllable_count": 2, "sentences": [{"text": "棚の上のお皿を取ってください。", "target_word": "取って", "complexity_tier": "T3", "furigana": "棚[たな]の上[うえ]のお皿[さら]を取[と]ってください。", "sentence_source": "generated"}, {"text": "母は引き出しからはさみを取って、私にわたしました。", "target_word": "取って", "complexity_tier": "T3", "furigana": "母[はは]は引[ひ]き出[だ]しからはさみを取[と]って、私[わたし]にわたしました。", "sentence_source": "generated"}, {"text": "手がとどかないので、あの本を取ってくれませんか。", "target_word": "取って", "complexity_tier": "T3", "furigana": "手[て]がとどかないので、あの本[ほん]を取[と]ってくれませんか。", "sentence_source": "generated"}, {"text": "子どもは机の上のおもちゃを取ろうとしました。", "target_word": "取ろう", "complexity_tier": "T3", "furigana": "子[こ]どもは机[つくえ]の上[うえ]のおもちゃを取[と]ろうとしました。", "sentence_source": "generated"}, {"text": "彼は手を伸ばして、テーブルの塩を取りました。", "target_word": "取り", "complexity_tier": "T3", "furigana": "彼[かれ]は手[て]を伸[の]ばして、テーブルの塩[しお]を取[と]りました。", "sentence_source": "generated"}, {"text": "はしごに乗って、木の高いところのりんごを取ります。", "target_word": "取り", "complexity_tier": "T3", "furigana": "はしごに乗[の]って、木[き]の高[たか]いところのりんごを取[と]ります。", "sentence_source": "generated"}, {"text": "料理の途中で、棚から砂糖を取って鍋に入れました。", "target_word": "取って", "complexity_tier": "T3", "furigana": "料理[りょうり]の途中[とちゅう]で、棚[たな]から砂糖[さとう]を取[と]って鍋[なべ]に入[い]れました。", "sentence_source": "generated"}, {"text": "網棚の荷物は、背の高い人が取ってくれました。", "target_word": "取って", "complexity_tier": "T3", "furigana": "網棚[あみだな]の荷物[にもつ]は、背[せ]の高[たか]い人[ひと]が取[と]ってくれました。", "sentence_source": "generated"}, {"text": "手を伸ばして、落ちそうなコップを取りました。", "target_word": "取り", "complexity_tier": "T3", "furigana": "手[て]を伸[の]ばして、落[お]ちそうなコップを取[と]りました。", "sentence_source": "generated"}, {"text": "そこのリモコンを取って、テレビをつけてもらえますか。", "target_word": "取って", "complexity_tier": "T3", "furigana": "そこのリモコンを取[と]って、テレビをつけてもらえますか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取る", "label": "終止形"}, {"form": "取り", "label": "連用形"}, {"form": "取って", "label": "て形"}, {"form": "取った", "label": "過去形"}, {"form": "取らない", "label": "否定形"}, {"form": "取れば", "label": "仮定形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "取る|手で物をつかんで自分の方へ|動詞|五段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 網棚 (Zipf 2.22)']::text[], '241fa7e4-e5ef-46f7-8ead-7bb2111dc929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取って", "is_correct": true, "explanation": "手で取って渡すという動作を表し、「棚の上のお皿を___ください」に入ると意味が通る。"}, {"text": "読んで", "is_correct": false, "explanation": "「お皿を読む」は成り立たず、空欄に入らない。"}, {"text": "歌って", "is_correct": false, "explanation": "「お皿を歌う」は成り立たず、意味が通らない。"}, {"text": "眠って", "is_correct": false, "explanation": "眠る動作は物に対して行えず、「お皿を眠って」は空欄に入らない。"}], "explanations": {"取って": "手で取って渡すという動作を表し、「棚の上のお皿を___ください」に入ると意味が通る。", "読んで": "「お皿を読む」は成り立たず、空欄に入らない。", "歌って": "「お皿を歌う」は成り立たず、意味が通らない。", "眠って": "眠る動作は物に対して行えず、「お皿を眠って」は空欄に入らない。"}, "sentence_index": 0, "correct_answer": "取って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを取って、部屋に入りました。", "explanation": "ここは〈押す〉の意味。ドアを前へ動かすのは「押す」で、「取る」は手でつかんで自分の方に動かすことなので合わない。"}, {"text": "荷物を棚の上に取りました。", "explanation": "ここは〈置く〉の意味。物を据える動作は「置く」で、「取る」は自分の方へ動かすことなので合わない。"}, {"text": "ごみを箱に取りました。", "explanation": "ここは〈入れる〉の意味。ごみを中へ収める動作は「入れる」で、「取る」は手でつかむ動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取って", "is_correct": true, "explanation": "棚から砂糖を手に取る動作を表し、「棚から砂糖を___鍋に入れました」に合う。"}, {"text": "歩いて", "is_correct": false, "explanation": "砂糖を歩くことはできず、空欄に入らない。"}, {"text": "泣いて", "is_correct": false, "explanation": "砂糖を泣くことはできず、「砂糖を泣いて」は意味をなさない。"}, {"text": "走って", "is_correct": false, "explanation": "砂糖を走らせることはできず、空欄に入らない。"}], "explanations": {"取って": "棚から砂糖を手に取る動作を表し、「棚から砂糖を___鍋に入れました」に合う。", "歩いて": "砂糖を歩くことはできず、空欄に入らない。", "泣いて": "砂糖を泣くことはできず、「砂糖を泣いて」は意味をなさない。", "走って": "砂糖を走らせることはできず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "取って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車を取って、遠くまで行きました。", "explanation": "ここは〈運転する〉の意味。車を操作する意味は「運転する」で、「取る」は物を手でつかむ動作なので合わない。"}, {"text": "彼は大きな声で、歌を取りました。", "explanation": "ここは〈歌う〉の意味。歌を声に出す動作は「歌う」で、「取る」は手でつかむことに使うので合わない。"}, {"text": "窓を取って、部屋に風を入れました。", "explanation": "ここは〈開ける〉の意味。窓を開ける動作は「開ける」で、「取る」は手でつかんで自分の方に動かすことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本棚の上の本が取ってください。", "corrected_sentence": "本棚の上の本を取ってください。", "error_description": "「取る」の目的語は「を」で示す。「が」では「本が取る」となり、不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取って", "is_correct": true, "explanation": "て形で、「取って、私にわたしました」と動作を順に続ける形。"}, {"text": "取ろう", "is_correct": false, "explanation": "意志形で、「取ろう、私に」と続けると意志を表すだけになり、「わたしました」とは続かない。"}, {"text": "取らない", "is_correct": false, "explanation": "否定形で、動作を続けて渡す文には合わない。"}, {"text": "取れば", "is_correct": false, "explanation": "仮定形で、「取れば、わたしました」とは続かない。"}], "correct_form": "取って", "base_form": "取る", "form_label": "て形", "sentence_index": 1, "explanations": {"取って": "て形で、「取って、私にわたしました」と動作を順に続ける形。", "取ろう": "意志形で、「取ろう、私に」と続けると意志を表すだけになり、「わたしました」とは続かない。", "取らない": "否定形で、動作を続けて渡す文には合わない。", "取れば": "仮定形で、「取れば、わたしました」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39203, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールを取らとして、手を伸ばしました。", "corrected_sentence": "ボールを取ろうとして、手を伸ばしました。", "error_description": "「取ろうとする」の意志形は「取ろう」。「取ら」は「とする」に続かず、活用が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取って", "is_correct": true, "explanation": "て形で、「取ってくれました」と動作を続けて受け手に恩恵が及ぶ形。"}, {"text": "取ろう", "is_correct": false, "explanation": "意志形で、「くれました」には続かない。"}, {"text": "取れる", "is_correct": false, "explanation": "可能形で、「取れてくれました」は成り立たない。"}, {"text": "取りたい", "is_correct": false, "explanation": "願望の形で、「取りたいくれました」は成り立たない。"}], "correct_form": "取って", "base_form": "取る", "form_label": "て形", "sentence_index": 7, "explanations": {"取って": "て形で、「取ってくれました」と動作を続けて受け手に恩恵が及ぶ形。", "取ろう": "意志形で、「くれました」には続かない。", "取れる": "可能形で、「取れてくれました」は成り立たない。", "取りたい": "願望の形で、「取りたいくれました」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「虫が飛ぶ」で、飛ぶ主体の虫を示す主格の「が」になる。"}, {"text": "を", "is_correct": false, "explanation": "「虫を飛ぶ」では対象を示す「を」になり、移動の主体が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「虫に飛ぶ」では受け手を示す「に」になり、飛ぶ主体にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「虫へ飛ぶ」では方向を示すことになり、飛ぶ主体を表す格にならない。"}], "correct_answer": "が", "explanations": {"が": "「虫が飛ぶ」で、飛ぶ主体の虫を示す主格の「が」になる。", "を": "「虫を飛ぶ」では対象を示す「を」になり、移動の主体が成り立たない。", "に": "「虫に飛ぶ」では受け手を示す「に」になり、飛ぶ主体にならない。", "へ": "「虫へ飛ぶ」では方向を示すことになり、飛ぶ主体を表す格にならない。"}, "error_tags": {"を": "対象", "に": "受け手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「虫に刺された」で、刺した主体を示す受身の「に」になる。"}, {"text": "が", "is_correct": false, "explanation": "「虫が刺された」では虫が受け身の主語になり、刺す主体が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「虫と刺された」では並列・共同の「と」になり、刺された文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「虫の刺された」では名詞修飾の「の」になり、文の骨組みが成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「虫に刺された」で、刺した主体を示す受身の「に」になる。", "が": "「虫が刺された」では虫が受け身の主語になり、刺す主体が成り立たない。", "と": "「虫と刺された」では並列・共同の「と」になり、刺された文の意味が通らない。", "の": "「虫の刺された」では名詞修飾の「の」になり、文の骨組みが成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・共同", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "庭や公園などでよく見かける、小さな昆虫。", "primary_collocate": null, "pronunciation": "むし", "ipa": "mɯɕi", "syllable_count": 2, "sentences": [{"text": "庭で小さな虫を見つけた。", "target_word": "虫", "complexity_tier": "T3", "furigana": "庭[にわ]で小[ちい]さな虫[むし]を見[み]つけた。", "sentence_source": "generated"}, {"text": "夜になると、虫が電気のまわりを飛ぶ。", "target_word": "虫", "complexity_tier": "T3", "furigana": "夜[よる]になると、虫[むし]が電気[でんき]のまわりを飛[と]ぶ。", "sentence_source": "generated"}, {"text": "弟は虫が大好きで、毎日公園で探している。", "target_word": "虫", "complexity_tier": "T3", "furigana": "弟[おとうと]は虫[むし]が大好[だいす]きで、毎日[まいにち]公園[こうえん]で探[さが]している。", "sentence_source": "generated"}, {"text": "この虫は葉を食べるので、花が枯れてしまった。", "target_word": "虫", "complexity_tier": "T3", "furigana": "この虫[むし]は葉[は]を食[た]べるので、花[はな]が枯[か]れてしまった。", "sentence_source": "generated"}, {"text": "夏は窓を開けると、虫が部屋に入ってくる。", "target_word": "虫", "complexity_tier": "T3", "furigana": "夏[なつ]は窓[まど]を開[あ]けると、虫[むし]が部屋[へや]に入[はい]ってくる。", "sentence_source": "generated"}, {"text": "姉は虫が苦手なので、森には行きたがらない。", "target_word": "虫", "complexity_tier": "T3", "furigana": "姉[あね]は虫[むし]が苦手[にがて]なので、森[もり]には行[い]きたがらない。", "sentence_source": "generated"}, {"text": "木の上に、緑色の虫が止まっている。", "target_word": "虫", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]に、緑色[みどりいろ]の虫[むし]が止[と]まっている。", "sentence_source": "generated"}, {"text": "虫に刺されたところが、かゆくてたまらない。", "target_word": "虫", "complexity_tier": "T3", "furigana": "虫[むし]に刺[さ]されたところが、かゆくてたまらない。", "sentence_source": "generated"}, {"text": "虫の絵をかく宿題が出た。", "target_word": "虫", "complexity_tier": "T3", "furigana": "虫[むし]の絵[え]をかく宿題[しゅくだい]が出[で]た。", "sentence_source": "generated"}, {"text": "朝、道に黒い虫が歩いていた。", "target_word": "虫", "complexity_tier": "T3", "furigana": "朝[あさ]、道[みち]に黒[くろ]い虫[むし]が歩[ある]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "虫", "label": "基本形"}, {"form": "虫たち", "label": "複数を表す形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "庭や公園で見かける、小さくて足のある生き物（昆虫）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虫", "is_correct": true, "explanation": "「小さな虫」は庭で見つけられる小さな生き物で、文脈に合う。"}, {"text": "会議", "is_correct": false, "explanation": "庭で見つける対象ではなく、「小さな会議を見つけた」は文として成り立たない。"}, {"text": "文法", "is_correct": false, "explanation": "「小さな文法を見つけた」は庭の場面に合わず、意味が通らない。"}, {"text": "税金", "is_correct": false, "explanation": "「小さな税金を見つけた」は庭の場面に合わず、不自然な文になる。"}], "explanations": {"虫": "「小さな虫」は庭で見つけられる小さな生き物で、文脈に合う。", "会議": "庭で見つける対象ではなく、「小さな会議を見つけた」は文として成り立たない。", "文法": "「小さな文法を見つけた」は庭の場面に合わず、意味が通らない。", "税金": "「小さな税金を見つけた」は庭の場面に合わず、不自然な文になる。"}, "sentence_index": 0, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "腹の虫が収まらず、弟に言い返した。", "explanation": "ここは〈怒り・不満〉を表す「腹の虫」で、昆虫の虫とは別の意味。"}, {"text": "壁に虫を打ち込んで、棚を取り付けた。", "explanation": "ここは〈ねじ〉の意味。壁に打ち込んで固定するのはねじで、生き物の虫は打ち込めないので合わない。"}, {"text": "服に糸くずのように虫がついていたので、取った。", "explanation": "ここは〈糸くず〉の意味。服につくのは糸くずで、生き物の虫を糸くずのようにたとえるのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虫", "is_correct": true, "explanation": "「緑色の虫が止まっている」で、木に止まる小さな生き物として文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "「緑色の歌が止まっている」は意味をなさず、文が不自然になる。"}, {"text": "砂", "is_correct": false, "explanation": "「緑色の砂が止まっている」は木の上の場面に合わず、不自然になる。"}, {"text": "絵", "is_correct": false, "explanation": "「緑色の絵が止まっている」は木の上の場面に合わず、意味が通らない。"}], "explanations": {"虫": "「緑色の虫が止まっている」で、木に止まる小さな生き物として文に合う。", "歌": "「緑色の歌が止まっている」は意味をなさず、文が不自然になる。", "砂": "「緑色の砂が止まっている」は木の上の場面に合わず、不自然になる。", "絵": "「緑色の絵が止まっている」は木の上の場面に合わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に虫が痛くなって、歯医者に行った。", "explanation": "ここは〈虫歯〉の意味。歯の病気は虫だけでは指さず、虫歯と言うので合わない。"}, {"text": "パンを作るため、生地に虫を入れてふくらませた。", "explanation": "ここは〈酵母〉の意味。生地をふくらませる微生物は酵母で、昆虫の虫は入れないので合わない。"}, {"text": "庭の雑草を抜いたついでに、庭の虫を抜いた。", "explanation": "ここは〈雑草〉の意味。雑草は抜くが、昆虫の虫は抜く対象にならず、動詞が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓の外で大きな虫に見かけた。", "corrected_sentence": "窓の外で大きな虫を見かけた。", "error_description": "「見かける」の対象は「を」で示す。「虫に」と書くと格が誤りになり、正しくは「虫を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39204, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の上に虫が三本いた。", "corrected_sentence": "机の上に虫が三匹いた。", "error_description": "虫を数える助数詞は「匹」。「本」は細長いものに使うので誤りで、正しくは「三匹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「虫がつかない」で、くっつく主体の虫を示す主格の「が」になる。"}, {"text": "を", "is_correct": false, "explanation": "「虫をつかない」では対象を示すことになり、つくのは虫自身なので成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「虫へつかない」では方向を示すことになり、付着する主体を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「虫とつかない」では共同の「と」になり、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「虫がつかない」で、くっつく主体の虫を示す主格の「が」になる。", "を": "「虫をつかない」では対象を示すことになり、つくのは虫自身なので成り立たない。", "へ": "「虫へつかない」では方向を示すことになり、付着する主体を表せない。", "と": "「虫とつかない」では共同の「と」になり、文の意味が通らない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "昆虫や小さな生き物の総称。", "primary_collocate": null, "pronunciation": "むし", "ipa": "mɯɕi", "syllable_count": 2, "sentences": [{"text": "秋の夜は、草むらで虫の声がよく聞こえる。", "target_word": "虫", "complexity_tier": "T3", "furigana": "秋[あき]の夜[よる]は、草[くさ]むらで虫[むし]の声[こえ]がよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "ミミズやダンゴムシのような虫も、土を豊かにしている。", "target_word": "虫", "complexity_tier": "T3", "furigana": "ミミズやダンゴムシのような虫[むし]も、土[つち]を豊[ゆた]かにしている。", "sentence_source": "generated"}, {"text": "虫の種類は多く、まだ名前のないものもいる。", "target_word": "虫", "complexity_tier": "T3", "furigana": "虫[むし]の種類[しゅるい]は多[おお]く、まだ名前[なまえ]のないものもいる。", "sentence_source": "generated"}, {"text": "キャンプでは、虫に刺されないように長い服を着た。", "target_word": "虫", "complexity_tier": "T3", "furigana": "キャンプでは、虫[むし]に刺[さ]されないように長[なが]い服[ふく]を着[き]た。", "sentence_source": "generated"}, {"text": "トンボもチョウも、広く言えば虫の仲間だ。", "target_word": "虫", "complexity_tier": "T3", "furigana": "トンボもチョウも、広[ひろ]く言[い]えば虫[むし]の仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "冬になると、多くの虫は土の中でじっとしている。", "target_word": "虫", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、多[おお]くの虫[むし]は土[つち]の中[なか]でじっとしている。", "sentence_source": "generated"}, {"text": "鳥は虫を食べて、子どもを育てる。", "target_word": "虫", "complexity_tier": "T3", "furigana": "鳥[とり]は虫[むし]を食[た]べて、子[こ]どもを育[そだ]てる。", "sentence_source": "generated"}, {"text": "野菜に虫がつかないよう、毎朝葉を調べている。", "target_word": "虫", "complexity_tier": "T3", "furigana": "野菜[やさい]に虫[むし]がつかないよう、毎朝[まいあさ]葉[は]を調[しら]べている。", "sentence_source": "generated"}, {"text": "この図鑑には、世界中の虫がのっている。", "target_word": "虫", "complexity_tier": "T3", "furigana": "この図鑑[ずかん]には、世界中[せかいじゅう]の虫[むし]がのっている。", "sentence_source": "generated"}, {"text": "雨がやむと、虫がいっせいに鳴き始めた。", "target_word": "虫", "complexity_tier": "T3", "furigana": "雨[あめ]がやむと、虫[むし]がいっせいに鳴[な]き始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "虫", "label": "基本形"}, {"form": "虫たち", "label": "複数を表す形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "昆虫のほか、ミミズやクモなど小さな動物までまとめて呼ぶ総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虫", "is_correct": true, "explanation": "「草むらで虫の声」は草むらにいる生き物の声を表し、文脈に合う。"}, {"text": "紙", "is_correct": false, "explanation": "「草むらで紙の声」は意味をなさず、文が成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「草むらで砂糖の声」は場面に合わず、不自然な文になる。"}, {"text": "皿", "is_correct": false, "explanation": "「草むらで皿の声」は場面に合わず、意味が通らない。"}], "explanations": {"虫": "「草むらで虫の声」は草むらにいる生き物の声を表し、文脈に合う。", "紙": "「草むらで紙の声」は意味をなさず、文が成り立たない。", "砂糖": "「草むらで砂糖の声」は場面に合わず、不自然な文になる。", "皿": "「草むらで皿の声」は場面に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、鶏が虫を産んだ。", "explanation": "鶏が産むのは卵などで、虫を産むとは言えない。「産む」と合わない。"}, {"text": "庭の草を刈るように、庭の虫を刈った。", "explanation": "草は刈るが、生き物の虫は刈る対象として自然ではない。「刈る」と合わない。"}, {"text": "古い紙を破るように、庭の虫を破った。", "explanation": "紙は破るものだが、虫は破る対象ではない。「破る」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虫", "is_correct": true, "explanation": "「鳥は虫を食べて」は鳥の餌として自然で、文に合う。"}, {"text": "本", "is_correct": false, "explanation": "「鳥は本を食べて」は成り立たず、文の意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "「鳥は窓を食べて」は意味をなさず、文が不自然になる。"}, {"text": "雲", "is_correct": false, "explanation": "「鳥は雲を食べて」は成り立たず、文が不自然になる。"}], "explanations": {"虫": "「鳥は虫を食べて」は鳥の餌として自然で、文に合う。", "本": "「鳥は本を食べて」は成り立たず、文の意味が通らない。", "窓": "「鳥は窓を食べて」は意味をなさず、文が不自然になる。", "雲": "「鳥は雲を食べて」は成り立たず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭に木を植えるように、庭に虫を植えた。", "explanation": "虫は植えるものではなく、「植える」の対象として成り立たない。"}, {"text": "虫を三枚におろして、夕食に出した。", "explanation": "三枚におろすのは魚などに使う動作で、虫には使わない。"}, {"text": "春になり、庭の虫がいっせいに咲いた。", "explanation": "咲くのは花で、虫は咲かないので「咲いた」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の公園で虫に鳴いていた。", "corrected_sentence": "夜の公園で虫が鳴いていた。", "error_description": "「鳴く」の主語は「が」で示す。「虫に」と書くと格が誤りになり、正しくは「虫が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜、草むらで虫が吠えていた。", "corrected_sentence": "夜、草むらで虫が鳴いていた。", "error_description": "「吠える」は犬などの動物の鳴き方。虫の声には「鳴く」を使うので、動詞が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "到達点を表す助詞。「うちに来る」の形で、来る先を示す。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すが、到達点には使わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、移動先を示すことはできない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表し、ここでは文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "到達点を表す助詞。「うちに来る」の形で、来る先を示す。", "で": "場所や手段を表すが、到達点には使わない。", "を": "目的語を表す助詞で、移動先を示すことはできない。", "と": "共同や引用を表し、ここでは文が成り立たない。"}, "error_tags": {"で": "場所を示すが、到達点には使わない", "を": "目的語の助詞で、移動先には使えない", "と": "共同や引用を示し、ここでは文が成り立たない"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "行く", "is_correct": true, "explanation": "離れていく意味で、〈来る〉の対義語として類語辞典に載る。"}, {"text": "食べる", "is_correct": false, "explanation": "飲食の動作で、〈来る〉の対義語ではない。"}, {"text": "作る", "is_correct": false, "explanation": "ものを生み出す動作で、〈来る〉の対義語ではない。"}, {"text": "見る", "is_correct": false, "explanation": "視覚の動作で、〈来る〉の対義語ではない。"}], "correct_answer": "行く", "explanations": {"行く": "離れていく意味で、〈来る〉の対義語として類語辞典に載る。", "食べる": "飲食の動作で、〈来る〉の対義語ではない。", "作る": "ものを生み出す動作で、〈来る〉の対義語ではない。", "見る": "視覚の動作で、〈来る〉の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "行く", "is_correct": true, "explanation": "離れていく意味で、〈来る〉の対義語として類語辞典に載る。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠の動作で、〈来る〉の対義語ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "足で進む動作で、〈来る〉の対義語としては辞書に載らない。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を発する動作で、〈来る〉の対義語ではない。"}], "correct_answer": "行く", "explanations": {"行く": "離れていく意味で、〈来る〉の対義語として類語辞典に載る。", "眠る": "睡眠の動作で、〈来る〉の対義語ではない。", "歩く": "足で進む動作で、〈来る〉の対義語としては辞書に載らない。", "話す": "言葉を発する動作で、〈来る〉の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "どこかからここへ来るという意味。", "primary_collocate": null, "pronunciation": "くる", "ipa": "kuru", "syllable_count": 2, "sentences": [{"text": "友だちが明日うちに来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "友[とも]だちが明日[あした]うちに来[き]ます。", "sentence_source": "generated"}, {"text": "バスはもうすぐ来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "バスはもうすぐ来[き]ます。", "sentence_source": "generated"}, {"text": "もうすぐ春が来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "もうすぐ春[はる]が来[き]ます。", "sentence_source": "generated"}, {"text": "田中さんは、あとで来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "田中[たなか]さんは、あとで来[き]ます。", "sentence_source": "generated"}, {"text": "母は日曜日に東京から来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "母[はは]は日曜日[にちようび]に東京[とうきょう]から来[き]ます。", "sentence_source": "generated"}, {"text": "電車が来ますから、下がってください。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が来[き]ますから、下[さ]がってください。", "sentence_source": "generated"}, {"text": "来週の月曜日、会社に来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の月曜日[げつようび]、会社[かいしゃ]に来[き]ます。", "sentence_source": "generated"}, {"text": "先生は明日、十時に教室に来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "先生[せんせい]は明日[あした]、十時[じゅうじ]に教室[きょうしつ]に来[き]ます。", "sentence_source": "generated"}, {"text": "夏休みに、姉が子どもを連れて来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、姉[あね]が子[こ]どもを連[つ]れて来[き]ます。", "sentence_source": "generated"}, {"text": "大事なお客さんが三時に来ます。", "target_word": "来ます", "complexity_tier": "T3", "furigana": "大事[だいじ]なお客[きゃく]さんが三時[さんじ]に来[き]ます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "来る", "label": "終止形"}, {"form": "来ます", "label": "丁寧形"}, {"form": "来ません", "label": "丁寧否定形"}, {"form": "来ました", "label": "丁寧過去形"}], "register": "polite", "sense_fingerprint": "どこかからこちらへ来る動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来ます", "is_correct": true, "explanation": "友だちがこちらへ来るという意味で、「明日うちに」の文脈に合う。"}, {"text": "洗います", "is_correct": false, "explanation": "汚れを取る動作で、「うちに」の文脈では文が成り立たない。"}, {"text": "切ります", "is_correct": false, "explanation": "物を分ける動作で、来訪の文脈には合わない。"}, {"text": "磨きます", "is_correct": false, "explanation": "表面をきれいにする動作で、来訪の文脈には合わない。"}], "explanations": {"来ます": "友だちがこちらへ来るという意味で、「明日うちに」の文脈に合う。", "洗います": "汚れを取る動作で、「うちに」の文脈では文が成り立たない。", "切ります": "物を分ける動作で、来訪の文脈には合わない。", "磨きます": "表面をきれいにする動作で、来訪の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "来ます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は今、東京にいて、明日は大阪に来ます。", "explanation": "話し手は東京にいるので、大阪へ移動するなら〈行く〉を使う。〈来る〉は話し手のいる場所へ近づく動き。"}, {"text": "私は今、家にいて、駅前の図書館に来ます。", "explanation": "話し手は家にいるので、図書館へ向かうなら〈行く〉を使う。〈来る〉は話し手のいる場所への動き。"}, {"text": "私は今、大阪のホテルにいて、明日は京都の友だちの家に来ます。", "explanation": "話し手は大阪にいるので、京都へ向かうなら〈行く〉を使う。〈来る〉は話し手のいる場所への動き。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来ます", "is_correct": true, "explanation": "会社に来るという意味で、「来週の月曜日」の文脈に合う。"}, {"text": "焼きます", "is_correct": false, "explanation": "熱で加える動作で、会社への移動の文脈には合わない。"}, {"text": "掃きます", "is_correct": false, "explanation": "ほうきで掃除する動作で、来訪の文脈には合わない。"}, {"text": "噛みます", "is_correct": false, "explanation": "歯で食べ物を砕く動作で、会社への移動とは関係がない。"}], "explanations": {"来ます": "会社に来るという意味で、「来週の月曜日」の文脈に合う。", "焼きます": "熱で加える動作で、会社への移動の文脈には合わない。", "掃きます": "ほうきで掃除する動作で、来訪の文脈には合わない。", "噛みます": "歯で食べ物を砕く動作で、会社への移動とは関係がない。"}, "sentence_index": 6, "correct_answer": "来ます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は今、会社にいて、明日は病院に来ます。", "explanation": "話し手は会社にいるので、病院へ移動するなら〈行く〉を使う。〈来る〉は話し手のいる場所への動き。"}, {"text": "私は今、家にいて、来週は海辺の町に来ます。", "explanation": "話し手は家にいるので、海辺の町へ向かうなら〈行く〉を使う。〈来る〉は話し手のいる場所への動き。"}, {"text": "私は今、大阪にいて、夏休みに東京の大学に来ます。", "explanation": "話し手は大阪にいるので、東京へ向かうなら〈行く〉を使う。〈来る〉は話し手のいる場所への動き。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちが明日、私の家を来ます。", "corrected_sentence": "友だちが明日、私の家に来ます。", "error_description": "『来る』は到達点に『に』を取る。『を』は目的語を表す助詞で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "来ます", "is_correct": true, "explanation": "来るの丁寧形。「バスはもうすぐ〜」の述語として文が丁寧に締まる。"}, {"text": "来ない", "is_correct": false, "explanation": "否定形で、バスが来ないという逆の意味になる。"}, {"text": "来て", "is_correct": false, "explanation": "て形で、文を続ける途中の形。ここでは文が完結しない。"}, {"text": "来よう", "is_correct": false, "explanation": "意志の形で、バスの到着を述べる文には合わない。"}], "correct_form": "来ます", "base_form": "来る", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"来ます": "来るの丁寧形。「バスはもうすぐ〜」の述語として文が丁寧に締まる。", "来ない": "否定形で、バスが来ないという逆の意味になる。", "来て": "て形で、文を続ける途中の形。ここでは文が完結しない。", "来よう": "意志の形で、バスの到着を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、友だちが会社に来るます。", "corrected_sentence": "来週、友だちが会社に来ます。", "error_description": "『来ます』は『来る』の語幹に『ます』を付けた形。『来るます』は『る』が余分で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "来ます", "is_correct": true, "explanation": "来るの丁寧形で、「先生は〜」の述語として文を締める。"}, {"text": "来ました", "is_correct": false, "explanation": "丁寧過去形で、過去の出来事を表す。予定を述べる文には合わない。"}, {"text": "来ませんでした", "is_correct": false, "explanation": "丁寧過去の否定形で、来なかったという逆の意味になる。"}, {"text": "来れば", "is_correct": false, "explanation": "仮定の形で、文が完結せず述語として合わない。"}], "correct_form": "来ます", "base_form": "来る", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"来ます": "来るの丁寧形で、「先生は〜」の述語として文を締める。", "来ました": "丁寧過去形で、過去の出来事を表す。予定を述べる文には合わない。", "来ませんでした": "丁寧過去の否定形で、来なかったという逆の意味になる。", "来れば": "仮定の形で、文が完結せず述語として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「帽子が」は主語になり、「飛ばされた」の主語として文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「帽子に」では、風に飛ばされた物（主語）を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「帽子と」は並列や共同を表し、ここでは主語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「帽子へ」は方向を示すが、ここは飛ばされた物の主語なので合わない。"}], "correct_answer": "が", "explanations": {"が": "「帽子が」は主語になり、「飛ばされた」の主語として文が成り立つ。", "に": "「帽子に」では、風に飛ばされた物（主語）を示せないので合わない。", "と": "「帽子と」は並列や共同を表し、ここでは主語の位置に合わない。", "へ": "「帽子へ」は方向を示すが、ここは飛ばされた物の主語なので合わない。"}, "error_tags": {"に": "相手・場所", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「帽子を」は「選んだ」の目的語になり、選ばれたものを示す。"}, {"text": "より", "is_correct": false, "explanation": "「帽子より」は比較の基準を表し、選んだ対象にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「帽子の」は所属や修飾を表し、「選んだ」の目的語にはならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「帽子で」は手段を示し、「選んだ」の目的語を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「帽子を」は「選んだ」の目的語になり、選ばれたものを示す。", "より": "「帽子より」は比較の基準を表し、選んだ対象にはならないので合わない。", "の": "「帽子の」は所属や修飾を表し、「選んだ」の目的語にはならないので合わない。", "で": "「帽子で」は手段を示し、「選んだ」の目的語を示せないので合わない。"}, "error_tags": {"より": "比較", "の": "所属・修飾", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あたまにかぶるものです。", "primary_collocate": null, "pronunciation": "ぼうし", "ipa": "boːɕi", "syllable_count": 3, "sentences": [{"text": "公園へ行く前に、帽子をかぶった。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "公園[こうえん]へ行[い]く前[まえ]に、帽子[ぼうし]をかぶった。", "sentence_source": "generated"}, {"text": "弟の赤い帽子が、風で飛ばされた。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "弟[おとうと]の赤[あか]い帽子[ぼうし]が、風[かぜ]で飛[と]ばされた。", "sentence_source": "generated"}, {"text": "この帽子は、おじいちゃんからもらった。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "この帽子[ぼうし]は、おじいちゃんからもらった。", "sentence_source": "generated"}, {"text": "教室に入る前に、帽子をぬいでください。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "教室[きょうしつ]に入[はい]る前[まえ]に、帽子[ぼうし]をぬいでください。", "sentence_source": "generated"}, {"text": "店で、黒い帽子を二つ買った。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "店[みせ]で、黒[くろ]い帽子[ぼうし]を二[ふた]つ買[か]った。", "sentence_source": "generated"}, {"text": "妹は帽子の中に小さな花を入れて遊んだ。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "妹[いもうと]は帽子[ぼうし]の中[なか]に小[ちい]さな花[はな]を入[い]れて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "かばんの上に帽子がのっている。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "かばんの上[うえ]に帽子[ぼうし]がのっている。", "sentence_source": "generated"}, {"text": "姉は新しい服に合う帽子を選んだ。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "姉[あね]は新[あたら]しい服[ふく]に合[あ]う帽子[ぼうし]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "先生が白い帽子を見せて、「だれのですか」と聞いた。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "先生[せんせい]が白[しろ]い帽子[ぼうし]を見[み]せて、「だれのですか」と聞[き]いた。", "sentence_source": "generated"}, {"text": "帽子をかぶったまま、写真をとった。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "帽子[ぼうし]をかぶったまま、写真[しゃしん]をとった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帽子", "label": "基本形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "頭の上にのせて身につける、ふちやつばのある物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "「かぶった」の目的語になる、頭にかぶる衣類。文の流れに合う。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋は手にはめるもので、「かぶった」とは言わないので合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下ははくもので、かぶるものではないので合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡はかけるもので、「かぶった」とは言わないので合わない。"}], "explanations": {"帽子": "「かぶった」の目的語になる、頭にかぶる衣類。文の流れに合う。", "手袋": "手袋は手にはめるもので、「かぶった」とは言わないので合わない。", "靴下": "靴下ははくもので、かぶるものではないので合わない。", "眼鏡": "眼鏡はかけるもので、「かぶった」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪が邪魔なので、帽子で前髪を留めた。", "explanation": "ここは〈ヘアピン〉の意味。前髪を留めるのはヘアピンで、帽子では合わない。"}, {"text": "寒いので、帽子を首に巻いた。", "explanation": "ここは〈マフラー〉の意味。帽子は頭にかぶるもので、首に巻くものではないので合わない。"}, {"text": "暑いので、帽子で顔の汗をふいた。", "explanation": "ここは〈タオル〉の意味。汗をふく道具は帽子ではなくタオルなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "かばんの上にのっている持ち物として自然。文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "かばんの上に冷蔵庫がのるような状況は不自然で、この文に合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は地面に立つもので、かばんの上にのっているとは言わないので合わない。"}, {"text": "ベッド", "is_correct": false, "explanation": "ベッドは大きすぎて、かばんの上にのる状況ではないので合わない。"}], "explanations": {"帽子": "かばんの上にのっている持ち物として自然。文に合う。", "冷蔵庫": "かばんの上に冷蔵庫がのるような状況は不自然で、この文に合わない。", "電柱": "電柱は地面に立つもので、かばんの上にのっているとは言わないので合わない。", "ベッド": "ベッドは大きすぎて、かばんの上にのる状況ではないので合わない。"}, "sentence_index": 6, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日差しが強いので、帽子をさして歩いた。", "explanation": "ここは〈日傘〉の意味。「さす」のは日傘で、帽子は頭にかぶるものなので合わない。"}, {"text": "寒いので、帽子を足にはいて寝た。", "explanation": "ここは〈靴下〉の意味。足にはくのは靴下で、帽子を足にはくとは言わないので合わない。"}, {"text": "大切な人にもらった帽子を、指にはめた。", "explanation": "ここは〈指輪〉の意味。指にはめるのは指輪で、帽子は頭にかぶるものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、帽子を首まで巻いて出かける。", "corrected_sentence": "寒い日は、マフラーを首まで巻いて出かける。", "error_description": "「帽子」は頭にかぶるもの。首まで巻くのは「マフラー」なので、「帽子」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は畑で働くとき、帽子にかぶる。", "corrected_sentence": "祖父は畑で働くとき、帽子をかぶる。", "error_description": "「かぶる」は目的語に「を」をとる。「帽子に」の「に」が誤りで、「帽子を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「帽子が」は主語になり、「欠かせない」の主語として文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「帽子を欠かせない」とは結びつかないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「帽子と」は並列を表し、ここでは主語にならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「帽子へ」は方向を示すが、「欠かせない」とは合わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「帽子が」は主語になり、「欠かせない」の主語として文が成り立つ。", "を": "「帽子を欠かせない」とは結びつかないので合わない。", "と": "「帽子と」は並列を表し、ここでは主語にならないので合わない。", "へ": "「帽子へ」は方向を示すが、「欠かせない」とは合わないので合わない。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「帽子のおかげで」は定型の表現で、「の」が「おかげ」を修飾する。"}, {"text": "で", "is_correct": false, "explanation": "「帽子でおかげで」は成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「帽子におかげで」は成り立たないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「帽子よりおかげで」は意味が通らないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「帽子のおかげで」は定型の表現で、「の」が「おかげ」を修飾する。", "で": "「帽子でおかげで」は成り立たないので合わない。", "に": "「帽子におかげで」は成り立たないので合わない。", "より": "「帽子よりおかげで」は意味が通らないので合わない。"}, "error_tags": {"で": "手段", "に": "相手・場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "頭にかぶって、日差しや寒さから守るための衣類。", "primary_collocate": null, "pronunciation": "ぼうし", "ipa": "boːɕi", "syllable_count": 3, "sentences": [{"text": "日差しが強いので、帽子をかぶって出かけた。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "日差[ひざ]しが強[つよ]いので、帽子[ぼうし]をかぶって出[で]かけた。", "sentence_source": "generated"}, {"text": "寒い朝は、耳まで隠れる帽子が欠かせない。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、耳[みみ]まで隠[かく]れる帽子[ぼうし]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "登山では、頭を守るために帽子を持って行く。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "登山[とざん]では、頭[あたま]を守[まも]るために帽子[ぼうし]を持[も]って行[い]く。", "sentence_source": "generated"}, {"text": "帽子を忘れたせいで、首のうしろが日焼けした。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "帽子[ぼうし]を忘[わす]れたせいで、首[くび]のうしろが日焼[ひや]けした。", "sentence_source": "generated"}, {"text": "子どもたちは、日よけの帽子をかぶって運動場に出た。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、日[ひ]よけの帽子[ぼうし]をかぶって運動場[うんどうじょう]に出[で]た。", "sentence_source": "generated"}, {"text": "雪の日は、毛糸の帽子があたたかい。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、毛糸[けいと]の帽子[ぼうし]があたたかい。", "sentence_source": "generated"}, {"text": "父は畑で働くとき、必ず帽子をかぶる。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "父[ちち]は畑[はたけ]で働[はたら]くとき、必[かなら]ず帽子[ぼうし]をかぶる。", "sentence_source": "generated"}, {"text": "帽子のおかげで、強い日差しの中でも気分が悪くならなかった。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "帽子[ぼうし]のおかげで、強[つよ]い日差[ひざ]しの中[なか]でも気分[きぶん]が悪[わる]くならなかった。", "sentence_source": "generated"}, {"text": "風の強い海辺では、帽子が飛ばないように押さえた。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "風[かぜ]の強[つよ]い海辺[うみべ]では、帽子[ぼうし]が飛[と]ばないように押[お]さえた。", "sentence_source": "generated"}, {"text": "寒さから頭を守る帽子を、冬の前に買った。", "target_word": "帽子", "complexity_tier": "T3", "furigana": "寒[さむ]さから頭[あたま]を守[まも]る帽子[ぼうし]を、冬[ふゆ]の前[まえ]に買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帽子", "label": "基本形"}], "register": "日常的な話し言葉（常体）", "sense_fingerprint": "日差し・寒さ・風などから頭を守るために身につける衣類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723fedc8-6b9e-4a1a-accb-29050b2aecb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "頭にかぶるものなので、「かぶって出かけた」に合う。"}, {"text": "靴", "is_correct": false, "explanation": "靴ははくもので、「かぶって」とは言わないので合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡はかけるもので、「かぶって」とは言わないので合わない。"}, {"text": "ベルト", "is_correct": false, "explanation": "ベルトは腰に締めるもので、「かぶって」とは言わないので合わない。"}], "explanations": {"帽子": "頭にかぶるものなので、「かぶって出かけた」に合う。", "靴": "靴ははくもので、「かぶって」とは言わないので合わない。", "眼鏡": "眼鏡はかけるもので、「かぶって」とは言わないので合わない。", "ベルト": "ベルトは腰に締めるもので、「かぶって」とは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面接の前に、帽子を首に結んだ。", "explanation": "ここは〈ネクタイ〉の意味。首に結ぶのはネクタイで、帽子は頭にかぶるものなので合わない。"}, {"text": "寒い夜は、帽子を体にかけて寝た。", "explanation": "ここは〈布団〉の意味。体にかけて寝るのは布団で、帽子は頭にかぶるものなので合わない。"}, {"text": "涙をぬぐうために、帽子で目元をふいた。", "explanation": "ここは〈ハンカチ〉の意味。目元をふくのはハンカチで、帽子では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帽子", "is_correct": true, "explanation": "頭にかぶるものなので、「父は必ず帽子をかぶる」に合う。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋ははめるもので、かぶるとは言わないので合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下ははくもので、かぶるとは言わないので合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡はかけるもので、「かぶる」とは言わないので合わない。"}], "explanations": {"帽子": "頭にかぶるものなので、「父は必ず帽子をかぶる」に合う。", "手袋": "手袋ははめるもので、かぶるとは言わないので合わない。", "靴下": "靴下ははくもので、かぶるとは言わないので合わない。", "眼鏡": "眼鏡はかけるもので、「かぶる」とは言わないので合わない。"}, "sentence_index": 6, "correct_answer": "帽子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を防ぐため、帽子を口に当てて歩いた。", "explanation": "ここは〈マスク〉の意味。口に当てるのはマスクで、帽子は頭にかぶるものなので合わない。"}, {"text": "おしゃれのために、帽子を片方の耳につけた。", "explanation": "ここは〈イヤリング〉の意味。耳につけるのはイヤリングで、帽子ではないので合わない。"}, {"text": "ズボンを固定するため、帽子を腰に締めた。", "explanation": "ここは〈ベルト〉の意味。腰に締めるのはベルトで、帽子ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪の日は、毛糸の帽子を耳まで巻いて出かける。", "corrected_sentence": "雪の日は、毛糸のマフラーを耳まで巻いて出かける。", "error_description": "「帽子」は頭にかぶるもの。耳まで巻くのは「マフラー」なので、「帽子」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は畑で働くとき、帽子をはく。", "corrected_sentence": "祖母は畑で働くとき、帽子をかぶる。", "error_description": "「帽子」は頭にかぶるもの。「はく」は足に使う動詞なので、「はく」が誤りで「かぶる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a21c34ec-dae3-4733-9dcf-451cff20ed2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
