INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す助詞。「話をする」の形で、する動作の対象を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。「話より」では「する」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の助詞。「話のしました」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の助詞。「話としました」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す助詞。「話をする」の形で、する動作の対象を示す。", "より": "比較の助詞。「話より」では「する」の目的語にならない。", "の": "連体の助詞。「話のしました」は文として成り立たない。", "と": "並列・共同の助詞。「話としました」は意味が通らない。"}, "error_tags": {"より": "比較の助詞。「話より」では「する」の目的語にならない", "の": "連体の助詞。「話のしました」は文として成り立たない", "と": "並列・共同の助詞。「話としました」は意味が通らない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何らかの動作や行為を行うこと。", "primary_collocate": null, "pronunciation": "する", "ipa": "sɯɾɯ", "syllable_count": 2, "sentences": [{"text": "昨日、宿題をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "昨日[きのう]、宿題[しゅくだい]をしました。", "sentence_source": "generated"}, {"text": "先週の日曜日に、友だちとテニスをしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "先週[せんしゅう]の日曜日[にちようび]に、友[とも]だちとテニスをしました。", "sentence_source": "generated"}, {"text": "きのう、料理をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "きのう、料理[りょうり]をしました。", "sentence_source": "generated"}, {"text": "夏休みに、いい経験をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、いい経験[けいけん]をしました。", "sentence_source": "generated"}, {"text": "先週、新しい仕事の話をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "先週[せんしゅう]、新[あたら]しい仕事[しごと]の話[はなし]をしました。", "sentence_source": "generated"}, {"text": "朝、部屋のそうじをしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "朝[あさ]、部屋[へや]のそうじをしました。", "sentence_source": "generated"}, {"text": "父と、海で釣りをしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "父[ちち]と、海[うみ]で釣[つ]りをしました。", "sentence_source": "generated"}, {"text": "昨夜は、電話で長い話をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "昨夜[さくや]は、電話[でんわ]で長[なが]い話[はなし]をしました。", "sentence_source": "generated"}, {"text": "去年、京都で買い物をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "去年[きょねん]、京都[きょうと]で買[か]い物[もの]をしました。", "sentence_source": "generated"}, {"text": "母に、大事なお願いをしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "母[はは]に、大事[だいじ]なお願[ねが]いをしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "する", "label": "終止形"}, {"form": "します", "label": "丁寧形"}, {"form": "しました", "label": "丁寧過去形"}, {"form": "しません", "label": "丁寧否定形"}], "register": "polite", "sense_fingerprint": "動作や行為を行う（目的語が具体的な行為を決める）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d3d8d6-b464-4341-8055-ce9a23691820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "しました", "is_correct": true, "explanation": "「宿題をする」の丁寧過去形。昨日の出来事を丁寧に述べる形として合う。"}, {"text": "食べました", "is_correct": false, "explanation": "「宿題を食べる」は意味が通らない。宿題は食べ物ではない。"}, {"text": "浴びました", "is_correct": false, "explanation": "「宿題を浴びる」とは言わない。浴びるは水や光など体にかかるものに使う。"}, {"text": "歩きました", "is_correct": false, "explanation": "「宿題を歩く」は意味が通らない。歩く動作は宿題の対象にならない。"}], "explanations": {"しました": "「宿題をする」の丁寧過去形。昨日の出来事を丁寧に述べる形として合う。", "食べました": "「宿題を食べる」は意味が通らない。宿題は食べ物ではない。", "浴びました": "「宿題を浴びる」とは言わない。浴びるは水や光など体にかかるものに使う。", "歩きました": "「宿題を歩く」は意味が通らない。歩く動作は宿題の対象にならない。"}, "sentence_index": 0, "correct_answer": "しました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちに、お金をしました。", "explanation": "「お金を使う・払う」の意味で「する」は使えない。ここでは「お金」を目的語にできない。"}, {"text": "毎朝、スーツをしました。", "explanation": "「スーツを着る」の意味で「する」は使えない。ここは「着る」と言う。"}, {"text": "今朝、紅茶をしました。", "explanation": "「紅茶を入れる・飲む」の意味で「する」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しました", "is_correct": true, "explanation": "「釣りをする」の丁寧過去形。過去の出来事を丁寧に述べる形として合う。"}, {"text": "歌いました", "is_correct": false, "explanation": "「釣りを歌う」は意味が通らない。歌うは歌を対象にする動詞。"}, {"text": "笑いました", "is_correct": false, "explanation": "「釣りを笑う」とは言わない。笑うは人や出来事を対象にする。"}, {"text": "踊りました", "is_correct": false, "explanation": "「釣りを踊る」は意味が通らない。踊りは釣りとは組み合わさない。"}], "explanations": {"しました": "「釣りをする」の丁寧過去形。過去の出来事を丁寧に述べる形として合う。", "歌いました": "「釣りを歌う」は意味が通らない。歌うは歌を対象にする動詞。", "笑いました": "「釣りを笑う」とは言わない。笑うは人や出来事を対象にする。", "踊りました": "「釣りを踊る」は意味が通らない。踊りは釣りとは組み合わさない。"}, "sentence_index": 6, "correct_answer": "しました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母に、大事な荷物をしました。", "explanation": "「荷物を運ぶ・持つ」の意味で「する」は使えない。ここは「運ぶ」と言う。"}, {"text": "母に、大事な絵をしました。", "explanation": "「絵を描く」の意味で「する」は使えない。ここは「描く」と言う。"}, {"text": "母に、大事な手紙をしました。", "explanation": "「手紙を書く」の意味で「する」は使えない。ここは「書く」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、部屋で宿題をします。", "corrected_sentence": "昨日、部屋で宿題をしました。", "error_description": "「昨日」は過去なので丁寧過去形の「しました」が必要。「します」は非過去形で、誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "しました", "is_correct": true, "explanation": "丁寧過去形。過去の出来事を肯定で丁寧に述べる形で、文中の形と一致する。"}, {"text": "します", "is_correct": false, "explanation": "丁寧な非過去形。過去の出来事を述べる文には合わない。"}, {"text": "しません", "is_correct": false, "explanation": "丁寧な否定形。文は肯定で過去を述べているので合わない。"}, {"text": "しませんでした", "is_correct": false, "explanation": "丁寧な過去の否定形。「しなかった」の意味になり、文の肯定と合わない。"}], "correct_form": "しました", "base_form": "する", "form_label": "丁寧過去形", "sentence_index": 1, "explanations": {"しました": "丁寧過去形。過去の出来事を肯定で丁寧に述べる形で、文中の形と一致する。", "します": "丁寧な非過去形。過去の出来事を述べる文には合わない。", "しません": "丁寧な否定形。文は肯定で過去を述べているので合わない。", "しませんでした": "丁寧な過去の否定形。「しなかった」の意味になり、文の肯定と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39210, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父と、川で釣りをするました。", "corrected_sentence": "父と、川で釣りをしました。", "error_description": "「する」の丁寧過去形は「しました」。「するました」は活用の誤りで、語形が崩れている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "しました", "is_correct": true, "explanation": "丁寧過去形。過去の出来事を丁寧に述べる形で、文中の形と一致する。"}, {"text": "しなかった", "is_correct": false, "explanation": "普通形の過去否定。文は肯定で丁寧さも示していないので合わない。"}, {"text": "しています", "is_correct": false, "explanation": "進行・結果の形。昨夜の完了した出来事を述べる文には合わない。"}, {"text": "しよう", "is_correct": false, "explanation": "意志・勧誘の形。過去の出来事を述べる文には合わない。"}], "correct_form": "しました", "base_form": "する", "form_label": "丁寧過去形", "sentence_index": 7, "explanations": {"しました": "丁寧過去形。過去の出来事を丁寧に述べる形で、文中の形と一致する。", "しなかった": "普通形の過去否定。文は肯定で丁寧さも示していないので合わない。", "しています": "進行・結果の形。昨夜の完了した出来事を述べる文には合わない。", "しよう": "意志・勧誘の形。過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac6f3e0f-a8cd-4630-9e37-1a8bdc789970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「世話をする」は目的語に「を」を取るので、妹の世話の直後は「を」になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、世話の対象を表す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、世話の対象を表すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「世話をする」は目的語に「を」を取るので、妹の世話の直後は「を」になる。", "に": "「に」は相手や場所を示すので、世話の対象を表す位置には入らない。", "で": "「で」は手段や場所を示すので、ここでは意味が通らない。", "へ": "「へ」は方向を示すので、世話の対象を表すことはできない。"}, "error_tags": {"に": "相手・場所を表す格助詞の誤り", "で": "手段・場所を表す格助詞の誤り", "へ": "方向を表す格助詞の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「世話をしてくれました」の「世話」は目的語に「を」を取るので、猫の直後は「を」になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、世話の対象を表す位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すので、世話の対象を表すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、ここでは意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「世話をしてくれました」の「世話」は目的語に「を」を取るので、猫の直後は「を」になる。", "が": "「が」は主語を示すので、世話の対象を表す位置には入らない。", "と": "「と」は相手を示すので、世話の対象を表すことはできない。", "より": "「より」は比較を示すので、ここでは意味が通らない。"}, "error_tags": {"が": "主語を表す格助詞の誤り", "と": "相手を表す格助詞の誤り", "より": "比較を表す格助詞の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "だれかのために、なにかをすることです。", "primary_collocate": null, "pronunciation": "せわをする", "ipa": "sewa o sɯɾɯ", "syllable_count": 5, "sentences": [{"text": "毎朝、犬の世話をするのが私の仕事です。", "target_word": "世話をする", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、犬[いぬ]の世話[せわ]をするのが私[わたし]の仕事[しごと]です。", "sentence_source": "generated"}, {"text": "母が病気のとき、わたしが妹の世話をしました。", "target_word": "世話をしました", "complexity_tier": "T3", "furigana": "母[はは]が病気[びょうき]のとき、わたしが妹[いもうと]の世話[せわ]をしました。", "sentence_source": "generated"}, {"text": "田中さんは、おばあさんの世話をするために仕事を休んだ。", "target_word": "世話をする", "complexity_tier": "T3", "furigana": "田中[たなか]さんは、おばあさんの世話[せわ]をするために仕事[しごと]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "兄は子どもたちの世話をして、宿題も見てくれた。", "target_word": "世話をして", "complexity_tier": "T3", "furigana": "兄[あに]は子[こ]どもたちの世話[せわ]をして、宿題[しゅくだい]も見[み]てくれた。", "sentence_source": "generated"}, {"text": "留学生の世話をしたので、友だちがたくさんできた。", "target_word": "世話をした", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]の世話[せわ]をしたので、友[とも]だちがたくさんできた。", "sentence_source": "generated"}, {"text": "毎日花に水をやり、世話をしているから、きれいに咲く。", "target_word": "世話をして", "complexity_tier": "T3", "furigana": "毎日[まいにち]花[はな]に水[みず]をやり、世話[せわ]をしているから、きれいに咲[さ]く。", "sentence_source": "generated"}, {"text": "入院中の父の世話をするため、毎日病院へ通った。", "target_word": "世話をする", "complexity_tier": "T3", "furigana": "入院中[にゅういんちゅう]の父[ちち]の世話[せわ]をするため、毎日[まいにち]病院[びょういん]へ通[かよ]った。", "sentence_source": "generated"}, {"text": "彼女は、近所の猫の世話をしてくれました。", "target_word": "世話をして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、近所[きんじょ]の猫[ねこ]の世話[せわ]をしてくれました。", "sentence_source": "generated"}, {"text": "新入社員の世話をする係に、先輩が選ばれた。", "target_word": "世話をする", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]の世話[せわ]をする係[かかり]に、先輩[せんぱい]が選[えら]ばれた。", "sentence_source": "generated"}, {"text": "休みの日は、庭の植物の世話をして過ごす。", "target_word": "世話をして", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、庭[にわ]の植物[しょくぶつ]の世話[せわ]をして過[す]ごす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "世話をする", "label": "終止形"}, {"form": "世話をします", "label": "丁寧形"}, {"form": "世話をしました", "label": "丁寧過去形"}, {"form": "世話をして", "label": "て形"}, {"form": "世話をしない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "世話をする=人・動物・植物のために面倒を見て、必要なことをしてやる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世話をする", "is_correct": true, "explanation": "面倒を見て必要なことをするという意味。犬の世話が仕事だという文に合う。"}, {"text": "世話を断る", "is_correct": false, "explanation": "依頼や申し出を断る意味で、犬の面倒を見る仕事の説明とは合わない。"}, {"text": "世話を忘れる", "is_correct": false, "explanation": "面倒を見ることを忘れる意味で、仕事の内容として成立しない。"}, {"text": "世話を怠る", "is_correct": false, "explanation": "面倒を見るのをおろそかにする意味で、仕事の説明には合わない。"}], "explanations": {"世話をする": "面倒を見て必要なことをするという意味。犬の世話が仕事だという文に合う。", "世話を断る": "依頼や申し出を断る意味で、犬の面倒を見る仕事の説明とは合わない。", "世話を忘れる": "面倒を見ることを忘れる意味で、仕事の内容として成立しない。", "世話を怠る": "面倒を見るのをおろそかにする意味で、仕事の説明には合わない。"}, "sentence_index": 0, "correct_answer": "世話をする"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友人の誤字の世話をした。", "explanation": "ここは〈訂正する〉の意味。世話をするは面倒を見ることで、誤字を直す文には合わない。"}, {"text": "大切な書類は金庫で世話をしている。", "explanation": "ここは〈保管する〉の意味。世話をするは人や動植物の面倒を見ることで、物をしまって守る文には合わない。"}, {"text": "相手の意見に世話をした。", "explanation": "ここは〈反論する〉の意味。世話をするは面倒を見ることで、相手の意見に言い返す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世話をする", "is_correct": true, "explanation": "面倒を見るという意味。入院中の父の面倒を見るために通ったという文に合う。"}, {"text": "世話を断つ", "is_correct": false, "explanation": "関係を断つ意味で、通院の理由として合わない。"}, {"text": "世話を汚す", "is_correct": false, "explanation": "汚すという意味で、面倒を見る理由とは結びつかない。"}, {"text": "世話を隠す", "is_correct": false, "explanation": "隠すという意味で、通う理由と合わない。"}], "explanations": {"世話をする": "面倒を見るという意味。入院中の父の面倒を見るために通ったという文に合う。", "世話を断つ": "関係を断つ意味で、通院の理由として合わない。", "世話を汚す": "汚すという意味で、面倒を見る理由とは結びつかない。", "世話を隠す": "隠すという意味で、通う理由と合わない。"}, "sentence_index": 6, "correct_answer": "世話をする"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で、難しい問題の世話をした。", "explanation": "ここは〈解決する〉の意味。世話をするは面倒を見ることで、問題を片づける文には合わない。"}, {"text": "毎晩、夜空の星の世話をして過ごす。", "explanation": "ここは〈観察する〉の意味。世話をするは面倒を見ることで、星をじっと見る文には合わない。"}, {"text": "生徒の質問に世話をした。", "explanation": "ここは〈答える〉の意味。世話をするは面倒を見ることで、質問への返答には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は毎週、祖母の世話がしに実家へ帰る。", "corrected_sentence": "母は毎週、祖母の世話をしに実家へ帰る。", "error_description": "「世話をする」の目的語は「を」で示す。「世話が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "世話をしました", "is_correct": true, "explanation": "丁寧過去形。妹の面倒を見たという過去の出来事に合う。"}, {"text": "世話をしまして", "is_correct": false, "explanation": "連用中止の丁寧形。文末に置けず、文が完結しない。"}, {"text": "世話をしたくて", "is_correct": false, "explanation": "て形の願望。文末に置けず、文が完結しない。"}, {"text": "世話をしていて", "is_correct": false, "explanation": "進行のて形。文末に置けず、文が完結しない。"}], "correct_form": "世話をしました", "base_form": "世話をする", "form_label": "丁寧過去形", "sentence_index": 1, "explanations": {"世話をしました": "丁寧過去形。妹の面倒を見たという過去の出来事に合う。", "世話をしまして": "連用中止の丁寧形。文末に置けず、文が完結しない。", "世話をしたくて": "て形の願望。文末に置けず、文が完結しない。", "世話をしていて": "進行のて形。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39214, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は、祖父の世話をするてから出かける。", "corrected_sentence": "週末は、祖父の世話をしてから出かける。", "error_description": "て形は「して」。「するて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "世話をして", "is_correct": true, "explanation": "て形。「世話をしてくれました」の一部で、て形を含む文の形に合う。"}, {"text": "世話をした", "is_correct": false, "explanation": "過去形で、この文の形とは合わない。"}, {"text": "世話をしない", "is_correct": false, "explanation": "否定形で、この文の形と合わない。"}, {"text": "世話をしろ", "is_correct": false, "explanation": "命令形で、この文の形とは合わない。"}], "correct_form": "世話をして", "base_form": "世話をする", "form_label": "て形", "sentence_index": 7, "explanations": {"世話をして": "て形。「世話をしてくれました」の一部で、て形を含む文の形に合う。", "世話をした": "過去形で、この文の形とは合わない。", "世話をしない": "否定形で、この文の形と合わない。", "世話をしろ": "命令形で、この文の形とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「日曜から始まる」は起点を表し、カレンダーの説明として合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「日曜で始まる」は起点を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「日曜を始まる」は「始まる」が目的語を取らないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、起点の「日曜へ始まる」とは続かない。"}], "correct_answer": "から", "explanations": {"から": "「日曜から始まる」は起点を表し、カレンダーの説明として合う。", "で": "「で」は場所や手段を表すので、「日曜で始まる」は起点を表せない。", "を": "「日曜を始まる」は「始まる」が目的語を取らないので不自然。", "へ": "「へ」は方向を表すので、起点の「日曜へ始まる」とは続かない。"}, "error_tags": {"で": "place/means", "を": "object", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「来週の日曜」は来週を日曜に続けて修飾する「の」で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「来週を日曜」は目的語にならず、日曜を修飾できない。"}, {"text": "に", "is_correct": false, "explanation": "「来週に日曜」は時点の「に」になり、二つの名詞を並べる形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「来週で日曜」は場所や手段の「で」になり、成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「来週の日曜」は来週を日曜に続けて修飾する「の」で、正しい。", "を": "「来週を日曜」は目的語にならず、日曜を修飾できない。", "に": "「来週に日曜」は時点の「に」になり、二つの名詞を並べる形にならない。", "で": "「来週で日曜」は場所や手段の「で」になり、成り立たない。"}, "error_tags": {"を": "object", "に": "time point", "で": "place/means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一週間のうち、最初の曜日である日曜日のこと。", "primary_collocate": null, "pronunciation": "にちよう", "ipa": "nitɕijoː", "syllable_count": 4, "sentences": [{"text": "日曜は、一週間の最初の日です。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]は、一週間[いっしゅうかん]の最初[さいしょ]の日[ひ]です。", "sentence_source": "generated"}, {"text": "カレンダーは、日曜から始まるものもあります。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "カレンダーは、日曜[にちよう]から始[はじ]まるものもあります。", "sentence_source": "generated"}, {"text": "日曜の次の日は月曜です。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]の次[つぎ]の日[ひ]は月曜[げつよう]です。", "sentence_source": "generated"}, {"text": "この図書館は日曜だけ休みです。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "この図書館[としょかん]は日曜[にちよう]だけ休[やす]みです。", "sentence_source": "generated"}, {"text": "日曜に映画を見る約束をしました。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]に映画[えいが]を見[み]る約束[やくそく]をしました。", "sentence_source": "generated"}, {"text": "土曜は忙しかったですが、日曜は何もありませんでした。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "土曜[どよう]は忙[いそが]しかったですが、日曜[にちよう]は何[なに]もありませんでした。", "sentence_source": "generated"}, {"text": "日曜の教会には、多くの人が集まります。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]の教会[きょうかい]には、多[おお]くの人[ひと]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "来週の日曜、妹の誕生日会をします。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の日曜[にちよう]、妹[いもうと]の誕生日会[たんじょうびかい]をします。", "sentence_source": "generated"}, {"text": "日曜になると、父は朝から釣りに出かけます。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]になると、父[ちち]は朝[あさ]から釣[つ]りに出[で]かけます。", "sentence_source": "generated"}, {"text": "日曜のバスは、本数が少ないです。", "target_word": "日曜", "complexity_tier": "T3", "furigana": "日曜[にちよう]のバスは、本数[ほんすう]が少[すく]ないです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日曜", "label": "基本形"}, {"form": "日曜に", "label": "時"}], "register": "neutral", "sense_fingerprint": "一週間の最初の曜日としての日曜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日曜", "is_correct": true, "explanation": "「日曜は、一週間の最初の日です」は曜日の日曜として正しい。"}, {"text": "夕食", "is_correct": false, "explanation": "夕食は食事なので、「一週間の最後の日」の主語にはならない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は個人の記念日で、一週間の区切りを表さないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態を表すので、「一週間の最後の日」とは結びつかない。"}], "explanations": {"日曜": "「日曜は、一週間の最初の日です」は曜日の日曜として正しい。", "夕食": "夕食は食事なので、「一週間の最後の日」の主語にはならない。", "誕生日": "誕生日は個人の記念日で、一週間の区切りを表さないので合わない。", "天気": "天気は空の状態を表すので、「一週間の最後の日」とは結びつかない。"}, "sentence_index": 0, "correct_answer": "日曜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日曜が強くて、汗が止まりません。", "explanation": "ここは〈日差し〉の意味。日曜は曜日で、日の光の強さは表せない。"}, {"text": "日曜が西に沈んで、空が暗くなりました。", "explanation": "ここは〈日没〉の意味。日曜は太陽が沈むことを表さないので合わない。"}, {"text": "日曜が続いて、畑が乾きました。", "explanation": "ここは〈日照り〉の意味。日曜は曜日で、雨が降らない状態は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日曜", "is_correct": true, "explanation": "「日曜の教会には、多くの人が集まります」は礼拝の日の曜日として自然。"}, {"text": "病院", "is_correct": false, "explanation": "「病院の教会」は場所の組み合わせが成り立たず、文に入らない。"}, {"text": "図書館", "is_correct": false, "explanation": "「図書館の教会」は場所が矛盾するので、この文には合わない。"}, {"text": "駅", "is_correct": false, "explanation": "「駅の教会」は場所が矛盾するので、人が集まる文とは合わない。"}], "explanations": {"日曜": "「日曜の教会には、多くの人が集まります」は礼拝の日の曜日として自然。", "病院": "「病院の教会」は場所の組み合わせが成り立たず、文に入らない。", "図書館": "「図書館の教会」は場所が矛盾するので、この文には合わない。", "駅": "「駅の教会」は場所が矛盾するので、人が集まる文とは合わない。"}, "sentence_index": 6, "correct_answer": "日曜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜明けに日曜が昇り、空が明るくなりました。", "explanation": "ここは〈日の出〉の意味。日曜は曜日で、太陽が昇る意味では使えない。"}, {"text": "毎晩、寝る前に日曜を書いて、一日を振り返ります。", "explanation": "ここは〈日記〉の意味。日曜は曜日で、書いて残すものではない。"}, {"text": "真夏の海で遊んだら、腕に日曜ができました。", "explanation": "ここは〈日焼け〉の意味。日曜は皮膚の状態を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日曜へ、友達と買い物に行きました。", "corrected_sentence": "日曜に、友達と買い物に行きました。", "error_description": "時点の日曜には「へ」（方向）ではなく「に」（時点）を付ける。誤: 日曜へ / 正: 日曜に。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の日曜で、妹と食事に行きます。", "corrected_sentence": "来週の日曜に、妹と食事に行きます。", "error_description": "時点を表す日曜には「で」ではなく「に」を付ける。誤: 日曜で / 正: 日曜に。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、活動そのものを対象にすると「拾う」と結びつかず意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や時点を示すので、活動を手段として述べる文には合わない。"}, {"text": "で", "is_correct": true, "explanation": "「ボランティア活動で」は手段を表し、その活動の中で公園のごみを拾ったという意味になる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、活動の中で拾ったという手段の意味にならない。"}], "correct_answer": "で", "explanations": {"を": "「を」は目的語を示すが、活動そのものを対象にすると「拾う」と結びつかず意味が合わない。", "に": "「に」は方向や時点を示すので、活動を手段として述べる文には合わない。", "で": "「ボランティア活動で」は手段を表し、その活動の中で公園のごみを拾ったという意味になる。", "の": "「の」は所属や修飾を示すので、活動の中で拾ったという手段の意味にならない。"}, "error_tags": {"を": "目的語", "に": "方向・時点", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここでは仲間が所属する活動を示す必要があるので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べて示すので、活動と仲間が並んで増える形になり、「増えて」の主語として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、活動の仲間を表す文には合わない。"}, {"text": "の", "is_correct": true, "explanation": "「ボランティア活動の仲間」は、活動に所属する仲間という意味で正しい。"}], "correct_answer": "の", "explanations": {"を": "「を」は目的語を示すが、ここでは仲間が所属する活動を示す必要があるので合わない。", "と": "「と」は並べて示すので、活動と仲間が並んで増える形になり、「増えて」の主語として不自然。", "へ": "「へ」は方向を示すので、活動の仲間を表す文には合わない。", "の": "「ボランティア活動の仲間」は、活動に所属する仲間という意味で正しい。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなでいっしょに、だれかのために何かをする活動のことです。", "primary_collocate": null, "pronunciation": "ぼらんてぃあかつどう", "ipa": "boɾaɴtia kat͡sɯdoː", "syllable_count": 7, "sentences": [{"text": "休みの日に、みんなでボランティア活動をしました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に、みんなでボランティア活動[かつどう]をしました。", "sentence_source": "generated"}, {"text": "ボランティア活動で、公園のごみを拾いました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]で、公園[こうえん]のごみを拾[ひろ]いました。", "sentence_source": "generated"}, {"text": "学校のボランティア活動に、友だちといっしょに参加します。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "学校[がっこう]のボランティア活動[かつどう]に、友[とも]だちといっしょに参加[さんか]します。", "sentence_source": "generated"}, {"text": "ボランティア活動をすると、人の役に立てて嬉しいです。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]をすると、人[ひと]の役[やく]に立[た]てて嬉[うれ]しいです。", "sentence_source": "generated"}, {"text": "お年寄りの家を訪ねるボランティア活動に、毎週行っています。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "お年寄[としよ]りの家[いえ]を訪[たず]ねるボランティア活動[かつどう]に、毎週[まいしゅう]行[い]っています。", "sentence_source": "generated"}, {"text": "ボランティア活動は、お金をもらわずに、だれかのためにすることです。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[ぼらんてぃあかつどう]は、お金[かね]をもらわずに、だれかのためにすることです。", "sentence_source": "generated"}, {"text": "町をきれいにするボランティア活動が、日曜日にあります。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "町[まち]をきれいにするボランティア活動[かつどう]が、日曜日[にちようび]にあります。", "sentence_source": "generated"}, {"text": "ボランティア活動の仲間が増えて、にぎやかになりました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]の仲間[なかま]が増[ふ]えて、にぎやかになりました。", "sentence_source": "generated"}, {"text": "台風のあと、ボランティア活動で水にぬれた家具を運びました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、ボランティア活動[かつどう]で水[みず]にぬれた家具[かぐ]を運[はこ]びました。", "sentence_source": "generated"}, {"text": "ボランティア活動に興味があるので、先生に相談しました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]に興味[きょうみ]があるので、先生[せんせい]に相談[そうだん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボランティア活動", "label": "基本形"}], "register": "中立", "sense_fingerprint": "みんなで人のために何かをする活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "台風", "is_correct": false, "explanation": "台風は自然現象で、人が「みんなでする」ものではないので文が成り立たない。"}, {"text": "ボランティア活動", "is_correct": true, "explanation": "「みんなで〜をしました」に入る、人のために皆でする活動の名前。"}, {"text": "地震", "is_correct": false, "explanation": "地震は起こる出来事で、「〜をする」対象にならない。"}, {"text": "大雨", "is_correct": false, "explanation": "大雨は降る現象で、皆で行う活動の名前としては合わない。"}], "explanations": {"台風": "台風は自然現象で、人が「みんなでする」ものではないので文が成り立たない。", "ボランティア活動": "「みんなで〜をしました」に入る、人のために皆でする活動の名前。", "地震": "地震は起こる出来事で、「〜をする」対象にならない。", "大雨": "大雨は降る現象で、皆で行う活動の名前としては合わない。"}, "sentence_index": 0, "correct_answer": "ボランティア活動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボランティア活動を箱に詰めて、郵便で送りました。", "explanation": "ここは〈荷物〉の意味。ボランティア活動は形のある物ではないので、箱に詰めて送ることはできない。"}, {"text": "ボランティア活動の屋上で、洗濯物を干しました。", "explanation": "ここは〈建物〉の意味。ボランティア活動は場所ではないので、屋上があるという話とは合わない。"}, {"text": "ボランティア活動が三人、教室に入ってきました。", "explanation": "ここは〈人〉の意味。ボランティア活動は人ではないので、三人が教室に入ってくるという話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、「町をきれいにする」行事の名前にならない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、町をきれいにする活動の名前として文が成り立たない。"}, {"text": "雨漏り", "is_correct": false, "explanation": "雨漏りは建物の不具合で、日曜日にある行事の名前ではない。"}, {"text": "ボランティア活動", "is_correct": true, "explanation": "町をきれいにする活動が日曜日にある、という文に合う活動名。"}], "explanations": {"夕焼け": "夕焼けは空の現象で、「町をきれいにする」行事の名前にならない。", "雷": "雷は自然現象で、町をきれいにする活動の名前として文が成り立たない。", "雨漏り": "雨漏りは建物の不具合で、日曜日にある行事の名前ではない。", "ボランティア活動": "町をきれいにする活動が日曜日にある、という文に合う活動名。"}, "sentence_index": 6, "correct_answer": "ボランティア活動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボランティア活動を歌いながら、掃除をしました。", "explanation": "ここは〈歌〉の意味。ボランティア活動は歌う曲ではないので、歌いながら掃除をするという話とは合わない。"}, {"text": "ボランティア活動に勝ったので、先生に報告しました。", "explanation": "ここは〈試合〉の意味。ボランティア活動は競うものではないので、勝つという話とは合わない。"}, {"text": "ボランティア活動を焼いて、おやつにしました。", "explanation": "ここは〈食べ物〉の意味。ボランティア活動は焼いて食べるものではないので、おやつにしたという話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週のボランティア活動を、友だちといっしょに参加します。", "corrected_sentence": "来週のボランティア活動に、友だちといっしょに参加します。", "error_description": "「参加する」は「に」を取るので、「を」は誤り。正しい形は「ボランティア活動に参加する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週のボランティア活動を、町の公園で行われました。", "corrected_sentence": "先週のボランティア活動は、町の公園で行われました。", "error_description": "「行われる」は目的語の「を」を取らない。主題の「は」を使い、「ボランティア活動は、〜行われました」とするのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "を", "is_correct": false, "explanation": "「を」にすると活動が目的語になり、無料で時間と力を提供するという説明文の主題が立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や時点を示すので、説明の主題として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、活動の定義を述べる主題の役割を果たさない。"}, {"text": "は", "is_correct": true, "explanation": "「ボランティア活動は、〜ことです」の形で、定義の主題を示す正しい助詞。"}], "correct_answer": "は", "explanations": {"を": "「を」にすると活動が目的語になり、無料で時間と力を提供するという説明文の主題が立たない。", "に": "「に」は方向や時点を示すので、説明の主題として文が成り立たない。", "と": "「と」は並列や相手を示すので、活動の定義を述べる主題の役割を果たさない。", "は": "「ボランティア活動は、〜ことです」の形で、定義の主題を示す正しい助詞。"}, "error_tags": {"を": "目的語", "に": "方向・時点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「ボランティア活動がするつもり」では活動が主語になり、「する」の目的語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、活動を「する」の対象として示す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「する」の目的語を表せない。"}, {"text": "を", "is_correct": true, "explanation": "「ボランティア活動をする」の目的語を示す正しい助詞。"}], "correct_answer": "を", "explanations": {"が": "「ボランティア活動がするつもり」では活動が主語になり、「する」の目的語にならず不自然。", "へ": "「へ」は方向を示すので、活動を「する」の対象として示す文には合わない。", "の": "「の」は所属や修飾を示すので、「する」の目的語を表せない。", "を": "「ボランティア活動をする」の目的語を示す正しい助詞。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の時間や労力を無料で提供し、社会や地域のために役立つ活動のこと。", "primary_collocate": null, "pronunciation": "ぼらんてぃあかつどう", "ipa": "boɾaɴtia kat͡sɯdoː", "syllable_count": 7, "sentences": [{"text": "彼は地域のボランティア活動に、毎月参加しています。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "彼[かれ]は地域[ちいき]のボランティア活動[かつどう]に、毎月[まいつき]参加[さんか]しています。", "sentence_source": "generated"}, {"text": "ボランティア活動は、無料で自分の時間と力を提供することです。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]は、無料[むりょう]で自分[じぶん]の時間[じかん]と力[ちから]を提供[ていきょう]することです。", "sentence_source": "generated"}, {"text": "大学生のときに、海外でボランティア活動を経験しました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "大学生[だいがくせい]のときに、海外[かいがい]でボランティア活動[かつどう]を経験[けいけん]しました。", "sentence_source": "generated"}, {"text": "災害の被災地では、多くのボランティア活動が支えになりました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "災害[さいがい]の被災地[ひさいち]では、多[おお]くのボランティア活動[かつどう]が支[ささ]えになりました。", "sentence_source": "generated"}, {"text": "ボランティア活動を通じて、地域の人と知り合いました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]を通[つう]じて、地域[ちいき]の人[ひと]と知[し]り合[あ]いました。", "sentence_source": "generated"}, {"text": "会社は、社員のボランティア活動を応援しています。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、社員[しゃいん]のボランティア活動[かつどう]を応援[おうえん]しています。", "sentence_source": "generated"}, {"text": "ボランティア活動を続けるには、無理のない時間の使い方が大切です。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]を続[つづ]けるには、無理[むり]のない時間[じかん]の使[つか]い方[かた]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "退職後は、子ども食堂でボランティア活動をするつもりです。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "退職後[たいしょくご]は、子[こ]ども食堂[しょくどう]でボランティア活動[かつどう]をするつもりです。", "sentence_source": "generated"}, {"text": "ボランティア活動の報告書を、市役所に出しました。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]の報告書[ほうこくしょ]を、市役所[しやくしょ]に出[だ]しました。", "sentence_source": "generated"}, {"text": "ボランティア活動は、仕事とは違って給料が出ません。", "target_word": "ボランティア活動", "complexity_tier": "T3", "furigana": "ボランティア活動[かつどう]は、仕事[しごと]とは違[ちが]って給料[きゅうりょう]が出[で]ません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ボランティア活動", "label": "基本形"}], "register": "中立", "sense_fingerprint": "時間や労力を無料で提供し、社会や地域に役立つ活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6435f60-912e-4507-b563-edf7dbd7d03d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停電", "is_correct": false, "explanation": "停電は起きる出来事で、地域の活動に参加するものではない。"}, {"text": "ボランティア活動", "is_correct": true, "explanation": "「地域の〜に参加する」に入る、無料で社会に役立つ活動。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、参加の対象にならない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、毎月参加する対象ではない。"}], "explanations": {"停電": "停電は起きる出来事で、地域の活動に参加するものではない。", "ボランティア活動": "「地域の〜に参加する」に入る、無料で社会に役立つ活動。", "夕焼け": "夕焼けは空の現象で、参加の対象にならない。", "雷": "雷は自然現象で、毎月参加する対象ではない。"}, "sentence_index": 0, "correct_answer": "ボランティア活動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボランティア活動を、一日二回飲みます。", "explanation": "ここは〈薬〉の意味。ボランティア活動は飲むものではないので、一日二回飲むという話とは合わない。"}, {"text": "ボランティア活動を運転して、空港まで行きました。", "explanation": "ここは〈車〉の意味。ボランティア活動は運転する乗り物ではないので、運転して空港まで行くという話とは合わない。"}, {"text": "ボランティア活動を飼っていて、毎朝散歩に連れて行きます。", "explanation": "ここは〈ペット〉の意味。ボランティア活動は生き物ではないので、飼って散歩に連れて行く話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "台風", "is_correct": false, "explanation": "台風は続けるものではないので、「〜を続けるには」に入らない。"}, {"text": "夕立", "is_correct": false, "explanation": "夕立は一時的な雨で、続けて取り組むものではない。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は飛んでくるもので、続ける活動の対象にならない。"}, {"text": "ボランティア活動", "is_correct": true, "explanation": "続けて行う活動で、無理のない時間の使い方が必要だという文に合う。"}], "explanations": {"台風": "台風は続けるものではないので、「〜を続けるには」に入らない。", "夕立": "夕立は一時的な雨で、続けて取り組むものではない。", "花粉": "花粉は飛んでくるもので、続ける活動の対象にならない。", "ボランティア活動": "続けて行う活動で、無理のない時間の使い方が必要だという文に合う。"}, "sentence_index": 6, "correct_answer": "ボランティア活動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボランティア活動を畑に植えて、夏に収穫しました。", "explanation": "ここは〈植物〉の意味。ボランティア活動は植えて育てるものではないので、畑に植えて収穫する話とは合わない。"}, {"text": "ボランティア活動を腕に巻いて、時間を確かめました。", "explanation": "ここは〈腕時計〉の意味。ボランティア活動は身につけて時間を見る物ではないので、腕に巻いて時間を確かめる話とは合わない。"}, {"text": "ボランティア活動で、選手が順位を争います。", "explanation": "ここは〈競技〉の意味。ボランティア活動は順位を争うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は地域のボランティア活動を、毎週参加しています。", "corrected_sentence": "彼は地域のボランティア活動に、毎週参加しています。", "error_description": "「参加する」は「に」を取るので、「を」は誤り。正しくは「ボランティア活動に参加する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39223, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "退職後は、子ども食堂のボランティア活動を参加するつもりです。", "corrected_sentence": "退職後は、子ども食堂のボランティア活動に参加するつもりです。", "error_description": "「参加する」は「に」を取るので、「を」は誤り。正しくは「ボランティア活動に参加する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a89e440-6cef-4321-b9d6-f64a47f8ed14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大人が三百円です」の「が」は主格で、「大人」が料金の主体として文を成り立たせる。"}, {"text": "を", "is_correct": false, "explanation": "「大人を三百円です」は目的語の形になり、料金の文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「大人に三百円です」は相手を表す形になり、料金の文として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「大人へ三百円です」は方向を表す形になり、料金の文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「大人が三百円です」の「が」は主格で、「大人」が料金の主体として文を成り立たせる。", "を": "「大人を三百円です」は目的語の形になり、料金の文として成り立たない。", "に": "「大人に三百円です」は相手を表す形になり、料金の文として意味が通らない。", "へ": "「大人へ三百円です」は方向を表す形になり、料金の文として成り立たない。"}, "error_tags": {"を": "対象", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おとなは、こどもではない人です。", "primary_collocate": null, "pronunciation": "おとな", "ipa": "otona", "syllable_count": 3, "sentences": [{"text": "大人は仕事をして、お金をかせぎます。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]は仕事[しごと]をして、お金[かね]をかせぎます。", "sentence_source": "generated"}, {"text": "この電車の料金は、大人が三百円で、子どもが百五十円です。", "target_word": "大人", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]の料金[りょうきん]は、大人[おとな]が三百円[さんびゃくえん]で、子[こ]どもが百五十円[ひゃくごじゅうえん]です。", "sentence_source": "generated"}, {"text": "子どもだけでは入れません。大人と一緒に来てください。", "target_word": "大人", "complexity_tier": "T3", "furigana": "子[こ]どもだけでは入[はい]れません。大人[おとな]と一緒[いっしょ]に来[き]てください。", "sentence_source": "generated"}, {"text": "わたしの父も母も、大人です。", "target_word": "大人", "complexity_tier": "T3", "furigana": "わたしの父[ちち]も母[はは]も、大人[おとな]です。", "sentence_source": "generated"}, {"text": "大人になったら、車を買いたいです。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]になったら、車[くるま]を買[か]いたいです。", "sentence_source": "generated"}, {"text": "この本は大人のための本で、子どもには少し難しいです。", "target_word": "大人", "complexity_tier": "T3", "furigana": "この本[ほん]は大人[おとな]のための本[ほん]で、子[こ]どもには少[すこ]し難[むずか]しいです。", "sentence_source": "generated"}, {"text": "公園で大人たちがボールで遊んでいます。", "target_word": "大人", "complexity_tier": "T3", "furigana": "公園[こうえん]で大人[おとな]たちがボールで遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "大人は夜おそくまで起きていてもいいです。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]は夜[よる]おそくまで起[お]きていてもいいです。", "sentence_source": "generated"}, {"text": "大人も子どもも、このまつりを楽しみます。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]も子[こ]どもも、このまつりを楽[たの]しみます。", "sentence_source": "generated"}, {"text": "弟はまだ子どもですが、姉はもう大人です。", "target_word": "大人", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ子[こ]どもですが、姉[あね]はもう大人[おとな]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大人", "label": "基本形"}, {"form": "大人たち", "label": "複数形"}, {"form": "大人の", "label": "連体形(の)"}], "register": "polite", "sense_fingerprint": "子どもではない年上の人、料金や場面で子どもと区別される成人(大人料金・大人と子ども)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: かせぎ (Zipf 2.23)','sentence 7 above tier T2: contains vocabulary far above tier T2: おそく (Zipf 2.34)']::text[], '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大人", "is_correct": true, "explanation": "「大人」は成人を指し、「___は仕事をしてお金をかせぎます」で成り立つ。"}, {"text": "猫", "is_correct": false, "explanation": "「猫は仕事をしてお金をかせぎます」は意味が通らず、文として成り立たない。"}, {"text": "木", "is_correct": false, "explanation": "「木は仕事をしてお金をかせぎます」は主体として不自然で、文が成り立たない。"}, {"text": "海", "is_correct": false, "explanation": "「海は仕事をしてお金をかせぎます」は主体として不自然で、文が成り立たない。"}], "explanations": {"大人": "「大人」は成人を指し、「___は仕事をしてお金をかせぎます」で成り立つ。", "猫": "「猫は仕事をしてお金をかせぎます」は意味が通らず、文として成り立たない。", "木": "「木は仕事をしてお金をかせぎます」は主体として不自然で、文が成り立たない。", "海": "「海は仕事をしてお金をかせぎます」は主体として不自然で、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この子は十歳ですが、もう大人です。", "explanation": "「大人」は子どもではない人を指すので、十歳の子を「もう大人」とするのは定義に反する。"}, {"text": "お菓子をまとめて大人買いしたら、子どもが喜んだ。", "explanation": "ここは〈大人買い〉（まとめて買うこと）の意味。〈大人〉の定義は人を指すので、買い方を表す語とは合わない。"}, {"text": "その子は大人しく、ほとんど声を出しません。", "explanation": "ここは〈大人しい〉（静かで控えめ）の意味。子どもの静かな様子を表す語で、〈子どもではない人〉の〈大人〉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大人", "is_correct": true, "explanation": "「大人たち」は成人の集まりを指し、「公園で___たちがボールで遊んでいます」で成り立つ。"}, {"text": "車", "is_correct": false, "explanation": "「公園で車たちがボールで遊んでいます」は主体として成り立たず、意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "「公園で雨たちがボールで遊んでいます」は意味が通らず、文として成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "「公園で空たちがボールで遊んでいます」は主体として不自然で、文が成り立たない。"}], "explanations": {"大人": "「大人たち」は成人の集まりを指し、「公園で___たちがボールで遊んでいます」で成り立つ。", "車": "「公園で車たちがボールで遊んでいます」は主体として成り立たず、意味が通らない。", "雨": "「公園で雨たちがボールで遊んでいます」は意味が通らず、文として成り立たない。", "空": "「公園で空たちがボールで遊んでいます」は主体として不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子は十歳ですが、大人気の選手です。", "explanation": "ここは〈大人気〉（非常に人気があること）の意味。人そのものを指す〈大人〉の定義とは別の語なので合わない。"}, {"text": "この子は十歳で、もう大人の味が分かる。", "explanation": "ここは〈大人の味〉（洗練された味）の意味。十歳の子を指す〈大人〉の定義には合わない。"}, {"text": "大の大人が、子どもの前で泣きました。", "explanation": "ここは〈大の大人〉（いい年をした）の意味。固定表現で、〈子どもではない人〉の〈大人〉とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大人を百円、子どもは五十円です。", "corrected_sentence": "大人は百円、子どもは五十円です。", "error_description": "料金の主題を示す「は」を「を」にした誤り。「を」は目的語を表すので、料金を述べる文では使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39224, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は大人でにあこがれています。", "corrected_sentence": "弟は大人にあこがれています。", "error_description": "「大人」の後に余計な「で」が入った誤り。「あこがれる」は「に」で対象を取るので、「で」を除く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「なる」は「に」で変化後の状態を取るので、「大人になると」となる。"}, {"text": "が", "is_correct": false, "explanation": "「大人が なると」は「なる」の補語として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「大人を なると」は「なる」が目的語を取らないので誤り。"}, {"text": "で", "is_correct": false, "explanation": "「大人で なると」は「なる」の変化先を表せず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「なる」は「に」で変化後の状態を取るので、「大人になると」となる。", "が": "「大人が なると」は「なる」の補語として成り立たない。", "を": "「大人を なると」は「なる」が目的語を取らないので誤り。", "で": "「大人で なると」は「なる」の変化先を表せず、文が成り立たない。"}, "error_tags": {"が": "主格", "を": "対象", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「大人の責任」の「の」は連体修飾で、「責任」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「大人を責任として」は目的語の形になり、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「大人で責任として」は場所や手段を表す形になり、成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「大人へ責任として」は方向を表すが、ここでは意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「大人の責任」の「の」は連体修飾で、「責任」を修飾する。", "を": "「大人を責任として」は目的語の形になり、文の意味が通らない。", "で": "「大人で責任として」は場所や手段を表す形になり、成り立たない。", "へ": "「大人へ責任として」は方向を表すが、ここでは意味が通らない。"}, "error_tags": {"を": "対象", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "成長して、体も心も十分に発達した人。子どもではなくなった人。", "primary_collocate": null, "pronunciation": "おとな", "ipa": "otona", "syllable_count": 3, "sentences": [{"text": "我々大人が往々にして見落とす微小な営みを、彼は無心に、そして厳粛に刻み続けているのである。", "target_word": "大人", "complexity_tier": "T3", "furigana": "我々[われわれ]大人[おとな]が往々[おうおう]にして見落[みおと]とす微小[びしょう]な営[いとな]みを、彼[かれ]は無心[むしん]に、そして厳粛[げんしゅく]に刻[きざ]み続[つづ]けているのである。", "sentence_source": "mined"}, {"text": "大人になると、子どものころの夢を忘れてしまう人も多い。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]になると、子[こ]どものころの夢[ゆめ]を忘[わす]れてしまう人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "二十歳になれば、法律の上でも大人として扱われる。", "target_word": "大人", "complexity_tier": "T3", "furigana": "二十歳[はたち]になれば、法律[ほうりつ]の上[うえ]でも大人[おとな]として扱[あつか]われる。", "sentence_source": "generated"}, {"text": "彼は子どもの頃から大人に混じって仕事を手伝い、今では頼りにされている。", "target_word": "大人", "complexity_tier": "T3", "furigana": "彼[かれ]は子[こ]どもの頃[ころ]から大人[おとな]に混[ま]じって仕事[しごと]を手伝[てつだ]い、今[いま]では頼[たよ]りにされている。", "sentence_source": "generated"}, {"text": "大人の意見ばかりでなく、子どもの声も聞くべきだ。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]の意見[いけん]ばかりでなく、子[こ]どもの声[こえ]も聞[き]くべきだ。", "sentence_source": "generated"}, {"text": "この映画は内容が難しく、大人でも理解できないことがある。", "target_word": "大人", "complexity_tier": "T3", "furigana": "この映画[えいが]は内容[ないよう]が難[むずか]しく、大人[おとな]でも理解[りかい]できないことがある。", "sentence_source": "generated"}, {"text": "大人が約束を守らなければ、子どもも守らなくなる。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]が約束[やくそく]を守[まも]らなければ、子[こ]どもも守[まも]らなくなる。", "sentence_source": "generated"}, {"text": "大人の責任として、危険な遊びは止めさせなければならない。", "target_word": "大人", "complexity_tier": "T3", "furigana": "大人[おとな]の責任[せきにん]として、危険[きけん]な遊[あそ]びは止[と]めさせなければならない。", "sentence_source": "generated"}, {"text": "このプールは、大人と子どもで入る時間が分かれている。", "target_word": "大人", "complexity_tier": "T3", "furigana": "このプールは、大人[おとな]と子[こ]どもで入[はい]る時間[じかん]が分[わ]かれている。", "sentence_source": "generated"}, {"text": "兄は大人になって、自分の力で家賃を払い始めた。", "target_word": "大人", "complexity_tier": "T3", "furigana": "兄[あに]は大人[おとな]になって、自分[じぶん]の力[ちから]で家賃[やちん]を払[はら]い始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大人", "label": "基本形"}, {"form": "大人たち", "label": "複数形"}, {"form": "大人の", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "心身ともに成長しきった人、子どもに対する成人(大人になる・大人の責任)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 見落とす (Zipf 2.36)']::text[], '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大人", "is_correct": true, "explanation": "「大人」は成長した人を指すので、「我々___が見落とす」に入り、人の見落としとして成り立つ。"}, {"text": "猫", "is_correct": false, "explanation": "「我々」に続けて「猫が」とすると、見落とす主体として文が成り立たない。"}, {"text": "木", "is_correct": false, "explanation": "「我々」と並べて「木が」とすると、人の行為を述べる文にならない。"}, {"text": "海", "is_correct": false, "explanation": "「我々」と並べて「海が」とすると、「見落とす」の主体として意味が通らない。"}], "explanations": {"大人": "「大人」は成長した人を指すので、「我々___が見落とす」に入り、人の見落としとして成り立つ。", "猫": "「我々」に続けて「猫が」とすると、見落とす主体として文が成り立たない。", "木": "「我々」と並べて「木が」とすると、人の行為を述べる文にならない。", "海": "「我々」と並べて「海が」とすると、「見落とす」の主体として意味が通らない。"}, "sentence_index": 0, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まだ十歳の妹は、もう大人だ。", "explanation": "十歳の妹は子どもなので、成長した人を指す「大人」には当てはまらない。"}, {"text": "その子は十歳で、もう大人の年齢に達している。", "explanation": "十歳は成人の年齢ではないので、「大人」の〈成長した人〉の意味とは合わない。"}, {"text": "その子は大人しく、ほとんど声を出さない。", "explanation": "ここは〈大人しい〉（静かで控えめ）の意味。子どもの静かな様子を表す語で、〈大人〉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大人", "is_correct": true, "explanation": "「大人」は成人を指し、「___が約束を守らなければ」で大人の行いとして成り立つ。"}, {"text": "車", "is_correct": false, "explanation": "「車が約束を守らなければ」は意味が通らず、約束の主体にならない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨が約束を守らなければ」は主体として不自然で、文が成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "「空が約束を守らなければ」は意味が通らず、文の主体として合わない。"}], "explanations": {"大人": "「大人」は成人を指し、「___が約束を守らなければ」で大人の行いとして成り立つ。", "車": "「車が約束を守らなければ」は意味が通らず、約束の主体にならない。", "雨": "「雨が約束を守らなければ」は主体として不自然で、文が成り立たない。", "空": "「空が約束を守らなければ」は意味が通らず、文の主体として合わない。"}, "sentence_index": 6, "correct_answer": "大人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この子は大人買いのように、おもちゃを全部一人で持っていった。", "explanation": "ここは〈大人買い〉（まとめて買うこと）の意味。子どもの行動を指す語ではないので、〈大人〉の定義とは合わない。"}, {"text": "この子は十歳なのに、大人気を博している。", "explanation": "ここは〈大人気〉（非常に人気があること）の意味。人を指す〈大人〉の定義とは別の語なので合わない。"}, {"text": "大の大人が、子どもの前で泣いた。", "explanation": "ここは〈大の大人〉（いい年をした）の意味。固定表現で、〈成長した人〉の〈大人〉とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は大人を、責任を果たした。", "corrected_sentence": "彼は大人として、責任を果たした。", "error_description": "「大人として」（立場を表す）の「として」を「を」にした誤り。「大人」は「として」で立場を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39225, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は大人なとして、社会に出る準備をしている。", "corrected_sentence": "彼女は大人として、社会に出る準備をしている。", "error_description": "「大人なとして」の「な」は余計。名詞の「大人」はそのまま「大人として」と続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「新しい木を植える」で、植えるものを示す。"}, {"text": "が", "is_correct": false, "explanation": "「木が植える」では木が植える主体になり、文の主語「みんな」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「木へ植える」は目的語を示せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「木より植える」は比べる相手がなく、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「新しい木を植える」で、植えるものを示す。", "が": "「木が植える」では木が植える主体になり、文の主語「みんな」と合わない。", "へ": "方向を表すが、「木へ植える」は目的語を示せず、意味が通らない。", "より": "比較を表すが、「木より植える」は比べる相手がなく、文が成り立たない。"}, "error_tags": {"が": "主体の誤り", "へ": "方向の誤り", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「球根を植えた」で、植えるものを示す。"}, {"text": "と", "is_correct": false, "explanation": "「球根と植えた」は並列の形になり、植えるものを示せず、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「球根が植えた」では球根が植える主体になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「球根の植えた」では修飾先の名詞がなく、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「球根を植えた」で、植えるものを示す。", "と": "「球根と植えた」は並列の形になり、植えるものを示せず、意味が通らない。", "が": "「球根が植えた」では球根が植える主体になり、文が成り立たない。", "の": "「球根の植えた」では修飾先の名詞がなく、文が成り立たない。"}, "error_tags": {"と": "並列の誤り", "が": "主語の誤り", "の": "修飾の誤り"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "土に何かを入れて、そこから生き物を育てること。", "primary_collocate": null, "pronunciation": "うえる", "ipa": "ɯeɾɯ", "syllable_count": 3, "sentences": [{"text": "春になったので、庭にチューリップの球根を植えた。", "target_word": "植えた", "complexity_tier": "T3", "furigana": "春(はる)になったので、庭(にわ)にチューリップの球根(きゅうこん)を植(う)えた。", "sentence_source": "generated"}, {"text": "公園に新しい木を植えるために、みんなで穴を掘った。", "target_word": "植える", "complexity_tier": "T3", "furigana": "公園(こうえん)に新(あたら)しい木(き)を植(う)えるために、みんなで穴(あな)を掘(ほ)った。", "sentence_source": "generated"}, {"text": "祖母は毎年、畑にトマトの苗を植えている。", "target_word": "植えている", "complexity_tier": "T3", "furigana": "祖母(そぼ)は毎年(まいとし)、畑(はたけ)にトマトの苗(なえ)を植(う)えている。", "sentence_source": "generated"}, {"text": "雨の日は土がやわらかいので、花を植えやすい。", "target_word": "植えやすい", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)は土(つち)がやわらかいので、花(はな)を植(う)えやすい。", "sentence_source": "generated"}, {"text": "庭の隅に桜の木を植えようと、父が言った。", "target_word": "植えよう", "complexity_tier": "T3", "furigana": "庭(にわ)の隅(すみ)に桜(さくら)の木(き)を植(う)えようと、父(ちち)が言(い)った。", "sentence_source": "generated"}, {"text": "まだ寒いから、今は花の種を植えないほうがいい。", "target_word": "植えない", "complexity_tier": "T3", "furigana": "まだ寒(さむ)いから、今(いま)は花(はな)の種(たね)を植(う)えないほうがいい。", "sentence_source": "generated"}, {"text": "この野菜は夏の初めに植えれば、秋においしく食べられる。", "target_word": "植えれば", "complexity_tier": "T3", "furigana": "この野菜(やさい)は夏(なつ)の初(はじ)めに植(う)えれば、秋(あき)においしく食(た)べられる。", "sentence_source": "generated"}, {"text": "この土なら、ブルーベリーも植えられる。", "target_word": "植えられる", "complexity_tier": "T3", "furigana": "この土(つち)なら、ブルーベリーも植(う)えられる。", "sentence_source": "generated"}, {"text": "土に穴をあけて種を植え、水をたっぷりやった。", "target_word": "植え", "complexity_tier": "T3", "furigana": "土(つち)に穴(あな)をあけて種(たね)を植(う)え、水(みず)をたっぷりやった。", "sentence_source": "generated"}, {"text": "卒業の記念に、校庭に小さな松の木を植えて帰った。", "target_word": "植えて", "complexity_tier": "T3", "furigana": "卒業(そつぎょう)の記念(きねん)に、校庭(こうてい)に小(ちい)さな松(まつ)の木(き)を植(う)えて帰(かえ)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植えます", "label": "丁寧形"}, {"form": "植えた", "label": "過去形"}, {"form": "植えて", "label": "て形"}, {"form": "植えない", "label": "否定形"}, {"form": "植えれば", "label": "仮定形"}, {"form": "植えよう", "label": "意志形"}, {"form": "植えられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "苗・種・木などを土に入れて育てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植えた", "is_correct": true, "explanation": "正解。過去形で文末を言い切り、庭に球根を植えたことを表す。"}, {"text": "植えて", "is_correct": false, "explanation": "て形は文を言い切れず、「球根を植えて。」では文が途中で止まる。"}, {"text": "植え", "is_correct": false, "explanation": "連用形（語幹）は単独で文末にできず、文が成り立たない。"}, {"text": "植えられ", "is_correct": false, "explanation": "可能形の連用形で、文末を言い切れない。「植えた」の意味にもならない。"}], "explanations": {"植えた": "正解。過去形で文末を言い切り、庭に球根を植えたことを表す。", "植えて": "て形は文を言い切れず、「球根を植えて。」では文が途中で止まる。", "植え": "連用形（語幹）は単独で文末にできず、文が成り立たない。", "植えられ": "可能形の連用形で、文末を言い切れない。「植えた」の意味にもならない。"}, "sentence_index": 0, "correct_answer": "植えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "タイムカプセルを校庭の隅に植えた。", "explanation": "ここは〈埋める〉の意味。物を地中に入れて隠す意味で、生き物を育てる〈植える〉とは合わない。"}, {"text": "庭の隅に石のベンチを植えた。", "explanation": "ここは〈置く〉の意味。物をそこに据えるだけで、苗や種を入れて育てる意味ではない。"}, {"text": "花瓶に一輪の花を植えた。", "explanation": "ここは〈挿す〉の意味。切り花を容器に差す意味で、根を土に入れて育てることではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植えれば", "is_correct": true, "explanation": "正解。仮定形で「植えれば」と条件を表し、後ろの「食べられる」につながる。"}, {"text": "植える", "is_correct": false, "explanation": "辞書形のあとに読点で続けると条件がつながらず、文が成り立たない。"}, {"text": "植えよう", "is_correct": false, "explanation": "意志形になり、「植えよう、秋に」では条件を表せない。"}, {"text": "植えます", "is_correct": false, "explanation": "丁寧形は文を言い切るので、条件の「〜ば」にならない。"}], "explanations": {"植えれば": "正解。仮定形で「植えれば」と条件を表し、後ろの「食べられる」につながる。", "植える": "辞書形のあとに読点で続けると条件がつながらず、文が成り立たない。", "植えよう": "意志形になり、「植えよう、秋に」では条件を表せない。", "植えます": "丁寧形は文を言い切るので、条件の「〜ば」にならない。"}, "sentence_index": 6, "correct_answer": "植えれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑一面に肥料を植えた。", "explanation": "ここは〈撒く〉の意味。肥料を土にまく場面で、苗や種を土に入れて育てる意味ではない。"}, {"text": "庭に池を植えた。", "explanation": "ここは〈掘る〉の意味。穴をあける動作を表し、植物を入れて育てる意味ではない。"}, {"text": "食べ物がなく、子どもたちは何日も飢えて苦しんだ。", "explanation": "ここは〈飢える〉（うえる）の意味。空腹に苦しむ意味で、植物を土に入れる〈植える〉とは別の語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋のうちに、庭にチューリップの球根が植えた。", "corrected_sentence": "秋のうちに、庭にチューリップの球根を植えた。", "error_description": "『植えた』は他動詞で、植えるものは『を』で示す。『球根が』とすると、球根が植える主体になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植える", "is_correct": true, "explanation": "正解。「植えるために」の前は辞書形で、目的を表す。"}, {"text": "植えよう", "is_correct": false, "explanation": "意志形は「植えようために」と続かず、文が成り立たない。"}, {"text": "植えて", "is_correct": false, "explanation": "て形は「ために」の前に置けず、文が成り立たない。"}, {"text": "植えれば", "is_correct": false, "explanation": "仮定形は「植えればために」と続かず、文が成り立たない。"}], "correct_form": "植える", "base_form": "植える", "form_label": "基本形", "sentence_index": 1, "explanations": {"植える": "正解。「植えるために」の前は辞書形で、目的を表す。", "植えよう": "意志形は「植えようために」と続かず、文が成り立たない。", "植えて": "て形は「ために」の前に置けず、文が成り立たない。", "植えれば": "仮定形は「植えればために」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39226, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月、友人と一緒に苗木と植えた。", "corrected_sentence": "先月、友人と一緒に苗木を植えた。", "error_description": "『植えた』の目的語は『を』で示す。『と』にすると並列の形になり、苗木を植えるという意味が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植えられる", "is_correct": true, "explanation": "正解。可能形で「植えることができる」の意味になる。"}, {"text": "植えながら", "is_correct": false, "explanation": "連用形に「ながら」が付いた形で、「植えながら」と続けないと文が終わらず、述語にならない。"}, {"text": "植えたら", "is_correct": false, "explanation": "たら形は「植えたら」と続けないと文が終わらず、述語にならない。"}, {"text": "植えられ", "is_correct": false, "explanation": "連用形は文末にできず、「植えられ。」では述語として成り立たない。"}], "correct_form": "植えられる", "base_form": "植える", "form_label": "可能形", "sentence_index": 7, "explanations": {"植えられる": "正解。可能形で「植えることができる」の意味になる。", "植えながら": "連用形に「ながら」が付いた形で、「植えながら」と続けないと文が終わらず、述語にならない。", "植えたら": "たら形は「植えたら」と続けないと文が終わらず、述語にならない。", "植えられ": "連用形は文末にできず、「植えられ。」では述語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鳥が電線に止まって」で、鳥を動作の主体として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「止まる」は自動詞なので、鳥を目的語の「を」で示すと文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「鳥に電線に止まって」は場所や相手の関係が成立せず、主体を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、鳥の動作の主体を示すことはできない。"}], "correct_answer": "が", "explanations": {"が": "「鳥が電線に止まって」で、鳥を動作の主体として示す正しい助詞。", "を": "「止まる」は自動詞なので、鳥を目的語の「を」で示すと文が成り立たない。", "に": "「鳥に電線に止まって」は場所や相手の関係が成立せず、主体を示せない。", "で": "「で」は手段や場所を示すので、鳥の動作の主体を示すことはできない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空を飛ぶ小さな生き物です。", "primary_collocate": null, "pronunciation": "とり", "ipa": "toɾi", "syllable_count": 2, "sentences": [{"text": "朝、窓の外で小さな鳥が鳴いている。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "朝(あさ)、窓(まど)の外(そと)で小(ちい)さな鳥(とり)が鳴(な)いている。", "sentence_source": "generated"}, {"text": "鳥は空高く飛んで、あっという間に見えなくなった。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)は空(そら)高(たか)く飛(と)んで、あっという間(ま)に見(み)えなくなった。", "sentence_source": "generated"}, {"text": "公園の木に鳥が集まって、にぎやかに歌っていた。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "公園(こうえん)の木(き)に鳥(とり)が集(あつ)まって、にぎやかに歌(うた)っていた。", "sentence_source": "generated"}, {"text": "空を飛ぶ鳥を見ていると、自由でうらやましくなる。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "空(そら)を飛(と)ぶ鳥(とり)を見(み)ていると、自由(じゆう)でうらやましくなる。", "sentence_source": "generated"}, {"text": "鳥のように飛べたらと、子どものころはよく思った。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)のように飛(と)べたらと、子(こ)どものころはよく思(おも)った。", "sentence_source": "generated"}, {"text": "青い空を、白い鳥が一羽ゆっくり横切っていく。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "青(あお)い空(そら)を、白(しろ)い鳥(とり)が一羽(いちわ)ゆっくり横切(よこぎ)っていく。", "sentence_source": "generated"}, {"text": "猫が近づくと、鳥はすぐに屋根の上へ飛び立った。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "猫(ねこ)が近(ちか)づくと、鳥(とり)はすぐに屋根(やね)の上(うえ)へ飛(と)び立(た)った。", "sentence_source": "generated"}, {"text": "鳥が電線に止まって、道を歩く人たちを見下ろしている。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)が電線(でんせん)に止(と)まって、道(みち)を歩(ある)く人(ひと)たちを見下(みお)ろしている。", "sentence_source": "generated"}, {"text": "春になると、渡りの鳥が南から空を渡ってくる。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "春(はる)になると、渡(わた)りの鳥(とり)が南(みなみ)から空(そら)を渡(わた)ってくる。", "sentence_source": "generated"}, {"text": "台風の前は、鳥が低いところを飛ぶと言われている。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "台風(たいふう)の前(まえ)は、鳥(とり)が低(ひく)いところを飛(と)ぶと言(い)われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空を飛ぶ姿や鳴き声で身近に感じられる鳥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳥", "is_correct": true, "explanation": "窓の外で小さく鳴く生き物を指し、「小さな＿＿が鳴いている」に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は鳴かないので、「鳴いている」と合わない。"}, {"text": "魚", "is_correct": false, "explanation": "魚は窓の外で鳴かないので、この文の主語にならない。"}, {"text": "石", "is_correct": false, "explanation": "石は鳴かないので、「鳴いている」と合わない。"}], "explanations": {"鳥": "窓の外で小さく鳴く生き物を指し、「小さな＿＿が鳴いている」に合う。", "花": "花は鳴かないので、「鳴いている」と合わない。", "魚": "魚は窓の外で鳴かないので、この文の主語にならない。", "石": "石は鳴かないので、「鳴いている」と合わない。"}, "sentence_index": 0, "correct_answer": "鳥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大物の鳥が釣れて、みんなで歓声を上げた。", "explanation": "ここは〈魚〉の話。釣れるのは魚で、空を飛ぶ〈鳥〉は釣れないので合わない。"}, {"text": "鳥はひれを動かして、川の中をゆっくり進む。", "explanation": "ここは〈魚〉の話。ひれで泳ぐのは魚で、〈鳥〉は羽で空を飛ぶので、この文には合わない。"}, {"text": "鳥が低いところを流れて、雨が近づいた。", "explanation": "ここは〈雲〉の話。流れるのは雲や水で、鳥は自分の力で飛ぶので〈流れる〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳥", "is_correct": true, "explanation": "屋根の上へ飛び立つ生き物を指し、この文に合う。"}, {"text": "犬", "is_correct": false, "explanation": "犬は屋根の上へ飛び立たないので、「飛び立った」と合わない。"}, {"text": "馬", "is_correct": false, "explanation": "馬は空を飛ばないので、「飛び立った」と合わない。"}, {"text": "亀", "is_correct": false, "explanation": "亀は空を飛ばず、ゆっくり歩くので、「飛び立った」と合わない。"}], "explanations": {"鳥": "屋根の上へ飛び立つ生き物を指し、この文に合う。", "犬": "犬は屋根の上へ飛び立たないので、「飛び立った」と合わない。", "馬": "馬は空を飛ばないので、「飛び立った」と合わない。", "亀": "亀は空を飛ばず、ゆっくり歩くので、「飛び立った」と合わない。"}, "sentence_index": 6, "correct_answer": "鳥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥がすっかり溶けて、水になった。", "explanation": "ここは〈氷〉の話。溶けるのは物質で、空を飛ぶ生き物の鳥には使わない。"}, {"text": "鳥が風で大きくはためいて、ぱたぱた音を立てた。", "explanation": "ここは〈旗〉の話。はためくのは布や旗で、鳥の動きには使わない。"}, {"text": "鳥が春になって、きれいに咲いた。", "explanation": "ここは〈花〉の話。咲くのは花や木で、鳥が咲くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園で鳥を鳴いている。", "corrected_sentence": "公園で鳥が鳴いている。", "error_description": "「鳴く」は自動詞で、鳴く主体は「が」で示す。「鳥を」は誤りで、正しくは「鳥が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39228, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭に来た鳥に、えさを食べている。", "corrected_sentence": "庭に来た鳥が、えさを食べている。", "error_description": "食べる主体を示すのは「が」。「鳥に」は誤りで、正しくは「鳥が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鳥の仲間」で、鳥と仲間を結ぶ「の」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「鳥へ仲間だ」は向かう先を示す形で、仲間の関係を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「鳥を仲間だ」は目的語の形が文の意味と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「鳥に仲間だ」は相手や場所を示す助詞として成立しない。"}], "correct_answer": "の", "explanations": {"の": "「鳥の仲間」で、鳥と仲間を結ぶ「の」が正しい。", "へ": "「鳥へ仲間だ」は向かう先を示す形で、仲間の関係を表せない。", "を": "「鳥を仲間だ」は目的語の形が文の意味と合わない。", "に": "「鳥に仲間だ」は相手や場所を示す助詞として成立しない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「鳥とほ乳類」で、二つの種類を並べる「と」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「鳥でほ乳類のちがい」は手段や場所の意味になり、二つの種類を並べられない。"}, {"text": "へ", "is_correct": false, "explanation": "「鳥へほ乳類のちがい」は向かう先を示す形になり、並列の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「鳥よりほ乳類のちがい」は比較の意味になり、二つを並べる文の意味と合わない。"}], "correct_answer": "と", "explanations": {"と": "「鳥とほ乳類」で、二つの種類を並べる「と」が正しい。", "で": "「鳥でほ乳類のちがい」は手段や場所の意味になり、二つの種類を並べられない。", "へ": "「鳥へほ乳類のちがい」は向かう先を示す形になり、並列の意味にならない。", "より": "「鳥よりほ乳類のちがい」は比較の意味になり、二つを並べる文の意味と合わない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "羽とくちばしを持ち、卵を産む動物です。", "primary_collocate": null, "pronunciation": "とり", "ipa": "toɾi", "syllable_count": 2, "sentences": [{"text": "鳥は羽とくちばしを持っていて、卵を産む動物だ。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)は羽(はね)とくちばしを持(も)っていて、卵(たまご)を産(う)む動物(どうぶつ)だ。", "sentence_source": "generated"}, {"text": "ペンギンは空を飛べないが、鳥の仲間だ。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "ペンギンは空(そら)を飛(と)べないが、鳥(とり)の仲間(なかま)だ。", "sentence_source": "generated"}, {"text": "この鳥は木の枝に巣を作り、毎年春に卵を産む。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "この鳥(とり)は木(き)の枝(えだ)に巣(す)を作(つく)り、毎年(まいとし)春(はる)に卵(たまご)を産(う)む。", "sentence_source": "generated"}, {"text": "鳥の卵は、親が温めるとやがてひなが生まれる。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)の卵(たまご)は、親(おや)が温(あたた)めるとやがてひなが生(う)まれる。", "sentence_source": "generated"}, {"text": "図鑑で調べると、鳥の体は軽い羽でおおわれていた。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "図鑑(ずかん)で調(しら)べると、鳥(とり)の体(からだ)は軽(かる)い羽(はね)でおおわれていた。", "sentence_source": "generated"}, {"text": "鳥のくちばしは、食べ物によって形がちがう。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)のくちばしは、食(た)べ物(もの)によって形(かたち)がちがう。", "sentence_source": "generated"}, {"text": "動物園には、鳥を専門に飼っている大きな小屋がある。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "動物園(どうぶつえん)には、鳥(とり)を専門(せんもん)に飼(か)っている大(おお)きな小屋(こや)がある。", "sentence_source": "generated"}, {"text": "理科の授業で、鳥とほ乳類のちがいを勉強した。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "理科(りか)の授業(じゅぎょう)で、鳥(とり)とほ乳類(にゅうるい)のちがいを勉強(べんきょう)した。", "sentence_source": "generated"}, {"text": "ダチョウは世界で一番大きい鳥で、卵もとても大きい。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "ダチョウは世界(せかい)で一番(いちばん)大(おお)きい鳥(とり)で、卵(たまご)もとても大(おお)きい。", "sentence_source": "generated"}, {"text": "鳥のひなは、卵の殻を割って外に出てくる。", "target_word": "鳥", "complexity_tier": "T3", "furigana": "鳥(とり)のひなは、卵(たまご)の殻(から)を割(わ)って外(そと)に出(で)てくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "羽・くちばし・卵産みで分類される動物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: ほ乳類 (Zipf 2.06)']::text[], 'c24002b6-c864-4b47-b0ab-4d78dc52710d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳥", "is_correct": true, "explanation": "羽とくちばしを持ち、卵を産む動物を指し、文の内容に合う。"}, {"text": "猫", "is_correct": false, "explanation": "猫は羽もくちばしも持たないので、この文の主語にならない。"}, {"text": "魚", "is_correct": false, "explanation": "魚は羽を持たないので、「羽とくちばしを持っていて」と合わない。"}, {"text": "犬", "is_correct": false, "explanation": "犬はくちばしを持たないので、「羽とくちばしを持っていて」と合わない。"}], "explanations": {"鳥": "羽とくちばしを持ち、卵を産む動物を指し、文の内容に合う。", "猫": "猫は羽もくちばしも持たないので、この文の主語にならない。", "魚": "魚は羽を持たないので、「羽とくちばしを持っていて」と合わない。", "犬": "犬はくちばしを持たないので、「羽とくちばしを持っていて」と合わない。"}, "sentence_index": 0, "correct_answer": "鳥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥の甲羅はとても硬く、ふつうの力では割れない。", "explanation": "ここは〈カメ〉の話。甲羅があるのはカメで、羽とくちばしを持つ〈鳥〉には合わない。"}, {"text": "鳥の触角が長くて、よく動いた。", "explanation": "ここは〈虫〉の話。触角があるのは虫で、羽とくちばしを持つ〈鳥〉には合わない。"}, {"text": "鳥はひれを動かして、川の中をゆっくり進む。", "explanation": "ここは〈魚〉の話。ひれで泳ぐのは魚で、羽を持つ〈鳥〉の定義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳥", "is_correct": true, "explanation": "大きな小屋で専門に飼われる生き物を指し、この文に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は専門に飼う対象ではないので、「飼っている」と合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は飼えないので、「飼っている」と合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は飼えないので、「飼っている」と合わない。"}], "explanations": {"鳥": "大きな小屋で専門に飼われる生き物を指し、この文に合う。", "花": "花は専門に飼う対象ではないので、「飼っている」と合わない。", "石": "石は飼えないので、「飼っている」と合わない。", "雲": "雲は飼えないので、「飼っている」と合わない。"}, "sentence_index": 6, "correct_answer": "鳥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥が風で大きくはためいて、ぱたぱた音を立てた。", "explanation": "ここは〈旗〉の話。はためくのは布や旗で、鳥の動きには使わない。"}, {"text": "鳥を開けて、中の手紙を読んだ。", "explanation": "ここは〈封筒〉の話。開けるのは封筒などの入れ物で、羽を持つ〈鳥〉には使わない。"}, {"text": "鳥が春になって、きれいに咲いた。", "explanation": "ここは〈花〉の話。咲くのは花や木で、鳥が咲くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木の上で鳥を鳴いている。", "corrected_sentence": "庭の木の上で鳥が鳴いている。", "error_description": "「鳴く」は自動詞で、鳴く主体は「が」で示す。「鳥を」は誤りで、正しくは「鳥が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鳥を卵から、ひなが生まれてくる。", "corrected_sentence": "鳥の卵から、ひなが生まれてくる。", "error_description": "「鳥の卵」と所有の「の」で結ぶ。「鳥を卵から」の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b77179-de73-4edd-b945-3cf1952683bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
