INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39230, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みんなでいっしょに何かをすることです。", "primary_collocate": null, "pronunciation": "きょうりょくする", "ipa": "kʲoːɾʲokɯsɯɾɯ", "syllable_count": 6, "sentences": [{"text": "クラスのみんなで協力して、文化祭の準備をした。", "target_word": "協力して", "complexity_tier": "T3", "furigana": "クラスのみんなで協力[きょうりょく]して、文化祭[ぶんかさい]の準備[じゅんび]をした。", "sentence_source": "generated"}, {"text": "町の人が協力すれば、きれいな川を守れる。", "target_word": "協力すれば", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]が協力[きょうりょく]すれば、きれいな川[かわ]を守[まも]れる。", "sentence_source": "generated"}, {"text": "重い机は一人では運べないので、友だちと協力した。", "target_word": "協力した", "complexity_tier": "T3", "furigana": "重[おも]い机[つくえ]は一人[ひとり]では運[はこ]べないので、友[とも]だちと協力[きょうりょく]した。", "sentence_source": "generated"}, {"text": "警察に協力して、見たことを話しました。", "target_word": "協力して", "complexity_tier": "T3", "furigana": "警察[けいさつ]に協力[きょうりょく]して、見[み]たことを話[はな]しました。", "sentence_source": "generated"}, {"text": "二つの国は、環境を守るために協力することにした。", "target_word": "協力する", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は、環境[かんきょう]を守[まも]るために協力[きょうりょく]することにした。", "sentence_source": "generated"}, {"text": "家族が協力しないと、大そうじは終わらない。", "target_word": "協力しない", "complexity_tier": "T3", "furigana": "家族[かぞく]が協力[きょうりょく]しないと、大[おお]そうじは終[お]わらない。", "sentence_source": "generated"}, {"text": "皆さんが協力してくれたおかげで、試合に勝てた。", "target_word": "協力して", "complexity_tier": "T3", "furigana": "皆[みな]さんが協力[きょうりょく]してくれたおかげで、試合[しあい]に勝[か]てた。", "sentence_source": "generated"}, {"text": "先生は、チームで協力する大切さを話した。", "target_word": "協力する", "complexity_tier": "T3", "furigana": "先生[せんせい]は、チームで協力[きょうりょく]する大切[たいせつ]さを話[はな]した。", "sentence_source": "generated"}, {"text": "工場と農家が協力して、新しい野菜を作っている。", "target_word": "協力して", "complexity_tier": "T3", "furigana": "工場[こうじょう]と農家[のうか]が協力[きょうりょく]して、新[あたら]しい野菜[やさい]を作[つく]っている。", "sentence_source": "generated"}, {"text": "兄と協力して、母の誕生日のケーキを作った。", "target_word": "協力して", "complexity_tier": "T3", "furigana": "兄[あに]と協力[きょうりょく]して、母[はは]の誕生日[たんじょうび]のケーキを作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協力する", "label": "終止形"}, {"form": "協力します", "label": "丁寧形"}, {"form": "協力した", "label": "過去形"}, {"form": "協力して", "label": "て形"}, {"form": "協力しない", "label": "否定形"}, {"form": "協力すれば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "協力する=目的のために複数の人が力を合わせて一緒に行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4566c31a-91e9-4ecb-9af6-fe525442f3ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39230, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協力して", "is_correct": true, "explanation": "て形で「みんなで協力して」と手段・様子を表し、「、文化祭の準備をした」とつながる。正しい。"}, {"text": "協力した", "is_correct": false, "explanation": "過去形で言い切ると「、」の前に置けず、「クラスのみんなで協力した、文化祭の準備をした」が成り立たない。"}, {"text": "協力する", "is_correct": false, "explanation": "終止形は文を言い切るので、「、」で続く文の途中には入らない。"}, {"text": "協力しよう", "is_correct": false, "explanation": "意向形は文を言い切る形なので、「、」でつながる文の途中には入らない。"}], "explanations": {"協力して": "て形で「みんなで協力して」と手段・様子を表し、「、文化祭の準備をした」とつながる。正しい。", "協力した": "過去形で言い切ると「、」の前に置けず、「クラスのみんなで協力した、文化祭の準備をした」が成り立たない。", "協力する": "終止形は文を言い切るので、「、」で続く文の途中には入らない。", "協力しよう": "意向形は文を言い切る形なので、「、」でつながる文の途中には入らない。"}, "sentence_index": 0, "correct_answer": "協力して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一人で部屋の掃除を全部済ませて、協力した。", "explanation": "ここは〈肩代わり〉の意味。協力は複数の人が力を合わせることなので、一人で全部引き受ける行為とは合わない。"}, {"text": "試合の日、スタンドから大きな声で選手に協力した。", "explanation": "ここは〈応援〉の意味。協力は力を合わせて何かを行うことで、声援を送るだけの行為には使わない。"}, {"text": "先生の注意に協力して、教室で騒いだ。", "explanation": "ここは〈無視〉の意味。協力は相手と力を合わせることなので、注意を聞き流す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39230, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協力して", "is_correct": true, "explanation": "て形で「協力してくれた」となり、「おかげで」につながる。正しい。"}, {"text": "協力し", "is_correct": false, "explanation": "連用形で止めると「くれた」とつながらず、文が成り立たない。"}, {"text": "協力せず", "is_correct": false, "explanation": "「せず」は否定の中止形で、「くれた」の前には置けない。"}, {"text": "協力しろ", "is_correct": false, "explanation": "命令形なので、感謝の「くれたおかげで」とは文として合わない。"}], "explanations": {"協力して": "て形で「協力してくれた」となり、「おかげで」につながる。正しい。", "協力し": "連用形で止めると「くれた」とつながらず、文が成り立たない。", "協力せず": "「せず」は否定の中止形で、「くれた」の前には置けない。", "協力しろ": "命令形なので、感謝の「くれたおかげで」とは文として合わない。"}, "sentence_index": 6, "correct_answer": "協力して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ライバルの選手と協力して、記録を争った。", "explanation": "ここは〈競争〉の意味。協力は同じ目的のために力を合わせることで、争う相手とは一緒にできない。"}, {"text": "仲間に協力して、一人で逃げた。", "explanation": "ここは〈見捨てる〉の意味。協力は仲間と力を合わせることで、仲間を置いていく行為とは合わない。"}, {"text": "新しい案に協力して、やり直しを求めた。", "explanation": "ここは〈批判〉の意味。協力は力を貸すことで、欠点を指摘する行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39230, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "クラスのみんなを協力して、文化祭の準備を進めた。", "corrected_sentence": "クラスのみんなで協力して、文化祭の準備を進めた。", "error_description": "助詞の誤り。「協力して」の前は「で」（みんなで）が正しい。「を」は協力の対象にならず、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "協力すれば", "is_correct": true, "explanation": "仮定形で「協力すれば、〜できる」と条件を表す。正しい。"}, {"text": "協力しよう", "is_correct": false, "explanation": "意向形は文を言い切る形で、「、」の前に置くと「、きれいな川を守れる」とつながらない。"}, {"text": "協力しない", "is_correct": false, "explanation": "否定形なので、川を守れるという肯定の文脈と逆になる。"}, {"text": "協力しろ", "is_correct": false, "explanation": "命令形は文を言い切る形で、「、きれいな川を守れる」と条件の文脈でつながらない。"}], "correct_form": "協力すれば", "base_form": "協力する", "form_label": "仮定形", "sentence_index": 1, "explanations": {"協力すれば": "仮定形で「協力すれば、〜できる」と条件を表す。正しい。", "協力しよう": "意向形は文を言い切る形で、「、」の前に置くと「、きれいな川を守れる」とつながらない。", "協力しない": "否定形なので、川を守れるという肯定の文脈と逆になる。", "協力しろ": "命令形は文を言い切る形で、「、きれいな川を守れる」と条件の文脈でつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39230, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皆さんが協力したくれたおかげで、大会が成功した。", "corrected_sentence": "皆さんが協力してくれたおかげで、大会が成功した。", "error_description": "て形の誤り。「協力してくれた」が正しく、「協力したくれた」は「〜してくれた」の形にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "協力する", "is_correct": true, "explanation": "連体形で「協力する大切さ」と名詞を修飾する。正しい。"}, {"text": "協力します", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できず、「大切さ」につながらない。"}, {"text": "協力し", "is_correct": false, "explanation": "連用形は名詞修飾に使えず、「大切さ」の前に置けない。"}, {"text": "協力せず", "is_correct": false, "explanation": "否定の中止形なので、「大切さ」を修飾する形にならない。"}], "correct_form": "協力する", "base_form": "協力する", "form_label": "連体形", "sentence_index": 7, "explanations": {"協力する": "連体形で「協力する大切さ」と名詞を修飾する。正しい。", "協力します": "丁寧形は名詞を直接修飾できず、「大切さ」につながらない。", "協力し": "連用形は名詞修飾に使えず、「大切さ」の前に置けない。", "協力せず": "否定の中止形なので、「大切さ」を修飾する形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75542d5b-6519-412a-b56f-702ba700c697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝の挨拶」は朝を挨拶に続けて修飾する「の」で、正しい。"}, {"text": "で", "is_correct": false, "explanation": "「朝で挨拶」は手段や場所の「で」になり、名詞を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「朝を挨拶です」は目的語にならず、文の構造が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「朝が挨拶です」は主語にならず、「朝の挨拶」の意味を表さない。"}], "correct_answer": "の", "explanations": {"の": "「朝の挨拶」は朝を挨拶に続けて修飾する「の」で、正しい。", "で": "「朝で挨拶」は手段や場所の「で」になり、名詞を修飾できない。", "を": "「朝を挨拶です」は目的語にならず、文の構造が成り立たない。", "が": "「朝が挨拶です」は主語にならず、「朝の挨拶」の意味を表さない。"}, "error_tags": {"で": "place/means", "を": "object", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が会ったときに言う言葉です。", "primary_collocate": null, "pronunciation": "あいさつ", "ipa": "aisatsɯ", "syllable_count": 4, "sentences": [{"text": "朝は、近所の人に挨拶をします。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "朝[あさ]は、近所[きんじょ]の人[ひと]に挨拶[あいさつ]をします。", "sentence_source": "generated"}, {"text": "「おはよう」は、朝の挨拶です。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "「おはよう」は、朝[あさ]の挨拶[あいさつ]です。", "sentence_source": "generated"}, {"text": "先生に会ったら、大きな声で挨拶しましょう。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "先生[せんせい]に会[あ]ったら、大[おお]きな声[こえ]で挨拶[あいさつ]しましょう。", "sentence_source": "generated"}, {"text": "挨拶をされたら、笑顔で返事をします。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "挨拶[あいさつ]をされたら、笑顔[えがお]で返事[へんじ]をします。", "sentence_source": "generated"}, {"text": "彼は挨拶もしないで、部屋に入りました。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "彼[かれ]は挨拶[あいさつ]もしないで、部屋[へや]に入[はい]りました。", "sentence_source": "generated"}, {"text": "「こんにちは」は、昼によく使う挨拶です。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "「こんにちは」は、昼[ひる]によく使[つか]う挨拶[あいさつ]です。", "sentence_source": "generated"}, {"text": "新しい学校で、最初に友達へ挨拶しました。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "新[あたら]しい学校[がっこう]で、最初[さいしょ]に友達[ともだち]へ挨拶[あいさつ]しました。", "sentence_source": "generated"}, {"text": "隣に引っ越してきた人が、笑顔で挨拶しました。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "隣[となり]に引[ひ]っ越[こ]してきた人[ひと]が、笑顔[えがお]で挨拶[あいさつ]しました。", "sentence_source": "generated"}, {"text": "子どもに、挨拶の大切さを教えています。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "子[こ]どもに、挨拶[あいさつ]の大切[たいせつ]さを教[おし]えています。", "sentence_source": "generated"}, {"text": "店に入ると、店員が元気に挨拶してくれました。", "target_word": "挨拶", "complexity_tier": "T3", "furigana": "店[みせ]に入[はい]ると、店員[てんいん]が元気[げんき]に挨拶[あいさつ]してくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "挨拶", "label": "基本形"}, {"form": "挨拶する", "label": "動詞形"}, {"form": "挨拶を", "label": "目的語"}], "register": "neutral", "sense_fingerprint": "会ったときに交わす決まった言葉（おはよう等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1008a082-97df-4e54-bb3b-338a2360e5cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挨拶", "is_correct": true, "explanation": "「近所の人に挨拶をします」は人と会ったときの言葉として自然に通る。"}, {"text": "運転", "is_correct": false, "explanation": "「近所の人に運転をします」は行為として意味が通らず、空欄に入らない。"}, {"text": "採点", "is_correct": false, "explanation": "「近所の人に採点をします」は文脈に合わず、朝の文に入らない。"}, {"text": "出勤", "is_correct": false, "explanation": "「近所の人に出勤をします」は主語と動作が合わず、成り立たない。"}], "explanations": {"挨拶": "「近所の人に挨拶をします」は人と会ったときの言葉として自然に通る。", "運転": "「近所の人に運転をします」は行為として意味が通らず、空欄に入らない。", "採点": "「近所の人に採点をします」は文脈に合わず、朝の文に入らない。", "出勤": "「近所の人に出勤をします」は主語と動作が合わず、成り立たない。"}, "sentence_index": 0, "correct_answer": "挨拶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の中に、挨拶が入っています。", "explanation": "ここは〈荷物〉の意味。挨拶は形のない言葉なので、箱に入るものではない。"}, {"text": "挨拶で床を磨きました。", "explanation": "ここは〈雑巾〉の意味。挨拶は掃除の道具にはならないので合わない。"}, {"text": "このお店は、挨拶が高くて買えません。", "explanation": "ここは〈値段〉の意味。挨拶には値段がなく、高い・安いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挨拶", "is_correct": true, "explanation": "「新しい学校で、最初に友達へ挨拶しました」は初対面の場面として自然。"}, {"text": "解剖", "is_correct": false, "explanation": "「友達へ解剖しました」は行為として不自然で、この文には入らない。"}, {"text": "出荷", "is_correct": false, "explanation": "「友達へ出荷しました」は商品を送る意味で、場面に合わない。"}, {"text": "測量", "is_correct": false, "explanation": "「友達へ測量しました」は土地を測る行為で、人への動作として成り立たない。"}], "explanations": {"挨拶": "「新しい学校で、最初に友達へ挨拶しました」は初対面の場面として自然。", "解剖": "「友達へ解剖しました」は行為として不自然で、この文には入らない。", "出荷": "「友達へ出荷しました」は商品を送る意味で、場面に合わない。", "測量": "「友達へ測量しました」は土地を測る行為で、人への動作として成り立たない。"}, "sentence_index": 6, "correct_answer": "挨拶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店に入ると、挨拶が元気に鳴りました。", "explanation": "ここは〈ベル〉の意味。挨拶は音を出すものではないので、鳴るとは言えない。"}, {"text": "友達に挨拶を借りました。", "explanation": "ここは〈お金〉の意味。挨拶は貸し借りできるものではないので、借りるとは言えない。"}, {"text": "明日は挨拶が降るでしょう。", "explanation": "ここは〈雨〉の意味。挨拶は空から降るものではないので、降るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、近所の人に挨拶がします。", "corrected_sentence": "毎朝、近所の人に挨拶をします。", "error_description": "「挨拶する」の目的語は「を」で表す。誤: 挨拶が / 正: 挨拶を。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放課後、先生に挨拶のしました。", "corrected_sentence": "放課後、先生に挨拶をしました。", "error_description": "「挨拶をする」の目的語は「の」ではなく「を」で表す。誤: 挨拶の / 正: 挨拶を。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39233, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「笑顔で挨拶しました」は笑顔という様子で挨拶したことを表す「で」で、正しい。"}, {"text": "に", "is_correct": false, "explanation": "「笑顔に挨拶しました」は様子を表す「に」として成り立たず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「笑顔を挨拶しました」は目的語にならず、動作の様子を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「笑顔が挨拶しました」は笑顔が主語になり、文の意味が変わってしまう。"}], "correct_answer": "で", "explanations": {"で": "「笑顔で挨拶しました」は笑顔という様子で挨拶したことを表す「で」で、正しい。", "に": "「笑顔に挨拶しました」は様子を表す「に」として成り立たず、不自然。", "を": "「笑顔を挨拶しました」は目的語にならず、動作の様子を表せない。", "が": "「笑顔が挨拶しました」は笑顔が主語になり、文の意味が変わってしまう。"}, "error_tags": {"に": "direction/target", "を": "object", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fa5edfe-0c0f-4bc2-8079-af983ceda906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
