INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「冗談」は交わす動作の対象なので「を」を使います。"}, {"text": "に", "is_correct": false, "explanation": "「冗談に交わせる」は対象を示せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「冗談へ交わせる」は方向を表せず不自然です。"}, {"text": "から", "is_correct": false, "explanation": "「冗談から交わせる」は対象を示せず不自然です。"}], "correct_answer": "を", "explanations": {"を": "「冗談」は交わす動作の対象なので「を」を使います。", "に": "「冗談に交わせる」は対象を示せず不自然です。", "へ": "「冗談へ交わせる」は方向を表せず不自然です。", "から": "「冗談から交わせる」は対象を示せず不自然です。"}, "error_tags": {"に": "target", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "互いに言葉や物をやりとりすること。", "primary_collocate": null, "pronunciation": "かわす", "ipa": "kawasɯ", "syllable_count": 3, "sentences": [{"text": "それは、言葉を持たぬ者が自然と交わす、最も純粋な対話の形なのかもしれない。", "target_word": "交わす", "complexity_tier": "T6", "furigana": "それは、言葉[ことば]を持[も]たぬ者[もの]が自然[しぜん]と交[か]わす、最[もっと]も純粋[じゅんすい]な対話[たいわ]の形[かたち]なのかもしれない。", "sentence_source": "mined"}, {"text": "二人は握手を交わした。", "target_word": "交わした", "complexity_tier": "T2", "furigana": "二人[ふたり]は握手[あくしゅ]を交[か]わした。", "sentence_source": "generated"}, {"text": "友達とあいさつを交わします。", "target_word": "交わします", "complexity_tier": "T2", "furigana": "友達[ともだち]とあいさつを交[か]わします。", "sentence_source": "generated"}, {"text": "彼と交わした約束を忘れない。", "target_word": "交わした", "complexity_tier": "T3", "furigana": "彼[かれ]と交[か]わした約束[やくそく]を忘[わす]れない。", "sentence_source": "generated"}, {"text": "会議では活発な議論が交わされた。", "target_word": "交わされた", "complexity_tier": "T4", "furigana": "会議[かいぎ]では活発[かっぱつ]な議論[ぎろん]が交[か]わされた。", "sentence_source": "generated"}, {"text": "言葉を交わさなくても、気持ちは伝わる。", "target_word": "交わさなくても", "complexity_tier": "T3", "furigana": "言葉[ことば]を交[か]わさなくても、気持[きも]ちは伝[つた]わる。", "sentence_source": "generated"}, {"text": "二人は視線を交わして笑った。", "target_word": "交わして", "complexity_tier": "T3", "furigana": "二人[ふたり]は視線[しせん]を交[か]わして笑[わら]った。", "sentence_source": "generated"}, {"text": "近所の人と冗談を交わせる関係だ。", "target_word": "交わせる", "complexity_tier": "T4", "furigana": "近所[きんじょ]の人[ひと]と冗談[じょうだん]を交[か]わせる関係[かんけい]だ。", "sentence_source": "generated"}, {"text": "契約を交わす前によく読んでください。", "target_word": "交わす", "complexity_tier": "T3", "furigana": "契約[けいやく]を交[か]わす前[まえ]によく読[よ]んでください。", "sentence_source": "generated"}, {"text": "彼とは長い間、言葉を交わしていない。", "target_word": "交わしていない", "complexity_tier": "T3", "furigana": "彼[かれ]とは長[なが]い間[あいだ]、言葉[ことば]を交[か]わしていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交わした", "label": "活用"}, {"form": "交わして", "label": "活用"}, {"form": "交わさない", "label": "活用"}, {"form": "交わせる", "label": "活用"}, {"form": "交わされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 言葉や物を互いにやりとりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb0ade9-23c9-46b2-b597-ca2a2de71a08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "交わす", "is_correct": true, "explanation": "見出し語そのものの発音です。"}, {"text": "回す", "is_correct": false, "explanation": "「まわす」で、最初の1拍だけが違います。"}, {"text": "枯らす", "is_correct": false, "explanation": "「からす」で、2拍目の「わ」が「ら」に変わっています。"}, {"text": "変わる", "is_correct": false, "explanation": "「かわる」で、最後の1拍だけが違います。"}, {"text": "乾く", "is_correct": false, "explanation": "「かわく」で、最後の1拍だけが違います。"}], "explanations": {"交わす": "見出し語そのものの発音です。", "回す": "「まわす」で、最初の1拍だけが違います。", "枯らす": "「からす」で、2拍目の「わ」が「ら」に変わっています。", "変わる": "「かわる」で、最後の1拍だけが違います。", "乾く": "「かわく」で、最後の1拍だけが違います。"}, "sentence_index": null, "correct_answer": "交わす"}, "level_3": {"options": [{"text": "交わす", "is_correct": true, "explanation": "言葉を互いにやりとりする意味で文脈に合います。"}, {"text": "破る", "is_correct": false, "explanation": "形は合うが意味が合わない。「対話の形」を破るでは文意が通りません。"}, {"text": "避ける", "is_correct": false, "explanation": "形は合うが意味が合わない。避けるでは対話の形になりません。"}, {"text": "数える", "is_correct": false, "explanation": "形は合うが意味が合わない。数えるでは対話の形を表せません。"}], "explanations": {"交わす": "言葉を互いにやりとりする意味で文脈に合います。", "破る": "形は合うが意味が合わない。「対話の形」を破るでは文意が通りません。", "避ける": "形は合うが意味が合わない。避けるでは対話の形になりません。", "数える": "形は合うが意味が合わない。数えるでは対話の形を表せません。"}, "sentence_index": 0, "correct_answer": "交わす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、ジョギングで公園を交わしている。", "explanation": "「交わす」は言葉や物を互いにやりとりする意味で、場所を通ることには使えません。"}, {"text": "彼は財布から千円札を交わして店員に渡した。", "explanation": "一方的に取り出す動作に「交わす」は使えません。やりとりが必要です。"}, {"text": "一人で部屋の中で独り言を交わした。", "explanation": "「交わす」は相手との互いのやりとりが必要で、一人の動作には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "交わす", "is_correct": true, "explanation": "見出し語そのものの発音です。"}, {"text": "返す", "is_correct": false, "explanation": "「かえす」で、2拍目だけが違います。"}, {"text": "噛ます", "is_correct": false, "explanation": "「かます」で、2拍目の「わ」が「ま」に変わっています。"}, {"text": "蛙", "is_correct": false, "explanation": "「かわず」で、最後の1拍だけが違います。"}], "explanations": {"交わす": "見出し語そのものの発音です。", "返す": "「かえす」で、2拍目だけが違います。", "噛ます": "「かます」で、2拍目の「わ」が「ま」に変わっています。", "蛙": "「かわず」で、最後の1拍だけが違います。"}, "sentence_index": null, "correct_answer": "交わす"}, "level_3": {"options": [{"text": "交わして", "is_correct": true, "explanation": "視線を互いに向け合う意味で文に合います。"}, {"text": "数えて", "is_correct": false, "explanation": "形は合うが意味が合わない。視線を数えるとは言えません。"}, {"text": "洗って", "is_correct": false, "explanation": "形は合うが意味が合わない。視線は洗えません。"}, {"text": "建てて", "is_correct": false, "explanation": "形は合うが意味が合わない。視線は建てられません。"}], "explanations": {"交わして": "視線を互いに向け合う意味で文に合います。", "数えて": "形は合うが意味が合わない。視線を数えるとは言えません。", "洗って": "形は合うが意味が合わない。視線は洗えません。", "建てて": "形は合うが意味が合わない。視線は建てられません。"}, "sentence_index": 6, "correct_answer": "交わして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、駅で財布を交わしてしまった。", "explanation": "「交わす」は財布を落とすという意味では使えません。"}, {"text": "この道は大きな道路と交わしている。", "explanation": "道が交差するのは「交わる」で、「交わす」は人が行うやりとりです。"}, {"text": "先生は黒板に名前を交わした。", "explanation": "書く動作に「交わす」は使えません。互いのやりとりではないからです。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人は固い握手が交わした。", "corrected_sentence": "二人は固い握手を交わした。", "error_description": "「握手」は「交わす」の対象なので「が」ではなく「を」を使います。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "交わした", "is_correct": true, "explanation": "過去の完了を表す文末の形で、この文に合います。"}, {"text": "交わすと", "is_correct": false, "explanation": "「〜と」の形では後ろが続かず、文が終われません。"}, {"text": "交わせば", "is_correct": false, "explanation": "仮定形では文が終われません。"}, {"text": "交わし", "is_correct": false, "explanation": "連用形（ます形の語幹）だけでは文が終われません。"}], "correct_form": "交わした", "base_form": "交わす", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"交わした": "過去の完了を表す文末の形で、この文に合います。", "交わすと": "「〜と」の形では後ろが続かず、文が終われません。", "交わせば": "仮定形では文が終われません。", "交わし": "連用形（ます形の語幹）だけでは文が終われません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39235, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄と別れ際に約束に交わした。", "corrected_sentence": "兄と別れ際に約束を交わした。", "error_description": "「交わす」の対象には「を」を使います。「約束に交わす」は誤りです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "交わせる", "is_correct": true, "explanation": "「冗談を交わすことができる」という可能の意味で、名詞「関係」を修飾します。"}, {"text": "交わせば", "is_correct": false, "explanation": "仮定形では「関係」を直接修飾できません。"}, {"text": "交わして", "is_correct": false, "explanation": "て形では「関係」を直接修飾できません。"}, {"text": "交わそう", "is_correct": false, "explanation": "意志形では「関係」を修飾できません。"}], "correct_form": "交わせる", "base_form": "交わす", "form_label": "可能形", "sentence_index": 7, "explanations": {"交わせる": "「冗談を交わすことができる」という可能の意味で、名詞「関係」を修飾します。", "交わせば": "仮定形では「関係」を直接修飾できません。", "交わして": "て形では「関係」を直接修飾できません。", "交わそう": "意志形では「関係」を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64da86de-6581-4613-aca1-f464b168db87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
