INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「コミュニティー作りを考える」の目的語を示す。考える対象を示す自然な形。"}, {"text": "に", "is_correct": false, "explanation": "「作りに考える」は成り立たず、文の述語とつながらない。"}, {"text": "が", "is_correct": false, "explanation": "「作りが考える」は主語の選び方が不自然で、考える主体になれない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、名詞のまま文が止まり「考えるべきだ」と続かない。"}], "correct_answer": "を", "explanations": {"を": "「コミュニティー作りを考える」の目的語を示す。考える対象を示す自然な形。", "に": "「作りに考える」は成り立たず、文の述語とつながらない。", "が": "「作りが考える」は主語の選び方が不自然で、考える主体になれない。", "の": "「の」は連体修飾で、名詞のまま文が止まり「考えるべきだ」と続かない。"}, "error_tags": {"に": "方向（考える対象にならない）", "が": "主語（述語と合わない）", "の": "連体修飾（述語が立たない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が集まって、いっしょに住みやすい場所や仲間を作ること。", "primary_collocate": null, "pronunciation": "こみゅにてぃーつくり", "ipa": "komʲɯnitiːtsɯkuɾi", "syllable_count": 8, "sentences": [{"text": "引っ越してきた私たちは、近所の人とのコミュニティー作りから始めた。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してきた私[わたし]たちは、近所[きんじょ]の人[ひと]とのコミュニティー作[づく]りから始[はじ]めた。", "sentence_source": "generated"}, {"text": "新しい団地では、住民が集まるコミュニティー作りが大切だと言われている。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "新[あたら]しい団地[だんち]では、住民[じゅうみん]が集[あつ]まるコミュニティー作[づく]りが大切[たいせつ]だと言[い]われている。", "sentence_source": "generated"}, {"text": "彼女はコミュニティー作りが上手で、すぐに友だちが増える。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はコミュニティー作[づく]りが上手[じょうず]で、すぐに友[とも]だちが増[ふ]える。", "sentence_source": "generated"}, {"text": "町の公園で月に一度お茶会を開いて、コミュニティー作りを進めている。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "町[まち]の公園[こうえん]で月[つき]に一度[いちど]お茶会[ちゃかい]を開[ひら]いて、コミュニティー作[づく]りを進[すす]めている。", "sentence_source": "generated"}, {"text": "一人暮らしの留学生にとって、コミュニティー作りは安心して暮らすために必要だ。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしの留学生[りゅうがくせい]にとって、コミュニティー作[づく]りは安心[あんしん]して暮[く]らすために必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "コミュニティー作りのために、みんなで集会所の掃除をした。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "コミュニティー作[づく]りのために、みんなで集会所[しゅうかいじょ]の掃除[そうじ]をした。", "sentence_source": "generated"}, {"text": "会社の中にも、趣味の仲間とのコミュニティー作りを応援する制度がある。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の中[なか]にも、趣味[しゅみ]の仲間[なかま]とのコミュニティー作[づく]りを応援[おうえん]する制度[せいど]がある。", "sentence_source": "generated"}, {"text": "住みやすい町にするには、まずコミュニティー作りを考えるべきだ。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "住[す]みやすい町[まち]にするには、まずコミュニティー作[づく]りを考[かんが]えるべきだ。", "sentence_source": "generated"}, {"text": "親たちは、子どもを通したコミュニティー作りを楽しんでいる。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "親[おや]たちは、子[こ]どもを通[とお]したコミュニティー作[づく]りを楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "コミュニティー作りは時間がかかるので、あせらずに続けたい。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "コミュニティー作[づく]りは時間[じかん]がかかるので、あせらずに続[つづ]けたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー作り", "label": "基本形"}, {"form": "コミュニティー作りをする", "label": "動詞句"}], "register": "中立", "sense_fingerprint": "人が集まって、住みやすい場所や仲間をつくっていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニティー作り", "is_correct": true, "explanation": "「近所の人との〜から始めた」に入り、引っ越し後に近所と関係を築く活動を指す。文脈に合う唯一の語。"}, {"text": "回覧板", "is_correct": false, "explanation": "回覧板は回して読む連絡板で、人との関係を始める行為ではないので「から始めた」とつながらない。"}, {"text": "確定申告", "is_correct": false, "explanation": "確定申告は税金の手続きで、近所の人との関係づくりとは結びつかないので文が不自然。"}, {"text": "家賃交渉", "is_correct": false, "explanation": "近所の人と家賃を交渉することは通常ないので、「近所の人との家賃交渉から始めた」は意味が通らない。"}], "explanations": {"コミュニティー作り": "「近所の人との〜から始めた」に入り、引っ越し後に近所と関係を築く活動を指す。文脈に合う唯一の語。", "回覧板": "回覧板は回して読む連絡板で、人との関係を始める行為ではないので「から始めた」とつながらない。", "確定申告": "確定申告は税金の手続きで、近所の人との関係づくりとは結びつかないので文が不自然。", "家賃交渉": "近所の人と家賃を交渉することは通常ないので、「近所の人との家賃交渉から始めた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "コミュニティー作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、一人で走るのが、私のコミュニティー作りの日課だ。", "explanation": "ここは〈体力作り〉の意味。コミュニティー作りは人が集まって仲間や場をつくることで、一人の運動には当てはまらない。"}, {"text": "母は誕生日に、コミュニティー作りのケーキを焼いてくれた。", "explanation": "ここは〈手作り〉の意味。コミュニティー作りは物を作る語ではないので、ケーキには使わない。"}, {"text": "新しいコミュニティー作りを、一晩で仕上げた。", "explanation": "ここは〈名刺作り〉の意味。コミュニティー作りは時間をかけて人間関係を育てるもので、一晩で仕上がる印刷物の話とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニティー作り", "is_correct": true, "explanation": "「趣味の仲間との〜を応援する制度」に入り、仲間を集めて関係を育てる活動を指す。文脈に合う唯一の語。"}, {"text": "社内報", "is_correct": false, "explanation": "「趣味の仲間との社内報」は不自然で、社内報は応援の対象になる活動ではない。"}, {"text": "健康診断", "is_correct": false, "explanation": "「趣味の仲間との健康診断」は意味が通らず、仲間づくりの活動とは別物。"}, {"text": "通勤手当", "is_correct": false, "explanation": "通勤手当は給与の一部で、趣味の仲間との関係づくりを表さないので文が成り立たない。"}], "explanations": {"コミュニティー作り": "「趣味の仲間との〜を応援する制度」に入り、仲間を集めて関係を育てる活動を指す。文脈に合う唯一の語。", "社内報": "「趣味の仲間との社内報」は不自然で、社内報は応援の対象になる活動ではない。", "健康診断": "「趣味の仲間との健康診断」は意味が通らず、仲間づくりの活動とは別物。", "通勤手当": "通勤手当は給与の一部で、趣味の仲間との関係づくりを表さないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "コミュニティー作り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コミュニティー作りは、ネタの鮮度が味を決める。", "explanation": "ここは〈寿司作り〉の意味。ネタの鮮度で味が決まるのは寿司の話で、人の集まりづくりとは違う。"}, {"text": "コミュニティー作りは、米の質で味が決まる。", "explanation": "ここは〈酒作り〉の意味。米の質で味が決まるのは醸造の話で、仲間づくりには合わない。"}, {"text": "コミュニティー作りは、紙の色を揃えるのがコツだ。", "explanation": "ここは〈掲示板作り〉の意味。紙の色を揃える作業は掲示物の話で、人の集まりづくりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はコミュニティー作りを上手だ。", "corrected_sentence": "彼女はコミュニティー作りが上手だ。", "error_description": "「上手だ」は「が」を取る形容動詞。「を」は誤りで、正しくは「コミュニティー作りが上手だ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39236, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域では、コミュニティー作りを続けてている。", "corrected_sentence": "地域では、コミュニティー作りを続けている。", "error_description": "「続けている」が正しい（続ける＋ている）。「続けてている」は「て」を重ねた誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「参加する」は「〜に」で場や相手を取る。コミュニティー作りに学生が加わるという自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "「参加する」は「を」を取らないので、「作りを参加している」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」だと文が名詞で止まり、「参加している」と続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」になり、「学生も参加している」と話がつながらない。"}], "correct_answer": "に", "explanations": {"に": "「参加する」は「〜に」で場や相手を取る。コミュニティー作りに学生が加わるという自然な文になる。", "を": "「参加する」は「を」を取らないので、「作りを参加している」は不自然。", "の": "「の」だと文が名詞で止まり、「参加している」と続かない。", "より": "比較の「より」になり、「学生も参加している」と話がつながらない。"}, "error_tags": {"を": "目的語（参加と合わない）", "の": "連体修飾（述語が立たない）", "より": "比較（文脈と合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "農村で「共同の作業がコミュニティー作りになる」の「に」。変化の結果を示す自然な形。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語を取らないので、「作りをなっていた」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「作りがなっていた」は主語と述語が噛み合わず、文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾で、「なっていた」の述語が立たない。"}], "correct_answer": "に", "explanations": {"に": "農村で「共同の作業がコミュニティー作りになる」の「に」。変化の結果を示す自然な形。", "を": "「なる」は目的語を取らないので、「作りをなっていた」は成り立たない。", "が": "「作りがなっていた」は主語と述語が噛み合わず、文が崩れる。", "の": "「の」は連体修飾で、「なっていた」の述語が立たない。"}, "error_tags": {"を": "目的語（変化の動詞と合わない）", "が": "主語（述語と合わない）", "の": "連体修飾（述語が立たない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人と人がつながり、助け合いながら、地域やグループの絆を育てていくこと。", "primary_collocate": null, "pronunciation": "こみゅにてぃーつくり", "ipa": "komʲɯnitiːtsɯkuɾi", "syllable_count": 8, "sentences": [{"text": "災害のあと、助け合いのコミュニティー作りが地域の力になった。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "災害[さいがい]のあと、助[たす]け合[あ]いのコミュニティー作[づく]りが地域[ちいき]の力[ちから]になった。", "sentence_source": "generated"}, {"text": "お年寄りを見守るコミュニティー作りに、学生も参加している。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "お年寄[としよ]りを見守[みまも]るコミュニティー作[づく]りに、学生[がくせい]も参加[さんか]している。", "sentence_source": "generated"}, {"text": "地域の祭りは、人々の絆を深めるコミュニティー作りの場でもある。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "地域[ちいき]の祭[まつ]りは、人々[ひとびと]の絆[きずな]を深[ふか]めるコミュニティー作[づく]りの場[ば]でもある。", "sentence_source": "generated"}, {"text": "市は、住民が互いに声をかけ合うコミュニティー作りを支援している。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "市[し]は、住民[じゅうみん]が互[たが]いに声[こえ]をかけ合[あ]うコミュニティー作[づく]りを支援[しえん]している。", "sentence_source": "generated"}, {"text": "顔を合わせる機会が少ないと、コミュニティー作りは難しくなる。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "顔[かお]を合[あ]わせる機会[きかい]が少[すく]ないと、コミュニティー作[づく]りは難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "彼は、地域の若者と高齢者をつなぐコミュニティー作りに十年取り組んでいる。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "彼[かれ]は、地域[ちいき]の若者[わかもの]と高齢者[こうれいしゃ]をつなぐコミュニティー作[づく]りに十年[じゅうねん]取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "孤立する人を減らすためには、日ごろからのコミュニティー作りが欠かせない。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "孤立[こりつ]する人[ひと]を減[へ]らすためには、日[ひ]ごろからのコミュニティー作[づく]りが欠[か]かせない。", "sentence_source": "generated"}, {"text": "農村では、共同の作業がそのままコミュニティー作りになっていた。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "農村[のうそん]では、共同[きょうどう]の作業[さぎょう]がそのままコミュニティー作[づく]りになっていた。", "sentence_source": "generated"}, {"text": "長く続くコミュニティー作りには、無理のない活動が向いている。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]くコミュニティー作[づく]りには、無理[むり]のない活動[かつどう]が向[む]いている。", "sentence_source": "generated"}, {"text": "防災訓練をきっかけに、コミュニティー作りが進んだ。", "target_word": "コミュニティー作り", "complexity_tier": "T3", "furigana": "防災訓練[ぼうさいくんれん]をきっかけに、コミュニティー作[づく]りが進[すす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー作り", "label": "基本形"}, {"form": "コミュニティー作りをする", "label": "動詞句"}], "register": "やや硬い", "sense_fingerprint": "人のつながりと助け合いで、地域やグループの絆を育てていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T4: contains vocabulary far above tier T4: かけ合う (Zipf 1.26)']::text[], 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニティー作り", "is_correct": true, "explanation": "「助け合いの〜が地域の力になった」に入り、人のつながりで地域の絆を育てる活動を指す。文脈に合う唯一の語。"}, {"text": "防火扉", "is_correct": false, "explanation": "防火扉は建物の設備で、助け合いの活動にはならないので「助け合いの防火扉」は意味が通らない。"}, {"text": "避難経路", "is_correct": false, "explanation": "避難経路は逃げる道筋で、助け合いの活動そのものではないので文脈に合わない。"}, {"text": "警報機", "is_correct": false, "explanation": "警報機は機械で、助け合いの関係づくりを表さないので「助け合いの警報機」は意味が通らない。"}], "explanations": {"コミュニティー作り": "「助け合いの〜が地域の力になった」に入り、人のつながりで地域の絆を育てる活動を指す。文脈に合う唯一の語。", "防火扉": "防火扉は建物の設備で、助け合いの活動にはならないので「助け合いの防火扉」は意味が通らない。", "避難経路": "避難経路は逃げる道筋で、助け合いの活動そのものではないので文脈に合わない。", "警報機": "警報機は機械で、助け合いの関係づくりを表さないので「助け合いの警報機」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "コミュニティー作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毎年冬、大豆を煮て麹と混ぜるコミュニティー作りをしている。", "explanation": "ここは〈味噌作り〉の意味。大豆や麹を扱う作業はコミュニティー作りの内容ではないので合わない。"}, {"text": "コミュニティー作りは、まず土をこねるところから始まる。", "explanation": "ここは〈陶器作り〉の意味。土をこねる工程は物を作る話で、人の絆を育てる活動には当てはまらない。"}, {"text": "このコミュニティー作りでは、句読点の打ち方が大事だ。", "explanation": "ここは〈文章作り〉の意味。句読点の打ち方は文章の話で、人と人の関係づくりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニティー作り", "is_correct": true, "explanation": "「日ごろからの〜が欠かせない」に入り、孤立を防ぐために人の関係を日常的に育てる活動を指す。文脈に合う唯一の語。"}, {"text": "花火大会", "is_correct": false, "explanation": "花火大会は日ごろから続けるものではなく、孤立を減らす活動とは結びつかないので文が不自然。"}, {"text": "美術館", "is_correct": false, "explanation": "美術館は施設で、「日ごろからの美術館が欠かせない」は意味が通らない。"}, {"text": "製薬会社", "is_correct": false, "explanation": "製薬会社は企業で、人の孤立を減らす取り組みとしては文脈に合わない。"}], "explanations": {"コミュニティー作り": "「日ごろからの〜が欠かせない」に入り、孤立を防ぐために人の関係を日常的に育てる活動を指す。文脈に合う唯一の語。", "花火大会": "花火大会は日ごろから続けるものではなく、孤立を減らす活動とは結びつかないので文が不自然。", "美術館": "美術館は施設で、「日ごろからの美術館が欠かせない」は意味が通らない。", "製薬会社": "製薬会社は企業で、人の孤立を減らす取り組みとしては文脈に合わない。"}, "sentence_index": 6, "correct_answer": "コミュニティー作り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コミュニティー作りは、ペンの字が印象を決める。", "explanation": "ここは〈年賀状作り〉の意味。ペンの字で印象が決まるのは書き物の話で、人の絆づくりには合わない。"}, {"text": "コミュニティー作りは、絵の具を重ねる工程が長い。", "explanation": "ここは〈絵画作り〉の意味。絵の具を重ねる工程は描画の話で、人のつながりを育てる活動には当てはまらない。"}, {"text": "コミュニティー作りは、茎の長さを揃えるのがコツだ。", "explanation": "ここは〈花束作り〉の意味。茎の長さを揃える作業は花束の話で、地域の関係づくりには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は、コミュニティー作りが力を入れている。", "corrected_sentence": "町は、コミュニティー作りに力を入れている。", "error_description": "「力を入れる」の相手は「に」で示す。「が」は誤りで、正しくは「コミュニティー作りに力を入れている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39237, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は、コミュニティー作りに長く取り組みでいる。", "corrected_sentence": "町は、コミュニティー作りに長く取り組んでいる。", "error_description": "「取り組んでいる」が正しい（取り組む→取り組んで＋いる）。「取り組みでいる」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
